(function(){
  if (typeof LESSONS === "undefined") return;
  if (typeof STAGES !== "undefined") STAGES[22] = "Tin học 12 — Khoa học máy tính";
  if (typeof QUESTION_BANK !== "undefined") QUESTION_BANK.push.apply(QUESTION_BANK, [{"id":"CC-mc-101","type":"mc","topic":"G","grade":12,"level":"easy","question":"Trí tuệ nhân tạo (AI) là gì?","options":["Một loại phần cứng máy tính có tốc độ xử lí nhanh hơn bình thường","Việc làm cho máy tính thực hiện được những việc thường cần trí thông minh của con người","Một ngôn ngữ lập trình mới dùng để viết ứng dụng di động","Một loại virus máy tính có khả năng tự nhân bản"],"answer":1,"explain":"AI là một nhánh của khoa học máy tính, hướng đến việc làm cho máy tính thực hiện những việc như nhận dạng hình ảnh, hiểu giọng nói hay ra quyết định — những việc vốn thường cần trí thông minh của con người. AI không phải là phần cứng, ngôn ngữ lập trình hay virus máy tính."},{"id":"CC-mc-102","type":"mc","topic":"G","grade":12,"level":"easy","question":"Việc nào sau đây là một ví dụ về ứng dụng AI trong đời sống hằng ngày?","options":["Máy tính bỏ túi cộng hai số do người dùng nhập vào","Đồng hồ hiển thị đúng giờ hiện tại","Ứng dụng gợi ý video tiếp theo dựa trên lịch sử xem của người dùng","Máy in in ra văn bản theo đúng nội dung đã soạn"],"answer":2,"explain":"Gợi ý video dựa trên lịch sử xem thể hiện đặc điểm của AI: hệ thống phải phân tích hành vi người dùng để đưa ra gợi ý phù hợp. Ba việc còn lại chỉ thực hiện đúng một thao tác cố định theo quy tắc đơn giản, không cần học từ dữ liệu."},{"id":"CC-mc-103","type":"mc","topic":"G","grade":12,"level":"medium","question":"Điểm khác biệt cốt lõi giữa một chương trình máy tính thông thường (dùng các quy tắc `if`, `else` do người lập trình đặt ra) với phần lớn hệ thống AI hiện nay là gì?","options":["Chương trình thông thường luôn chạy nhanh hơn AI trong mọi trường hợp","AI luôn cho kết quả chính xác tuyệt đối, còn chương trình thông thường thì không","Phần lớn hệ thống AI học quy luật từ dữ liệu, thay vì được lập trình cứng từng quy tắc","AI chỉ chạy được trên điện thoại, còn chương trình thông thường chỉ chạy trên máy tính để bàn"],"answer":2,"explain":"Chương trình thông thường dựa vào các quy tắc được liệt kê sẵn bằng `if`, `else`. Phần lớn hệ thống AI hiện nay thay vào đó học từ nhiều ví dụ dữ liệu để tự tìm ra quy luật, rồi áp dụng cho trường hợp mới. Các phương án còn lại không đúng bản chất của AI."},{"id":"CC-mc-104","type":"mc","topic":"G","grade":12,"level":"medium","question":"Một bộ lọc thư rác được cho xem hàng trăm nghìn email đã đánh dấu sẵn là “rác” hoặc “bình thường”, sau đó tự nhận ra các đặc điểm thường gặp ở thư rác để áp dụng cho email mới. Cách hoạt động này thể hiện rõ nhất đặc điểm nào của AI?","options":["AI luôn cần kết nối Internet liên tục để hoạt động","AI học từ dữ liệu thay vì dựa vào một danh sách quy tắc cố định","AI chỉ hoạt động chính xác với văn bản tiếng Anh","AI không thể áp dụng cho các email chưa từng xuất hiện trước đó"],"answer":1,"explain":"Ví dụ trong bài minh hoạ đúng đặc điểm học từ dữ liệu: hệ thống không được lập trình sẵn từng từ khoá, mà tự rút ra đặc điểm chung từ rất nhiều email mẫu, rồi áp dụng cho email mới — kể cả những email chưa từng gặp trước đó."},{"id":"CC-mc-105","type":"mc","topic":"G","grade":12,"level":"hard","question":"Một hệ thống AI được huấn luyện rất tốt để nhận diện khuôn mặt trong ảnh chụp ban ngày, đủ ánh sáng. Nhận định nào sau đây hợp lí nhất về hệ thống này?","options":["Hệ thống có thể hoạt động kém chính xác hơn trong điều kiện thiếu sáng hoặc góc chụp lạ, vì đó là tình huống khác với dữ liệu đã học","Hệ thống chắc chắn cũng nhận diện chính xác giọng nói và dịch được ngôn ngữ, vì đã có trí tuệ nhân tạo","Hệ thống đã có ý thức và tự hiểu được mình đang làm gì khi nhận diện khuôn mặt","Hệ thống không cần dữ liệu nào để hoạt động, vì đã được lập trình cứng toàn bộ quy tắc"],"answer":0,"explain":"AI hiện nay chỉ giỏi trong phạm vi được huấn luyện; gặp tình huống khác biệt lớn so với dữ liệu đã học (thiếu sáng, góc chụp lạ...) thì độ chính xác có thể giảm. Giỏi một việc hẹp không kéo theo giỏi việc khác, hệ thống không có ý thức, và vẫn cần dữ liệu để học — nên các phương án còn lại đều không hợp lí."},{"id":"CC-tf-101","type":"tf","topic":"G","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Nhiều hệ thống AI hiện nay hoạt động dựa trên việc học từ một lượng lớn dữ liệu ví dụ.","correct":true},{"text":"AI hiện chỉ được dùng trong phòng thí nghiệm nghiên cứu, chưa xuất hiện trong ứng dụng hằng ngày.","correct":false},{"text":"Một hệ thống AI giỏi trong một việc cụ thể, như nhận diện khuôn mặt, không đồng nghĩa với việc nó có ý thức hoặc hiểu biết toàn diện như con người.","correct":true},{"text":"Trợ lí ảo trên điện thoại luôn hiểu chính xác mọi câu nói của người dùng trong mọi tình huống, không bao giờ sai.","correct":false}],"explain":"(1) Đúng — phần lớn hệ thống AI hiện nay dựa trên việc học từ dữ liệu. (2) Sai — AI đã xuất hiện phổ biến trong đời sống hằng ngày, như trợ lí ảo, gợi ý nội dung hay lọc thư rác. (3) Đúng — giỏi một việc hẹp không đồng nghĩa với có ý thức hay hiểu biết toàn diện như con người. (4) Sai — hệ thống AI vẫn có thể hiểu sai, đặc biệt khi giọng nói không rõ, có tiếng ồn, hoặc cách diễn đạt lạ."},{"id":"CC-mc-201","type":"mc","topic":"G","grade":12,"level":"easy","question":"Hệ thống gợi ý phim, gợi ý sản phẩm khi bạn mua sắm trên các nền tảng trực tuyến là ứng dụng của AI trong lĩnh vực nào?","options":["Giải trí","Y tế","Nông nghiệp","Giao thông"],"answer":0,"explain":"Hệ thống gợi ý (`recommendation`) phân tích thói quen xem, nghe, mua sắm để đề xuất nội dung phù hợp là ứng dụng AI tiêu biểu trong lĩnh vực giải trí và tiêu dùng trực tuyến. Y tế, nông nghiệp, giao thông là những lĩnh vực khác có ứng dụng AI riêng, không liên quan đến hệ thống gợi ý này."},{"id":"CC-mc-202","type":"mc","topic":"G","grade":12,"level":"easy","question":"Trong ví dụ phần mềm hỗ trợ chẩn đoán qua ảnh X-quang, ai là người đưa ra kết luận và quyết định điều trị cuối cùng?","options":["Phần mềm AI","Người bệnh tự quyết định","Không ai cần quyết định vì AI đã đủ chính xác","Bác sĩ"],"answer":3,"explain":"Phần mềm AI chỉ đưa ra một khả năng ước lượng và khoanh vùng nghi ngờ để tham khảo; bác sĩ mới là người đối chiếu thêm triệu chứng, tiền sử bệnh và đưa ra kết luận, quyết định điều trị cuối cùng. AI không thay thế hoàn toàn vai trò của bác sĩ."},{"id":"CC-mc-203","type":"mc","topic":"G","grade":12,"level":"medium","question":"Vì sao dữ liệu huấn luyện bị lệch hoặc thiếu đa dạng lại là vấn đề nghiêm trọng đối với AI?","options":["Vì khi đó AI sẽ chạy chậm hơn bình thường","Vì AI hình thành ‘hiểu biết’ hoàn toàn từ dữ liệu huấn luyện, nên dữ liệu lệch sẽ khiến kết quả đưa ra cũng thiên lệch hoặc sai theo","Vì dữ liệu lệch làm phần mềm AI bị lỗi, không thể chạy được nữa","Vì đó chỉ là lỗi kĩ thuật, có thể sửa bằng cách khởi động lại phần mềm"],"answer":1,"explain":"AI, đặc biệt các hệ thống học máy, không suy luận độc lập mà hình thành mọi ‘hiểu biết’ từ dữ liệu huấn luyện đã học; khi dữ liệu đó lệch, thiếu đa dạng hoặc mang sẵn định kiến, kết quả AI đưa ra sẽ phản ánh lại sự lệch đó. Đây không phải là lỗi kĩ thuật đơn thuần, không liên quan đến tốc độ chạy, và không thể khắc phục chỉ bằng cách khởi động lại phần mềm."},{"id":"CC-mc-204","type":"mc","topic":"G","grade":12,"level":"medium","question":"Phát biểu nào sau đây mô tả đúng nhất việc AI ‘hiểu’ vấn đề?","options":["AI hiểu vấn đề y hệt như con người, kể cả suy luận có ý thức","AI luôn từ chối trả lời khi gặp tình huống chưa từng gặp trong dữ liệu đã học","AI nhận diện khuôn mẫu (`pattern`) lặp lại trong dữ liệu đã học, không suy luận có ý thức như con người","AI không thể xử lí bất kì dữ liệu nào ngoài dữ liệu đã học"],"answer":2,"explain":"AI nhận diện khuôn mẫu lặp lại trong dữ liệu, chứ không ‘hiểu’ và suy luận có ý thức như con người. Vì vậy khi gặp tình huống khác lạ, AI vẫn thường đưa ra câu trả lời — thậm chí rất tự tin — dù câu trả lời có thể sai, chứ không phải lúc nào cũng từ chối trả lời hay không xử lí được."},{"id":"CC-mc-205","type":"mc","topic":"G","grade":12,"level":"hard","question":"Một hệ thống tuyển dụng dùng AI để tự động xếp hạng hồ sơ ứng viên, được huấn luyện từ dữ liệu tuyển dụng thành công suốt 10 năm qua của công ty — giai đoạn mà phần lớn người được tuyển ở một vị trí nhất định đều thuộc cùng một nhóm nhân khẩu học. Nguy cơ lớn nhất khi triển khai hệ thống này là gì?","options":["Hệ thống có xu hướng ưu tiên nhóm nhân khẩu học từng chiếm đa số trong dữ liệu cũ, gây thiên lệch, bất công với ứng viên thuộc nhóm khác dù năng lực tương đương","Hệ thống sẽ chạy chậm hơn nhiều so với xếp hạng thủ công","Hệ thống sẽ từ chối xếp hạng vì không đủ dữ liệu để hoạt động","Hệ thống sẽ tự động phát hiện và sửa lại định kiến có sẵn trong dữ liệu cũ"],"answer":0,"explain":"Vì AI học từ dữ liệu tuyển dụng cũ, nếu dữ liệu đó vốn nghiêng về một nhóm nhân khẩu học, hệ thống rất dễ lặp lại xu hướng đó, dẫn tới thiên lệch, bất công cho ứng viên thuộc nhóm khác dù năng lực tương đương — đây là hệ quả trực tiếp của việc AI phụ thuộc vào dữ liệu huấn luyện. AI không tự động phát hiện và sửa định kiến có sẵn trong dữ liệu nếu không có sự can thiệp có chủ đích của con người khi thiết kế hệ thống."},{"id":"CC-tf-201","type":"tf","topic":"G","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"AI được ứng dụng trong nông nghiệp có thể giúp phát hiện sớm sâu bệnh nhờ phân tích ảnh vệ tinh hoặc dữ liệu cảm biến.","correct":true},{"text":"Vì AI xử lí dữ liệu rất nhanh, kết quả do AI đưa ra luôn luôn chính xác nên không cần kiểm chứng lại.","correct":false},{"text":"Công nghệ tạo ảnh, video, giọng nói giả bằng AI (`deepfake`) có thể bị lạm dụng để lan truyền thông tin sai lệch.","correct":true},{"text":"AI suy luận có ý thức và hiểu vấn đề giống hệt con người, do đó AI không bao giờ trả lời sai.","correct":false}],"explain":"(1) Đúng, đây là một ứng dụng thực tế của AI trong nông nghiệp đã nêu trong bài. (2) Sai vì AI có thể trả lời sai, đặc biệt khi dữ liệu huấn luyện bị lệch hoặc gặp tình huống lạ; kết quả AI đưa ra luôn cần được kiểm chứng lại trước khi dùng cho việc quan trọng. (3) Đúng, đây là một rủi ro thực tế của AI được nêu trong bài. (4) Sai vì AI chỉ nhận diện khuôn mẫu trong dữ liệu, không suy luận có ý thức như con người, và hoàn toàn có thể trả lời sai một cách tự tin."},{"id":"CC-mc-301","type":"mc","topic":"B","grade":12,"level":"easy","question":"Câu nào sau đây mô tả đúng nhất mô hình khách – chủ (client-server)?","options":["Máy chủ luôn là bên chủ động gửi yêu cầu trước, máy khách chỉ chờ nhận","Máy khách và máy chủ là hai loại thiết bị cố định, không thể đổi vai trò cho nhau","Máy khách là bên gửi yêu cầu; máy chủ tiếp nhận, xử lý và gửi lại đúng dữ liệu hoặc dịch vụ được yêu cầu","Một máy chủ chỉ có thể phục vụ đúng một máy khách tại một thời điểm"],"answer":2,"explain":"Trong mô hình khách – chủ, máy khách là bên gửi yêu cầu, còn máy chủ tiếp nhận, xử lý rồi trả lại đúng dữ liệu hoặc dịch vụ được yêu cầu. Vai trò này xác định theo hành động (ai gửi, ai đáp ứng) chứ không cố định theo loại thiết bị, và một máy chủ thường phục vụ được rất nhiều máy khách cùng lúc chứ không chỉ một."},{"id":"CC-mc-302","type":"mc","topic":"B","grade":12,"level":"easy","question":"Khi một trình duyệt gửi yêu cầu xem một trang web tới nơi lưu trữ trang đó, trình duyệt lúc này đang đóng vai trò gì?","options":["Máy khách, vì trình duyệt là bên gửi yêu cầu và nhận về nội dung để hiển thị","Máy chủ, vì trình duyệt hiển thị nội dung ra màn hình cho người dùng xem","Vừa là máy khách vừa là máy chủ trong cùng một yêu cầu đó","Không đóng vai trò nào trong mô hình khách – chủ, vì trình duyệt chỉ là phần mềm"],"answer":0,"explain":"Trình duyệt là bên chủ động gửi yêu cầu xin xem trang web rồi nhận về nội dung để hiển thị, nên nó đóng vai máy khách. Nơi lưu trữ và trả về nội dung trang web mới là máy chủ."},{"id":"CC-mc-303","type":"mc","topic":"B","grade":12,"level":"medium","question":"Vai trò của giao thức (`protocol`) trong việc trao đổi dữ liệu qua mạng là gì?","options":["Là tên gọi khác của địa chỉ dùng để nhận diện một thiết bị trên mạng","Là một loại thiết bị phần cứng dùng để khuếch đại tín hiệu mạng đi xa hơn","Chỉ thật sự cần thiết khi hai thiết bị kết nối với nhau là do cùng một hãng sản xuất","Là bộ quy tắc chung, quy định cách gửi, cách nhận và trình tự trao đổi, để các thiết bị khác nhau vẫn hiểu được nhau"],"answer":3,"explain":"Giao thức là bộ quy tắc chung mà các thiết bị cùng tuân theo khi trao đổi dữ liệu, quy định cách gửi, cách nhận và trình tự thực hiện. Nó không phải là địa chỉ hay thiết bị phần cứng, và giá trị lớn nhất của nó chính là giúp các thiết bị khác hãng sản xuất vẫn hiểu được nhau, không chỉ riêng thiết bị cùng hãng."},{"id":"CC-mc-304","type":"mc","topic":"B","grade":12,"level":"medium","question":"Vì sao dữ liệu thường được chia thành nhiều gói tin trước khi gửi qua mạng, thay vì gửi nguyên khối một lần?","options":["Vì mỗi gói tin bắt buộc phải được gửi đến một máy chủ khác nhau","Để mỗi gói tin có thể đi theo đường truyền khác nhau, tránh mất toàn bộ dữ liệu nếu một đoạn đường gặp sự cố, đồng thời tận dụng đường truyền hiệu quả hơn","Vì các thiết bị mạng chỉ xử lý được dữ liệu có kích thước đúng bằng một byte","Để giảm bớt số lượng địa chỉ cần cấp phát trên mạng"],"answer":1,"explain":"Chia dữ liệu thành nhiều gói tin nhỏ giúp mỗi gói có thể đi theo đường truyền khác nhau, tận dụng nhiều tuyến đường cùng lúc và tránh việc toàn bộ dữ liệu bị ảnh hưởng nếu chỉ một đoạn đường gặp sự cố. Các phương án còn lại không đúng với lý do chia gói tin."},{"id":"CC-mc-305","type":"mc","topic":"B","grade":12,"level":"hard","question":"Hai gói tin thuộc cùng một tệp video được gửi đi qua mạng, nhưng do đi theo hai đường truyền khác nhau, gói gửi sau lại đến nơi nhận trước gói gửi trước đó. Nhờ đâu thiết bị nhận vẫn ghép lại đúng tệp video ban đầu?","options":["Thiết bị nhận đoán thứ tự dựa trên thời gian mỗi gói tin đến nơi","Chỉ gói tin đến trước được giữ lại, gói đến sau bị loại bỏ khỏi dữ liệu","Mỗi gói tin mang theo số thứ tự, cho biết vị trí của nó trong toàn bộ dữ liệu gốc, giúp ghép đúng dù các gói đến không theo thứ tự","Toàn bộ tệp video phải được gửi lại từ đầu để đảm bảo đúng thứ tự"],"answer":2,"explain":"Mỗi gói tin mang theo số thứ tự xác định vị trí của nó trong dữ liệu gốc, nên dù các gói đến nơi nhận không theo đúng thứ tự gửi đi, thiết bị nhận vẫn dựa vào số thứ tự đó để sắp xếp và ghép lại đúng tệp video ban đầu, không cần đoán theo thời gian đến hay gửi lại từ đầu."},{"id":"CC-tf-301","type":"tf","topic":"B","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Một máy chủ chỉ có thể tiếp nhận yêu cầu từ một máy khách duy nhất tại một thời điểm.","correct":false},{"text":"`HTTP` và `TCP/IP` đều là ví dụ của giao thức, mỗi loại phụ trách một công việc khác nhau trên mạng.","correct":true},{"text":"Nhờ có giao thức chung, các thiết bị của những hãng sản xuất khác nhau vẫn có thể trao đổi dữ liệu với nhau qua mạng.","correct":true},{"text":"Gói tin không cần mang theo địa chỉ nơi nhận, vì dữ liệu luôn đi theo một đường truyền cố định duy nhất tới đích.","correct":false}],"explain":"(1) sai vì một máy chủ thường tiếp nhận và trả lời cùng lúc rất nhiều máy khách khác nhau, không giới hạn ở một máy khách duy nhất. (2) đúng vì `HTTP` quy định cách trao đổi trang web, còn `TCP/IP` là giao thức nền tảng quy định cách đánh địa chỉ và truyền dữ liệu trên Internet — cả hai đều là giao thức, chỉ khác công việc đảm nhiệm. (3) đúng vì giao thức chính là bộ quy tắc chung giúp các thiết bị khác hãng sản xuất, khác hệ điều hành vẫn hiểu và trao đổi được với nhau. (4) sai vì mỗi gói tin luôn cần mang theo địa chỉ nơi gửi và nơi nhận, và trên thực tế các gói tin của cùng một dữ liệu có thể đi theo những đường truyền khác nhau chứ không cố định."},{"id":"CC-mc-401","type":"mc","topic":"B","grade":12,"level":"easy","question":"`Modem` có vai trò chính là gì trong một mạng gia đình?","options":["Nối nhiều máy tính trong cùng một mạng nội bộ lại với nhau","Phát sóng không dây để điện thoại, laptop kết nối mà không cần cắm dây","Nối ngôi nhà với nhà cung cấp dịch vụ Internet, chuyển đổi tín hiệu giữa hai bên","Lưu trữ toàn bộ nội dung của một trang web để người dùng truy cập"],"answer":2,"explain":"`Modem` là thiết bị nối ngôi nhà (hay văn phòng) với nhà cung cấp dịch vụ Internet, chuyển đổi tín hiệu giữa đường truyền của nhà mạng và dữ liệu mà các thiết bị trong nhà dùng được. Nối nhiều máy trong mạng nội bộ là vai trò của `switch`; phát sóng không dây là vai trò của điểm phát wifi; lưu trữ nội dung trang web thuộc về máy chủ, không phải modem."},{"id":"CC-mc-402","type":"mc","topic":"B","grade":12,"level":"easy","question":"Trong một phòng máy tính, nhiều máy tính bàn cần được nối dây vào cùng một mạng nội bộ, nhưng router chỉ có sẵn vài cổng dây, không đủ dùng. Nên bổ sung thiết bị nào để chia thêm cổng nối?","options":["`Modem`","Bộ chuyển mạch (`switch`)","Điểm phát wifi","Cáp quang"],"answer":1,"explain":"Bộ chuyển mạch (`switch`) dùng để nối nhiều máy tính trong cùng một mạng nội bộ, và thường được thêm vào khi số máy cần nối dây nhiều hơn số cổng có sẵn trên router. Modem lo việc kết nối ra Internet; điểm phát wifi phục vụ kết nối không dây; cáp quang là một loại đường truyền, không phải thiết bị chia cổng."},{"id":"CC-mc-403","type":"mc","topic":"B","grade":12,"level":"medium","question":"Một `router` (bộ định tuyến) và một `modem` cùng có mặt trong một mạng gia đình. Điểm khác biệt cốt lõi giữa hai thiết bị này là gì?","options":["Router chuyển đổi tín hiệu giữa nhà cung cấp dịch vụ Internet và mạng trong nhà; modem đọc địa chỉ đích để dẫn đường gói tin giữa các mạng","Router dẫn đường cho gói tin giữa các mạng khác nhau; modem chuyển đổi tín hiệu giữa đường truyền của nhà cung cấp dịch vụ và mạng trong nhà","Cả hai thiết bị làm cùng một việc hệt nhau, chỉ khác tên gọi tuỳ theo nhà sản xuất","Router chỉ dùng cho mạng không dây; modem chỉ dùng cho mạng có dây"],"answer":1,"explain":"`Router` đọc địa chỉ đích của mỗi gói tin để quyết định hướng chuyển tiếp giữa các mạng, chẳng hạn giữa mạng trong nhà và Internet; `modem` lo việc chuyển đổi tín hiệu giữa đường truyền của nhà cung cấp dịch vụ Internet và dữ liệu mà mạng trong nhà dùng được. Hai thiết bị đảm nhiệm hai việc khác nhau (dù nhiều sản phẩm hiện nay tích hợp chung một hộp), và không thiết bị nào giới hạn chỉ dùng cho có dây hoặc không dây."},{"id":"CC-mc-404","type":"mc","topic":"B","grade":12,"level":"medium","question":"Vì sao các nhà cung cấp dịch vụ Internet thường dùng cáp quang, thay vì cáp xoắn đôi bằng đồng, để kéo đường trục chính tới từng khu vực?","options":["Vì cáp quang rẻ hơn và dễ lắp đặt hơn cáp đồng trong mọi trường hợp","Vì cáp xoắn đôi bằng đồng không thể dùng để truyền tín hiệu Internet","Vì cáp quang truyền dữ liệu tốc độ cao và ít suy hao hơn khi đi qua khoảng cách xa","Vì cáp quang không cần bất kỳ thiết bị nào để đưa dữ liệu vào mạng trong nhà"],"answer":2,"explain":"Cáp quang truyền dữ liệu bằng ánh sáng, cho tốc độ cao và ít suy hao tín hiệu hơn nhiều so với cáp xoắn đôi bằng đồng khi đi qua khoảng cách xa, nên phù hợp làm đường trục chính. Cáp quang thường không rẻ hơn hay dễ lắp đặt hơn trong mọi trường hợp; cáp đồng vẫn truyền được Internet tốt ở khoảng cách ngắn; và bất kỳ đường truyền nào cũng cần thêm thiết bị (như modem, router) để đưa dữ liệu vào mạng trong nhà."},{"id":"CC-mc-405","type":"mc","topic":"B","grade":12,"level":"hard","question":"Một hộ gia đình dùng gói cước Internet có băng thông vừa đủ cho một người xem video chất lượng cao. Một buổi tối, ba người trong nhà cùng lúc xem video chất lượng cao trên ba thiết bị khác nhau, và cả ba video đều liên tục bị giật, phải chờ tải. Cách giải thích hợp lý nhất cho hiện tượng này là gì?","options":["Tổng lượng dữ liệu mà ba thiết bị cần truyền trong mỗi giây đã vượt quá băng thông mà đường truyền hiện có đáp ứng được","Router trong nhà chắc chắn đã hỏng, vì có từ hai thiết bị trở lên cùng kết nối wifi","Cáp quang không thể phục vụ được cho việc xem video chất lượng cao","Wifi chỉ cho phép duy nhất một thiết bị kết nối tại một thời điểm"],"answer":0,"explain":"Băng thông là lượng dữ liệu tối đa truyền được mỗi giây; khi nhiều thiết bị cùng truyền dữ liệu nặng như video chất lượng cao trong cùng một khoảng thời gian, tổng nhu cầu có thể vượt quá băng thông vốn chỉ vừa đủ cho một thiết bị, khiến tất cả cùng bị giật, chờ tải. Router không tự hỏng chỉ vì nhiều thiết bị kết nối, cáp quang trên thực tế đáp ứng tốt việc xem video chất lượng cao, và wifi vẫn cho nhiều thiết bị kết nối cùng lúc — nên các phương án còn lại không hợp lý."},{"id":"CC-tf-401","type":"tf","topic":"B","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"`Switch` được dùng để nối nhiều máy tính trong cùng một mạng nội bộ, không phải để dẫn đường gói tin ra Internet.","correct":true},{"text":"Cáp xoắn đôi bằng đồng truyền dữ liệu xa hơn và ít suy hao hơn cáp quang.","correct":false},{"text":"Mạng di động `4G`/`5G` chỉ phủ sóng trong phạm vi một ngôi nhà, giống hệt như wifi.","correct":false},{"text":"Băng thông càng lớn, lượng dữ liệu truyền được trong mỗi giây càng nhiều, nên các thao tác cần nhiều dữ liệu thường diễn ra nhanh hơn.","correct":true}],"explain":"(1) Đúng — `switch` chỉ nối các máy trong cùng một mạng nội bộ; việc dẫn đường gói tin ra các mạng khác, kể cả Internet, là vai trò của `router`. (2) Sai — cáp quang mới là loại truyền xa hơn và ít suy hao hơn cáp xoắn đôi bằng đồng, ngược lại hoàn toàn với phát biểu. (3) Sai — `wifi` chỉ phủ sóng trong phạm vi hẹp như một ngôi nhà hay văn phòng, còn mạng di động `4G`/`5G` phủ sóng phạm vi rộng hơn nhiều nhờ các cột phát sóng của nhà mạng viễn thông. (4) Đúng — băng thông lớn hơn nghĩa là truyền được nhiều dữ liệu hơn mỗi giây, nên các thao tác cần nhiều dữ liệu (tải tệp nặng, xem video chất lượng cao...) sẽ diễn ra nhanh hơn."},{"id":"CC-mc-501","type":"mc","topic":"B","grade":12,"level":"easy","question":"Thiết bị nào có vai trò nhận đường truyền Internet từ nhà cung cấp dịch vụ và phân phối mạng cho các thiết bị trong nhà, trong phòng?","options":["Máy in mạng","`Router` (thường tích hợp cùng modem)","`Switch`","Ổ cứng gắn ngoài"],"answer":1,"explain":"`Router` (nhiều khi tích hợp luôn chức năng modem) là thiết bị nhận đường truyền Internet rồi phân phối cho mạng nội bộ. `Switch` chỉ mở rộng thêm cổng dây trong nội bộ chứ không kết nối ra Internet; máy in mạng và ổ cứng ngoài chỉ là thiết bị sử dụng mạng, không phải thiết bị hạ tầng mạng."},{"id":"CC-mc-502","type":"mc","topic":"B","grade":12,"level":"easy","question":"Theo quy trình thiết kế mạng LAN đã học, bước đầu tiên cần thực hiện là gì?","options":["Đặt mật khẩu wifi","Vẽ sơ đồ kết nối","Xác định nhu cầu sử dụng (số thiết bị, mục đích, có cần wifi không)","Mua switch nhiều cổng nhất có thể"],"answer":2,"explain":"Bước đầu tiên luôn là xác định nhu cầu: biết rõ có bao nhiêu thiết bị, dùng để làm gì, có cần không dây hay không — vì các bước sau (chọn thiết bị, vẽ sơ đồ, cấu hình) đều dựa trên câu trả lời này. Mua thiết bị nhiều cổng nhất có thể mà chưa rõ nhu cầu là lãng phí, đi ngược tinh thần cân đối chi phí."},{"id":"CC-mc-503","type":"mc","topic":"B","grade":12,"level":"medium","question":"Một phòng có router chỉ có 4 cổng dây (LAN) sẵn có, nhưng cần nối dây cố định cho 10 máy tính bàn. Nên bổ sung thiết bị nào?","options":["Một `switch` có đủ số cổng cần thiết, nối vào router","Một `modem` thứ hai","Đổi toàn bộ 10 máy sang kết nối wifi","Không cần thêm gì, chia nhau dùng 4 cổng có sẵn"],"answer":0,"explain":"`Switch` dùng đúng để mở rộng số cổng nối dây khi router có sẵn không đủ; nối switch vào router giúp chia đường mạng cho nhiều máy hơn. Thêm modem thứ hai không giải quyết được vấn đề thiếu cổng; chuyển hết sang wifi hoặc chia nhau 4 cổng có sẵn đều không đáp ứng được yêu cầu nối dây cố định cho 10 máy."},{"id":"CC-mc-504","type":"mc","topic":"B","grade":12,"level":"medium","question":"Việc đặt tên mạng (`SSID`) và mật khẩu wifi đủ mạnh thuộc bước nào trong quy trình thiết kế mạng LAN?","options":["Xác định nhu cầu","Vẽ sơ đồ kết nối","Chọn thiết bị","Cấu hình cơ bản"],"answer":3,"explain":"Đặt `SSID` và mật khẩu wifi là một phần của bước cấu hình cơ bản — diễn ra sau khi đã xác định nhu cầu, chọn xong thiết bị và đấu nối phần cứng theo sơ đồ."},{"id":"CC-mc-505","type":"mc","topic":"B","grade":12,"level":"hard","question":"Một hộ gia đình có 2 máy tính bàn, 1 laptop và 3 điện thoại; nhu cầu chủ yếu là lướt web và học trực tuyến, không truyền file nặng. Theo tinh thần cân đối chi phí và nhu cầu, lựa chọn nào hợp lý nhất?","options":["Mua một switch chuyên dụng 24 cổng cho doanh nghiệp cỡ lớn","Mua 5 router riêng biệt, mỗi thiết bị dùng một router","Mua một `router` tích hợp modem và wifi, có đủ cổng LAN cho 2 máy bàn, phần còn lại nối wifi","Không cần router, nối trực tiếp dây mạng của nhà cung cấp vào từng máy"],"answer":2,"explain":"Với nhu cầu nhẹ (lướt web, học trực tuyến) và số thiết bị vừa phải, một `router` tích hợp modem và wifi là đủ dùng, tránh lãng phí vào thiết bị cỡ lớn không cần thiết như switch 24 cổng cho doanh nghiệp, hay các phương án không hợp lý như dùng 5 router riêng lẻ hoặc bỏ qua router hoàn toàn."},{"id":"CC-tf-501","type":"tf","topic":"B","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"`Switch` chỉ nên được thêm vào mạng khi số máy cần nối dây nhiều hơn số cổng LAN có sẵn trên router.","correct":true},{"text":"Sau khi lắp đặt xong phần cứng, không cần kiểm tra lại kết nối vì thiết bị mới mua chắc chắn hoạt động đúng.","correct":false},{"text":"Đổi mật khẩu quản trị mặc định của router là một việc nên làm để tăng cường an toàn cho mạng.","correct":true},{"text":"Khi thiết kế mạng LAN, luôn nên mua thiết bị đắt tiền và nhiều tính năng nhất có thể, bất kể nhu cầu thực tế.","correct":false}],"explain":"(1) Đúng — switch dùng để mở rộng số cổng dây khi router không đủ, không cần thêm nếu số máy đã vừa với router. (2) Sai — bước cuối luôn cần kiểm tra kết nối thực tế (vào được Internet chưa, sóng wifi có yếu chỗ nào không) để kịp điều chỉnh. (3) Đúng — mật khẩu quản trị mặc định thường in sẵn trên nhãn thiết bị, ai cũng tra được, nên cần đổi ngay. (4) Sai — bài học nhấn mạnh cân đối chi phí và nhu cầu thực tế, không phải cứ mua thiết bị đắt và nhiều tính năng nhất."},{"id":"CC-mc-601","type":"mc","topic":"D","grade":12,"level":"easy","question":"Hành vi nào sau đây thể hiện việc TÔN TRỌNG quyền riêng tư của người khác?","options":["Đăng ảnh chụp lén một người bạn trong khoảnh khắc kém may mắn lên mạng xã hội để mọi người cùng xem","Xin phép trước khi đăng một tấm ảnh có mặt người khác lên mạng xã hội","Chia sẻ số điện thoại của bạn cùng lớp vào một nhóm chat công khai mà không hỏi ý kiến","Lưu lại và phát tán ảnh chụp màn hình đoạn trò chuyện riêng tư của người khác"],"answer":1,"explain":"Xin phép trước khi đăng ảnh có người khác là biểu hiện cụ thể của việc tôn trọng quyền riêng tư — để người trong ảnh được quyền quyết định thông tin của mình có bị công khai hay không. Ba phương án còn lại đều là hành vi thu thập hoặc phát tán thông tin, hình ảnh của người khác mà không được đồng ý, vi phạm quyền riêng tư."},{"id":"CC-mc-602","type":"mc","topic":"D","grade":12,"level":"easy","question":"Việc tải một bức ảnh từ mạng về và sử dụng lại được xem là hợp lý về mặt bản quyền khi nào?","options":["Khi ảnh thuộc nguồn cho phép sử dụng lại (ví dụ gắn nhãn `Creative Commons`) hoặc đã ghi rõ nguồn/tác giả theo đúng điều khoản","Khi ảnh đó dễ dàng tìm thấy qua công cụ tìm kiếm","Khi ảnh đó được dùng cho mục đích học tập, không nhằm kiếm tiền","Khi không ai phát hiện ra mình đã lấy ảnh từ đâu"],"answer":0,"explain":"Việc sử dụng lại nội dung hợp lý về bản quyền phụ thuộc vào việc nội dung đó có được phép dùng lại hay không (theo giấy phép, điều khoản của nguồn), chứ không phụ thuộc vào việc dễ tìm thấy, mục đích phi lợi nhuận, hay việc không bị phát hiện. Ngay cả mục đích học tập cũng có thể vi phạm bản quyền nếu nguồn không cho phép sử dụng lại."},{"id":"CC-mc-603","type":"mc","topic":"D","grade":12,"level":"medium","question":"Hành vi nào sau đây được xem là VI PHẠM pháp luật về an ninh mạng?","options":["Cập nhật phần mềm diệt virus định kỳ trên máy tính cá nhân","Đặt mật khẩu mạnh, khác nhau cho từng tài khoản trực tuyến","Báo cáo (report) một tài khoản đang phát tán tin giả cho nền tảng mạng xã hội","Giả danh nhân viên ngân hàng, nhắn tin yêu cầu người khác cung cấp mã `OTP`"],"answer":3,"explain":"Giả danh tổ chức, cá nhân khác để lừa lấy thông tin (như mã `OTP`) là hành vi lừa đảo chiếm đoạt thông tin/tài sản, bị pháp luật về an ninh mạng nghiêm cấm. Ba phương án còn lại đều là hành vi tích cực, giúp bảo vệ an toàn thông tin, không phải hành vi vi phạm."},{"id":"CC-mc-604","type":"mc","topic":"D","grade":12,"level":"medium","question":"Một người dùng công cụ AI để tạo ra một đoạn video có khuôn mặt và giọng nói giống hệt một người nổi tiếng đang phát biểu những điều người đó chưa từng nói, rồi đăng lên mạng xã hội ‘cho vui’. Hành vi này nên được đánh giá như thế nào?","options":["Hoàn toàn bình thường, vì chỉ là sản phẩm do AI tạo ra, không phải người dùng tự làm","Không đáng lo ngại vì video sẽ tự biến mất sau một thời gian trên mạng xã hội","Vi phạm cả đạo đức lẫn có thể vi phạm pháp luật, vì đây là một dạng `deepfake` gây ảnh hưởng đến danh dự người thật, dù mục đích ban đầu chỉ là ‘cho vui’","Chấp nhận được, miễn là không thu tiền từ video đó"],"answer":2,"explain":"Tạo và phát tán deepfake giả mạo hình ảnh, giọng nói của người có thật để nói những điều họ chưa từng nói là hành vi ảnh hưởng trực tiếp đến danh dự, uy tín của nạn nhân — vi phạm văn hoá ứng xử số và có thể vi phạm pháp luật, bất kể mục đích là đùa vui hay không thu lợi. Việc do AI tạo ra không miễn trừ trách nhiệm cho người tạo và người phát tán."},{"id":"CC-mc-605","type":"mc","topic":"D","grade":12,"level":"hard","question":"Một người tình cờ có được bộ ảnh riêng tư của người khác (do rò rỉ từ một vụ tấn công mạng trước đó), rồi đăng tải lại toàn bộ lên một hội nhóm công khai kèm lời bình luận chê bai ngoại hình người trong ảnh. Hành vi này vi phạm những khía cạnh nào đã học trong bài?","options":["Chỉ vi phạm quyền riêng tư, không liên quan gì đến pháp luật hay văn hoá ứng xử","Chỉ vi phạm văn hoá ứng xử vì lời bình luận thiếu tôn trọng; việc đăng lại ảnh thì không sao vì ảnh vốn đã bị rò rỉ sẵn trên mạng","Không vi phạm gì, vì người đăng không phải là người trực tiếp thực hiện vụ tấn công mạng ban đầu","Vi phạm đồng thời quyền riêng tư (phát tán ảnh khi chưa được đồng ý), pháp luật (sử dụng dữ liệu rò rỉ trái phép, xúc phạm danh dự người khác), và văn hoá ứng xử (bình luận thiếu tôn trọng)"],"answer":3,"explain":"Tình huống này chồng lấn nhiều vi phạm: phát tán ảnh riêng tư khi chưa được đồng ý là xâm phạm quyền riêng tư; sử dụng dữ liệu rò rỉ trái phép kèm lời xúc phạm là vi phạm pháp luật về an ninh mạng; bình luận chê bai thiếu tôn trọng là vi phạm văn hoá ứng xử. Việc ảnh ‘đã có sẵn trên mạng’ hay việc không trực tiếp thực hiện vụ tấn công mạng ban đầu không hề miễn trừ trách nhiệm cho người phát tán lại và bình luận xúc phạm."},{"id":"CC-tf-601","type":"tf","topic":"D","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Một nội dung (ảnh, nhạc, phần mềm) dễ dàng tải xuống từ mạng không có nghĩa là đương nhiên được phép sử dụng tự do.","correct":true},{"text":"Vì mạng xã hội không cho thấy mặt người dùng thật, nên hành vi xúc phạm hay lừa đảo trên đó không bị coi là vi phạm pháp luật.","correct":false},{"text":"Việc tạo và lan truyền `deepfake` giả mạo hình ảnh người khác vẫn có thể gây thiệt hại thật cho nạn nhân, dù nội dung do AI tạo ra.","correct":true},{"text":"Chỉ cần không thu tiền, mọi hành vi chia sẻ lại nội dung có bản quyền của người khác đều được xem là hợp pháp.","correct":false}],"explain":"(1) Đúng — nội dung dễ sao chép về mặt kỹ thuật không đồng nghĩa được phép dùng tự do về mặt pháp lý, vẫn cần tuân theo bản quyền. (2) Sai — hành vi trên mạng vẫn để lại dấu vết và vẫn phải chịu trách nhiệm trước pháp luật như ngoài đời thực, không có ‘vùng an toàn’ vì ẩn danh. (3) Đúng — nạn nhân của deepfake là người thật, thiệt hại về danh dự và tâm lý mà họ gánh chịu cũng là thật, bất kể nội dung do AI tạo ra. (4) Sai — việc không thu tiền không miễn trừ trách nhiệm vi phạm bản quyền; yếu tố quyết định là nội dung đó có được phép chia sẻ lại hay không, theo đúng giấy phép/điều khoản của nguồn."},{"id":"CC-mc-701","type":"mc","topic":"E","grade":12,"level":"easy","question":"Trang web là gì?","options":["Một loại virus máy tính lây lan qua email","Một tài liệu được trình duyệt đọc và hiển thị ra màn hình cho người xem","Một ngôn ngữ lập trình dùng để tính toán","Một thiết bị phần cứng dùng để kết nối Internet"],"answer":1,"explain":"Trang web (`web page`) là một tài liệu được trình duyệt đọc và hiển thị lên màn hình cho người dùng xem — có thể gồm chữ, hình ảnh, đường liên kết... Ba phương án còn lại mô tả sai bản chất: đây không phải virus, không phải ngôn ngữ lập trình, cũng không phải một thiết bị phần cứng."},{"id":"CC-mc-702","type":"mc","topic":"E","grade":12,"level":"easy","question":"`HTML` là viết tắt của cụm từ nào, và bản chất của nó là gì?","options":["`HyperText Markup Language` — một ngôn ngữ đánh dấu, dùng thẻ để tạo cấu trúc cho nội dung","`High Technology Modern Language` — một ngôn ngữ lập trình hiện đại, có đầy đủ vòng lặp và điều kiện","`Home Tool Media Layout` — một phần mềm dùng để thiết kế giao diện","`Hyper Transfer Machine Logic` — một giao thức dùng để truyền dữ liệu qua mạng"],"answer":0,"explain":"`HTML` là viết tắt của `HyperText Markup Language` — một ngôn ngữ đánh dấu (không phải ngôn ngữ lập trình), dùng các thẻ để gắn nhãn, tạo cấu trúc cho nội dung trang web (đâu là tiêu đề, đâu là đoạn văn...). Ba phương án còn lại là tên gọi bịa ra, không đúng với `HTML`."},{"id":"CC-mc-703","type":"mc","topic":"E","grade":12,"level":"medium","question":"Trong bốn phần dưới đây của một trang HTML, phần nào chứa nội dung được hiển thị trực tiếp lên trang cho người xem?","options":["`<head>`","`<title>`","`<body>`","`<!DOCTYPE html>`"],"answer":2,"explain":"`<body>` là phần chứa nội dung thực sự hiển thị lên trang: tiêu đề, đoạn văn, hình ảnh... `<head>` chỉ chứa thông tin không hiển thị trực tiếp giữa trang; `<title>` tuy nằm trong `<head>` và có hiển thị, nhưng chỉ hiện trên tab của trình duyệt chứ không hiện giữa nội dung trang; `<!DOCTYPE html>` chỉ là lời khai báo chuẩn cho trình duyệt, không phải nội dung của trang."},{"id":"CC-mc-704","type":"mc","topic":"E","grade":12,"level":"medium","question":"Nhận định nào đúng nhất khi so sánh `HTML` với một ngôn ngữ lập trình thật sự như `Python`?","options":["`HTML` có đầy đủ phép tính, điều kiện rẽ nhánh và vòng lặp giống hệt `Python`","`HTML` dùng để mô tả cấu trúc nội dung bằng các thẻ, không dùng để tính toán hay xử lí logic như một ngôn ngữ lập trình","`HTML` và `Python` chỉ là hai tên gọi khác nhau của cùng một ngôn ngữ","Trang viết bằng `HTML` chỉ hiển thị được khi máy tính đang kết nối Internet, còn `Python` thì không cần"],"answer":1,"explain":"`HTML` là ngôn ngữ đánh dấu — chỉ mô tả “đây là tiêu đề”, “đây là đoạn văn”... chứ không có phép tính, điều kiện hay vòng lặp như một ngôn ngữ lập trình thật sự; vì vậy không thể coi `HTML` là ngôn ngữ lập trình, và nó cũng không phải cùng một thứ với `Python`. Việc xem được một trang `HTML` cũng không phụ thuộc có Internet hay không — mở tệp `.html` ngay trên máy vẫn xem bình thường."},{"id":"CC-mc-705","type":"mc","topic":"E","grade":12,"level":"hard","question":"Xét đoạn mã sau: `<html><head><title>Trang của tôi</title><body><h1>Chào mừng</h1></head></body></html>`. Đoạn mã này có vấn đề gì về cách lồng thẻ?","options":["Thiếu `<!DOCTYPE html>` nên trình duyệt chắc chắn từ chối hiển thị trang","Thẻ `<body>` được mở ra trước khi `<head>` kịp đóng lại — các cặp thẻ lồng vào nhau sai thứ tự","Thẻ `<h1>` không được phép đặt bên trong `<body>`","Đoạn mã hoàn toàn không có lỗi gì về cấu trúc"],"answer":1,"explain":"Trong đoạn mã, `<body>` được mở ra khi `<head>` chưa đóng (`</head>` chỉ xuất hiện sau `<h1>Chào mừng</h1>`) — các cặp thẻ lồng vào nhau sai thứ tự, giống như mở ngoặc `(` rồi mở tiếp `[` nhưng lại đóng `)` trước `]`. Thiếu `<!DOCTYPE html>` chỉ là thiếu lời khai báo chuẩn, trình duyệt vẫn cố hiển thị trang chứ không “chắc chắn từ chối”; và `<h1>` hoàn toàn được phép đặt trong `<body>` — vấn đề ở đây là thứ tự đóng/mở, không phải vị trí của `<h1>`."},{"id":"CC-tf-701","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"`HTML` là một ngôn ngữ lập trình có đầy đủ phép tính và vòng lặp giống như `Python`.","correct":false},{"text":"Thẻ `<title>` đặt trong `<head>` sẽ hiển thị trên tab của trình duyệt, chứ không hiển thị giữa nội dung trang.","correct":true},{"text":"Một `website` có thể gồm nhiều trang web liên kết với nhau.","correct":true},{"text":"Mọi thẻ HTML đều bắt buộc phải có thẻ đóng riêng, không có ngoại lệ nào.","correct":false}],"explain":"(1) Sai — `HTML` là ngôn ngữ đánh dấu, dùng thẻ để tạo cấu trúc cho nội dung, không có phép tính hay vòng lặp như một ngôn ngữ lập trình. (2) Đúng — nội dung trong `<title>` (nằm trong `<head>`) chỉ hiện trên tab trình duyệt, không hiện giữa nội dung trang. (3) Đúng — nhiều trang liên kết với nhau qua các đường dẫn tạo thành một `website`. (4) Sai — một số thẻ như `<br>` hay `<img>` không bao nội dung nên tự đóng, không cần thẻ đóng riêng."},{"id":"CC-mc-801","type":"mc","topic":"E","grade":12,"level":"easy","question":"Trong sáu mức tiêu đề của HTML, thẻ nào tạo ra tiêu đề lớn và quan trọng nhất trên trang?","options":["`<h6>`","`<h1>`","`<h4>`","Không có thẻ nào lớn hơn thẻ nào"],"answer":1,"explain":"Số đứng sau chữ h càng nhỏ thì tiêu đề càng lớn và càng quan trọng, nên `<h1>` là mức tiêu đề lớn nhất, thường dùng cho tên chính của trang; `<h6>` mới là mức nhỏ nhất."},{"id":"CC-mc-802","type":"mc","topic":"E","grade":12,"level":"easy","question":"Thẻ nào dùng để tạo một đoạn văn bản thông thường trong trang HTML?","options":["`<p>`","`<a>`","`<li>`","`<ol>`"],"answer":0,"explain":"`<p>` (paragraph) dùng để bao quanh một đoạn văn; trình duyệt tự tạo khoảng cách giữa các đoạn `<p>` với nhau. `<a>` tạo liên kết, `<li>` là một mục trong danh sách, `<ol>` là danh sách có thứ tự."},{"id":"CC-mc-803","type":"mc","topic":"E","grade":12,"level":"medium","question":"Trong danh sách được viết bằng cặp thẻ `<ol>...</ol>`, các mục con sẽ hiển thị như thế nào?","options":["Chỉ mục đầu tiên trong danh sách được hiển thị","Mỗi mục có một dấu chấm tròn phía trước, không phân biệt thứ tự","Các mục không hiển thị gì cho tới khi được bấm vào","Mỗi mục được trình duyệt tự động đánh số thứ tự 1, 2, 3..."],"answer":3,"explain":"`<ol>` là danh sách có thứ tự (ordered list) nên trình duyệt tự động đánh số cho từng thẻ `<li>` bên trong; kiểu hiển thị dấu chấm tròn là của `<ul>`, không phải `<ol>`."},{"id":"CC-mc-804","type":"mc","topic":"E","grade":12,"level":"medium","question":"Đoạn mã `<a href=\"trangsau.html\">Xem tiếp</a>` có nghĩa gì?","options":["Cả ‘Xem tiếp’ và ‘trangsau.html’ đều hiển thị cùng lúc trên trang","Dòng chữ ‘trangsau.html’ hiển thị trên trang, còn ‘Xem tiếp’ là địa chỉ đích","Dòng chữ ‘Xem tiếp’ hiển thị và có thể bấm để mở trang ‘trangsau.html’","Đoạn mã bị lỗi vì thẻ `<a>` không được phép chứa chữ"],"answer":2,"explain":"Thuộc tính `href` ghi địa chỉ trang đích (‘trangsau.html’), còn phần nội dung nằm giữa thẻ mở và thẻ đóng (‘Xem tiếp’) mới là dòng chữ người đọc nhìn thấy và bấm vào; đây là cách viết liên kết hợp lệ."},{"id":"CC-mc-805","type":"mc","topic":"E","grade":12,"level":"hard","question":"Đoạn HTML nào sau đây lồng thẻ đúng quy tắc (thẻ mở sau phải đóng trước)?","options":["`<p><strong>Hạn nộp</strong> là thứ Sáu.</p>`","`<p><strong>Hạn nộp</p></strong> là thứ Sáu.`","`<strong><p>Hạn nộp là thứ Sáu.</strong></p>`","`<p><strong>Hạn nộp là thứ Sáu.</p>`"],"answer":0,"explain":"Phương án 1 đóng thẻ theo đúng thứ tự ngược với lúc mở: mở `<p>` rồi `<strong>`, đóng `</strong>` trước rồi mới đóng `</p>`. Phương án 2 đóng `</p>` khi `<strong>` chưa đóng, gây chồng chéo. Phương án 3 mở `<strong>` trước `<p>` nhưng lại đóng `</strong>` sau khi đã đóng `</p>`, cũng chồng chéo. Phương án 4 mở `<strong>` nhưng thiếu hẳn thẻ đóng `</strong>` tương ứng."},{"id":"CC-tf-801","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Thẻ `<h1>` tạo ra tiêu đề nhỏ hơn thẻ `<h6>`.","correct":false},{"text":"Mỗi mục trong danh sách `<ul>` hoặc `<ol>` đều phải được đặt trong một thẻ `<li>`.","correct":true},{"text":"Trong thẻ `<a href=\"dia-chi.html\">Trang sau</a>`, phần chữ hiển thị cho người đọc bấm vào là ‘Trang sau’.","correct":true},{"text":"Có thể đặt thẻ `<li>` một mình, không cần nằm trong `<ul>` hay `<ol>`, trình duyệt vẫn hiểu đó là một mục danh sách.","correct":false}],"explain":"(1) Sai – số càng nhỏ thì tiêu đề càng lớn, nên `<h1>` là tiêu đề lớn nhất, lớn hơn `<h6>` chứ không nhỏ hơn. (2) Đúng – dù danh sách không thứ tự hay có thứ tự, mỗi mục con đều nằm trong một thẻ `<li>`. (3) Đúng – phần nội dung giữa thẻ mở và thẻ đóng của `<a>` chính là chữ hiển thị cho người đọc bấm; `href` chỉ là địa chỉ đích, không hiển thị ra. (4) Sai – `<li>` chỉ có ý nghĩa danh sách khi lồng bên trong `<ul>` hoặc `<ol>`; đặt một mình, trình duyệt không hiểu đó là một mục danh sách."},{"id":"CC-mc-901","type":"mc","topic":"E","grade":12,"level":"easy","question":"Thẻ `<img>` khác với thẻ `<p>` ở điểm nào?","options":["`<img>` là thẻ tự đóng, không có thẻ đóng riêng đi kèm, còn `<p>` cần cặp `<p>...</p>`","`<img>` chỉ được phép đặt trong `<head>`, còn `<p>` chỉ được phép đặt trong `<body>`","`<img>` không thể có thuộc tính, còn `<p>` bắt buộc phải có thuộc tính","`<img>` chỉ dùng để hiển thị chữ, còn `<p>` chỉ dùng để hiển thị ảnh"],"answer":0,"explain":"`<img>` là thẻ tự đóng — không bao nội dung ở giữa và không cần thẻ đóng riêng, khác với `<p>` vốn phải có cặp mở-đóng bao quanh đoạn văn. Cả hai đều đặt trong `<body>` và đều có thể mang thuộc tính (`<img>` có `src`, `alt`...); `<img>` dùng để hiển thị ảnh chứ không phải chữ."},{"id":"CC-mc-902","type":"mc","topic":"E","grade":12,"level":"easy","question":"Thuộc tính `alt` trong thẻ `<img>` dùng để làm gì?","options":["Thu nhỏ kích thước ảnh hiển thị trên trang","Cho biết đường dẫn tới tệp ảnh cần hiển thị","Cung cấp chữ mô tả thay thế, hiện ra khi ảnh không tải được và được phần mềm đọc màn hình đọc lên","Đổi màu nền phía sau tấm ảnh"],"answer":2,"explain":"`alt` là chữ mô tả thay thế: hiện ra khi ảnh lỗi hoặc không tải được, đồng thời được phần mềm đọc màn hình đọc to cho người khiếm thị. Thu nhỏ ảnh là vai trò của `width`; chỉ đường dẫn ảnh là vai trò của `src`; đổi màu nền không phải chức năng của thuộc tính nào được học ở bài này."},{"id":"CC-mc-903","type":"mc","topic":"E","grade":12,"level":"medium","question":"Trong một bảng HTML, thẻ nào tạo ra một HÀNG mới của bảng?","options":["`<table>`","`<tr>`","`<th>`","`<td>`"],"answer":1,"explain":"`<tr>` tạo ra một hàng mới; mỗi cặp `<tr>...</tr>` viết thêm là thêm một hàng. `<table>` là khung bao cả bảng chứ không phải một hàng riêng lẻ; `<th>` và `<td>` tạo ra từng ô bên trong một hàng, không phải cả hàng."},{"id":"CC-mc-904","type":"mc","topic":"E","grade":12,"level":"medium","question":"Sự khác nhau chính giữa `<th>` và `<td>` trong một bảng là gì?","options":["`<th>` dùng cho ô tiêu đề (mặc định chữ đậm, căn giữa), `<td>` dùng cho ô dữ liệu bình thường","`<th>` chỉ được phép dùng ở cột đầu tiên, `<td>` chỉ được phép dùng ở cột cuối cùng","`<th>` bắt buộc chứa số, `<td>` bắt buộc chứa chữ","`<th>` và `<td>` hoàn toàn giống nhau về mọi mặt, dùng thẻ nào cũng được"],"answer":0,"explain":"`<th>` dành cho ô tiêu đề, mặc định hiển thị chữ đậm và căn giữa; `<td>` dành cho ô chứa dữ liệu bình thường. Cả hai đều có thể đặt ở bất kỳ vị trí nào trong hàng, không giới hạn cột đầu hay cột cuối, cũng không giới hạn kiểu dữ liệu chứa bên trong là số hay chữ."},{"id":"CC-mc-905","type":"mc","topic":"E","grade":12,"level":"hard","question":"Một bảng có 3 cặp `<tr>`: hàng đầu tiên chứa 3 cặp `<th>`, còn hai hàng còn lại mỗi hàng chỉ chứa 2 cặp `<td>`. Điều gì có khả năng xảy ra khi xem trang này?","options":["Bảng hiển thị hoàn toàn bình thường vì số ô mỗi hàng không ảnh hưởng đến cách hiển thị","Trình duyệt báo lỗi và không hiển thị được toàn bộ trang","Các ô dữ liệu ở hai hàng sau có thể bị lệch so với 3 cột tiêu đề, vì số ô giữa các hàng không khớp nhau","`<th>` và `<td>` xung đột nhau nên không thể cùng xuất hiện trong một bảng"],"answer":2,"explain":"Số ô trong mỗi `<tr>` nên bằng nhau để các cột thẳng hàng; ở đây hàng tiêu đề có 3 ô nhưng hai hàng dữ liệu chỉ có 2 ô, nên nội dung dễ bị lệch cột so với tiêu đề tương ứng. Trình duyệt vẫn cố hiển thị chứ không báo lỗi dừng cả trang; và `<th>` với `<td>` hoàn toàn được phép cùng xuất hiện trong một bảng — đây thực ra là cách dùng bình thường (hàng tiêu đề dùng `<th>`, hàng dữ liệu dùng `<td>`), chỉ là số ô mỗi hàng cần khớp nhau."},{"id":"CC-tf-901","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Thẻ `<img>` là thẻ tự đóng, không cần thẻ đóng `</img>` đi kèm.","correct":true},{"text":"Thuộc tính `src` của thẻ `<img>` dùng để mô tả nội dung ảnh cho người khiếm thị.","correct":false},{"text":"Trong một bảng, mỗi cặp `<tr>` tương ứng với một hàng, còn mỗi `<th>`/`<td>` bên trong hàng đó tương ứng với một ô.","correct":true},{"text":"Nên dùng `<table>` để chia cột trái phải, đặt menu và dàn toàn bộ bố cục cho trang web.","correct":false}],"explain":"(1) Đúng — `<img>` là thẻ tự đóng, không có thẻ đóng riêng. (2) Sai — mô tả nội dung ảnh cho người khiếm thị là vai trò của `alt`; `src` chỉ dùng để chỉ đường dẫn tới tệp ảnh. (3) Đúng — đây đúng là cách một bảng được dựng: `<tr>` là hàng, `<th>`/`<td>` là ô bên trong hàng. (4) Sai — dùng `<table>` để dàn bố cục trang là cách lạm dụng không nên làm; bảng nên dành để trình bày dữ liệu thật sự có hàng có cột, còn việc dàn trang nên để cho công cụ khác đảm nhiệm."},{"id":"CC-mc-1001","type":"mc","topic":"E","grade":12,"level":"easy","question":"Trong một trang web, CSS chủ yếu đảm nhiệm việc gì?","options":["Tạo cấu trúc và nội dung của trang, ví dụ đâu là tiêu đề, đâu là đoạn văn","Quy định cách trang được trình bày: màu sắc, phông chữ, kích thước, bố cục","Xử lí dữ liệu do người dùng nhập vào ô tìm kiếm","Lưu trữ dữ liệu của trang trên máy chủ"],"answer":1,"explain":"CSS (Cascading Style Sheets) lo phần trình bày của trang. Việc tạo cấu trúc và nội dung là vai trò của HTML, còn xử lí dữ liệu nhập hay lưu trữ trên máy chủ là công việc của các công nghệ khác, không phải CSS."},{"id":"CC-mc-1002","type":"mc","topic":"E","grade":12,"level":"easy","question":"Một quy tắc CSS có cấu trúc chung như thế nào?","options":["`bộ-chọn { thuộc-tính: giá-trị; }`","`thuộc-tính { bộ-chọn: giá-trị; }`","`<bộ-chọn thuộc-tính='giá-trị'>`","`giá-trị: thuộc-tính { bộ-chọn }`"],"answer":0,"explain":"Một quy tắc CSS gồm bộ chọn đứng trước, theo sau là cặp dấu ngoặc nhọn chứa một hay nhiều khai báo dạng thuộc-tính: giá-trị;, kết thúc bằng dấu chấm phẩy."},{"id":"CC-mc-1003","type":"mc","topic":"E","grade":12,"level":"medium","question":"Để áp dụng một quy tắc CSS cho mọi thẻ `<p>` có trên trang, bộ chọn phù hợp là gì?","options":["`.p { ... }`","`#p { ... }`","`p { ... }`","`*p { ... }`"],"answer":2,"explain":"Bộ chọn theo tên thẻ chỉ cần viết đúng tên thẻ, không kèm dấu chấm hay dấu thăng — `p` sẽ chọn tất cả thẻ `<p>`. Dấu chấm dùng cho bộ chọn theo lớp, dấu thăng dùng cho bộ chọn theo id."},{"id":"CC-mc-1004","type":"mc","topic":"E","grade":12,"level":"medium","question":"Một trang có nhiều đoạn văn `<p>`, trong đó chỉ vài đoạn mang `class='ghi-chu'`. Muốn riêng những đoạn đó có màu chữ xám mà không ảnh hưởng các đoạn `<p>` khác, nên viết quy tắc nào?","options":["`p { color: gray; }`","`.ghi-chu { color: gray; }`","`#ghi-chu { color: gray; }`","`ghi-chu { color: gray; }`"],"answer":1,"explain":"Bộ chọn theo lớp bắt đầu bằng dấu chấm và khớp với thuộc tính class của thẻ, nên chỉ áp dụng cho đúng những thẻ mang lớp đó — phù hợp khi cần định dạng riêng một nhóm thẻ chứ không phải toàn bộ thẻ `<p>`."},{"id":"CC-mc-1005","type":"mc","topic":"E","grade":12,"level":"hard","question":"Một thẻ vừa khớp quy tắc `p { font-size: 16px; }` (theo tên thẻ), vừa khớp quy tắc `#ket-luan { font-size: 22px; }` (theo id, vì thẻ mang `id='ket-luan'`). Thẻ này sẽ hiển thị với cỡ chữ bao nhiêu?","options":["16px, vì quy tắc theo tên thẻ luôn được ưu tiên","22px, vì bộ chọn theo id được ưu tiên hơn bộ chọn theo tên thẻ","Không hiển thị được vì hai quy tắc mâu thuẫn nhau","Trình duyệt bỏ qua cả hai quy tắc, chữ không có cỡ"],"answer":1,"explain":"Khi hai quy tắc cùng quy định một thuộc tính cho cùng một thẻ, quy tắc theo id được ưu tiên hơn quy tắc theo tên thẻ, nên cỡ chữ hiển thị là 22px."},{"id":"CC-tf-1001","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Bộ chọn `p` áp dụng cho mọi thẻ `<p>` có trên trang.","correct":true},{"text":"Bộ chọn `.thongbao` khớp với thẻ có thuộc tính `id='thongbao'`.","correct":false},{"text":"Có thể gắn CSS trực tiếp vào một thẻ bằng thuộc tính `style` của chính thẻ đó.","correct":true},{"text":"Nếu chỉ muốn định dạng riêng cho đúng một thẻ duy nhất trên trang, cách phù hợp nhất là dùng bộ chọn theo lớp (class).","correct":false}],"explain":"(1) Đúng — bộ chọn theo tên thẻ áp dụng cho mọi thẻ cùng loại. (2) Sai — bộ chọn bắt đầu bằng dấu chấm khớp với thuộc tính class, còn khớp id phải dùng dấu thăng, tức `#thongbao`. (3) Đúng — đây chính là cách gắn CSS trực tiếp qua thuộc tính style. (4) Sai — lớp (class) phù hợp khi cần dùng lại cho nhiều thẻ; khi chỉ cần định dạng riêng đúng một thẻ duy nhất, cách phù hợp hơn là dùng bộ chọn theo id."},{"id":"CC-mc-1101","type":"mc","topic":"E","grade":12,"level":"easy","question":"Thuộc tính CSS nào dùng để đổi màu của chữ trong một phần tử?","options":["`background-color`","`text-color`","`color`","`font-color`"],"answer":2,"explain":"`color` là thuộc tính quy định màu chữ. `background-color` quy định màu nền chứ không phải màu chữ, còn `text-color` và `font-color` không phải là thuộc tính CSS hợp lệ."},{"id":"CC-mc-1102","type":"mc","topic":"E","grade":12,"level":"easy","question":"Mã màu `#ffffff` biểu diễn màu gì?","options":["Đen","Trắng","Đỏ thuần","Xanh dương thuần"],"answer":1,"explain":"Mã `#RRGGBB` gồm ba cặp số hex cho đỏ, xanh lá, xanh dương, mỗi cặp chạy từ `00` đến `ff`. `#ffffff` có cả ba cặp ở mức cao nhất (`ff`), tức trộn đủ ba màu ở cường độ tối đa, cho ra màu trắng."},{"id":"CC-mc-1103","type":"mc","topic":"E","grade":12,"level":"medium","question":"Trong mô hình hộp CSS, thuộc tính nào tạo ra khoảng trống nằm giữa nội dung và viền của hộp?","options":["`margin`","`border`","`padding`","`text-align`"],"answer":2,"explain":"`padding` là đệm trong, nằm giữa nội dung và viền (`border`). `margin` là lề ngoài, nằm bên ngoài viền; `text-align` chỉ canh chữ chứ không tạo khoảng đệm."},{"id":"CC-mc-1104","type":"mc","topic":"E","grade":12,"level":"medium","question":"Một đoạn văn bản cần được canh vào giữa theo chiều ngang trong phần tử chứa nó. Thuộc tính và giá trị nào phù hợp?","options":["`font-weight: center;`","`padding: center;`","`text-align: center;`","`color: center;`"],"answer":2,"explain":"`text-align` quy định cách canh chữ theo chiều ngang, với giá trị `center` là canh giữa. `font-weight` chỉnh độ đậm, `padding` cần giá trị khoảng cách chứ không phải `center`, còn `color` chỉnh màu chữ — không phương án nào trong ba cái đó dùng để canh chữ."},{"id":"CC-mc-1105","type":"mc","topic":"E","grade":12,"level":"hard","question":"Một phần tử được đặt `padding: 10px;`, `border: 2px solid;` và `margin: 15px;`. Thứ tự nào sau đây liệt kê đúng các lớp của hộp này, tính từ nội dung ra ngoài cùng?","options":["Nội dung → `margin` → `border` → `padding`","Nội dung → `border` → `padding` → `margin`","Nội dung → `padding` → `border` → `margin`","`margin` → `border` → `padding` → Nội dung"],"answer":2,"explain":"Mô hình hộp luôn lồng theo thứ tự cố định tính từ trong ra ngoài: nội dung, rồi đến `padding` (đệm trong), rồi đến `border` (viền), và ngoài cùng là `margin` (lề ngoài). Ba phương án còn lại đều đảo sai thứ tự này."},{"id":"CC-tf-1101","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"`background-color` là thuộc tính CSS dùng để đổi màu nền của một phần tử.","correct":true},{"text":"Mã màu dạng `#RRGGBB` chỉ có thể biểu diễn được đúng 16 màu khác nhau.","correct":false},{"text":"Trong mô hình hộp, `padding` nằm giữa nội dung và viền (`border`) của phần tử.","correct":true},{"text":"Trong mô hình hộp, `margin` nằm bên trong viền (`border`), sát ngay với nội dung.","correct":false}],"explain":"(1) Đúng — `background-color` chính là thuộc tính quy định màu nền của phần tử. (2) Sai — mỗi cặp hex trong `RRGGBB` có 256 giá trị (từ `00` đến `ff`), nên mã màu này biểu diễn được 256 × 256 × 256 ≈ 16,7 triệu màu, không phải chỉ 16 màu. (3) Đúng — `padding` là đệm trong, đúng vị trí nằm giữa nội dung và viền. (4) Sai — `margin` là lề ngoài, nằm bên ngoài viền chứ không sát nội dung; lớp nằm sát nội dung nhất (ngay sau nội dung) chính là `padding`."},{"id":"CC-mc-1201","type":"mc","topic":"E","grade":12,"level":"easy","question":"Trong các thẻ HTML sau, thẻ nào mặc định là phần tử nội tuyến (inline)?","options":["`<div>`","`<p>`","`<span>`","`<h1>`"],"answer":2,"explain":"`<span>` mặc định là phần tử nội tuyến, chỉ chiếm đúng phần nội dung bên trong nó. `<div>`, `<p>` và `<h1>` đều mặc định là phần tử khối, luôn chiếm trọn cả dòng."},{"id":"CC-mc-1202","type":"mc","topic":"E","grade":12,"level":"easy","question":"Đặc điểm nào sau đây đúng với một phần tử khối (block)?","options":["Luôn chiếm trọn cả chiều ngang có thể có và đẩy phần tử phía sau xuống dòng mới","Chỉ chiếm đúng phần nội dung bên trong nó, không tự xuống dòng","Luôn ẩn khỏi trang cho đến khi được nhấp vào","Không thể chứa bất kỳ phần tử nào khác bên trong"],"answer":0,"explain":"Phần tử khối luôn chiếm trọn chiều ngang đang có và đẩy phần tử đứng sau xuống dòng mới, bất kể nội dung bên trong dài hay ngắn. Phương án thứ hai mô tả phần tử nội tuyến; hai phương án còn lại không đúng với phần tử khối."},{"id":"CC-mc-1203","type":"mc","topic":"E","grade":12,"level":"medium","question":"Khi phần tử cha được gán `display: flex`, phát biểu nào sau đây là đúng?","options":["Chỉ phần tử con đầu tiên bị ảnh hưởng, các con còn lại giữ nguyên vị trí cũ","Mọi phần tử con trực tiếp bên trong tự động xếp thành một hàng ngang, cạnh nhau","Phần tử cha sẽ bị ẩn khỏi trang cho đến khi được nhấp vào","Từng phần tử con phải tự khai báo thêm `display: block` thì mới hiển thị được"],"answer":1,"explain":"`display: flex` khai báo trên phần tử cha khiến mọi phần tử con trực tiếp bên trong tự động xếp thành một hàng ngang, cạnh nhau, mà không cần khai báo gì thêm cho từng con. Ba phương án còn lại đều mô tả sai tác dụng của `display: flex`."},{"id":"CC-mc-1204","type":"mc","topic":"E","grade":12,"level":"medium","question":"Thuộc tính nào dùng để tạo khoảng cách đều nhau giữa các khối con trong một khối cha `display: flex`?","options":["`justify-content`","`display`","`gap`","`border`"],"answer":2,"explain":"`gap` tạo khoảng cách đều giữa các phần tử con trong khối cha flex. `justify-content` dùng để căn vị trí cả hàng khối (đầu, giữa, cuối,…), còn `display` và `border` không có chức năng tạo khoảng cách giữa các phần tử con."},{"id":"CC-mc-1205","type":"mc","topic":"E","grade":12,"level":"hard","question":"Một `<div>` cha chứa ba `<div>` con, nhưng phần tử cha KHÔNG có bất kỳ khai báo `display` nào. Ba `<div>` con này sẽ hiển thị như thế nào?","options":["Xếp cạnh nhau thành một hàng ngang","Xếp chồng lên nhau thành ba dòng riêng biệt, theo đúng thứ tự khai báo trong HTML","Chỉ hiển thị `<div>` con đầu tiên, hai `<div>` còn lại bị ẩn đi","Hiển thị ở vị trí ngẫu nhiên, không theo quy tắc nào"],"answer":1,"explain":"Vì `<div>` mặc định là phần tử khối, nếu phần tử cha không được khai báo `display: flex` (hay giá trị khác), các `<div>` con — cũng là phần tử khối — sẽ tự xếp chồng lên nhau thành từng dòng riêng, theo đúng thứ tự xuất hiện trong HTML."},{"id":"CC-tf-1201","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Thẻ `<a>` mặc định là phần tử nội tuyến (inline).","correct":true},{"text":"`display: flex` khai báo trên phần tử cha sẽ tự động ảnh hưởng đến mọi phần tử cháu ở bên trong, kể cả những phần tử nằm sâu bên trong các thẻ con.","correct":false},{"text":"Có thể chia một trang web thành các vùng như đầu trang, nội dung, chân trang bằng nhiều thẻ `<div>` riêng biệt.","correct":true},{"text":"Thuộc tính `justify-content` dùng để thay đổi màu nền của các khối con.","correct":false}],"explain":"(1) Đúng — `<a>` mặc định là phần tử nội tuyến, nằm lọt trong dòng chữ xung quanh. (2) Sai — `display: flex` chỉ sắp xếp các phần tử con trực tiếp bên trong phần tử cha; các phần tử cháu ở cấp sâu hơn không tự động bị ảnh hưởng. (3) Đúng — chia trang thành nhiều vùng bằng các `<div>` riêng biệt là cách bố cục cơ bản và rất phổ biến. (4) Sai — `justify-content` dùng để căn vị trí các khối con trên hàng ngang của flex, không liên quan đến màu nền; màu nền được đặt bằng thuộc tính khác như `background-color`."},{"id":"CC-mc-1301","type":"mc","topic":"E","grade":12,"level":"easy","question":"Theo các bước thực hành trong bài, việc nên làm đầu tiên khi xây một trang web nhỏ là gì?","options":["Viết ngay thẻ `<style>` để chọn màu cho trang","Phác thảo trước xem trang cần những phần nội dung nào","Tìm một trang có sẵn để sao chép nguyên bố cục","Chèn ảnh đại diện vào giữa trang"],"answer":1,"explain":"Bước đầu tiên nên làm là phác thảo nội dung: xác định trang cần phần nào, phần nào trước phần nào sau. Viết CSS hay chèn ảnh chỉ nên làm sau khi đã có khung HTML rõ ràng."},{"id":"CC-mc-1302","type":"mc","topic":"E","grade":12,"level":"easy","question":"Trong một trang giới thiệu bản thân, thẻ nào phù hợp nhất để trình bày phần liệt kê sở thích hoặc kĩ năng?","options":["`<p>` cùng `<br>`","`<ul>` cùng các `<li>`","`<img>` cùng `<title>`","`<head>` cùng `<meta>`"],"answer":1,"explain":"`<ul>` (danh sách không thứ tự) cùng các `<li>` bên trong là cách phù hợp để liệt kê nhiều mục như sở thích hay kĩ năng. `<p>` dùng cho đoạn văn, `<img>` để chèn ảnh, còn `<head>`/`<meta>` không hiển thị nội dung cho người xem."},{"id":"CC-mc-1303","type":"mc","topic":"E","grade":12,"level":"medium","question":"Sự khác nhau giữa vai trò của HTML và CSS khi xây một trang web được mô tả trong bài như thế nào?","options":["HTML quyết định màu sắc và bố cục, còn CSS quyết định nội dung chữ","HTML dựng khung nội dung (tiêu đề, đoạn văn, danh sách...), CSS lo phần trình bày (màu, phông, khoảng cách)","HTML và CSS làm cùng một việc, chỉ khác nhau ở cú pháp viết","CSS bắt buộc phải viết trước, sau đó HTML mới thêm nội dung vào"],"answer":1,"explain":"HTML tạo khung nội dung — trang có những phần gì như tiêu đề, đoạn văn, ảnh, danh sách — còn CSS quyết định các phần đó trông ra sao: màu sắc, phông chữ, khoảng cách, bố cục. Thứ tự hợp lý là dựng khung HTML trước, thêm CSS sau."},{"id":"CC-mc-1304","type":"mc","topic":"E","grade":12,"level":"medium","question":"Trong đoạn mã ví dụ của bài, khối `<main>` được canh vào giữa trang nhờ khai báo CSS nào?","options":["`text-align: center;`","`margin: 20px auto;`","`padding: 0;`","`color: #333;`"],"answer":1,"explain":"`margin: 20px auto;` đặt khoảng cách trên dưới 20px, còn giá trị `auto` ở hai bên trái phải khiến trình duyệt tự chia đều khoảng trống hai bên, nhờ đó khối `<main>` (đã giới hạn `max-width`) được canh vào giữa trang. `text-align: center` chỉ canh giữa văn bản bên trong một khối, không tự canh giữa cả khối đó trên trang."},{"id":"CC-mc-1305","type":"mc","topic":"E","grade":12,"level":"hard","question":"Bạn muốn thêm vào trang giới thiệu bản thân một mục mới: liệt kê ba dự án nhỏ đã từng làm, mỗi dự án một dòng ngắn. Theo cách tổ chức đã dùng trong bài, mục này nên đặt ở đâu và trình bày bằng thẻ nào?","options":["Trong `<header>`, mỗi dự án là một `<h1>` riêng","Trong `<main>`, dùng một danh sách `<ul>` cùng các `<li>`, giống cách trình bày sở thích/kĩ năng","Trong `<footer>`, mỗi dự án là một `<title>` riêng","Trong `<head>`, dùng thẻ `<meta>` cho mỗi dự án"],"answer":1,"explain":"Nội dung liệt kê nhiều mục ngắn (ở đây là các dự án) phù hợp đặt trong phần nội dung chính `<main>` và trình bày bằng danh sách `<ul>`/`<li>`, tương tự cách đã dùng cho phần sở thích/kĩ năng. `<header>` chỉ nên chứa tên/tiêu đề nổi bật, `<footer>` dành cho thông tin cuối trang, còn `<head>`/`<meta>` không hiển thị nội dung cho người xem trang."},{"id":"CC-tf-1301","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Nên phác thảo nội dung trang trước khi viết HTML, để biết trang cần những phần nào.","correct":true},{"text":"CSS chỉ có thể viết trong một tệp riêng, không thể đặt trong thẻ `<style>` ở phần `<head>`.","correct":false},{"text":"Một trang giới thiệu bản thân đơn giản có thể chia thành phần đầu trang, phần giới thiệu, phần danh sách và chân trang.","correct":true},{"text":"Trang web càng dùng nhiều màu sắc và hiệu ứng thì càng dễ đọc và chuyên nghiệp hơn.","correct":false}],"explain":"(1) Đúng — phác thảo trước giúp biết trang cần phần nào, tránh vừa viết vừa đoán. (2) Sai — trong ví dụ của bài, toàn bộ CSS được viết ngay trong thẻ `<style>` đặt ở phần `<head>`, không bắt buộc phải tách thành tệp riêng. (3) Đúng — đây đúng là cấu trúc gợi ý trong bài: đầu trang, giới thiệu, danh sách sở thích/kĩ năng, chân trang. (4) Sai — bài khuyên nên giữ trang đơn giản, ít màu chủ đạo (chừng 2–3 màu) và tránh nhồi nhét quá nhiều chi tiết, vì điều đó giúp trang dễ đọc hơn chứ không phải ngược lại."},{"id":"CC-mc-1401","type":"mc","topic":"E","grade":12,"level":"easy","question":"Theo bài học, vì sao nhu cầu tuyển dụng nhân lực công nghệ thông tin luôn ở mức cao và có xu hướng tiếp tục tăng?","options":["Vì công nghệ hiện diện trong hầu hết các lĩnh vực của đời sống, từ y tế, ngân hàng đến nông nghiệp","Vì chỉ riêng ngành công nghệ thông tin mới cần dùng đến máy tính","Vì mỗi công ty đều bị quy định phải có ít nhất một kĩ sư phần mềm","Vì ngành công nghệ thông tin không đòi hỏi đào tạo chuyên môn, ai cũng có thể làm ngay"],"answer":0,"explain":"Bài học nêu rõ công nghệ len lỏi vào hầu hết các lĩnh vực đời sống (y tế, ngân hàng, nông nghiệp...) nên nhu cầu nhân lực luôn cao; ba phương án còn lại không được nhắc đến trong bài và không phản ánh đúng thực tế."},{"id":"CC-mc-1402","type":"mc","topic":"E","grade":12,"level":"easy","question":"Nhóm nghề nào trong ngành công nghệ thông tin chuyên bảo vệ hệ thống và dữ liệu khỏi các cuộc tấn công, rò rỉ thông tin?","options":["Phát triển phần mềm/web","An ninh mạng","Quản trị hệ thống/đám mây","Khoa học và phân tích dữ liệu"],"answer":1,"explain":"An ninh mạng là nhóm nghề tập trung bảo vệ hệ thống, dữ liệu và người dùng khỏi tấn công, rò rỉ thông tin. Phát triển phần mềm thiên về xây dựng chương trình, quản trị hệ thống/đám mây thiên về vận hành hạ tầng, còn khoa học dữ liệu thiên về phân tích số liệu."},{"id":"CC-mc-1403","type":"mc","topic":"E","grade":12,"level":"medium","question":"Một tổ chức muốn xây dựng một hệ thống có khả năng tự nhận diện email rác dựa trên việc phân tích hàng nghìn email mẫu trước đó, rồi tự rút ra quy luật để nhận diện email mới. Công việc này gần với nhóm nghề nào nhất?","options":["Quản trị hệ thống/đám mây","Phát triển phần mềm/web","Trí tuệ nhân tạo và học máy","An ninh mạng"],"answer":2,"explain":"Một hệ thống ‘học’ từ dữ liệu mẫu để tự rút ra quy luật và đưa ra dự đoán trên dữ liệu mới chính là đặc trưng của trí tuệ nhân tạo và học máy, dù kết quả ứng dụng (lọc email rác) có liên quan đến an ninh."},{"id":"CC-mc-1404","type":"mc","topic":"E","grade":12,"level":"medium","question":"Vì sao bài học cho rằng khả năng tự học đặc biệt quan trọng đối với người làm trong ngành công nghệ thông tin?","options":["Vì các trường học hiện nay không dạy đủ kiến thức về công nghệ thông tin","Vì công nghệ thay đổi rất nhanh, kiến thức và công cụ có thể lạc hậu chỉ sau vài năm","Vì người làm công nghệ thông tin không cần bằng cấp","Vì tự học giúp tiết kiệm học phí hơn so với học chính quy"],"answer":1,"explain":"Bài học giải thích công nghệ thay đổi rất nhanh nên khả năng tự tìm hiểu cái mới quan trọng hơn việc chỉ dựa vào kiến thức đã học; các phương án còn lại không phải lí do được nêu trong bài."},{"id":"CC-mc-1405","type":"mc","topic":"E","grade":12,"level":"hard","question":"Một người vừa hoàn thành một khoá học lập trình ngắn hạn, sau đó tự xây dựng một ứng dụng quản lí chi tiêu cá nhân để thực hành, rồi đăng kí thi lấy chứng chỉ về phát triển phần mềm. Theo lộ trình định hướng nghề nghiệp trong bài, người này đã lần lượt thực hiện những bước nào?","options":["Chọn hướng theo sở thích -> lấy chứng chỉ -> làm dự án thực tế","Học tiếp (khoá học) -> làm dự án thực tế -> lấy chứng chỉ","Làm dự án thực tế -> học tiếp -> chọn hướng theo sở thích","Lấy chứng chỉ -> học tiếp -> làm dự án thực tế"],"answer":1,"explain":"Người này lần lượt: học một khoá lập trình (bước học tiếp), tự làm ứng dụng để thực hành (bước làm dự án thực tế), rồi thi lấy chứng chỉ (bước lấy chứng chỉ) — đúng thứ tự ba bước cuối trong lộ trình bốn bước của bài học."},{"id":"CC-tf-1401","type":"tf","topic":"E","grade":12,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Theo bài học, làm việc trong ngành công nghệ thông tin có nghĩa là hầu như ai cũng phải ngồi viết mã suốt cả ngày.","correct":false},{"text":"Nhóm nghề quản trị hệ thống và điện toán đám mây chịu trách nhiệm vận hành, giám sát máy chủ và hạ tầng công nghệ để các dịch vụ luôn chạy ổn định.","correct":true},{"text":"Theo lộ trình định hướng nghề nghiệp trong bài, bước đầu tiên là phải lấy được chứng chỉ chuyên môn, sau đó mới tìm hiểu sở thích của bản thân.","correct":false},{"text":"Ngoại ngữ, đặc biệt là tiếng Anh, được xem là kĩ năng cần thiết vì phần lớn tài liệu kĩ thuật và công cụ mới thường xuất hiện bằng tiếng Anh trước tiên.","correct":true}],"explain":"(1) Sai — bài học nêu rõ ngành công nghệ thông tin có nhiều nhóm nghề khác nhau, không phải ai cũng viết mã suốt ngày. (2) Đúng — đây chính là vai trò của nhóm quản trị hệ thống/đám mây theo bài học. (3) Sai — lộ trình bắt đầu bằng việc chọn hướng theo sở thích và thế mạnh; lấy chứng chỉ là bước cuối cùng, không phải bước đầu tiên. (4) Đúng — bài học giải thích ngoại ngữ quan trọng vì tài liệu kĩ thuật, công cụ mới thường xuất hiện bằng tiếng Anh trước."},{"id":"CC-mc-1501","type":"mc","topic":"G","grade":12,"level":"easy","question":"Điểm khác biệt cốt lõi giữa **lập trình truyền thống** và **học máy** (`machine learning`) là gì?","options":["Lập trình truyền thống dùng máy tính, còn học máy thì không cần dùng máy tính.","Trong lập trình truyền thống, con người viết sẵn từng luật; trong học máy, máy tự rút ra quy luật từ dữ liệu ví dụ.","Học máy chỉ áp dụng được cho các phép tính số học đơn giản như cộng, trừ.","Lập trình truyền thống luôn cho kết quả chính xác hơn học máy trong mọi bài toán."],"answer":1,"explain":"Trong lập trình truyền thống, người viết chương trình nghĩ ra và viết sẵn từng luật cụ thể. Trong học máy, máy được cho xem nhiều dữ liệu ví dụ và tự rút ra quy luật, không cần ai viết luật sẵn."},{"id":"CC-mc-1502","type":"mc","topic":"G","grade":12,"level":"easy","question":"Học máy (`machine learning`) là một nhánh của lĩnh vực nào?","options":["Trí tuệ nhân tạo (AI)","Thiết kế web","Quản trị mạng máy tính","Xử lý văn bản soạn thảo"],"answer":0,"explain":"Học máy là một nhánh của trí tuệ nhân tạo (AI) — lĩnh vực nghiên cứu cách giúp máy tính thực hiện những việc vốn cần đến trí thông minh của con người."},{"id":"CC-mc-1503","type":"mc","topic":"G","grade":12,"level":"medium","question":"Nếu dữ liệu huấn luyện đưa cho máy có rất nhiều nhãn bị gắn sai (ví dụ nhiều ảnh chó bị chú thích nhầm thành mèo), điều gì có khả năng xảy ra?","options":["Máy sẽ tự động phát hiện và loại bỏ những nhãn sai đó trước khi học.","Máy vẫn học đúng quy luật vì máy tính luôn xử lý mọi dữ liệu một cách chính xác.","Máy có khả năng học theo đúng những sai lầm đó, dẫn đến dự đoán sai trên dữ liệu mới.","Lượng dữ liệu gắn nhãn sai không ảnh hưởng gì miễn là tổng số dữ liệu đủ nhiều."],"answer":2,"explain":"Máy hoàn toàn dựa vào dữ liệu huấn luyện để rút ra quy luật; nếu dữ liệu có nhiều nhãn sai, máy sẽ học theo đúng những sai lầm đó, dẫn đến dự đoán không chính xác trên dữ liệu mới."},{"id":"CC-mc-1504","type":"mc","topic":"G","grade":12,"level":"medium","question":"Khi nói một mô hình học máy ‘học’, điều này được hiểu chính xác nhất là gì?","options":["Máy hiểu và suy nghĩ có ý thức giống hệt con người.","Máy ghi nhớ nguyên văn toàn bộ dữ liệu huấn luyện để trả lời sau này.","Máy tự viết ra các luật kiểu nếu – thì để giải quyết bài toán.","Máy điều chỉnh dần dần dựa trên nhiều lần dự đoán và sửa sai, để dự đoán ngày càng chính xác hơn."],"answer":3,"explain":"‘Học’ trong học máy không phải là hiểu biết như con người, mà là một quá trình điều chỉnh dần dần: máy dự đoán, so sánh với đáp án đúng, rồi tự điều chỉnh để lần sau dự đoán chính xác hơn."},{"id":"CC-mc-1505","type":"mc","topic":"G","grade":12,"level":"hard","question":"Một người muốn xây dựng hai hệ thống: Hệ thống 1 – kiểm tra xem một số nguyên có phải số nguyên tố hay không. Hệ thống 2 – nhận diện chữ số viết tay trong ảnh. Nhận định nào dưới đây hợp lý nhất?","options":["Cả hai hệ thống đều nên dùng học máy, vì học máy luôn chính xác hơn lập trình truyền thống trong mọi trường hợp.","Hệ thống 1 phù hợp với lập trình truyền thống vì có luật toán học rõ ràng để kiểm tra; hệ thống 2 phù hợp với học máy vì rất khó viết luật rõ ràng cho mọi kiểu nét chữ viết tay.","Cả hai hệ thống đều nên dùng lập trình truyền thống, vì máy tính chỉ có thể làm việc với luật, không thể xử lý dữ liệu.","Hệ thống 1 phù hợp với học máy vì số nguyên tố có vô số giá trị; hệ thống 2 phù hợp với lập trình truyền thống vì ảnh chữ số viết tay luôn giống hệt nhau."],"answer":1,"explain":"Kiểm tra số nguyên tố dựa trên một luật toán học rõ ràng, không có ngoại lệ, nên lập trình truyền thống là đủ và hiệu quả. Chữ số viết tay lại có vô vàn kiểu nét khác nhau giữa người viết, rất khó liệt kê hết bằng luật, nên học máy — học quy luật từ nhiều ví dụ có sẵn — phù hợp hơn."},{"id":"CC-tf-1501","type":"tf","topic":"G","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trong học máy, máy tự rút ra quy luật từ dữ liệu ví dụ, thay vì được lập trình theo từng luật do con người viết sẵn.","correct":true},{"text":"Học máy là một lĩnh vực hoàn toàn tách biệt, không liên quan gì đến trí tuệ nhân tạo (AI).","correct":false},{"text":"Dữ liệu huấn luyện càng nhiều và càng chính xác thì máy càng có cơ hội học đúng quy luật.","correct":true},{"text":"Một khi đã huấn luyện xong, mô hình học máy sẽ luôn dự đoán chính xác tuyệt đối trên mọi dữ liệu mới, không bao giờ sai.","correct":false}],"explain":"(1) Đúng — đây là đặc trưng cốt lõi của học máy, khác hẳn lập trình truyền thống. (2) Sai — học máy là một nhánh của trí tuệ nhân tạo (AI), không tách biệt khỏi AI. (3) Đúng — dữ liệu huấn luyện là nguyên liệu duy nhất máy dựa vào để học, nên càng nhiều và càng chính xác thì máy càng học đúng quy luật. (4) Sai — mô hình học máy học quy luật từ dữ liệu đã có, nhưng vẫn có thể dự đoán sai trên dữ liệu mới, đặc biệt khi dữ liệu huấn luyện ít hoặc kém chất lượng."},{"id":"CC-mc-1601","type":"mc","topic":"G","grade":12,"level":"easy","question":"Trong học máy, bài toán **phân loại** (`classification`) yêu cầu máy làm gì?","options":["Chọn ra một nhãn phù hợp trong số các nhãn đã biết trước cho dữ liệu đưa vào.","Ước lượng một con số bất kỳ, không giới hạn trong các lựa chọn có sẵn.","Sắp xếp lại toàn bộ dữ liệu theo thứ tự tăng dần.","Xóa bỏ những dữ liệu bị coi là sai hoặc thiếu."],"answer":0,"explain":"Phân loại là chọn đúng một nhãn trong số các nhãn hữu hạn đã quy định trước, ví dụ thư rác/không rác."},{"id":"CC-mc-1602","type":"mc","topic":"G","grade":12,"level":"easy","question":"Bài toán nào dưới đây là một bài toán **dự đoán số** (`regression`)?","options":["Xác định một bức ảnh là chó hay mèo.","Ước lượng giá một căn nhà dựa vào diện tích của nó.","Đánh giá một bình luận là tích cực hay tiêu cực.","Xác định một email là thư rác hay không phải thư rác."],"answer":1,"explain":"Ước lượng giá nhà cho ra một con số (ví dụ 1400 triệu đồng), không phải một nhãn nhóm, nên đây là bài toán dự đoán số."},{"id":"CC-mc-1603","type":"mc","topic":"G","grade":12,"level":"medium","question":"Trong quy trình xây dựng mô hình học máy, dữ liệu **kiểm tra** (`test`) có vai trò gì?","options":["Được dùng để máy học và tìm ra quy luật ngay từ đầu.","Được trộn lẫn với dữ liệu huấn luyện để máy học nhanh hơn.","Dùng để đánh giá mô hình trên những trường hợp máy chưa từng thấy trong lúc học.","Được xóa bỏ ngay sau khi chia dữ liệu vì không cần dùng đến."],"answer":2,"explain":"Dữ liệu kiểm tra không được dùng lúc huấn luyện; nó dùng để đánh giá xem mô hình có thực sự học được quy luật hay không."},{"id":"CC-mc-1604","type":"mc","topic":"G","grade":12,"level":"medium","question":"**Độ chính xác** (`accuracy`) của một mô hình phân loại được hiểu là gì?","options":["Tổng số dữ liệu mà mô hình đã được học qua.","Thời gian mô hình cần để đưa ra một dự đoán.","Tỉ lệ số lần mô hình dự đoán đúng nhãn trên tổng số lần dự đoán ở tập kiểm tra.","Số lượng nhãn khác nhau có trong dữ liệu."],"answer":2,"explain":"Độ chính xác là tỉ lệ phần trăm số dự đoán đúng trên tổng số lần dự đoán, tính trên tập kiểm tra."},{"id":"CC-mc-1605","type":"mc","topic":"G","grade":12,"level":"hard","question":"Một hệ thống dự báo thời tiết có hai cách đưa ra kết quả cho cùng một dữ liệu đầu vào. Cách 1: đưa ra một trong ba nhãn “nắng”, “mưa”, “nhiều mây”. Cách 2: đưa ra nhiệt độ dự kiến, ví dụ 27,5°C. Nhận định nào dưới đây đúng?","options":["Cả hai cách đều là bài toán phân loại vì cùng dự báo thời tiết.","Cách 1 là bài toán phân loại (chọn một trong ba nhãn có sẵn); cách 2 là bài toán dự đoán số (ước lượng một con số).","Cách 1 là bài toán dự đoán số vì có nhiều khả năng xảy ra; cách 2 là bài toán phân loại vì nhiệt độ luôn là số nguyên.","Cả hai cách đều là bài toán dự đoán số vì cùng dùng chung một dữ liệu đầu vào."],"answer":1,"explain":"Cách 1 cho ra một nhãn trong số hữu hạn nhãn đã định sẵn (nắng/mưa/nhiều mây) nên là phân loại; cách 2 cho ra một con số có thể có phần thập phân (27,5°C) nên là dự đoán số. Cùng một dữ liệu đầu vào hoàn toàn có thể dùng cho cả hai dạng bài toán khác nhau, tùy vào câu hỏi ta đặt ra."},{"id":"CC-tf-1601","type":"tf","topic":"G","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trong bài toán phân loại, số lượng nhãn mà máy có thể chọn là hữu hạn và được quy định trước.","correct":true},{"text":"Trong bài toán dự đoán số, kết quả đưa ra bắt buộc phải trùng với một trong các giá trị đã có sẵn trong dữ liệu huấn luyện.","correct":false},{"text":"Mục đích của việc chia dữ liệu thành phần huấn luyện và phần kiểm tra là để đánh giá xem mô hình có học được quy luật chung hay không.","correct":true},{"text":"Một mô hình đạt độ chính xác rất cao trên chính dữ liệu đã dùng để huấn luyện thì chắc chắn sẽ hoạt động tốt trên dữ liệu mới.","correct":false}],"explain":"(1) Đúng — nhãn trong bài toán phân loại là hữu hạn và biết trước. (2) Sai — con số dự đoán có thể là một giá trị hoàn toàn mới, như ước lượng giá nhà 70 m² dù dữ liệu mẫu chỉ có 40, 60, 80 m². (3) Đúng — dữ liệu kiểm tra dùng để đánh giá mô hình trên trường hợp chưa từng thấy, qua đó biết mô hình có nắm được quy luật chung hay không. (4) Sai — độ chính xác cao trên chính dữ liệu huấn luyện có thể chỉ do mô hình “học vẹt”, ghi nhớ máy móc, nên vẫn có thể đoán sai trên dữ liệu mới."},{"id":"CC-mc-1701","type":"mc","topic":"G","grade":12,"level":"easy","question":"Khoa học dữ liệu là quá trình biến điều gì thành hiểu biết có ích để ra quyết định?","options":["Dữ liệu thô","Chương trình máy tính","Mạng máy tính","Hệ điều hành"],"answer":0,"explain":"Khoa học dữ liệu tập trung thu thập và xử lý dữ liệu thô — những con số, chữ viết chưa qua xử lý — để tìm ra hiểu biết có thể dùng cho việc ra quyết định."},{"id":"CC-mc-1702","type":"mc","topic":"G","grade":12,"level":"easy","question":"Trong quy trình khoa học dữ liệu, bước nào thường diễn ra ngay sau khi thu thập dữ liệu?","options":["Trực quan hoá","Làm sạch dữ liệu","Rút kết luận","Huấn luyện mô hình học máy"],"answer":1,"explain":"Sau khi thu thập, dữ liệu thường còn lỗi, thiếu hoặc trùng lặp nên bước tiếp theo là làm sạch, trước khi đem đi phân tích."},{"id":"CC-mc-1703","type":"mc","topic":"G","grade":12,"level":"medium","question":"Việc loại bỏ các hoá đơn ghi trùng và bổ sung ngày tháng còn thiếu trong dữ liệu bán hàng thuộc bước nào của quy trình khoa học dữ liệu?","options":["Thu thập dữ liệu","Làm sạch dữ liệu","Trực quan hoá","Rút kết luận"],"answer":1,"explain":"Loại bỏ bản ghi trùng và bổ sung dữ liệu thiếu chính là công việc của bước làm sạch dữ liệu — chuẩn bị dữ liệu đáng tin cậy trước khi phân tích."},{"id":"CC-mc-1704","type":"mc","topic":"G","grade":12,"level":"medium","question":"Nguyên tắc ‘rác vào thì rác ra’ trong khoa học dữ liệu muốn nói điều gì?","options":["Nên vẽ càng nhiều biểu đồ càng tốt","Dữ liệu đầu vào lỗi thì kết quả phân tích cũng không đáng tin, dù thuật toán tốt đến đâu","Chỉ cần thu thập thật nhiều dữ liệu là đủ","Nên bỏ qua bước làm sạch để tiết kiệm thời gian"],"answer":1,"explain":"Nguyên tắc này nhấn mạnh: nếu dữ liệu đầu vào bị lỗi, thiếu hoặc trùng mà không được làm sạch, thì mọi phân tích và kết luận phía sau — dù công cụ có mạnh đến đâu — cũng không đáng tin cậy."},{"id":"CC-mc-1705","type":"mc","topic":"G","grade":12,"level":"hard","question":"Một cửa hàng đã có bảng dữ liệu sạch (không còn lỗi, thiếu, trùng) về số lượng bán theo tháng. Vẽ biểu đồ cột thể hiện số lượng bán theo từng tháng thuộc bước nào, và bước nào phải hoàn tất trước đó để có được bảng dữ liệu sạch này?","options":["Trực quan hoá; bước trước đó là làm sạch dữ liệu","Rút kết luận; bước trước đó là thu thập dữ liệu","Phân tích dữ liệu; bước trước đó là trực quan hoá","Thu thập dữ liệu; bước trước đó là rút kết luận"],"answer":0,"explain":"Vẽ biểu đồ là bước trực quan hoá. Để có bảng dữ liệu sạch dùng cho bước này, dữ liệu phải được xử lý qua bước làm sạch dữ liệu trước đó — loại bỏ lỗi, chỗ thiếu và bản ghi trùng."},{"id":"CC-tf-1701","type":"tf","topic":"G","grade":12,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Dữ liệu thô là dữ liệu đã được làm sạch và phân tích xong, sẵn sàng để ra quyết định.","correct":false},{"text":"Trong quy trình khoa học dữ liệu, bước làm sạch thường được thực hiện trước bước phân tích.","correct":true},{"text":"Khoa học dữ liệu chỉ ứng dụng được trong lĩnh vực kinh doanh, không dùng được cho y tế hay giáo dục.","correct":false},{"text":"Dữ liệu đã được thu thập và làm sạch cẩn thận có thể dùng làm nguyên liệu để huấn luyện mô hình học máy.","correct":true}],"explain":"(1) Sai — dữ liệu thô là dữ liệu chưa qua xử lý; dữ liệu đã làm sạch và phân tích xong gọi là hiểu biết, không phải dữ liệu thô. (2) Đúng — làm sạch luôn thực hiện trước phân tích để đảm bảo dữ liệu đáng tin cậy. (3) Sai — khoa học dữ liệu còn ứng dụng trong y tế, thể thao, giáo dục và nhiều lĩnh vực khác. (4) Đúng — dữ liệu sạch chính là nguyên liệu đầu vào để huấn luyện các mô hình học máy."},{"id":"CC-mc-1801","type":"mc","topic":"G","grade":12,"level":"easy","question":"Trực quan hoá dữ liệu (`data visualization`) có nghĩa là gì?","options":["Xoá bớt dữ liệu thừa để bảng số liệu ngắn gọn hơn","Biến số liệu thành biểu đồ hoặc hình ảnh để dễ nhận ra xu hướng, so sánh, tỉ lệ","Dịch số liệu từ tiếng Việt sang tiếng Anh","Sắp xếp lại số liệu theo thứ tự từ nhỏ đến lớn"],"answer":1,"explain":"Trực quan hoá dữ liệu là biến số liệu thô thành biểu đồ hoặc hình ảnh để mắt người nhận ra nhanh những điều như xu hướng, phép so sánh hay tỉ lệ — không liên quan đến việc xoá bớt dữ liệu, dịch ngôn ngữ, hay chỉ đơn thuần sắp xếp lại thứ tự số liệu."},{"id":"CC-mc-1802","type":"mc","topic":"G","grade":12,"level":"easy","question":"Loại biểu đồ nào phù hợp nhất để thể hiện nhiệt độ thay đổi ra sao theo từng giờ trong một ngày?","options":["Biểu đồ tròn","Biểu đồ cột","Biểu đồ đường","Không loại biểu đồ nào thể hiện được điều này"],"answer":2,"explain":"Biểu đồ đường dùng để thể hiện xu hướng biến đổi của một đại lượng theo thời gian, đúng với bản chất của nhiệt độ đo theo từng giờ nối tiếp nhau. Biểu đồ cột phù hợp hơn để so sánh các nhóm, còn biểu đồ tròn phù hợp để thể hiện tỉ lệ của một tổng thể."},{"id":"CC-mc-1803","type":"mc","topic":"G","grade":12,"level":"medium","question":"Một người muốn so sánh doanh thu của năm cửa hàng khác nhau, tất cả đều được tính trong cùng một tháng. Biểu đồ nào phù hợp nhất?","options":["Biểu đồ đường, vì cần thể hiện xu hướng theo thời gian","Biểu đồ cột, vì cần so sánh giá trị giữa các nhóm tại cùng một thời điểm","Biểu đồ tròn, vì mỗi cửa hàng là một phần của tổng doanh thu cả nước","Không cần vẽ biểu đồ vì chỉ có năm số liệu"],"answer":1,"explain":"Đây là bài toán so sánh nhiều nhóm — năm cửa hàng — tại cùng một thời điểm, không phải theo dõi biến đổi theo thời gian hay thể hiện tỉ lệ của một tổng thể, nên biểu đồ cột là lựa chọn phù hợp nhất."},{"id":"CC-mc-1804","type":"mc","topic":"G","grade":12,"level":"medium","question":"Trước khi rút ra kết luận từ một biểu đồ, việc nào sau đây là cần thiết nhất?","options":["Chọn màu sắc thật đẹp mắt cho biểu đồ","Kiểm tra tiêu đề, các trục cùng đơn vị, và chú giải nếu có nhiều đường hoặc nhiều màu","Đếm xem biểu đồ có bao nhiêu cột hoặc bao nhiêu đường","Xem biểu đồ được vẽ bằng phần mềm nào"],"answer":1,"explain":"Đọc đúng một biểu đồ đòi hỏi kiểm tra tiêu đề, các trục cùng đơn vị đi kèm, và chú giải khi có nhiều màu hoặc nhiều đường — bỏ qua các yếu tố này rất dễ hiểu sai dữ liệu. Màu sắc, số lượng cột hay đường, hoặc phần mềm dùng để vẽ không phải điều quyết định để đọc đúng nội dung."},{"id":"CC-mc-1805","type":"mc","topic":"G","grade":12,"level":"hard","question":"Cửa hàng A đạt doanh thu 100 triệu, cửa hàng B đạt 105 triệu trong cùng một tháng, chênh lệch khoảng 5%. Một biểu đồ cột vẽ trục tung bắt đầu từ 95 thay vì từ 0, khiến cột B trông cao gấp nhiều lần cột A. Nhận định nào sau đây đúng nhất?","options":["Biểu đồ này chính xác vì số liệu 100 và 105 vẫn được giữ nguyên","Biểu đồ này gây hiểu nhầm vì trục bị cắt bớt khiến chênh lệch nhỏ trông như rất lớn, dù số liệu gốc không đổi","Biểu đồ này sai vì đã tự ý đổi số liệu của cửa hàng B","Không thể có chuyện hiểu nhầm nào xảy ra khi đã có đủ hai con số ghi trên biểu đồ"],"answer":1,"explain":"Số liệu 100 và 105 không hề bị thay đổi, nhưng việc cắt bớt trục tung, chỉ bắt đầu từ 95, khiến khoảng cách hình ảnh giữa hai cột bị phóng đại rất nhiều so với chênh lệch thực tế chỉ khoảng 5%. Đây chính là kiểu biểu đồ gây hiểu nhầm dù số liệu vẫn đúng, chứ không phải do số liệu bị đổi hay do biểu đồ không đủ thông tin."},{"id":"CC-tf-1801","type":"tf","topic":"G","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Biểu đồ đường phù hợp để thể hiện một đại lượng thay đổi ra sao theo thời gian.","correct":true},{"text":"Bất kì bộ dữ liệu nào cũng có thể vẽ bằng biểu đồ tròn, miễn là có đủ số liệu để vẽ.","correct":false},{"text":"Khi đọc một biểu đồ, cần chú ý xem trục có bắt đầu từ 0 hay đã bị cắt bớt, vì điều này ảnh hưởng đến ấn tượng thị giác mà biểu đồ tạo ra.","correct":true},{"text":"Chỉ cần nhìn hình dạng chung của biểu đồ là đủ, không cần quan tâm đến đơn vị trên các trục.","correct":false}],"explain":"(1) Đúng — biểu đồ đường dùng để thể hiện xu hướng biến đổi theo thời gian. (2) Sai — biểu đồ tròn chỉ phù hợp khi các phần thực sự cộng lại thành một tổng có ý nghĩa, không phải bộ dữ liệu nào cũng vẽ được theo cách này. (3) Đúng — trục bị cắt bớt hoặc phóng đại có thể khiến một chênh lệch nhỏ trông như rất lớn, nên cần kiểm tra trước khi tin vào ấn tượng ban đầu. (4) Sai — bỏ qua đơn vị trên trục rất dễ dẫn đến hiểu sai hoàn toàn ý nghĩa của số liệu."},{"id":"CC-mc-1901","type":"mc","topic":"G","grade":12,"level":"easy","question":"Mô phỏng (`simulation`) trên máy tính có nghĩa là gì?","options":["Sao chép y nguyên một sự vật thật vào máy tính mà không thay đổi gì","Dùng máy tính dựng một mô hình của một hiện tượng thực rồi chạy thử, để quan sát và dự đoán mà không cần làm thật","Chụp ảnh hoặc quay phim lại một sự việc đã xảy ra","Tính toán chính xác tuyệt đối mọi kết quả có thể xảy ra trong thực tế"],"answer":1,"explain":"Mô phỏng là dùng máy tính dựng một mô hình của một hiện tượng thực, rồi chạy thử mô hình đó để quan sát và dự đoán, thay vì phải làm thật ngoài đời. Sao chép nguyên vẹn, chụp ảnh lại, hay tính toán ‘chính xác tuyệt đối’ đều không đúng bản chất của mô phỏng — mô phỏng luôn dựa trên một mô hình đã được đơn giản hoá, nên kết quả chỉ là gần đúng."},{"id":"CC-mc-1902","type":"mc","topic":"G","grade":12,"level":"easy","question":"Ví dụ nào sau đây KHÔNG phải là một ứng dụng của mô phỏng trên máy tính?","options":["Dự báo thời tiết bằng cách chạy mô hình khí quyển trên máy tính","Huấn luyện phi công bằng buồng lái mô phỏng","Đánh số trang tự động cho một văn bản soạn thảo","Mô phỏng lan truyền dịch bệnh trong một cộng đồng"],"answer":2,"explain":"Dự báo thời tiết, huấn luyện phi công bằng buồng lái mô phỏng, và mô phỏng lan truyền dịch bệnh đều là những ví dụ điển hình của mô phỏng trên máy tính — dựng mô hình rồi chạy thử để dự đoán. Đánh số trang tự động chỉ là một thao tác xử lí văn bản đơn giản, không liên quan đến việc dựng mô hình hay chạy thử một hiện tượng thực."},{"id":"CC-mc-1903","type":"mc","topic":"G","grade":12,"level":"medium","question":"Trong ví dụ mô phỏng bệnh cảm ở trên, vì sao số người mắc bệnh ở kịch bản ‘có đeo khẩu trang’ tăng chậm hơn kịch bản ‘không đeo khẩu trang’?","options":["Vì mô hình giả định mỗi người lây cho ít người khác hơn mỗi ngày khi mọi người đeo khẩu trang","Vì số người ban đầu mắc bệnh ở hai kịch bản là khác nhau","Vì máy tính tính toán chậm hơn khi mô phỏng kịch bản có khẩu trang","Vì kịch bản có khẩu trang chỉ được chạy thử trong ít ngày hơn"],"answer":0,"explain":"Cả hai kịch bản đều bắt đầu từ 1 người mắc bệnh và được chạy thử trong cùng 4 ngày; điều duy nhất khác nhau là giả định đầu vào về số người bị lây mỗi ngày — 2 người nếu không đeo khẩu trang, 1 người nếu có đeo khẩu trang. Chính sự khác biệt trong giả định đầu vào này khiến hai kết quả mô phỏng khác nhau, chứ không phải do số người ban đầu, tốc độ tính toán, hay số ngày chạy thử."},{"id":"CC-mc-1904","type":"mc","topic":"G","grade":12,"level":"medium","question":"Một công ty ô tô muốn biết chuyện gì xảy ra khi xe va chạm ở tốc độ cao, nhưng không muốn cho người thật ngồi trong xe lúc va chạm thử. Việc thay bằng một mô phỏng va chạm trên máy tính thể hiện rõ nhất lợi ích nào?","options":["Tiết kiệm chi phí, vì công ty không cần mua xe để thử nghiệm","An toàn, vì thử được một tình huống nguy hiểm mà không có ai bị tổn hại thật","Thử được nhiều tình huống ‘nếu... thì...’ cùng lúc trên nhiều máy tính khác nhau","Không liên quan đến lợi ích nào của mô phỏng đã học"],"answer":1,"explain":"Va chạm ở tốc độ cao là một tình huống nguy hiểm đến tính mạng nếu thử bằng người thật; mô phỏng cho phép quan sát chuyện gì xảy ra trong tình huống đó mà không ai bị tổn hại thật, nên đây là ví dụ rõ nhất cho lợi ích an toàn. Công ty vẫn cần chi phí để dựng mô hình xe cho chính xác, nên tiết kiệm chi phí chưa phải lí do chính được nhấn mạnh ở đây; đề bài cũng không nhắc đến việc so sánh nhiều phương án khác nhau."},{"id":"CC-mc-1905","type":"mc","topic":"G","grade":12,"level":"hard","question":"Một mô hình dự báo thời tiết dự đoán trời sẽ nắng cả tuần, nhưng thực tế giữa tuần lại có mưa lớn bất ngờ. Nhận định nào sau đây hợp lí nhất để giải thích sự sai lệch này?","options":["Máy tính chạy mô phỏng luôn cho kết quả sai, nên không nên tin bất kì mô phỏng nào","Mô hình hoặc dữ liệu đầu vào dùng để dự báo có thể chưa phản ánh đủ đúng điều kiện thực tế của khí quyển, khiến kết quả dự đoán bị lệch","Trời mưa là điều không thể dự đoán được bằng bất kì phương pháp nào","Máy tính đã tính sai một phép cộng trừ cơ bản trong lúc chạy mô phỏng"],"answer":1,"explain":"Mô phỏng dự báo thời tiết dựa trên một mô hình khí quyển cùng dữ liệu đầu vào tại thời điểm dự báo; nếu mô hình chưa nắm bắt đủ đúng các yếu tố thực tế, hoặc dữ liệu đầu vào chưa chính xác, kết quả dự đoán sẽ lệch so với thực tế — đây là giới hạn vốn có của mọi mô phỏng. Kết luận mô phỏng ‘luôn sai’ là quá tuyệt đối, trời mưa vẫn có thể dự đoán được dù chưa hoàn hảo, và sự sai lệch này cũng không liên quan đến việc máy tính tính sai phép toán cơ bản."},{"id":"CC-tf-1901","type":"tf","topic":"G","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Mô phỏng cho phép thử một tình huống nguy hiểm trên máy tính mà không gây tổn hại thật ngoài đời.","correct":true},{"text":"Kết quả của một mô phỏng luôn hoàn toàn chính xác, không phụ thuộc vào mô hình hay dữ liệu đầu vào.","correct":false},{"text":"Muốn so sánh nhiều phương án khác nhau, có thể đổi số liệu giả định rồi chạy lại mô phỏng nhiều lần.","correct":true},{"text":"Mô phỏng có thể thay thế hoàn toàn việc quan sát, đo đạc thực tế trong mọi trường hợp.","correct":false}],"explain":"(1) Đúng — đây chính là lợi ích an toàn của mô phỏng, thử được tình huống nguy hiểm mà không ai bị tổn hại thật. (2) Sai — kết quả mô phỏng phụ thuộc vào mô hình và dữ liệu đầu vào; mô hình sai hoặc dữ liệu sai sẽ cho kết quả sai lệch. (3) Đúng — đổi giả định đầu vào rồi chạy lại mô phỏng là cách phổ biến để so sánh nhiều phương án, đúng như lợi ích thử nhiều tình huống ‘nếu... thì...’. (4) Sai — mô phỏng chỉ cho kết quả gần đúng và không thể thay thế hoàn toàn việc quan sát, đo đạc thực tế."},{"id":"CC-mc-2001","type":"mc","topic":"G","grade":12,"level":"easy","question":"Dữ liệu lớn (`big data`) dùng để chỉ điều gì?","options":["Một phần mềm chuyên dùng để nén tệp cho gọn nhẹ hơn","Khối dữ liệu khổng lồ, sinh ra liên tục từ nhiều nguồn khác nhau, lớn và phức tạp đến mức khó xử lí bằng các công cụ thông thường","Tên gọi khác của bộ nhớ trong (RAM) dung lượng lớn trên máy tính","Một tệp video có dung lượng trên 1 GB"],"answer":1,"explain":"Phương án đúng mô tả chính xác khái niệm dữ liệu lớn: một khối dữ liệu khổng lồ, sinh liên tục từ nhiều nguồn, đến mức các công cụ xử lí thông thường khó đảm đương. Phần mềm nén tệp, bộ nhớ RAM hay một tệp video đơn lẻ dù dung lượng lớn cũng không phải dữ liệu lớn theo đúng nghĩa này, vì thiếu tính liên tục và đa nguồn."},{"id":"CC-mc-2002","type":"mc","topic":"G","grade":12,"level":"easy","question":"Đặc điểm nào sau đây KHÔNG phải là một trong ba đặc điểm thường dùng để mô tả dữ liệu lớn?","options":["Khối lượng khổng lồ","Tốc độ sinh ra rất nhanh","Đa dạng về loại dữ liệu","Luôn được lưu trữ miễn phí, không tốn bất kì chi phí nào"],"answer":3,"explain":"Ba đặc điểm cốt lõi thường dùng để mô tả dữ liệu lớn là khối lượng khổng lồ, tốc độ sinh ra rất nhanh và đa dạng về loại dữ liệu. Việc lưu trữ, xử lí dữ liệu lớn trên thực tế đòi hỏi chi phí đáng kể cho hạ tầng, máy chủ và nhân lực, hoàn toàn không miễn phí, nên đây là phương án không đúng."},{"id":"CC-mc-2003","type":"mc","topic":"G","grade":12,"level":"medium","question":"Một chuỗi cửa hàng bán lẻ thu thập dữ liệu về từng hoá đơn, từng lượt quét mã giảm giá của hàng triệu khách hàng trên cả nước mỗi ngày. Việc phân tích khối dữ liệu này đem lại lợi ích rõ nhất nào sau đây?","options":["Giúp phát hiện xu hướng mua sắm của khách hàng, hỗ trợ quyết định nhập hàng, khuyến mãi phù hợp hơn","Giúp máy tính tại cửa hàng khởi động nhanh hơn","Giúp giảm số lượng nhân viên thu ngân cần thiết tại quầy","Giúp hoá đơn được in ra với tốc độ nhanh hơn"],"answer":0,"explain":"Phân tích khối dữ liệu khổng lồ về hoá đơn, mã giảm giá của hàng triệu khách hàng giúp phát hiện quy luật ẩn trong hành vi mua sắm của số đông, từ đó hỗ trợ ra quyết định kinh doanh — nhập hàng gì, khuyến mãi ra sao — chính xác hơn; đây chính là giá trị cốt lõi của việc phân tích dữ liệu lớn. Ba phương án còn lại đều không phải hệ quả trực tiếp của việc phân tích dữ liệu, mà là những vấn đề kĩ thuật hoặc nhân sự khác."},{"id":"CC-mc-2004","type":"mc","topic":"G","grade":12,"level":"medium","question":"Một hệ thống xe tự lái phải liên tục thu thập dữ liệu từ nhiều camera, cảm biến gắn trên xe, rồi dựa vào đó để nhận diện chướng ngại vật và ra quyết định trong tích tắc. Hệ thống này thể hiện rõ nhất sự kết hợp giữa dữ liệu lớn và công nghệ nào?","options":["Phần mềm xử lí văn bản","Máy in ba chiều (in 3D)","Trí tuệ nhân tạo, học máy","Đĩa quang (CD, DVD)"],"answer":2,"explain":"Việc phân tích liên tục dữ liệu từ camera, cảm biến để nhận diện chướng ngại vật và tự ra quyết định trong tích tắc chính là vai trò của trí tuệ nhân tạo, đặc biệt là học máy — đóng vai trò như bộ não xử lí dữ liệu lớn theo thời gian thực. Phần mềm xử lí văn bản, máy in ba chiều hay đĩa quang đều là những công nghệ không liên quan đến việc phân tích dữ liệu hay ra quyết định tự động."},{"id":"CC-mc-2005","type":"mc","topic":"G","grade":12,"level":"hard","question":"Một ứng dụng di động thu thập vị trí, lịch sử tìm kiếm và thói quen sử dụng của hàng chục triệu người dùng để huấn luyện một hệ thống gợi ý nội dung. Nhận định nào sau đây về tình huống này là hợp lí nhất?","options":["Vì dữ liệu được thu thập tự động, nhà phát triển ứng dụng không cần minh bạch hay chịu trách nhiệm gì về việc sử dụng dữ liệu đó","Ứng dụng có thể khai thác dữ liệu lớn để cải thiện chất lượng gợi ý, nhưng đồng thời phải minh bạch, bảo vệ dữ liệu và tôn trọng quyền riêng tư của người dùng","Không nên thu thập bất kì dữ liệu người dùng nào trong mọi trường hợp, vì như vậy luôn vi phạm quyền riêng tư","Chỉ cần dữ liệu đủ lớn thì hệ thống gợi ý chắc chắn sẽ chính xác tuyệt đối, không thể sai"],"answer":1,"explain":"Phương án đúng phản ánh đầy đủ cả hai mặt của vấn đề: dữ liệu lớn đúng là nguyên liệu quý để cải thiện các hệ thống thông minh, nhưng việc thu thập, khai thác luôn phải đi kèm trách nhiệm minh bạch và bảo vệ quyền riêng tư. Phương án đầu sai vì bỏ qua trách nhiệm bảo vệ dữ liệu; phương án thứ ba quá cực đoan vì dữ liệu lớn vẫn mang lại nhiều lợi ích chính đáng nếu được thu thập, sử dụng có trách nhiệm; phương án cuối sai vì dữ liệu lớn giúp cải thiện độ chính xác chứ không đảm bảo tuyệt đối, hệ thống dựa trên dữ liệu vẫn có thể sai."},{"id":"CC-tf-2001","type":"tf","topic":"G","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Dữ liệu lớn chỉ đơn giản là một tệp có dung lượng rất lớn, chẳng hạn một video dài vài giờ.","correct":false},{"text":"Một trong ba đặc điểm của dữ liệu lớn là dữ liệu được sinh ra với tốc độ rất nhanh, gần như không ngừng nghỉ.","correct":true},{"text":"Điện toán đám mây, `IoT` và trí tuệ nhân tạo là những công nghệ thường được kết hợp với dữ liệu lớn để tạo ra các ứng dụng thông minh.","correct":true},{"text":"Vì dữ liệu lớn phần lớn do máy móc tự động thu thập, nên việc khai thác dữ liệu lớn không cần quan tâm đến quyền riêng tư của người dùng.","correct":false}],"explain":"(1) Sai vì dữ liệu lớn là khối dữ liệu khổng lồ, sinh liên tục từ nhiều nguồn khác nhau, không phải một tệp đơn lẻ dù tệp đó có dung lượng lớn. (2) Đúng, tốc độ sinh ra rất nhanh (`velocity`) là một trong ba đặc điểm cốt lõi của dữ liệu lớn. (3) Đúng, dữ liệu lớn phát huy giá trị cao nhất khi kết hợp cùng các công nghệ này. (4) Sai vì dữ liệu lớn phần nhiều bắt nguồn từ hoạt động của con người, nên việc thu thập, khai thác luôn phải đi kèm trách nhiệm bảo vệ quyền riêng tư."},{"id":"CC-mc-2101","type":"mc","topic":"B","grade":12,"level":"easy","question":"Dãy nào sau đây là một địa chỉ IPv4 hợp lệ?","options":["192.168.1.256","10.0.45.300","172.16.8.20","192.168.1"],"answer":2,"explain":"Địa chỉ IPv4 gồm đúng bốn nhóm số, mỗi nhóm nhận giá trị từ 0 đến 255, nên 172.16.8.20 hợp lệ. Dãy 192.168.1.256 sai vì 256 vượt quá 255 (mỗi nhóm 8 bit chỉ biểu diễn được 0–255); dãy 10.0.45.300 sai vì 300 cũng vượt quá 255; dãy 192.168.1 sai vì chỉ có ba nhóm, thiếu mất một nhóm."},{"id":"CC-mc-2102","type":"mc","topic":"B","grade":12,"level":"easy","question":"Nhiệm vụ chính của hệ thống DNS là gì?","options":["Phân giải tên miền thành địa chỉ IP tương ứng của máy chủ","Cấp phát địa chỉ IP tự động cho các thiết bị vừa kết nối vào mạng","Mã hoá dữ liệu trước khi truyền đi để người ngoài không đọc được","Ghi sẵn một mã số cố định vào card mạng của mỗi thiết bị"],"answer":0,"explain":"DNS (Domain Name System) nhận vào một tên miền và trả về địa chỉ IP tương ứng, giúp con người dùng tên dễ nhớ thay cho dãy số. Việc cấp phát địa chỉ IP tự động là của máy chủ DHCP chứ không phải DNS; việc mã hoá dữ liệu khi truyền là do giao thức bảo mật đảm nhiệm; còn mã số ghi sẵn vào card mạng chính là địa chỉ MAC do nhà sản xuất ghi, không liên quan gì tới DNS."},{"id":"CC-mc-2103","type":"mc","topic":"B","grade":12,"level":"medium","question":"Nhà bạn Vy có bốn thiết bị cùng nối vào một router wifi. Khi cả bốn thiết bị cùng truy cập một trang web tra cứu “địa chỉ IP của bạn”, kết quả hiện ra sẽ thế nào?","options":["Bốn dãy số khác nhau, vì mỗi thiết bị được cấp riêng một địa chỉ IP công cộng","Cùng một dãy số giống nhau, vì cả bốn thiết bị ra Internet qua chung địa chỉ IP công cộng của router","Bốn thiết bị đều hiện dãy 192.168.1.1, vì đó là địa chỉ mà trang web ngoài Internet nhìn thấy","Không thiết bị nào hiện được kết quả, vì địa chỉ IP là thông tin bí mật của thiết bị"],"answer":1,"explain":"Trang web ngoài Internet chỉ nhìn thấy địa chỉ IP công cộng mà nhà cung cấp dịch vụ cấp cho router, nên cả bốn thiết bị đều hiện cùng một dãy số. Phương án đầu sai vì nhà cung cấp chỉ cấp một địa chỉ công cộng cho cả nhà, không cấp riêng cho từng máy. Phương án 192.168.1.1 sai vì đó là địa chỉ riêng trong mạng nội bộ, không đi ra được Internet. Phương án cuối sai vì địa chỉ IP công cộng vốn phải công khai thì máy chủ mới trả dữ liệu về đúng nơi được."},{"id":"CC-mc-2104","type":"mc","topic":"B","grade":12,"level":"medium","question":"Bạn Hải mang máy tính xách tay từ nhà đến thư viện trường rồi kết nối vào wifi ở đó. Nhận định nào sau đây đúng?","options":["Cả địa chỉ IP lẫn địa chỉ MAC của máy đều thay đổi vì máy đã sang một mạng khác","Địa chỉ MAC thay đổi theo mạng mới, còn địa chỉ IP thì giữ nguyên","Cả hai địa chỉ đều giữ nguyên vì chúng gắn liền với chiếc máy tính đó","Máy nhận một địa chỉ IP mới do router của thư viện cấp, còn địa chỉ MAC của card mạng vẫn không đổi"],"answer":3,"explain":"Địa chỉ IP cho biết thiết bị đang ở đâu trong mạng nên khi sang mạng khác, máy chủ DHCP của mạng đó sẽ cấp một địa chỉ IP mới; còn địa chỉ MAC do nhà sản xuất ghi cứng vào card mạng nên đi đâu cũng không đổi. Phương án đầu sai ở chỗ cho rằng MAC cũng đổi; phương án thứ hai đảo ngược hoàn toàn vai trò của hai loại địa chỉ; phương án thứ ba sai vì chỉ MAC mới gắn liền với phần cứng, còn IP thì phụ thuộc vào mạng đang kết nối."},{"id":"CC-mc-2105","type":"mc","topic":"B","grade":12,"level":"hard","question":"Bạn gõ một địa chỉ web hoàn toàn mới vào trình duyệt. Mô tả nào sau đây phản ánh đúng trình tự các việc diễn ra?","options":["Trình duyệt tự suy ra địa chỉ IP từ các chữ cái trong tên miền rồi kết nối thẳng tới máy chủ","Trình duyệt gửi yêu cầu tới máy chủ trước, nhận trang về rồi mới hỏi DNS xem tên miền đó ứng với địa chỉ IP nào","Trình duyệt hỏi máy chủ DNS địa chỉ IP ứng với tên miền, nhận được địa chỉ IP rồi mới gửi yêu cầu tới máy chủ mang địa chỉ đó","Router cấp cho trang web một địa chỉ IP riêng trong mạng nội bộ, sau đó trình duyệt tải trang về từ địa chỉ riêng ấy"],"answer":2,"explain":"Phải có địa chỉ IP trong tay thì mới gửi được yêu cầu đi, nên trình duyệt luôn hỏi DNS trước để phân giải tên miền, rồi mới kết nối tới máy chủ mang địa chỉ IP nhận được. Phương án đầu sai vì tên miền và địa chỉ IP không có quan hệ tính toán nào với nhau, bắt buộc phải tra cứu. Phương án thứ hai đảo ngược trình tự — chưa biết IP thì không thể gửi yêu cầu. Phương án cuối nhầm vai trò của router: router chỉ cấp địa chỉ riêng cho các thiết bị trong mạng nội bộ, không thể cấp địa chỉ cho một máy chủ ở nơi khác."},{"id":"CC-tf-2101","type":"tf","topic":"B","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trong địa chỉ IPv4, mỗi nhóm số chỉ nhận giá trị từ 0 đến 255, nên dãy 192.168.4.260 không phải là một địa chỉ IPv4 hợp lệ.","correct":true},{"text":"IPv6 được đưa vào sử dụng chủ yếu vì kho địa chỉ IPv4 đã cạn kiệt trước số lượng thiết bị nối mạng ngày càng lớn.","correct":true},{"text":"Địa chỉ IP động là địa chỉ do người dùng tự gõ cố định vào phần thiết lập mạng, còn địa chỉ IP tĩnh là do máy chủ DHCP cấp tự động mỗi lần kết nối.","correct":false},{"text":"Trong tên miền dulieu.sokhoahoc.gov.vn, thành phần dulieu chính là tên miền cấp cao nhất.","correct":false}],"explain":"(1) Đúng — mỗi nhóm của địa chỉ IPv4 được lưu bằng 8 bit nên chỉ biểu diễn được các giá trị từ 0 đến 255; số 260 vượt ngưỡng nên dãy đó không hợp lệ. (2) Đúng — IPv4 chỉ cho khoảng 4,3 tỉ địa chỉ, không đủ cho lượng thiết bị hiện nay, nên IPv6 với độ dài 128 bit ra đời để mở rộng kho địa chỉ. (3) Sai — hai khái niệm bị đảo ngược: IP tĩnh mới là địa chỉ do người dùng đặt cố định bằng tay, còn IP động do máy chủ DHCP cấp tự động mỗi lần thiết bị kết nối. (4) Sai — tên miền phải đọc từ phải sang trái, nên tên miền cấp cao nhất là vn, còn dulieu nằm ngoài cùng bên trái nên là tên miền con."},{"id":"CC-mc-2201","type":"mc","topic":"B","grade":12,"level":"easy","question":"Thứ nào sau đây KHÔNG phải là tài nguyên thường được chia sẻ giữa các máy trong một mạng nội bộ?","options":["Thư mục chứa tệp dữ liệu của một máy","Máy in đặt trong phòng","Bộ vi xử lí của một máy tính","Kết nối Internet của cả mạng"],"answer":2,"explain":"Bốn nhóm tài nguyên thường được chia sẻ trong mạng nội bộ là thư mục/tệp dữ liệu, máy in, ổ đĩa mạng và kết nối Internet — nên các phương án A, B, D đều là tài nguyên chia sẻ được và vì thế đều sai với câu hỏi phủ định này. Bộ vi xử lí là linh kiện phần cứng gắn liền bên trong một máy, chỉ máy đó dùng được; các thao tác chia sẻ tài nguyên trong mạng LAN không hề đụng tới nó."},{"id":"CC-mc-2202","type":"mc","topic":"B","grade":12,"level":"easy","question":"Được cấp quyền chỉ đọc với một thư mục dùng chung, người dùng có thể làm gì?","options":["Mở xem và sao chép tệp về máy mình, nhưng không sửa, không xoá được tệp trong thư mục đó","Chỉ nhìn thấy tên thư mục chứ không mở được nội dung bên trong","Mở và sửa nội dung tệp, chỉ riêng thao tác xoá tệp là bị cấm","Làm mọi thao tác với tệp giống hệt như khi tệp nằm trên máy của mình"],"answer":0,"explain":"Quyền chỉ đọc cho phép mở xem và sao chép về máy, nhưng chặn mọi thao tác thay đổi bản gốc trong thư mục dùng chung, nên A đúng. B sai vì chỉ đọc vẫn mở xem được nội dung, không phải chỉ thấy tên. C sai vì sửa nội dung cũng là một thao tác thay đổi bản gốc và bị chặn giống như xoá. D mô tả quyền đọc–ghi chứ không phải chỉ đọc."},{"id":"CC-mc-2203","type":"mc","topic":"B","grade":12,"level":"medium","question":"Máy tính tên PC-THUVIEN đã chia sẻ thư mục tên SachSo. Ngồi ở một máy khác trong cùng mạng, cần gõ đường dẫn nào vào ô địa chỉ để mở thư mục này?","options":["PC-THUVIEN/SachSo","\\\\SachSo\\PC-THUVIEN","http://PC-THUVIEN/SachSo","\\\\PC-THUVIEN\\SachSo"],"answer":3,"explain":"Đường dẫn mạng có dạng hai dấu gạch chéo ngược, tên máy, một dấu gạch chéo ngược rồi tên thư mục đã chia sẻ, nên D đúng. A sai vì thiếu hai dấu gạch chéo ngược mở đầu và dùng nhầm gạch chéo xuôi. B đảo ngược thứ tự: tên thư mục bị đặt vào chỗ của tên máy. C là dạng địa chỉ trang web dùng cho trình duyệt, không phải cách gọi một thư mục chia sẻ trong mạng nội bộ."},{"id":"CC-mc-2204","type":"mc","topic":"B","grade":12,"level":"medium","question":"Cô giáo muốn đặt thư mục ĐềCươngÔnTập lên mạng nội bộ để cả lớp tải về, nhưng không muốn học sinh nào sửa hay xoá tài liệu trong đó. Cách làm nào phù hợp nhất?","options":["Cấp quyền đọc–ghi cho cả lớp rồi dặn miệng các em đừng sửa gì","Cấp quyền chỉ đọc cho nhóm học sinh, còn quyền đọc–ghi chỉ giữ cho tài khoản của cô","Không chia sẻ gì cả, chép tài liệu ra thẻ nhớ rồi đưa cho từng bạn tự chép về","Chia sẻ toàn bộ ổ đĩa chứa thư mục đó với quyền chỉ đọc cho tiện tìm kiếm"],"answer":1,"explain":"B đúng vì áp dụng đúng nguyên tắc cấp quyền tối thiểu đủ dùng: học sinh chỉ cần xem và tải về nên chỉ đọc là đủ, còn người phải cập nhật tài liệu là cô giáo thì mới cần đọc–ghi. A sai vì quyền đọc–ghi đã cấp thì hệ thống vẫn cho sửa và xoá, một cái bấm nhầm cũng đủ mất tài liệu, lời dặn miệng không ngăn được. C sai vì quay lại đúng cách làm thủ công mà việc chia sẻ trong mạng nội bộ sinh ra để thay thế. D sai vì chia sẻ cả ổ đĩa là chia sẻ thừa rất nhiều thư mục không liên quan, làm lộ dữ liệu ngoài ý muốn."},{"id":"CC-mc-2205","type":"mc","topic":"B","grade":12,"level":"hard","question":"Phòng thực hành có một máy in nối bằng dây vào máy PC-GV và máy in này đã được chia sẻ cho cả phòng. Hùng ngồi ở máy PC-05 bấm lệnh in nhưng không có gì được in ra, trong khi máy in vẫn cắm điện và còn đủ giấy, mực. Nguyên nhân nào hợp lí nhất?","options":["Máy PC-05 chưa cài trình duyệt web nên không gửi được lệnh in qua mạng","Máy in bắt buộc phải nối dây trực tiếp vào PC-05 thì PC-05 mới in được","Máy PC-GV đang tắt hoặc đã tắt chia sẻ, nên chiếc máy in nối qua nó không phục vụ được máy khác","Thư mục dùng chung trên PC-GV đang được đặt ở mức quyền chỉ đọc"],"answer":2,"explain":"C đúng: khi máy in được chia sẻ thông qua một máy tính, chính máy tính đó làm cầu nối, nên nó phải đang bật và còn bật chia sẻ thì các máy khác mới gửi lệnh in tới được — đây là điểm khác biệt so với máy in có cổng mạng nối thẳng vào mạng. A sai vì lệnh in không đi qua trình duyệt web. B sai vì nếu buộc phải nối dây trực tiếp thì việc chia sẻ máy in trong mạng đã chẳng còn ý nghĩa gì. D sai vì quyền chỉ đọc hay đọc–ghi là quyền đặt cho thư mục dữ liệu, không liên quan đến việc máy in có nhận lệnh in hay không."},{"id":"CC-tf-2201","type":"tf","topic":"B","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Muốn các máy trong phòng nhìn thấy nhau để mở thư mục dùng chung, trước hết phải bật tính năng khám phá mạng trên máy đem tài nguyên ra chia sẻ.","correct":true},{"text":"Ánh xạ một thư mục chia sẻ thành ổ đĩa mạng sẽ tạo ra một bản sao đầy đủ của thư mục đó nằm ngay trên máy của người ánh xạ.","correct":false},{"text":"Nguyên tắc cấp quyền tối thiểu đủ dùng khuyên chỉ cấp quyền đọc–ghi cho những người thật sự cần thêm, sửa hoặc xoá dữ liệu, còn lại chỉ nên cấp quyền chỉ đọc.","correct":true},{"text":"Đã chia sẻ một thư mục thì nên để nguyên trạng thái chia sẻ mãi, vì tắt chia sẻ sau khi dùng xong sẽ làm mất dữ liệu bên trong thư mục.","correct":false}],"explain":"(1) Đúng — khám phá mạng là công tắc cho phép các máy khác trong cùng mạng thấy được máy của mình; tắt nó thì dù đã chia sẻ, máy bên cạnh vẫn không tìm ra tài nguyên. (2) Sai — ổ đĩa mạng chỉ là một lối vào tiện lợi trỏ tới thư mục gốc, dữ liệu vẫn nằm nguyên trên máy chia sẻ; máy kia tắt thì ổ đĩa mạng đó cũng không mở được. (3) Đúng — đây chính là phát biểu của nguyên tắc cấp quyền tối thiểu đủ dùng, giúp hạn chế sửa nhầm, xoá nhầm và lộ dữ liệu. (4) Sai — tắt chia sẻ chỉ khép lại đường vào từ mạng, tệp vẫn còn nguyên trên máy; ngược lại, đây còn là biện pháp an toàn nên làm khi công việc đã xong."},{"id":"CC-mc-2301","type":"mc","topic":"E","grade":12,"level":"easy","question":"Cần thêm thuộc tính nào vào thẻ `<audio>` hoặc `<video>` để người xem thấy thanh điều khiển phát, tạm dừng và chỉnh âm lượng?","options":["`src`","`controls`","`autoplay`","`width`"],"answer":1,"explain":"`controls` chính là thuộc tính yêu cầu trình duyệt vẽ ra thanh điều khiển. `src` chỉ cho biết tệp nằm ở đâu chứ không tạo nút bấm nào. `autoplay` chỉ khiến phim tự phát, người xem vẫn không có nút để tạm dừng. `width` chỉ đặt chiều rộng khung hình."},{"id":"CC-mc-2302","type":"mc","topic":"E","grade":12,"level":"easy","question":"Thẻ nào dùng để tạo khung nội tuyến, tức là nhúng nguyên một trang web khác vào bên trong trang hiện tại?","options":["`<iframe>`","`<video>`","`<embed-web>`","`<table>`"],"answer":0,"explain":"`<iframe>` tạo khung nội tuyến với `src` trỏ tới trang được nhúng. `<video>` chỉ nhận vào một tệp phim chứ không nhận cả một trang web. `<embed-web>` không phải là thẻ HTML. `<table>` dùng để trình bày dữ liệu theo hàng và cột."},{"id":"CC-mc-2303","type":"mc","topic":"E","grade":12,"level":"medium","question":"Cho đoạn mã: `<video src=\"clip.mp4\" width=\"400\" controls loop muted>Trình duyệt chưa mở được đoạn phim này.</video>`. Dòng chữ nằm giữa hai thẻ sẽ hiện ra khi nào?","options":["Luôn hiện ngay bên dưới khung phim, như một lời chú thích.","Hiện ra mỗi khi đoạn phim chạy hết một vòng và chuẩn bị lặp lại.","Hiện ra khi người xem bấm nút tắt tiếng.","Chỉ hiện ra khi trình duyệt không mở được đoạn phim."],"answer":3,"explain":"Nội dung viết giữa cặp thẻ `<video>` và `</video>` là phần dự phòng, chỉ hiện khi trình duyệt không hiển thị được đoạn phim. Nó không phải chú thích nên không luôn hiện; `loop` chỉ khiến phim lặp lại chứ không làm hiện dòng chữ; `muted` chỉ liên quan tới âm thanh."},{"id":"CC-mc-2304","type":"mc","topic":"E","grade":12,"level":"medium","question":"Muốn một đoạn phim ngắn tự phát ngay khi mở trang, chạy đi chạy lại liên tục và không phát ra tiếng, cần viết thêm bộ thuộc tính nào cho thẻ `<video>`?","options":["`controls` và `width`","`autoplay` và `controls`","`autoplay`, `loop` và `muted`","`loop`, `muted` và `controls`"],"answer":2,"explain":"`autoplay` cho tự phát, `loop` cho phát lặp lại, `muted` để tắt tiếng — đúng cả ba yêu cầu. Phương án 1 không có thuộc tính nào trong ba thuộc tính cần thiết. Phương án 2 có `autoplay` nhưng thiếu `loop` và `muted` nên phim chỉ chạy một lần và vẫn phát ra tiếng. Phương án 4 tuy có `loop` và `muted` nhưng thiếu `autoplay` nên phim đứng yên chờ người xem bấm nút; `controls` chỉ hiện thanh điều khiển, không liên quan tới việc tự phát."},{"id":"CC-mc-2305","type":"mc","topic":"E","grade":12,"level":"hard","question":"Nam muốn đưa một đoạn phim đang có sẵn trên một nền tảng chia sẻ video vào trang web của mình, nhưng Nam không hề có tệp phim đó trong máy. Cách làm hợp lí nhất là gì?","options":["Dùng `<video>` với `src` trỏ tới địa chỉ trang xem video của nền tảng đó.","Dùng `<iframe>` với `src` là địa chỉ nhúng do nền tảng đó cung cấp.","Dùng `<audio controls>` rồi đặt tên video vào giữa cặp thẻ.","Chép nguyên đường dẫn video vào giữa cặp thẻ `<video>` và `</video>`."],"answer":1,"explain":"Nền tảng chia sẻ video cung cấp một địa chỉ nhúng dạng trang web, nên phải dùng khung nội tuyến `<iframe>` để đặt trang phát video ấy vào trang của mình. Phương án 1 sai vì `src` của `<video>` cần một tệp phim (mp4, webm...), không phải một trang xem video. Phương án 3 sai vì `<audio>` chỉ dành cho âm thanh. Phương án 4 sai vì phần giữa cặp thẻ `<video>` chỉ là nội dung dự phòng khi trình duyệt không mở được phim, viết đường dẫn vào đó không làm phim chạy."},{"id":"CC-tf-2301","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Thuộc tính `controls` của thẻ `<video>` giúp hiện thanh điều khiển để người xem tự bấm phát, tạm dừng và chỉnh âm lượng.","correct":true},{"text":"Thẻ `<iframe>` chỉ dùng để chèn những tấm ảnh có kích thước lớn vào trang web.","correct":false},{"text":"Nếu tệp phim có định dạng mà trình duyệt không hỗ trợ thì dù thẻ `<video>` viết đúng cú pháp và đường dẫn chính xác, người xem vẫn không xem được.","correct":true},{"text":"Mọi tệp nhạc và video tìm thấy trên mạng đều được phép nhúng tự do vào trang web của mình, miễn là có ghi tên tác giả.","correct":false}],"explain":"(1) Đúng — `controls` là thuộc tính yêu cầu trình duyệt hiển thị thanh điều khiển phát/tạm dừng/âm lượng. (2) Sai — `<iframe>` tạo khung nội tuyến để nhúng cả một trang web khác (bản đồ, biểu mẫu, trang phát video); chèn ảnh là việc của thẻ `<img>`. (3) Đúng — trình duyệt chỉ mở được những định dạng nó giải mã được, nên chọn sai định dạng thì cú pháp có chuẩn đến đâu người xem cũng chỉ thấy khung trống. (4) Sai — tệp nhạc và video đều có bản quyền; ghi tên tác giả không thay thế được việc phải có quyền sử dụng, cần dùng sản phẩm tự làm hoặc tài nguyên có giấy phép cho phép."},{"id":"CC-mc-2401","type":"mc","topic":"E","grade":12,"level":"easy","question":"Trong HTML, cặp thẻ nào phải bao lấy toàn bộ các ô nhập của một biểu mẫu để dữ liệu có thể gửi đi được?","options":["`<table>` ... `</table>`","`<div>` ... `</div>`","`<form>` ... `</form>`","`<label>` ... `</label>`"],"answer":2,"explain":"Cặp thẻ `<form>` là ranh giới của một biểu mẫu: chỉ những ô nhập nằm bên trong nó mới được gom dữ liệu và gửi đi khi bấm nút gửi. `<table>` dùng để trình bày dữ liệu theo hàng cột, `<div>` chỉ là khối gom nhóm để dàn bố cục — cả hai đều không có khả năng gửi dữ liệu. `<label>` chỉ tạo nhãn mô tả cho một ô nhập chứ không bao cả biểu mẫu."},{"id":"CC-mc-2402","type":"mc","topic":"E","grade":12,"level":"easy","question":"Thuộc tính nào của thẻ `<input>` quyết định ô nhập đó là ô gõ chữ, ô mật khẩu, ô chọn ngày hay ô tích chọn?","options":["`type`","`name`","`value`","`id`"],"answer":0,"explain":"Chỉ có một thẻ `<input>` nhưng nó biến hoá thành nhiều kiểu ô nhập khác nhau tuỳ giá trị của `type` (`text`, `password`, `date`, `checkbox`...). `name` đặt tên cho dữ liệu gửi đi, `value` đặt giá trị sẵn có, còn `id` chỉ là định danh riêng để `<label>` hoặc CSS trỏ tới — không thuộc tính nào trong ba cái đó làm đổi kiểu ô nhập."},{"id":"CC-mc-2403","type":"mc","topic":"E","grade":12,"level":"medium","question":"Một biểu mẫu khảo sát có ba nút `<input type=\"radio\">` cho ba mức đánh giá, nhưng khi thử thì người dùng lại tích được cả ba nút cùng lúc. Nguyên nhân hợp lí nhất là gì?","options":["Thiếu thuộc tính `placeholder` ở cả ba nút","Ba nút đó chưa được đặt trong cặp thẻ `<label>`","Ba nút đó đang thiếu thuộc tính `required`","Ba nút đó có giá trị `name` khác nhau nên trình duyệt coi chúng là ba nhóm riêng biệt"],"answer":3,"explain":"Trình duyệt dựa vào thuộc tính `name` để biết các nút `radio` nào thuộc cùng một nhóm và loại trừ lẫn nhau; `name` khác nhau nghĩa là mỗi nút thành một nhóm riêng nên tích được hết. `placeholder` chỉ là chữ mờ gợi ý và không dùng cho `radio`; `<label>` chỉ tạo nhãn mô tả; còn `required` chỉ bắt buộc phải chọn chứ không hề quy định số mục được chọn."},{"id":"CC-mc-2404","type":"mc","topic":"E","grade":12,"level":"medium","question":"Để bấm vào dòng chữ 'Họ và tên:' thì con trỏ tự nhảy vào đúng ô nhập tương ứng, thuộc tính `for` của thẻ `<label>` phải trùng với thuộc tính nào của ô nhập đó?","options":["`name`","`id`","`value`","`type`"],"answer":1,"explain":"Mối nối giữa nhãn và ô nhập là cặp `for` của `<label>` trùng với `id` của ô nhập, vì `id` là định danh duy nhất trong trang. `name` chỉ là tên của dữ liệu khi gửi đi (nhiều ô có thể trùng `name`, như các nút `radio` cùng nhóm), `value` là giá trị chứa trong ô, còn `type` là kiểu ô nhập — không cái nào dùng để nối nhãn với ô."},{"id":"CC-mc-2405","type":"mc","topic":"E","grade":12,"level":"hard","question":"Cho đoạn mã: `<form action=\"xuli.php\" method=\"post\"> <input type=\"text\" placeholder=\"Số điện thoại\"> <input type=\"submit\" value=\"Gửi\"> </form>`. Người dùng gõ số điện thoại vào ô rồi bấm nút Gửi. Điều gì xảy ra?","options":["Số điện thoại được gửi tới `xuli.php` với tên dữ liệu là 'Số điện thoại'","Trình duyệt báo lỗi cú pháp và không hiển thị biểu mẫu","Biểu mẫu vẫn được gửi tới `xuli.php` nhưng số điện thoại vừa gõ không đi kèm, vì ô nhập thiếu thuộc tính `name`","Nút Gửi không có tác dụng vì chỉ thẻ `<button>` mới gửi được biểu mẫu"],"answer":2,"explain":"Trình duyệt chỉ gom và gửi dữ liệu của những ô nhập có thuộc tính `name`; ô ở đây chỉ có `placeholder` nên nội dung vừa gõ bị bỏ lại, biểu mẫu vẫn gửi đi nhưng rỗng. `placeholder` chỉ là chữ mờ gợi ý cho người nhìn, không bao giờ đóng vai trò tên dữ liệu, nên phương án đầu sai. Đoạn mã hoàn toàn đúng cú pháp nên không có lỗi hiển thị. Và `<input type=\"submit\">` cũng gửi được biểu mẫu y như `<button type=\"submit\">`."},{"id":"CC-tf-2401","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"`<input>` là thẻ tự đóng, không cần viết thẻ đóng `</input>` ở phía sau.","correct":true},{"text":"Thuộc tính `placeholder` vừa hiện chữ mờ gợi ý trong ô, vừa là tên dùng để nhận biết dữ liệu khi biểu mẫu được gửi đi.","correct":false},{"text":"Cặp thẻ `<textarea>` dùng để tạo ô nhập nhiều dòng, thích hợp cho những nội dung dài như lời nhắn hay góp ý.","correct":true},{"text":"Muốn tạo một danh sách thả xuống để chọn một mục, ta viết một thẻ `<input>` với `type` mang giá trị `dropdown`.","correct":false}],"explain":"(1) Đúng — `<input>` không bao nội dung nào bên trong nên được viết dưới dạng thẻ tự đóng, giống `<img>` hay `<br>`. (2) Sai — `placeholder` chỉ là chữ mờ gợi ý cho người nhìn và không được gửi đi; tên nhận biết dữ liệu luôn lấy từ thuộc tính `name`. (3) Đúng — `<textarea>` là cặp thẻ mở và đóng, tạo khung nhập nhiều dòng, có thể chỉnh kích thước bằng `rows` và `cols`. (4) Sai — danh sách thả xuống được tạo bằng cặp thẻ `<select>` chứa các thẻ `<option>` bên trong; `type` của `<input>` không hề có giá trị `dropdown`."},{"id":"CC-mc-2501","type":"mc","topic":"E","grade":12,"level":"easy","question":"Quy tắc CSS `h1, h2, p { font-family: Arial; }` có tác dụng gì?","options":["Chỉ áp dụng cho các phần tử `p` nằm bên trong `h1` và `h2`","Đặt phông Arial cho tất cả các phần tử `h1`, `h2` và `p` trên trang","Chỉ áp dụng cho phần tử nào mang đồng thời cả ba tên thẻ `h1`, `h2`, `p`","Chỉ áp dụng cho phần tử `h1` vì nó được viết đầu tiên trong danh sách"],"answer":1,"explain":"Dấu phẩy giữa các bộ chọn tạo thành bộ chọn nhóm: khai báo bên trong ngoặc nhọn được áp dụng cho từng bộ chọn một cách độc lập, nên cả `h1`, `h2` lẫn `p` đều đổi phông. Phương án chọn `p` nằm bên trong `h1`, `h2` là nhầm với bộ chọn hậu duệ (viết cách nhau bởi dấu cách, không có dấu phẩy). Không có phần tử nào mang cùng lúc ba tên thẻ, vì mỗi thẻ chỉ có đúng một tên. Việc viết đầu tiên hay cuối cùng trong nhóm không tạo ra khác biệt nào về phạm vi áp dụng."},{"id":"CC-mc-2502","type":"mc","topic":"E","grade":12,"level":"easy","question":"Lớp giả `:hover` trong quy tắc `a:hover { color: red; }` có ý nghĩa gì?","options":["Liên kết đổi sang màu đỏ khi con trỏ chuột được rê lên trên nó","Liên kết bị ẩn khỏi trang cho đến khi người dùng bấm vào","Liên kết luôn nổi lên phía trên các phần tử khác trong trang","Liên kết chỉ được tải xuống sau cùng khi trang đã hiển thị xong"],"answer":0,"explain":"`:hover` là lớp giả mô tả trạng thái đang có con trỏ chuột rê lên phần tử, nên định dạng trong quy tắc chỉ có hiệu lực trong đúng khoảng thời gian đó, rời chuột ra thì phần tử trở lại như cũ. Việc ẩn phần tử là do thuộc tính `display: none` hoặc `visibility`, không liên quan gì đến `:hover`. Việc xếp phần tử nổi lên trên do các thuộc tính về lớp chồng, cũng không phải nhiệm vụ của lớp giả. Thứ tự tải tài nguyên là chuyện của trình duyệt và HTML, CSS không điều khiển bằng `:hover`."},{"id":"CC-mc-2503","type":"mc","topic":"E","grade":12,"level":"medium","question":"Hai bộ chọn `div p` và `p.ghichu` khác nhau như thế nào?","options":["Cả hai đều chọn mọi phần tử `p` trên trang, chỉ khác nhau ở cách viết","`div p` chọn phần tử `div` có gắn lớp `p`; `p.ghichu` chọn mọi phần tử nằm trong lớp `ghichu`","`div p` chọn phần tử `p` đứng ngay sau thẻ `div`; `p.ghichu` chọn phần tử đứng ngay sau lớp `ghichu`","`div p` chọn mọi `p` nằm bên trong một `div`; `p.ghichu` chọn phần tử vừa đúng là thẻ `p` vừa có gắn lớp `ghichu`"],"answer":3,"explain":"Dấu cách giữa `div` và `p` tạo bộ chọn hậu duệ, nghĩa là chọn theo vị trí bên trong; còn khi viết dính liền `p.ghichu` thì hai điều kiện phải thoả mãn đồng thời trên cùng một phần tử, nên một thẻ `span` mang lớp `ghichu` sẽ không bị chọn. Phương án nói cả hai đều chọn mọi `p` là sai vì cả hai đều thu hẹp phạm vi so với bộ chọn `p` đơn thuần. Phương án đảo vai trò thẻ và lớp hiểu sai hoàn toàn cú pháp: chữ đứng trước dấu chấm là tên thẻ, chữ đứng sau dấu chấm mới là tên lớp. Phương án nói về phần tử đứng ngay sau là nhầm với quan hệ anh em kế tiếp, trong khi dấu cách chỉ quan hệ chứa bên trong."},{"id":"CC-mc-2504","type":"mc","topic":"E","grade":12,"level":"medium","question":"Thuộc tính CSS nào sau đây KHÔNG được kế thừa từ phần tử cha xuống các phần tử con?","options":["`color`","`border`","`font-family`","`font-size`"],"answer":1,"explain":"`border` thuộc nhóm thuộc tính mô tả khung bao quanh phần tử nên không kế thừa; nếu nó kế thừa thì đặt viền cho một `div` sẽ khiến mọi đoạn văn, mọi liên kết bên trong đều mọc thêm viền riêng, trang web sẽ rối loạn. Ngược lại, `color`, `font-family` và `font-size` đều là thuộc tính về chữ viết và đều có tính kế thừa, nhờ đó chỉ cần khai báo một lần cho `body` là gần như toàn bộ chữ trên trang đã đồng bộ. Các thuộc tính khác cùng nhóm với `border` và cũng không kế thừa gồm `margin`, `padding`, `background-color`."},{"id":"CC-mc-2505","type":"mc","topic":"E","grade":12,"level":"hard","question":"Cho tệp CSS viết theo đúng thứ tự sau: `#tbao { color: green; }` rồi `p.canhbao { color: orange; }` rồi `.canhbao { color: purple; }` rồi cuối cùng `p { color: blue; }`. Trên trang có phần tử `<p id=\"tbao\" class=\"canhbao\">Sắp hết hạn nộp bài</p>`. Chữ trong đoạn văn này hiển thị màu gì?","options":["Màu xanh dương, vì quy tắc `p { color: blue; }` được viết sau cùng nên ghi đè tất cả các quy tắc trước đó","Màu tím, vì `.canhbao { color: purple; }` được viết sau `p.canhbao { color: orange; }`","Màu xanh lá, vì bộ chọn id có mức ưu tiên cao nhất trong bốn quy tắc đang cùng tác động","Màu cam, vì `p.canhbao` là bộ chọn phối hợp nên cụ thể nhất trong bốn quy tắc"],"answer":2,"explain":"Cả bốn quy tắc đều nhắm trúng phần tử này, nên phải xét bậc thang ưu tiên trước: bộ chọn id `#tbao` đứng trên bộ chọn lớp và bộ chọn tên thẻ, vì vậy màu xanh lá thắng. Phương án màu xanh dương mắc bẫy phổ biến nhất: luật quy tắc viết sau thắng chỉ áp dụng khi hai quy tắc cùng mức ưu tiên, mà `p` chỉ là bộ chọn tên thẻ nên yếu nhất, dù đứng cuối tệp. Phương án màu tím so sánh đúng thứ tự viết nhưng `.canhbao` vẫn chỉ là bộ chọn lớp, thua id. Phương án màu cam đúng ở chỗ `p.canhbao` mạnh hơn `.canhbao` và `p`, nhưng bộ chọn phối hợp thẻ với lớp vẫn xếp dưới bộ chọn id."},{"id":"CC-tf-2501","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Bộ chọn `ul li` chọn mọi phần tử `li` nằm bên trong một phần tử `ul`.","correct":true},{"text":"Thuộc tính `margin` đặt cho phần tử cha sẽ tự động được kế thừa xuống mọi phần tử con bên trong.","correct":false},{"text":"Khi hai quy tắc CSS có cùng mức ưu tiên cùng tác động lên một phần tử thì quy tắc viết sau sẽ ghi đè quy tắc viết trước.","correct":true},{"text":"Một khai báo có gắn `!important` sẽ bị bộ chọn id ghi đè, vì bộ chọn id là mức ưu tiên cao nhất.","correct":false}],"explain":"(1) Đúng — hai bộ chọn viết cách nhau bởi dấu cách tạo thành bộ chọn hậu duệ, chọn phần tử nằm bên trong phần tử khác, nên `ul li` nhắm vào các mục danh sách nằm trong danh sách không thứ tự. (2) Sai — `margin` thuộc nhóm thuộc tính về khung (cùng với `border`, `padding`, `background-color`) và không có tính kế thừa; chỉ các thuộc tính về chữ như `color`, `font-family`, `font-size` mới tự truyền xuống phần tử con. (3) Đúng — bậc thang ưu tiên chỉ phân xử khi các quy tắc khác mức; khi đã ngang mức thì trình duyệt lấy quy tắc được đọc sau, nên sửa CSS mà không thấy đổi thường là do có quy tắc cũ nằm phía dưới đè lên. (4) Sai — ngược lại mới đúng: `!important` được đẩy lên trên tất cả các mức, thắng cả bộ chọn id lẫn khai báo viết trong thuộc tính `style` của thẻ, và chính vì phá vỡ trật tự ưu tiên thông thường nên nó khiến trang web khó bảo trì."},{"id":"CC-mc-2601","type":"mc","topic":"E","grade":12,"level":"easy","question":"Muốn một khung luôn chiếm 80% bề rộng của phần tử chứa nó, dù trang được xem trên điện thoại hay trên máy tính, nên khai báo thế nào?","options":["width: 80%;","width: 80px;","width: 80em;","height: 80%;"],"answer":0,"explain":"Đáp án đúng là `width: 80%;` vì `%` là đơn vị tương đối, tính theo bề rộng của phần tử cha, nên khung tự co giãn theo màn hình. `width: 80px;` sai vì `px` là đơn vị tuyệt đối — khung luôn rộng đúng 80 điểm ảnh, không liên quan gì đến kích thước màn hình. `width: 80em;` sai vì `em` tính theo cỡ chữ hiện hành chứ không theo bề rộng phần tử cha, và 80em là một con số rất lớn. `height: 80%;` sai vì đó là chiều cao, không phải bề rộng."},{"id":"CC-mc-2602","type":"mc","topic":"E","grade":12,"level":"easy","question":"Áp khai báo `border-radius: 50%;` cho một khung vuông kích thước 80 px × 80 px thì kết quả hiển thị sẽ là gì?","options":["Khung vẫn vuông nhưng thu nhỏ lại còn một nửa, tức 40 px × 40 px.","Khung biến thành một hình tròn.","Khung chỉ được bo tròn hai góc phía trên, hai góc dưới vẫn vuông.","Khung không thay đổi gì vì `border-radius` chỉ nhận giá trị theo `px`."],"answer":1,"explain":"Đáp án đúng là khung biến thành hình tròn: `border-radius` bo tròn cả bốn góc, giá trị càng lớn góc càng tròn, và với khung vuông thì `50%` là mức đủ để bốn góc gặp nhau tạo thành đường tròn hoàn chỉnh. Phương án thu nhỏ còn 40 px sai vì `border-radius` chỉ bo góc chứ không hề đổi kích thước khung. Phương án bo hai góc trên sai vì khi viết một giá trị duy nhất thì cả bốn góc đều được bo như nhau. Phương án cuối sai vì `border-radius` nhận được cả `px` lẫn `%`."},{"id":"CC-mc-2603","type":"mc","topic":"E","grade":12,"level":"medium","question":"Khai báo `padding: 8px 20px;` cho một nút bấm có ý nghĩa gì?","options":["Đệm trên 8 px, đệm phải 20 px, còn đệm dưới và đệm trái bằng 0.","Đệm trên và đệm dưới đều 8 px, đệm trái và đệm phải đều 20 px.","Đệm trên 8 px, ba phía còn lại đều 20 px.","Đệm trái 8 px, đệm phải 20 px, còn đệm trên và đệm dưới bằng 0."],"answer":1,"explain":"Đáp án đúng: khi viết gọn hai giá trị, giá trị đầu áp cho cặp trên – dưới, giá trị sau áp cho cặp trái – phải, nên nút có đệm dọc 8 px và đệm ngang 20 px. Phương án đầu nhầm với cách đọc bốn giá trị trên – phải – dưới – trái rồi bỏ trống hai giá trị cuối, nhưng cách viết gọn không bao giờ để phía nào bằng 0 một cách ngầm định. Phương án thứ ba mô tả kiểu ba giá trị và cũng hiểu sai vai trò của giá trị đầu. Phương án cuối đảo ngược thứ tự: giá trị đầu luôn thuộc về cặp trên – dưới chứ không phải phía trái."},{"id":"CC-mc-2604","type":"mc","topic":"E","grade":12,"level":"medium","question":"Một thẻ `<div>` đã có `width: 600px;` và nằm trong phần tử cha rộng hơn hẳn. Cần thêm khai báo nào để chiếc khung đó nằm chính giữa theo chiều ngang?","options":["text-align: center;","padding: 0 auto;","margin: 0 auto;","margin: auto 0;"],"answer":2,"explain":"Đáp án đúng là `margin: 0 auto;`: giá trị `auto` ở vị trí trái – phải khiến trình duyệt chia đều phần chỗ trống còn thừa sang hai bên, nhờ đó khối nằm giữa. `text-align: center;` sai vì nó chỉ canh giữa phần chữ và các phần tử nội tuyến bên trong khung, còn bản thân chiếc khung vẫn nằm sát lề trái. `padding: 0 auto;` sai vì `padding` không nhận giá trị `auto`. `margin: auto 0;` sai vì ở cách viết hai giá trị, `auto` đang rơi vào cặp trên – dưới, còn trái – phải bị đặt bằng 0 nên khung không hề dịch vào giữa."},{"id":"CC-mc-2605","type":"mc","topic":"E","grade":12,"level":"hard","question":"Một khung được khai báo `width: 240px; padding: 15px; border: 3px solid #333;` và không thay đổi cách tính kích thước mặc định. Chiếc khung này thực sự chiếm bề rộng bao nhiêu trên trang?","options":["240 px","258 px","270 px","276 px"],"answer":3,"explain":"Đáp án đúng là 276 px: theo cách tính mặc định (`content-box`), `width` chỉ tính vùng nội dung, nên phải cộng thêm đệm hai bên và viền hai bên: 240 + 15 + 15 + 3 + 3 = 276. Phương án 240 px sai vì đó là hiểu nhầm rằng `width` đã bao gồm cả đệm và viền — điều này chỉ đúng khi đặt `box-sizing: border-box`. Phương án 258 px sai vì chỉ cộng đệm và viền của một bên (240 + 15 + 3). Phương án 270 px sai vì cộng đủ đệm hai bên nhưng quên mất hai đường viền dày 3 px."},{"id":"CC-tf-2601","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Nếu chỉ khai báo `border-width: 2px;` và `border-color: #333;` mà không khai báo `border-style` thì đường viền vẫn không hiện ra trên trang.","correct":true},{"text":"Khai báo `margin: 12px 8px;` đặt lề trên 12 px, lề phải 8 px, còn lề dưới và lề trái bằng 0.","correct":false},{"text":"Khi đặt `box-sizing: border-box;`, giá trị của `width` được hiểu là đã bao gồm cả phần đệm và đường viền.","correct":true},{"text":"Giá trị `overflow: scroll` chỉ hiện thanh cuộn khi nội dung dài hơn khung, còn `overflow: auto` thì luôn hiện sẵn thanh cuộn.","correct":false}],"explain":"(1) Đúng — `border-style` mặc định là `none`, nên thiếu nó thì dù đã có độ dày và màu, trình duyệt vẫn không vẽ đường viền nào; đây là lỗi rất hay gặp khi mới học. (2) Sai — cách viết gọn hai giá trị nghĩa là giá trị đầu áp cho cặp trên – dưới (12 px) và giá trị sau áp cho cặp trái – phải (8 px), không có phía nào bằng 0. (3) Đúng — đó chính là điểm khác biệt của `border-box`: `width` tính cho cả chiếc khung nên phần nội dung tự co lại, giúp kiểm soát kích thước dễ dàng hơn. (4) Sai — hai giá trị bị mô tả ngược: `auto` mới là giá trị chỉ hiện thanh cuộn khi thật sự cần, còn `scroll` luôn chừa sẵn thanh cuộn kể cả khi nội dung ngắn."},{"id":"CC-mc-2701","type":"mc","topic":"G","grade":12,"level":"easy","question":"Dữ liệu có nhãn (labeled data) là loại dữ liệu như thế nào?","options":["Dữ liệu đã được sắp xếp theo thứ tự tăng dần trước khi đưa vào máy","Dữ liệu chỉ gồm các con số, không chứa chữ hay hình ảnh","Dữ liệu mà mỗi mẫu đã kèm sẵn đáp án đúng do con người gán từ trước","Dữ liệu được lưu trong tệp có đặt tên rõ ràng, dễ tìm lại"],"answer":2,"explain":"Nhãn chính là đáp án đúng đi kèm mỗi mẫu dữ liệu, do con người xác định trước — ví dụ mỗi email kèm sẵn ghi chú “thư rác” hay “không phải thư rác”, nên phương án thứ ba đúng. Phương án đầu nhầm “nhãn” với việc sắp xếp dữ liệu, hai việc hoàn toàn khác nhau: dữ liệu sắp xếp gọn gàng vẫn có thể không có đáp án đi kèm. Phương án thứ hai nhầm sang kiểu dữ liệu (số hay chữ), trong khi ảnh, âm thanh, văn bản đều có thể có nhãn. Phương án cuối nhầm “nhãn của dữ liệu” với “tên tệp” — đặt tên tệp là chuyện lưu trữ, không phải đáp án của từng mẫu."},{"id":"CC-mc-2702","type":"mc","topic":"G","grade":12,"level":"easy","question":"Bài toán phân cụm (clustering) là bài toán tiêu biểu của nhóm phương pháp nào?","options":["Học không giám sát","Học có giám sát","Học tăng cường","Lập trình truyền thống, không thuộc học máy"],"answer":0,"explain":"Phân cụm làm việc với dữ liệu KHÔNG có nhãn và tự tìm ra cấu trúc ẩn — đúng bản chất của học không giám sát, nên phương án đầu đúng. Học có giám sát bắt buộc phải có dữ liệu đã gắn nhãn để đối chiếu, điều mà bài toán phân cụm không hề có. Học tăng cường là học qua thử – sai với thưởng và phạt, không phải gom nhóm một tập dữ liệu cho sẵn. Phương án cuối sai vì phân cụm là một bài toán học máy thực thụ: máy tự rút ra cách chia nhóm từ dữ liệu chứ không chạy theo luật do người viết sẵn."},{"id":"CC-mc-2703","type":"mc","topic":"G","grade":12,"level":"medium","question":"Một hiệu sách trực tuyến có dữ liệu về lượt xem và lượt mua của 50 000 khách hàng, nhưng không có bất kì thông tin nào cho biết mỗi khách thuộc nhóm nào. Hiệu sách muốn máy tự tách khách thành vài nhóm có thói quen giống nhau. Đây là bài toán gì?","options":["Phân loại, vì kết quả cuối cùng là xếp khách vào các nhóm","Dự đoán số, vì phải tính ra doanh thu của từng khách hàng","Học tăng cường, vì máy phải thử nhiều cách rồi nhận thưởng hoặc phạt","Phân cụm, một bài toán thuộc học không giám sát"],"answer":3,"explain":"Dữ liệu không có nhãn và số nhóm cũng chưa được định trước, máy phải tự tách nhóm dựa trên độ tương tự — đó chính là phân cụm, thuộc học không giám sát, nên phương án cuối đúng. Phương án đầu là bẫy phổ biến nhất: kết quả tuy cũng là “các nhóm” nhưng phân loại đòi hỏi danh sách nhãn có sẵn do con người định nghĩa cùng dữ liệu huấn luyện đã gắn nhãn, ở đây hoàn toàn không có. Phương án thứ hai sai vì đề không yêu cầu ước lượng một con số nào cả. Phương án thứ ba sai vì không hề có cơ chế hành động — thưởng — phạt, mà chỉ có một bảng dữ liệu tĩnh cho sẵn."},{"id":"CC-mc-2704","type":"mc","topic":"G","grade":12,"level":"medium","question":"Điểm khác biệt cốt lõi giữa phân cụm và phân loại là gì?","options":["Phân loại chỉ làm được với dữ liệu số, còn phân cụm làm được với mọi loại dữ liệu","Phân loại có sẵn danh sách nhãn do con người định nghĩa trước, còn ở phân cụm các nhóm do máy tự tách ra và con người phải tự đặt tên cho chúng","Phân cụm luôn cho kết quả chính xác hơn phân loại vì máy không bị con người áp đặt","Phân cụm luôn chia dữ liệu thành đúng hai nhóm, còn phân loại chia thành nhiều nhóm"],"answer":1,"explain":"Khác biệt gốc rễ nằm ở chỗ có hay không có danh sách nhãn cho trước: phân loại chọn nhãn trong tập nhãn con người đã định nghĩa, còn phân cụm để máy tự tách nhóm rồi con người mới đặt tên và giải thích ý nghĩa từng cụm — nên phương án thứ hai đúng. Phương án đầu sai vì cả hai bài toán đều xử lí được nhiều dạng dữ liệu khác nhau, kiểu dữ liệu không phải tiêu chí phân biệt. Phương án thứ ba sai vì phân cụm không có nhãn đúng để đối chiếu nên không thể nói nó “chính xác hơn”; thậm chí hai lần chạy có thể cho hai cách chia khác nhau mà đều chấp nhận được. Phương án cuối sai vì số cụm hoàn toàn không bị giới hạn ở hai."},{"id":"CC-mc-2705","type":"mc","topic":"G","grade":12,"level":"hard","question":"Một trường THPT có bảng dữ liệu gồm thời gian tự học, số buổi đến thư viện và điểm trung bình của 800 học sinh. Nhà trường đặt ra hai yêu cầu: (I) dựa trên hồ sơ ba năm trước đã ghi rõ bạn nào đạt danh hiệu học sinh giỏi, hãy dự đoán một học sinh mới có đạt danh hiệu đó hay không; (II) tách 800 học sinh hiện tại thành vài nhóm có đặc điểm học tập giống nhau mà không định trước nhóm nào. Nhận định nào sau đây đúng?","options":["Cả (I) và (II) đều là học không giám sát, vì cùng khai thác một bảng dữ liệu của nhà trường","(I) là học không giám sát, còn (II) là học có giám sát","(I) là học có giám sát vì dữ liệu cũ đã có nhãn; (II) là học không giám sát, cụ thể là bài toán phân cụm","Cả (I) và (II) đều là phân cụm, vì kết quả của cả hai đều là các nhóm học sinh"],"answer":2,"explain":"Yêu cầu (I) có sẵn hồ sơ ba năm trước ghi rõ ai đạt danh hiệu, tức dữ liệu ĐÃ có nhãn, và mục tiêu là dự đoán nhãn cho học sinh mới — đó là học có giám sát; yêu cầu (II) không có nhãn nào, cũng không định trước nhóm, máy phải tự tách nhóm theo độ tương tự — đó là phân cụm, thuộc học không giám sát. Vì vậy phương án thứ ba đúng. Phương án đầu sai vì việc dùng chung một bảng dữ liệu không quyết định phương pháp; điều quyết định là bài toán đó có nhãn hay không. Phương án thứ hai đảo ngược hoàn toàn hai vế. Phương án cuối sai vì (I) không tách nhóm mới nào cả, nó chỉ gán một nhãn đã được định nghĩa sẵn cho từng học sinh."},{"id":"CC-tf-2701","type":"tf","topic":"G","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Học có giám sát cần dữ liệu huấn luyện đã được gắn nhãn sẵn để máy đối chiếu trong quá trình học.","correct":true},{"text":"Trong bài toán phân cụm, con người phải cho máy biết trước tên gọi và ý nghĩa của từng cụm.","correct":false},{"text":"Học không giám sát làm việc với dữ liệu không nhãn và tự tìm ra cấu trúc ẩn nằm sẵn trong dữ liệu.","correct":true},{"text":"Học tăng cường là cách máy học bằng việc được cung cấp sẵn nhãn đúng cho từng mẫu dữ liệu.","correct":false}],"explain":"(1) Đúng — bản chất của “giám sát” là luôn có đáp án đúng do con người gán sẵn để máy so kết quả dự đoán và tự điều chỉnh. (2) Sai — ngược lại mới đúng: máy tự tách các cụm dựa trên độ tương tự mà không biết gì về tên gọi, con người chỉ đặt tên và giải thích ý nghĩa SAU khi máy đã chia xong. (3) Đúng — đây chính là định nghĩa của học không giám sát: không có nhãn để đối chiếu nên nhiệm vụ là phát hiện trật tự ẩn trong dữ liệu, mà phân cụm là ví dụ tiêu biểu. (4) Sai — học từ nhãn có sẵn là học có giám sát; học tăng cường là học qua thử – sai, hành động tốt được thưởng, hành động dở bị phạt, thường gặp trong trò chơi và điều khiển rô-bốt."},{"id":"CC-mc-2801","type":"mc","topic":"G","grade":12,"level":"easy","question":"Trong một bảng dữ liệu khảo sát học sinh, mỗi hàng và mỗi cột thường tương ứng với điều gì?","options":["Mỗi hàng là một thuộc tính, mỗi cột là một quan sát","Mỗi hàng là một quan sát, mỗi cột là một thuộc tính","Mỗi hàng là một tệp dữ liệu, mỗi cột là một bảng con","Mỗi hàng và mỗi cột đều là một quan sát độc lập"],"answer":1,"explain":"Quy ước chuẩn của bảng dữ liệu là mỗi hàng ghi lại một đối tượng được quan sát (một học sinh trả lời phiếu), còn mỗi cột ghi một thuộc tính của đối tượng đó (lớp, phương tiện, thời gian) — nên phương án B đúng. Phương án A đảo ngược vai trò hàng và cột, dẫn tới hiểu sai toàn bộ cấu trúc bảng. Phương án C nhầm lẫn giữa đơn vị dữ liệu bên trong bảng với tệp và bảng, vốn là các khái niệm ở mức lớn hơn. Phương án D sai vì cột không phải là một quan sát; nếu cột cũng là quan sát thì bảng sẽ không còn phân biệt được đối tượng với thuộc tính của nó."},{"id":"CC-mc-2802","type":"mc","topic":"G","grade":12,"level":"easy","question":"Đặc điểm nào sau đây mô tả đúng định dạng tệp CSV?","options":["Là tệp nhị phân, chỉ mở được bằng một phần mềm bảng tính chuyên dụng","Chỉ lưu được duy nhất một cột dữ liệu trong mỗi tệp","Là tệp văn bản thuần, mỗi dòng ứng với một hàng của bảng, các giá trị ngăn cách bởi dấu phẩy","Tự động phát hiện và sửa các ô bị thiếu hoặc các dòng trùng lặp trong bảng"],"answer":2,"explain":"CSV là viết tắt của Comma-Separated Values: tệp lưu bảng dưới dạng văn bản thuần, mỗi dòng văn bản là một hàng và các giá trị cách nhau bởi dấu phẩy, nên phương án C đúng. Phương án A sai vì CSV không phải tệp nhị phân — chính vì là văn bản thuần nên mở được bằng cả trình soạn thảo văn bản đơn giản. Phương án B sai vì CSV lưu được bảng nhiều cột, đó mới là mục đích của nó. Phương án D là hiểu lầm phổ biến nhất: CSV chỉ lưu nguyên xi những gì được ghi vào, hoàn toàn không kiểm tra hay sửa lỗi hộ người dùng."},{"id":"CC-mc-2803","type":"mc","topic":"G","grade":12,"level":"medium","question":"Kiểm tra tệp khảo sát 400 phiếu, nhóm phát hiện 12 phiếu giống hệt nhau từng ô với 12 phiếu khác, do người trả lời bấm gửi hai lần. Cách xử lí phù hợp nhất là gì?","options":["Giữ nguyên tất cả, vì càng nhiều phiếu thì kết quả thống kê càng đáng tin","Xoá toàn bộ 24 phiếu liên quan, kể cả bản gửi lần đầu, cho chắc chắn","Điền giá trị trung bình của cả cột vào các phiếu bị trùng","Chỉ giữ lại đúng một bản cho mỗi phiếu và xoá các bản trùng còn lại"],"answer":3,"explain":"Bản ghi trùng lặp được xử lí bằng cách xoá bản trùng và giữ lại đúng một bản cho mỗi quan sát, nên phương án D đúng. Phương án A sai vì các phiếu lặp không mang thêm thông tin mới, chúng chỉ khiến những quan sát đó bị đếm hai lần và kéo lệch kết quả. Phương án B xử lí quá tay: bản gửi lần đầu là dữ liệu hợp lệ, xoá đi là mất mát thông tin thật. Phương án C nhầm cách xử lí của lỗi giá trị bị thiếu sang lỗi trùng lặp — ở đây các ô đều có giá trị, vấn đề nằm ở chỗ chúng bị ghi lặp."},{"id":"CC-mc-2804","type":"mc","topic":"G","grade":12,"level":"medium","question":"Cột thời gian đi từ nhà đến trường (tính bằng phút) có hầu hết giá trị nằm trong khoảng 5 đến 40, riêng một bản ghi có giá trị 400. Việc nên làm đầu tiên là gì?","options":["Kiểm tra lại bản ghi đó xem là lỗi nhập liệu hay là giá trị thật, rồi mới quyết định giữ hay bỏ","Xoá ngay bản ghi đó, vì giá trị nằm ngoài khoảng hợp lí thì chắc chắn là sai","Thay 400 bằng giá trị trung bình của cả cột để bảng trông đều đặn hơn","Bỏ hẳn cột thời gian vì cột này đã có giá trị lạ nên không còn đáng tin"],"answer":0,"explain":"Với giá trị bất thường, thao tác đúng là kiểm tra lại nguồn gốc của nó trước khi quyết định, vì nó có thể là lỗi gõ nhầm nhưng cũng có thể là một trường hợp đặc biệt có thật — nên phương án A đúng. Phương án B xoá vội, dễ làm mất những quan sát thật và khiến bức tranh dữ liệu bị méo. Phương án C còn tệ hơn: thay bằng trung bình là tự bịa ra một con số không ai cung cấp, làm sai lệch dữ liệu gốc. Phương án D loại bỏ cả cột chỉ vì một ô có vấn đề, tức là vứt đi đúng thuộc tính mà bài phân tích cần đến."},{"id":"CC-mc-2805","type":"mc","topic":"G","grade":12,"level":"hard","question":"Một nhóm chỉ gửi phiếu hỏi về thời gian tự học trong nhóm chat của đội tuyển học sinh giỏi, thu về 60 phiếu sạch, không thiếu ô nào, không trùng lặp, rồi kết luận: học sinh toàn trường tự học trung bình 3 giờ mỗi ngày. Nhận định nào đúng nhất?","options":["Kết luận đáng tin, vì dữ liệu đã sạch hoàn toàn và đủ 60 phiếu","Dữ liệu tuy sạch nhưng thiên lệch do nguồn thu thập không đại diện, nên kết luận không đúng cho toàn trường","Chỉ cần tăng số phiếu trong nhóm chat đó lên gấp đôi là kết luận sẽ trở nên chính xác","Lỗi ở đây là giá trị bất thường, cần loại bỏ các phiếu ghi trên 3 giờ rồi tính lại"],"answer":1,"explain":"Sạch và đại diện là hai chuyện khác nhau: bảng này không có ô trống, không trùng lặp, đúng định dạng, nhưng toàn bộ người trả lời đều là học sinh đội tuyển — một nhóm vốn tự học nhiều hơn mặt bằng chung — nên dữ liệu bị thiên lệch ngay từ khâu chọn nguồn, và kết luận không thể suy rộng ra toàn trường; phương án B đúng. Phương án A nhầm sạch với đại diện. Phương án C sai vì lấy thêm phiếu trong chính nhóm thiên lệch đó chỉ làm con số lệch thêm chắc chắn chứ không sửa được thiên lệch. Phương án D quy sai loại lỗi: các phiếu trên 3 giờ ở đây là dữ liệu thật của nhóm được hỏi, vấn đề nằm ở cách chọn người hỏi chứ không phải ở giá trị bất thường."},{"id":"CC-tf-2801","type":"tf","topic":"G","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Tệp CSV lưu bảng dữ liệu dưới dạng văn bản thuần nên có thể mở xem bằng một trình soạn thảo văn bản đơn giản.","correct":true},{"text":"Khi một cột số bị thiếu vài ô, cách duy nhất được phép làm là xoá toàn bộ những hàng có ô trống đó.","correct":false},{"text":"Nhật kí hoạt động của hệ thống và dữ liệu mở do cơ quan nhà nước công bố đều có thể trở thành nguồn dữ liệu cho một bài phân tích.","correct":true},{"text":"Nếu dữ liệu huấn luyện đã thiên lệch thì chỉ cần đổi sang một thuật toán học máy mạnh hơn là mô hình sẽ hết thiên lệch.","correct":false}],"explain":"(1) Đúng — CSV là văn bản thuần, mỗi dòng một hàng của bảng, các giá trị cách nhau bởi dấu phẩy, nên mở được bằng trình soạn thảo văn bản thông thường chứ không cần phần mềm chuyên dụng. (2) Sai — xoá hàng chỉ là một lựa chọn, và chỉ nên dùng khi hàng đó thiếu quá nhiều ô; nếu chỉ thiếu lác đác ở một cột số thì điền bằng giá trị trung bình của cột sẽ giữ lại được các thông tin còn lại của hàng. (3) Đúng — bên cạnh khảo sát trực tuyến và cảm biến, nhật kí hoạt động của hệ thống và dữ liệu mở là hai nguồn dữ liệu rất thông dụng. (4) Sai — mô hình chỉ học được từ đúng những gì có trong dữ liệu, nên dữ liệu thiên lệch sẽ cho mô hình thiên lệch theo bất kể thuật toán mạnh đến đâu; muốn khắc phục phải sửa từ khâu thu thập dữ liệu."},{"id":"CC-mc-2901","type":"mc","topic":"G","grade":12,"level":"easy","question":"Trong sổ theo dõi của thư viện trường có ghi dòng: “Ngày 5/10, lớp 12A mượn 23 cuốn sách”. Bản ghi này thuộc mức nào trong ba bậc dữ liệu – thông tin – tri thức?","options":["Dữ liệu, vì đó là bản ghi thô về một sự việc, chưa qua tổng hợp hay tính toán","Thông tin, vì nó đã cho biết một con số cụ thể","Tri thức, vì thư viện có thể dựa vào đó để mua thêm sách","Không thuộc mức nào, vì bản ghi có chứa chữ chứ không chỉ có số"],"answer":0,"explain":"Một dòng ghi lại đúng sự việc xảy ra, chưa qua tổng hợp hay tính toán, chính là dữ liệu thô. Nó chưa phải thông tin vì thông tin là kết quả tổng hợp từ nhiều bản ghi (ví dụ tổng số sách khối 12 mượn trong tháng, hay trung bình mỗi lớp mượn bao nhiêu cuốn). Nó càng chưa phải tri thức, vì tri thức là quy luật rút ra được để hành động — muốn có quy luật đó phải tổng hợp nhiều bản ghi chứ không thể dựa vào một dòng. Phương án cuối sai vì dữ liệu hoàn toàn có thể gồm cả chữ lẫn số."},{"id":"CC-mc-2902","type":"mc","topic":"G","grade":12,"level":"easy","question":"Một cột dữ liệu có vài giá trị lớn vượt trội hẳn so với phần còn lại. Đại lượng nào phản ánh trung thực hơn mức phổ biến của cột số đó?","options":["Tổng của cả cột","Giá trị lớn nhất","Trung bình cộng","Trung vị"],"answer":3,"explain":"Trung vị là giá trị đứng chính giữa khi đã sắp xếp dãy, nên một vài giá trị quá lớn hay quá nhỏ chỉ nằm ở hai đầu và gần như không làm nó xê dịch — vì thế trung vị mô tả đúng hơn mức thường gặp. Trung bình cộng thì ngược lại: mọi giá trị đều tham gia vào phép cộng nên một khoản đột biến sẽ kéo trung bình lệch hẳn đi (như ví dụ trung bình 100 nghìn trong khi phần lớn các bạn chỉ nộp 20–30 nghìn). Tổng chỉ cho biết quy mô chung, còn giá trị lớn nhất chính là phần tử đột biến gây lệch, nên cả hai đều không mô tả được mức phổ biến."},{"id":"CC-mc-2903","type":"mc","topic":"G","grade":12,"level":"medium","question":"Từ bảng ghi từng lượt mượn sách của thư viện (mỗi dòng gồm Ngày, Khối lớp, Thể loại, Số cuốn), muốn biết mỗi khối lớp đã mượn tổng cộng bao nhiêu cuốn trong tháng thì nên dùng thao tác nào?","options":["Lọc bảng theo điều kiện Số cuốn lớn hơn 0","Sắp xếp toàn bộ bảng tăng dần theo cột Ngày","Nhóm dữ liệu theo cột Khối lớp rồi tính tổng cột Số cuốn cho từng nhóm","Tính trung bình cộng của toàn bộ cột Số cuốn"],"answer":2,"explain":"Câu hỏi đòi một con số riêng cho từng khối lớp, tức là phải chia bảng thành các nhóm theo cột Khối lớp rồi mới tính thống kê trong từng nhóm — đó đúng là thao tác nhóm dữ liệu. Lọc theo điều kiện Số cuốn lớn hơn 0 gần như giữ nguyên cả bảng và vẫn không tách được các khối. Sắp xếp theo Ngày chỉ đổi thứ tự các dòng, không cộng gộp gì cả. Còn trung bình của toàn bộ cột chỉ cho một con số chung cho cả trường, không tách riêng được từng khối."},{"id":"CC-mc-2904","type":"mc","topic":"G","grade":12,"level":"medium","question":"Số cốc nước bán được của quầy câu lạc bộ trong 5 ngày lần lượt là: 30, 32, 28, 31, 129 (ngày cuối trùng hội chợ trường). Trung bình cộng và trung vị của dãy là bao nhiêu, và số nào mô tả đúng hơn mức bán thường ngày?","options":["Trung bình 50, trung vị 31 — trung vị 31 mô tả đúng hơn mức bán thường ngày","Trung bình 50, trung vị 31 — trung bình 50 mô tả đúng hơn mức bán thường ngày","Trung bình 31, trung vị 50 — trung vị 50 mô tả đúng hơn mức bán thường ngày","Trung bình 50, trung vị 28 — trung vị 28 mô tả đúng hơn mức bán thường ngày"],"answer":0,"explain":"Tổng của dãy là 30 + 32 + 28 + 31 + 129 = 250, chia cho 5 ngày được trung bình 50. Sắp xếp tăng dần ta có 28, 30, 31, 32, 129; dãy có 5 phần tử nên trung vị là giá trị đứng giữa, tức 31. Bốn ngày bình thường đều quanh mức 30 cốc, vậy trung vị 31 mới sát thực tế, còn trung bình 50 đã bị ngày hội chợ 129 cốc kéo lên cao. Phương án B đảo ngược nhận định, phương án C đổi chỗ hai đại lượng, phương án D lấy nhầm giá trị nhỏ nhất 28 làm trung vị."},{"id":"CC-mc-2905","type":"mc","topic":"G","grade":12,"level":"hard","question":"Một nhóm học sinh khảo sát 40 bạn cùng lớp và thấy: bạn nào dùng điện thoại nhiều giờ hơn trong ngày thì điểm bài kiểm tra thường thấp hơn. Kết luận nào là hợp lí nhất?","options":["Dùng điện thoại nhiều giờ chắc chắn là nguyên nhân làm điểm kiểm tra giảm","Trong nhóm 40 bạn được khảo sát, hai đại lượng biến thiên ngược chiều nhau; muốn nói về nguyên nhân thì cần thêm bằng chứng khác","Điểm kiểm tra thấp chính là nguyên nhân khiến học sinh dùng điện thoại nhiều hơn","Kết quả này đúng cho mọi học sinh trung học phổ thông trên cả nước"],"answer":1,"explain":"Dữ liệu mới chỉ cho thấy hai cột số biến thiên ngược chiều nhau, tức là có tương quan; tương quan không đồng nghĩa với nhân quả, vì rất có thể một yếu tố thứ ba (thời gian tự học, thói quen sinh hoạt, hoàn cảnh gia đình…) mới là nguyên nhân thật. Phương án A và C đều vội vàng gán quan hệ nhân quả theo hai chiều ngược nhau mà không có bằng chứng nào ngoài sự trùng hợp về xu hướng. Phương án D mắc lỗi vượt quá phạm vi dữ liệu: mẫu chỉ gồm 40 bạn trong một lớp, không đại diện cho học sinh cả nước."},{"id":"CC-tf-2901","type":"tf","topic":"G","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Với mọi dãy số liệu, trung vị luôn bằng trung bình cộng của dãy đó.","correct":false},{"text":"Lọc dữ liệu theo điều kiện chỉ giữ lại những dòng thoả mãn điều kiện, giúp thu hẹp bảng về đúng phần cần xem.","correct":true},{"text":"Tri thức là mức cao hơn thông tin: đó là quy luật, hiểu biết rút ra được để hành động và ra quyết định.","correct":true},{"text":"Vì máy tính tính toán chính xác nên mọi kết luận rút ra từ một bảng dữ liệu đều đúng cho cả những trường hợp nằm ngoài phạm vi dữ liệu đã thu thập.","correct":false}],"explain":"(1) Sai — hai đại lượng này chỉ tình cờ trùng nhau ở những dãy phân bố cân đối; với dãy 20, 30, 20, 50, 30, 20, 40, 30, 20, 740 thì trung bình là 100 còn trung vị chỉ là 30. (2) Đúng — lọc theo điều kiện giữ lại đúng những dòng thoả mãn, chẳng hạn lọc sổ bán hàng theo Buổi = 'Trưa' để chỉ xem các lượt bán buổi trưa. (3) Đúng — dữ liệu là bản ghi thô, thông tin là kết quả tổng hợp có ý nghĩa, còn tri thức là quy luật đủ chắc để dựa vào mà ra quyết định. (4) Sai — máy tính chỉ đảm bảo phép tính không nhầm, chứ không mở rộng được phạm vi áp dụng; kết luận rút ra chỉ có giá trị trong phạm vi thời gian, địa điểm và nhóm đối tượng mà dữ liệu đã thu thập."},{"id":"CC-mc-3001","type":"mc","topic":"G","grade":12,"level":"easy","question":"Một mô hình mô phỏng được lắp từ ba bộ phận nào?","options":["Các tham số đầu vào, các quy tắc/công thức mô tả cách hệ thống biến đổi, và các đại lượng đầu ra cần quan sát","Phần cứng máy tính, phần mềm mô phỏng và người sử dụng","Thu thập dữ liệu, làm sạch dữ liệu và trực quan hoá dữ liệu","Đề bài, thuật toán và ngôn ngữ lập trình được chọn"],"answer":0,"explain":"Đúng là phương án A: mọi mô hình mô phỏng đều gồm tham số đầu vào (số liệu ban đầu do người dùng đặt), quy tắc/công thức biến đổi qua từng bước, và đại lượng đầu ra để quan sát. Phương án B kể tên các thành phần của một hệ thống máy tính nói chung, không phải cấu tạo bên trong một mô hình. Phương án C là các bước của quy trình xử lí dữ liệu trong khoa học dữ liệu, khác hẳn với việc dựng mô hình. Phương án D là các bước giải một bài toán bằng lập trình, cũng không phải ba bộ phận của mô hình mô phỏng."},{"id":"CC-mc-3002","type":"mc","topic":"G","grade":12,"level":"easy","question":"Chạy một chương trình mô phỏng ba lần liên tiếp với cùng một bộ tham số đầu vào, kết quả ba lần lệch nhau một chút. Nhận định nào sau đây là hợp lí nhất?","options":["Chương trình chắc chắn bị lỗi, cần sửa lại công thức trong mô hình","Đây là mô phỏng ngẫu nhiên, nên cần chạy nhiều lần rồi lấy trung bình các kết quả","Máy tính không đủ mạnh nên tính toán bị sai lệch giữa các lần chạy","Các tham số đầu vào đã tự thay đổi sau mỗi lần chạy chương trình"],"answer":1,"explain":"Đúng là phương án B: kết quả hơi khác nhau qua mỗi lần chạy là dấu hiệu đặc trưng của mô phỏng ngẫu nhiên — trong mô hình có yếu tố may rủi, nên phải chạy nhiều lần rồi lấy trung bình thì con số mới đáng tin. Phương án A sai vì đó là bản chất của loại mô hình này chứ không phải lỗi lập trình. Phương án C sai vì sức mạnh máy tính chỉ ảnh hưởng tới tốc độ, không làm kết quả lệch đi như vậy. Phương án D sai vì tham số đầu vào do người dùng đặt và giữ nguyên; chính đề bài đã nói là cùng một bộ tham số."},{"id":"CC-mc-3003","type":"mc","topic":"G","grade":12,"level":"medium","question":"Với mô hình lan truyền tin trong trường, muốn biết yếu tố nào ảnh hưởng mạnh hơn tới tốc độ lan tin — số bạn biết tin ban đầu hay số bạn mà mỗi người kể lại mỗi ngày — thì cần làm thế nào?","options":["Đổi đồng thời cả hai tham số rồi xem kết quả đầu ra thay đổi bao nhiêu","Viết lại toàn bộ công thức của mô hình riêng cho từng yếu tố cần xét","Giữ nguyên mô hình, mỗi lần chỉ đổi một tham số rồi so sánh các kết quả đầu ra với nhau","Kéo bảng tính xuống thêm thật nhiều dòng để mô hình chạy được nhiều ngày hơn"],"answer":2,"explain":"Đúng là phương án C: chạy kịch bản giả định nghĩa là giữ nguyên mô hình, thay đổi lần lượt từng tham số đầu vào rồi so sánh các đầu ra để xem yếu tố nào tác động mạnh nhất. Phương án A sai vì đổi hai tham số cùng lúc thì dù kết quả có thay đổi cũng không biết là do tham số nào gây ra. Phương án B sai vì kịch bản giả định phải giữ nguyên quy tắc của mô hình, chỉ đổi tham số; viết lại công thức là tạo ra mô hình khác nên không còn so sánh được. Phương án D sai vì kéo dài bảng chỉ giúp quan sát thêm nhiều bước thời gian, không hề trả lời được câu hỏi yếu tố nào ảnh hưởng mạnh hơn."},{"id":"CC-mc-3004","type":"mc","topic":"G","grade":12,"level":"medium","question":"Khi dựng mô hình trên phần mềm bảng tính, vì sao nên đặt mỗi tham số vào một ô riêng rồi viết công thức tham chiếu tới ô đó, thay vì gõ thẳng con số vào trong công thức?","options":["Vì bảng tính không cho phép gõ trực tiếp con số vào bên trong công thức","Vì làm như vậy tệp bảng tính sẽ nhẹ hơn và mở nhanh hơn","Vì công thức tham chiếu tới ô luôn cho kết quả chính xác hơn công thức chứa số","Vì khi muốn thử một kịch bản khác, chỉ cần sửa một ô là toàn bộ mô hình tự tính lại"],"answer":3,"explain":"Đúng là phương án D: đặt tham số vào ô riêng chính là để chạy kịch bản giả định cho nhanh — sửa một ô, mọi dòng công thức phía dưới tự tính lại ngay, không phải sửa từng công thức. Phương án A sai vì bảng tính hoàn toàn cho phép gõ số trực tiếp trong công thức, chỉ là làm vậy thì rất khó sửa về sau. Phương án B sai vì dung lượng tệp gần như không đổi, đây không phải lí do. Phương án C sai vì hai cách viết cho ra cùng một kết quả tính toán; khác nhau nằm ở khả năng thay đổi và bảo trì, không phải ở độ chính xác."},{"id":"CC-mc-3005","type":"mc","topic":"G","grade":12,"level":"hard","question":"Một nhóm học sinh dựng mô hình lan truyền tin với giả thiết ‘mỗi ngày, mỗi bạn đã biết tin đều kể lại cho đúng 2 bạn chưa biết’. Mô hình dự đoán sau 5 ngày cả trường sẽ biết tin, nhưng theo dõi thực tế thì phải mất tới 9 ngày. Cách xử lí hợp lí nhất là gì?","options":["Kết luận rằng mô phỏng trên máy tính không dùng được cho những bài toán kiểu này","Đối chiếu kết quả mô phỏng với số liệu thực rồi điều chỉnh lại tham số hoặc quy tắc của mô hình cho khớp hơn","Giữ nguyên mô hình và cho rằng số liệu theo dõi thực tế đã bị đếm sai","Kéo bảng tính thêm thật nhiều dòng cho tới khi con số hiện ra đúng bằng 9 ngày"],"answer":1,"explain":"Đúng là phương án B: đây chính là cách kiểm tra độ tin cậy của mô hình — so kết quả mô phỏng với số liệu thực đã biết, thấy lệch thì hiệu chỉnh tham số (hạ số bạn được kể mỗi ngày xuống) hoặc sửa quy tắc (thêm khả năng có bạn quên không kể lại), rồi chạy lại. Phương án A sai vì lệch so với thực tế là chuyện bình thường của mọi mô hình, đó là tín hiệu để hiệu chỉnh chứ không phải lí do vứt bỏ công cụ. Phương án C sai vì trong đối chiếu, số liệu thực mới là chuẩn để so, không phải mô hình. Phương án D sai vì kéo thêm dòng không làm thay đổi tốc độ tăng do công thức quy định; hơn nữa sửa cho khớp một cách hình thức mà không sửa giả thiết thì mô hình vẫn sai về bản chất."},{"id":"CC-tf-3001","type":"tf","topic":"G","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trong một mô hình mô phỏng, tham số đầu vào là những số liệu ban đầu do người xây dựng mô hình đặt ra, còn quy tắc là phần mô tả cách hệ thống biến đổi qua từng bước.","correct":true},{"text":"Mô hình càng thêm nhiều giả thiết đơn giản hoá thì càng bám sát thực tế hơn.","correct":false},{"text":"Với mô phỏng tất định, chạy lại nhiều lần cùng một bộ tham số đầu vào luôn cho ra cùng một kết quả.","correct":true},{"text":"Khi mô hình chạy trơn tru và cho ra kết quả tròn trịa, đẹp mắt thì có thể kết luận ngay rằng mô hình phản ánh đúng thực tế.","correct":false}],"explain":"(1) Đúng — đó chính là vai trò của hai bộ phận đầu tiên: tham số đầu vào là số liệu ta tự do đặt và tự do đổi, còn quy tắc/công thức mô tả cách hệ thống chuyển từ bước này sang bước kế tiếp. (2) Sai — quan hệ ở đây là đánh đổi ngược chiều: càng nhiều giả thiết đơn giản hoá thì mô hình càng dễ dựng, dễ tính, nhưng càng xa thực tế nên kết quả càng phải đọc dè dặt. (3) Đúng — đây là dấu hiệu nhận biết mô phỏng tất định, và vì vậy chạy một lần là đủ; ngược lại mô phỏng ngẫu nhiên có yếu tố may rủi nên mỗi lần chạy cho kết quả hơi khác, phải chạy nhiều lần rồi lấy trung bình. (4) Sai — kết quả đẹp chỉ chứng tỏ công thức chạy trơn tru, không chứng tỏ các giả thiết đơn giản hoá là hợp lí; muốn tin được thì phải đối chiếu kết quả mô phỏng với số liệu thực đã biết rồi hiệu chỉnh lại mô hình."},{"id":"CC-tf-102","type":"tf","topic":"G","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Với những bài toán có quy tắc rõ ràng như sắp xếp một danh sách theo thứ tự tăng dần, cách lập trình liệt kê sẵn từng bước bằng câu lệnh điều kiện vẫn phù hợp và hiệu quả.","correct":true},{"text":"Đặc điểm chung của phần lớn hệ thống AI hiện nay là người lập trình phải liệt kê thủ công đầy đủ mọi trường hợp có thể xảy ra bằng các câu lệnh `if`, `else`.","correct":false},{"text":"Một lí do khiến cách liệt kê quy tắc thủ công khó áp dụng cho việc nhận dạng khuôn mặt là số trường hợp có thể xảy ra gần như vô hạn, không ai liệt kê hết được.","correct":true},{"text":"Vì học từ dữ liệu nên hệ thống AI hoạt động hoàn toàn không dựa trên bất kì phép tính nào của máy tính.","correct":false}],"explain":"(1) Đúng — với việc có quy tắc rõ ràng, việc viết sẵn từng bước bằng câu lệnh điều kiện là cách làm phù hợp. (2) Sai — đó chính là cách lập trình thông thường; điểm khác biệt của phần lớn AI hiện nay là tự học quy luật từ dữ liệu chứ không phải liệt kê thủ công từng luật. (3) Đúng — mỗi khuôn mặt một khác, số trường hợp gần như vô hạn nên không thể liệt kê hết bằng quy tắc viết tay. (4) Sai — AI vẫn chạy trên máy tính và đưa ra kết quả bằng các phép tính; \"học từ dữ liệu\" nói về cách hình thành quy luật, không có nghĩa là bỏ đi việc tính toán."},{"id":"CC-tf-103","type":"tf","topic":"G","grade":12,"level":"hard","question":"Xét độ tin cậy của một hệ thống AI học từ dữ liệu, cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Đã \"học từ dữ liệu\" thì hệ thống AI luôn cho kết quả đúng, không phụ thuộc vào chất lượng của dữ liệu dùng để huấn luyện.","correct":false},{"text":"Nếu dữ liệu huấn luyện bị thiếu đa dạng hoặc có sai lệch, kết quả dự đoán của hệ thống cũng có thể mang theo chính sai lệch đó.","correct":true},{"text":"Một hệ thống nhận diện khuôn mặt được huấn luyện chủ yếu với ảnh đủ ánh sáng có thể kém chính xác khi gặp ảnh chụp trong điều kiện thiếu sáng.","correct":true},{"text":"Khi gặp tình huống rất khác so với dữ liệu đã học, hệ thống AI vẫn luôn xử lí chính xác y như với dữ liệu quen thuộc.","correct":false}],"explain":"(1) Sai — học từ dữ liệu không bảo đảm luôn đúng; nếu dữ liệu kém chất lượng thì dự đoán cũng kém. (2) Đúng — chất lượng đầu ra phụ thuộc chất lượng dữ liệu, dữ liệu lệch thì kết quả lệch theo. (3) Đúng — hệ thống hoạt động tốt trong phạm vi giống dữ liệu đã học, gặp điều kiện khác (thiếu sáng) có thể sai lệch. (4) Sai — càng xa dữ liệu đã học thì hệ thống càng dễ sai, không thể luôn chính xác như với trường hợp quen thuộc."},{"id":"CC-tf-104","type":"tf","topic":"G","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trí tuệ nhân tạo là một nhánh của khoa học máy tính, hướng tới việc làm cho máy tính thực hiện những việc thường cần đến trí thông minh của con người.","correct":true},{"text":"Một hệ thống AI được huấn luyện để dịch thuật thì đương nhiên cũng tự biết lái xe mà không cần huấn luyện thêm cho việc lái xe.","correct":false},{"text":"Nhận ra một khuôn mặt trong ảnh hay nghe hiểu một câu nói là những việc thường được xem là cần đến trí thông minh của con người.","correct":true},{"text":"Khi trợ lí ảo trả lời một câu hỏi, có thể khẳng định nó đang suy nghĩ, có cảm xúc và mong muốn giống hệt như con người.","correct":false}],"explain":"(1) Đúng — đây là cách hiểu cơ bản về AI: một nhánh của khoa học máy tính nhằm làm những việc vốn cần trí thông minh của con người. (2) Sai — mỗi hệ thống AI hiện nay chỉ giỏi trong phạm vi hẹp đã được huấn luyện; giỏi dịch thuật không tự dưng biết lái xe. (3) Đúng — nhận diện khuôn mặt hay nghe hiểu câu nói đúng là những việc trước đây gần như chỉ con người mới làm được. (4) Sai — trợ lí ảo trả lời bằng một phép tính dựa trên dữ liệu đã học, không có ý thức, cảm xúc hay mong muốn như con người."},{"id":"CC-tf-202","type":"tf","topic":"G","grade":12,"level":"medium","question":"Xét các phát biểu về ứng dụng và lợi ích của AI trong đời sống:","statements":[{"text":"Phần mềm học thích ứng có thể theo dõi năng lực của từng người học để tự điều chỉnh độ khó bài tập và gợi ý nội dung cần ôn lại.","correct":true},{"text":"Hệ thống đèn tín hiệu thông minh điều chỉnh thời gian đèn theo một lịch cố định cài sẵn từ trước, hoàn toàn không dựa vào mật độ xe thực tế.","correct":false},{"text":"Một lợi ích chung của AI là xử lí được khối lượng dữ liệu rất lớn để tìm ra quy luật mà con người khó tổng hợp bằng mắt thường.","correct":true},{"text":"Vì AI xử lí công việc rất nhanh nên trong y tế cần để AI tự đưa ra kết luận và quyết định điều trị cuối cùng thay cho bác sĩ.","correct":false}],"explain":"(1) Đúng — phần mềm học thích ứng đúng là dạng ứng dụng AI trong giáo dục, bám sát năng lực từng người để điều chỉnh độ khó và gợi ý nội dung ôn tập. (2) Sai — điểm 'thông minh' của loại đèn này chính là tự điều chỉnh thời gian đèn theo mật độ xe thực tế nhằm giảm ùn tắc, chứ không chạy theo lịch cố định. (3) Đúng — xử lí được lượng dữ liệu lớn để tìm ra quy luật là một trong những lợi ích chung nổi bật của AI. (4) Sai — AI chỉ đóng vai trò hỗ trợ và đưa ra gợi ý ước lượng; quyết định cuối cùng, nhất là trong y tế, vẫn phải do con người đưa ra."},{"id":"CC-tf-203","type":"tf","topic":"G","grade":12,"level":"hard","question":"Xét các phát biểu về giới hạn và cách 'hiểu biết' của AI:","statements":[{"text":"AI hình thành 'hiểu biết' hoàn toàn từ dữ liệu huấn luyện, nên nó có thể lặp lại cả những sai sót hoặc định kiến vốn có sẵn trong dữ liệu đó.","correct":true},{"text":"Chỉ cần được cung cấp đủ nhiều dữ liệu, AI sẽ tự suy luận ra tri thức hoàn toàn mới nằm ngoài những gì đã có trong dữ liệu huấn luyện.","correct":false},{"text":"Khi gặp tình huống lạ chưa từng xuất hiện trong dữ liệu học, AI sẽ tự nhận biết giới hạn của mình và từ chối trả lời để tránh sai.","correct":false},{"text":"AI chủ yếu nhận diện khuôn mẫu lặp lại trong dữ liệu chứ không suy luận có ý thức, nên vẫn có thể đưa ra câu trả lời sai với giọng điệu rất tự tin.","correct":true}],"explain":"(1) Đúng — mọi 'hiểu biết' của AI đến từ dữ liệu huấn luyện, vì thế sai sót hay định kiến sẵn trong dữ liệu sẽ được AI phản chiếu lại. (2) Sai — AI không tự nghĩ ra tri thức mới mà chỉ phản chiếu những gì có trong dữ liệu; dữ liệu nhiều đến đâu cũng không tự sinh ra hiểu biết vượt ngoài dữ liệu đó. (3) Sai — trước tình huống lạ, AI vẫn thường đưa ra câu trả lời với giọng điệu chắc chắn chứ không tự nhận biết để từ chối; đây chính là điểm khiến nó rủi ro. (4) Đúng — AI nhận diện khuôn mẫu chứ không suy luận có ý thức như con người, nên có thể trả lời sai một cách rất tự tin."},{"id":"CC-tf-204","type":"tf","topic":"G","grade":12,"level":"medium","question":"Xét các phát biểu về rủi ro và cách dùng AI có trách nhiệm:","statements":[{"text":"Nhiều hệ thống AI cần thu thập lượng lớn dữ liệu cá nhân để hoạt động, nên tiềm ẩn nguy cơ xâm phạm quyền riêng tư nếu dữ liệu bị dùng sai mục đích hoặc rò rỉ.","correct":true},{"text":"Nguyên tắc dùng AI có trách nhiệm là tin tưởng hoàn toàn kết quả AI với các việc quan trọng như sức khoẻ, tiền bạc để tiết kiệm thời gian kiểm tra.","correct":false},{"text":"Những công việc có tính lặp lại và quy trình rõ ràng có nguy cơ dần được AI đảm nhận thay con người, ảnh hưởng đến việc làm.","correct":true},{"text":"Việc luôn dựa hoàn toàn vào gợi ý của AI mà không tự kiểm tra lại là hoàn toàn vô hại, vì AI đã tự xác minh thông tin chính xác giúp người dùng.","correct":false}],"explain":"(1) Đúng — để hoạt động, nhiều hệ thống AI thu thập nhiều dữ liệu cá nhân, kéo theo nguy cơ dữ liệu bị dùng sai mục đích hoặc rò rỉ, xâm phạm quyền riêng tư. (2) Sai — với những việc quan trọng như sức khoẻ, tiền bạc, pháp lí thì càng phải đối chiếu, kiểm chứng lại; dùng AI có trách nhiệm là xem kết quả như gợi ý tham khảo chứ không tin tuyệt đối. (3) Đúng — các công việc lặp lại, quy trình rõ ràng có nguy cơ dần được AI đảm nhận, ảnh hưởng đến việc làm. (4) Sai — phụ thuộc quá mức vào AI là một rủi ro thực sự; AI có thể trả lời sai, nên người dùng vẫn cần tự kiểm tra, xác minh lại thông tin."},{"id":"CC-tf-302","type":"tf","topic":"B","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Vai trò máy khách hay máy chủ được quyết định bởi loại thiết bị: điện thoại luôn là máy khách, còn máy tính cấu hình mạnh luôn là máy chủ.","correct":false},{"text":"Trong một lần trao đổi, bên chủ động gửi yêu cầu đóng vai máy khách, còn bên tiếp nhận và trả lại dữ liệu đóng vai máy chủ.","correct":true},{"text":"Cùng một chiếc máy tính có thể đóng vai máy khách khi truy cập một trang web, nhưng lại đóng vai máy chủ khi chia sẻ thư mục cho các máy khác trong nhà truy cập.","correct":true},{"text":"Một máy chủ bắt buộc phải là thiết bị chuyên dụng khác hẳn máy tính cá nhân thông thường thì mới có thể đảm nhiệm được vai trò của nó.","correct":false}],"explain":"(1) Sai — vai trò không do loại thiết bị quyết định mà do việc ai đang gửi yêu cầu, ai đang đáp ứng yêu cầu; một điện thoại vẫn có thể phục vụ dữ liệu cho máy khác, còn một máy tính mạnh vẫn có thể chỉ đi truy cập. (2) Đúng — bên chủ động gửi yêu cầu là máy khách, bên tiếp nhận rồi trả lại đúng thứ được yêu cầu là máy chủ. (3) Đúng — quan hệ khách – chủ gắn với việc ai gửi, ai đáp ứng trong từng tình huống, nên cùng một máy có thể lần lượt đóng cả hai vai. (4) Sai — máy chủ thường mạnh và luôn bật cho tiện phục vụ, nhưng một máy tính cá nhân thông thường vẫn có thể đóng vai máy chủ khi nó cung cấp dữ liệu hay dịch vụ cho máy khác."},{"id":"CC-tf-303","type":"tf","topic":"B","grade":12,"level":"hard","question":"Xét các phát biểu về cách dữ liệu được chia thành gói tin và truyền qua mạng:","statements":[{"text":"Các gói tin thuộc cùng một dữ liệu gốc bắt buộc phải đi chung một đường truyền và đến nơi nhận đúng theo thứ tự đã gửi.","correct":false},{"text":"Nhờ mỗi gói tin mang theo số thứ tự, thiết bị nhận vẫn ghép lại được đúng dữ liệu gốc dù các gói có thể đến nơi không theo trình tự ban đầu.","correct":true},{"text":"Việc chia dữ liệu lớn thành nhiều gói tin giúp giảm rủi ro: khi một đoạn đường truyền gặp lỗi, phần bị ảnh hưởng nhỏ hơn nhiều so với việc phải gửi lại toàn bộ khối dữ liệu.","correct":true},{"text":"Mỗi gói tin chỉ chứa đúng một phần dữ liệu gốc mà không kèm bất kỳ thông tin nào khác, vì địa chỉ và số thứ tự được gửi riêng trong một lần duy nhất trước đó.","correct":false}],"explain":"(1) Sai — các gói tin của cùng một dữ liệu có thể đi qua những đường khác nhau và đến nơi nhận không theo đúng thứ tự ban đầu, không hề bị buộc đi chung một đường. (2) Đúng — chính nhờ số thứ tự đi kèm mỗi gói mà nơi nhận biết gói nào là phần thứ mấy để ghép lại đúng trình tự, dù các gói đến lộn xộn. (3) Đúng — chia nhỏ giúp nếu một đoạn đường truyền nghẽn hay lỗi thì chủ yếu phần gói bị ảnh hưởng cần xử lý lại, thay vì phải gửi lại nguyên khối dữ liệu từ đầu. (4) Sai — mỗi gói tin luôn tự mang theo thông tin đi kèm ngay trong nó, quan trọng nhất là địa chỉ nơi gửi, nơi nhận và số thứ tự, chứ không phải chỉ gửi các thông tin đó một lần riêng lẻ."},{"id":"CC-tf-304","type":"tf","topic":"B","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Giao thức quy định cả cách gửi, cách nhận lẫn trình tự các bước trao đổi giữa các thiết bị, chứ không chỉ đơn thuần là tốc độ của đường truyền.","correct":true},{"text":"Chỉ cần máy chủ tuân theo giao thức là đủ; máy khách không cần biết hay tuân theo giao thức nào vẫn nhận được đúng dữ liệu.","correct":false},{"text":"Có thể ví giao thức trong mạng máy tính với quy định chung về cách viết địa chỉ của ngành bưu chính: nhờ mọi nơi cùng tuân theo một cách, việc chuyển tiếp mới diễn ra trơn tru.","correct":true},{"text":"Trên mạng chỉ tồn tại duy nhất một giao thức lo mọi việc; `HTTP` và `TCP/IP` thực chất chỉ là hai tên gọi khác nhau của cùng một giao thức đó.","correct":false}],"explain":"(1) Đúng — giao thức là bộ quy tắc chung quy định rõ cách gửi yêu cầu, cách trả lời và trình tự các bước, chứ không phải chỉ nói về tốc độ đường truyền. (2) Sai — để trao đổi được, cả hai bên đều phải cùng tuân theo giao thức chung; nếu máy khách không tuân theo thì máy chủ dù có tuân theo cũng không thể hiểu và đáp ứng đúng. (3) Đúng — giao thức đóng vai trò như quy định viết địa chỉ của bưu chính: mọi nơi cùng đọc và làm theo một cách thống nhất thì dữ liệu mới được chuyển tiếp đúng hướng, đến đúng đích. (4) Sai — trên mạng có nhiều giao thức, mỗi loại phụ trách một công việc riêng; `HTTP` lo việc trao đổi nội dung trang web, còn `TCP/IP` là nền tảng đánh địa chỉ và truyền dữ liệu, chúng là những giao thức khác nhau chứ không phải một."},{"id":"CC-tf-402","type":"tf","topic":"B","grade":12,"level":"medium","question":"Xét các phát biểu về vai trò của thiết bị mạng và đường đi của gói tin:","statements":[{"text":"Điểm phát wifi (`access point`) giúp điện thoại, laptop kết nối vào mạng mà không cần cắm dây.","correct":true},{"text":"Bộ định tuyến (`router`) đọc địa chỉ đích của gói tin để quyết định hướng chuyển tiếp giữa các mạng.","correct":true},{"text":"Một máy tính bàn nối dây vào mạng nội bộ vẫn phải gửi gói tin qua điểm phát wifi trước khi tới `router`.","correct":false},{"text":"Một `router` không thể vừa dẫn đường gói tin vừa phát sóng wifi, nên hai chức năng này luôn nằm ở hai thiết bị tách rời.","correct":false}],"explain":"(1) Đúng — điểm phát wifi phát sóng không dây, cho phép các thiết bị kết nối vào mạng mà không cần dây cắm. (2) Đúng — đây chính là vai trò dẫn đường của `router`: dựa vào địa chỉ đích để chọn hướng chuyển tiếp gói tin giữa các mạng, chẳng hạn giữa mạng trong nhà và Internet. (3) Sai — máy nối dây gửi gói tin thẳng qua đường dây (thường qua `switch` rồi tới `router`); sóng wifi chỉ dành cho thiết bị kết nối không dây, máy nối dây không đi qua điểm phát wifi. (4) Sai — nhiều `router` hiện nay đã tích hợp sẵn chức năng phát wifi, nên một thiết bị có thể vừa dẫn đường vừa phát sóng, không bắt buộc phải tách rời."},{"id":"CC-tf-403","type":"tf","topic":"B","grade":12,"level":"hard","question":"Xét các phát biểu về đường truyền có dây và không dây:","statements":[{"text":"Cáp quang truyền dữ liệu bằng ánh sáng đi trong sợi thuỷ tinh mảnh.","correct":true},{"text":"`wifi` và mạng di động `4G`/`5G` đều là đường truyền không dây, dùng sóng vô tuyến để mang dữ liệu.","correct":true},{"text":"Cáp xoắn đôi bằng đồng có giá thành cao hơn và khó lắp đặt hơn cáp quang.","correct":false},{"text":"Vì cáp quang nhanh hơn nên dây nối từ máy tính bàn tới `router` trong mọi mạng gia đình bắt buộc phải là cáp quang.","correct":false}],"explain":"(1) Đúng — cáp quang dẫn tín hiệu dưới dạng ánh sáng chạy trong sợi thuỷ tinh rất mảnh, nhờ đó truyền nhanh và xa với ít suy hao. (2) Đúng — cả `wifi` (phạm vi hẹp) lẫn mạng di động `4G`/`5G` (phạm vi rộng) đều thuộc nhóm đường truyền không dây, truyền dữ liệu bằng sóng vô tuyến. (3) Sai — ngược lại, cáp xoắn đôi bằng đồng mới là loại giá rẻ, dễ lắp đặt; cáp quang mới là loại hiện đại, chi phí cao hơn. (4) Sai — dây nối máy tính bàn tới `router` trong nhà thường chỉ cần cáp xoắn đôi bằng đồng là đủ dùng; việc chọn loại cáp tuỳ theo nhu cầu, không có quy định bắt buộc phải dùng cáp quang."},{"id":"CC-tf-404","type":"tf","topic":"B","grade":12,"level":"medium","question":"Xét các phát biểu về băng thông và cách chọn thiết bị, đường truyền:","statements":[{"text":"Băng thông thường được đo bằng đơn vị `Mbps` hoặc `Gbps`.","correct":true},{"text":"Với một người chỉ lướt web, nhắn tin, một đường truyền băng thông vừa phải đã đủ dùng, không nhất thiết chọn gói đắt nhất.","correct":true},{"text":"Băng thông chính là tổng dung lượng dữ liệu đang được lưu trữ trên một thiết bị mạng.","correct":false},{"text":"Khi chọn thiết bị mạng và đường truyền, nên luôn ưu tiên loại đắt tiền, hiện đại nhất để chắc chắn không bao giờ bị chậm.","correct":false}],"explain":"(1) Đúng — băng thông đo lượng dữ liệu tối đa truyền qua đường truyền trong mỗi giây, thường tính bằng `Mbps` (triệu bit mỗi giây) hoặc `Gbps` (tỉ bit mỗi giây). (2) Đúng — nhu cầu nhẹ như lướt web, nhắn tin không cần băng thông cao, nên một gói cước vừa phải đã đáp ứng đủ, chọn gói đắt nhất là lãng phí. (3) Sai — băng thông là lượng dữ liệu truyền được trong mỗi giây, không phải dung lượng lưu trữ; đây là hai khái niệm khác nhau, dễ nhầm lẫn. (4) Sai — việc chọn thiết bị và đường truyền nên bắt đầu từ nhu cầu sử dụng thực tế (số thiết bị, mục đích dùng), chứ không nhất thiết chọn loại đắt tiền, hiện đại nhất."},{"id":"CC-tf-502","type":"tf","topic":"B","grade":12,"level":"medium","question":"Xét các phát biểu về sơ đồ kết nối khi thiết kế một mạng LAN:","statements":[{"text":"Nên phác thảo sơ đồ đường đi của tín hiệu mạng trước khi tiến hành đi dây thật, để việc lắp đặt gọn gàng và ít phải sửa lại.","correct":true},{"text":"Trên đường đi của tín hiệu, đường truyền Internet từ nhà cung cấp dịch vụ đi vào `modem` trước, rồi mới tới `router` để phân phối cho mạng nội bộ.","correct":true},{"text":"Trong sơ đồ kết nối, `switch` phải luôn được đặt đứng trước `router` thì tín hiệu Internet mới đến được các máy.","correct":false},{"text":"`Access point` nằm ở đầu sơ đồ, có nhiệm vụ nhận trực tiếp đường truyền Internet từ nhà cung cấp dịch vụ rồi chuyển tiếp cho `modem`.","correct":false}],"explain":"(1) Đúng — vẽ trước sơ đồ đường đi của tín hiệu giúp xác định chỗ đặt máy, chỗ cần ổ cắm mạng, tránh phải đi dây nổi vòng vèo hay sửa đi sửa lại. (2) Đúng — thứ tự chuẩn là đường truyền vào `modem` trước, `modem` nối `router` để phân phối cho mạng nội bộ (nhiều thiết bị nay gộp chung modem và router). (3) Sai — `switch` đứng sau `router`, chỉ dùng để chia thêm cổng dây khi router không đủ cổng, không phải đứng trước router. (4) Sai — `access point` nằm ở cuối đường đi, chỉ phát sóng wifi cho thiết bị di chuyển; thiết bị nhận đường truyền đầu vào là `modem`, không phải access point."},{"id":"CC-tf-503","type":"tf","topic":"B","grade":12,"level":"hard","question":"Xét các phát biểu về vai trò của từng loại thiết bị trong một mạng LAN nhỏ:","statements":[{"text":"`Switch` dùng để chia thêm cổng dây cho mạng, nhưng bản thân nó không tạo ra kết nối Internet cho các thiết bị.","correct":true},{"text":"Nhiều `router` hiện nay đã tích hợp sẵn chức năng phát wifi, nên không phải mạng nào cũng cần mua thêm một `access point` riêng.","correct":true},{"text":"`Access point` là thiết bị nhận đường truyền Internet trực tiếp từ nhà cung cấp dịch vụ rồi chia dây tới từng máy tính bàn cố định.","correct":false},{"text":"Vì `switch` có nhiều cổng dây nên nó có thể thay thế hoàn toàn vai trò của `router` trong mọi mạng LAN.","correct":false}],"explain":"(1) Đúng — nhiệm vụ của `switch` là mở rộng số cổng dây; kết nối ra Internet là do `modem`/`router` đảm nhiệm, switch không tạo ra kết nối đó. (2) Đúng — khi router đã có wifi tích hợp và phạm vi phủ sóng đủ dùng thì một hộ nhỏ có thể không cần access point riêng. (3) Sai — nhận đường truyền đầu vào là `modem`, còn chia dây tới từng máy là router/switch; `access point` chỉ phát sóng không dây, không làm hai việc đó. (4) Sai — switch chỉ chia cổng, không nhận và phân phối đường truyền Internet như router, nên không thể thay thế router."},{"id":"CC-tf-504","type":"tf","topic":"B","grade":12,"level":"medium","question":"Xét các phát biểu về bước cấu hình và bảo đảm an toàn cho mạng LAN:","statements":[{"text":"Địa chỉ để các thiết bị nhận diện lẫn nhau trong mạng thường được `router` tự động cấp phát, người dùng không phải nhập tay cho từng máy.","correct":true},{"text":"Cập nhật `firmware` của router định kỳ giúp vá các lỗ hổng bảo mật mới được phát hiện.","correct":true},{"text":"Lấy chính dãy số ngày tháng năm sinh của mình làm mật khẩu wifi là một lựa chọn an toàn vì vừa dễ nhớ vừa khó đoán.","correct":false},{"text":"Đặt tên mạng (`SSID`) chỉ mang tính trang trí, không giúp ích gì cho việc nhận biết đúng mạng của mình để kết nối.","correct":false}],"explain":"(1) Đúng — sau khi lắp phần cứng, `router` thường tự động cấp phát địa chỉ cho từng thiết bị, người dùng không cần đặt tay từng máy. (2) Đúng — `firmware` là phần mềm điều khiển thiết bị; cập nhật định kỳ để vá các lỗ hổng bảo mật mới phát hiện. (3) Sai — dãy ngày tháng năm sinh là dãy số dễ đoán, người khác dễ dò ra; mật khẩu wifi mạnh cần kết hợp chữ, số và ký tự đặc biệt, tránh dãy dễ đoán. (4) Sai — `SSID` là tên mạng dễ nhận biết, giúp người dùng chọn đúng mạng của mình để kết nối, không chỉ là trang trí."},{"id":"CC-tf-602","type":"tf","topic":"D","grade":12,"level":"medium","question":"Xét các phát biểu về quyền riêng tư và dữ liệu cá nhân trong môi trường số:","statements":[{"text":"Dữ liệu cá nhân chỉ gồm những thông tin bí mật như mật khẩu hay số căn cước; còn họ tên và hình ảnh khuôn mặt đã đăng công khai thì không còn được xem là dữ liệu cá nhân.","correct":false},{"text":"Vị trí một người đang đứng, được ứng dụng ghi lại, cũng là một dạng dữ liệu cá nhân cần được bảo vệ.","correct":true},{"text":"Bảo vệ quyền riêng tư chỉ có nghĩa là giữ kín dữ liệu của bản thân, không liên quan gì tới cách mình xử lý dữ liệu của người khác.","correct":false},{"text":"Đăng ảnh chụp chung có mặt bạn bè lên mạng xã hội khi chưa hỏi ý kiến họ có thể xâm phạm quyền riêng tư của những người xuất hiện trong ảnh.","correct":true}],"explain":"(1) Sai — dữ liệu cá nhân là mọi thông tin gắn với một người cụ thể (họ tên, ngày sinh, hình ảnh khuôn mặt, số điện thoại, vị trí...), không giới hạn ở thông tin bí mật; một thông tin từng được đăng công khai vẫn là dữ liệu cá nhân của người đó. (2) Đúng — vị trí hiện tại gắn liền với một con người cụ thể nên cũng là dữ liệu cá nhân, cần cân nhắc khi cho phép ứng dụng thu thập. (3) Sai — nguyên tắc bảo vệ quyền riêng tư áp dụng theo hai chiều: vừa bảo vệ dữ liệu của chính mình, vừa tôn trọng, không tự ý thu thập hay phát tán dữ liệu của người khác. (4) Đúng — người trong ảnh có quyền quyết định hình ảnh của mình được chia sẻ hay không, nên đăng khi chưa hỏi ý kiến họ có thể xâm phạm quyền riêng tư của họ."},{"id":"CC-tf-603","type":"tf","topic":"D","grade":12,"level":"hard","question":"Xét các phát biểu về những hành vi bị pháp luật về an ninh mạng nghiêm cấm:","statements":[{"text":"Đăng nhập trái phép vào tài khoản mạng xã hội của người khác chỉ để ‘thử cho vui’, không thay đổi hay lấy cắp gì, thì không bị coi là vi phạm pháp luật.","correct":false},{"text":"Giả danh nhân viên ngân hàng gọi điện dụ người khác cung cấp mã `OTP` nhằm chiếm đoạt tiền trong tài khoản là hành vi bị nghiêm cấm.","correct":true},{"text":"Vì tin đồn lan trên mạng rất khó truy ra người đăng đầu tiên, nên việc phát tán thông tin sai sự thật gây hoang mang xã hội không thuộc nhóm hành vi bị cấm.","correct":false},{"text":"Tuỳ theo mức độ nghiêm trọng, một hành vi vi phạm pháp luật về an ninh mạng có thể bị xử phạt hành chính hoặc bị truy cứu trách nhiệm hình sự.","correct":true}],"explain":"(1) Sai — xâm nhập trái phép vào tài khoản, hệ thống của người khác khi chưa được cho phép đã là hành vi bị cấm, kể cả khi chỉ ‘thử cho vui’ và chưa gây thiệt hại rõ rệt. (2) Đúng — đây là hành vi lừa đảo chiếm đoạt tài sản, một trong những nhóm hành vi bị pháp luật về an ninh mạng nghiêm cấm. (3) Sai — khó truy ra người phát tán không làm cho hành vi trở nên hợp pháp; phát tán tin giả gây hoang mang, ảnh hưởng trật tự an toàn xã hội vẫn là hành vi bị cấm và có thể bị xử lý. (4) Đúng — tuỳ mức độ nghiêm trọng, người vi phạm có thể bị xử phạt hành chính hoặc bị truy cứu trách nhiệm hình sự."},{"id":"CC-tf-604","type":"tf","topic":"D","grade":12,"level":"medium","question":"Xét các phát biểu về bản quyền và sở hữu trí tuệ trong môi trường số:","statements":[{"text":"Bản quyền cho phép người tạo ra sản phẩm được quyết định ai được sao chép, chỉnh sửa hay phân phối lại sản phẩm đó.","correct":true},{"text":"Ảnh gắn nhãn `Creative Commons` được phép dùng lại mà không cần tuân theo bất kỳ điều kiện nào do tác giả đặt ra.","correct":false},{"text":"Dùng phần mềm bẻ khoá (`crack`) — bản đã bị chỉnh sửa trái phép để vượt qua cơ chế kiểm tra bản quyền — là hành vi xâm phạm bản quyền.","correct":true},{"text":"Chỉ cần ghi rõ tên tác giả thì được tự do sao chép và sử dụng lại mọi nội dung có bản quyền của người khác.","correct":false}],"explain":"(1) Đúng — bản quyền là quyền của người tạo ra sản phẩm, cho phép họ quyết định ai được sử dụng, sao chép, chỉnh sửa hay phân phối lại sản phẩm của mình. (2) Sai — `Creative Commons` là giấy phép cho phép dùng lại nội dung nhưng vẫn kèm theo một số điều kiện nhất định (ví dụ ghi nguồn, không dùng cho mục đích thương mại...), nên phải tuân theo các điều kiện đó chứ không phải dùng tuỳ ý. (3) Đúng — `crack` là bản chỉnh sửa trái phép nhằm vượt qua cơ chế kiểm tra bản quyền của phần mềm, nên sử dụng nó là hành vi vi phạm bản quyền. (4) Sai — ghi tên tác giả là cần thiết nhưng chưa đủ; muốn sử dụng lại vẫn phải được phép theo giấy phép hoặc điều khoản của nguồn, việc ghi nguồn không tự động cho phép sao chép mọi nội dung."},{"id":"CC-tf-702","type":"tf","topic":"E","grade":12,"level":"medium","question":"Xét bộ khung cơ bản của một trang HTML:","statements":[{"text":"`<!DOCTYPE html>` là một lời khai báo đặt ở dòng đầu, báo cho trình duyệt biết tài liệu viết theo chuẩn HTML5, chứ không phải một cặp thẻ mở/đóng.","correct":true},{"text":"Bên trong `<html>`, có thể đặt `<body>` lên trước `<head>` mà vẫn giữ đúng cấu trúc chuẩn của một trang HTML.","correct":false},{"text":"Cả `<head>` lẫn `<body>` đều nằm bên trong cặp `<html>...</html>` bao trùm toàn trang.","correct":true},{"text":"`<!DOCTYPE html>` cần một thẻ đóng tương ứng đặt ở cuối trang thì trình duyệt mới hiểu được.","correct":false}],"explain":"(1) Đúng — `<!DOCTYPE html>` là lời khai báo chuẩn đặt ở dòng đầu tiên, không phải cặp thẻ mở/đóng như các phần còn lại. (2) Sai — trong bộ khung chuẩn, `<head>` luôn đứng trước `<body>`; đảo thứ tự là lồng thẻ sai. (3) Đúng — `<html>` bao trùm toàn trang, `<head>` và `<body>` là hai phần nối tiếp nhau bên trong nó. (4) Sai — `<!DOCTYPE html>` chỉ là một lời khai báo viết một lần, không có và không cần thẻ đóng."},{"id":"CC-tf-703","type":"tf","topic":"E","grade":12,"level":"hard","question":"Xét đoạn mã đặt trong phần thân trang: `<body><h1>Chào</h1><br><p>Thân bài</p></body>`","statements":[{"text":"`<br>` ở đây là thẻ tự đóng dùng để xuống dòng, nên không cần viết kèm `</br>`.","correct":true},{"text":"Bản thân các thẻ `<h1>` và `<p>` cũng sẽ hiện ra thành chữ trên trang, nằm cạnh nội dung mà chúng bao.","correct":false},{"text":"`<h1>` và `<p>` là các cặp thẻ, mỗi cặp gồm một thẻ mở và một thẻ đóng bao lấy nội dung.","correct":true},{"text":"Vì `<br>` thiếu thẻ đóng nên trình duyệt sẽ báo lỗi và bỏ qua toàn bộ phần còn lại của đoạn.","correct":false}],"explain":"(1) Đúng — `<br>` không bao nội dung nên là thẻ tự đóng, chỉ viết một lần, không có `</br>`. (2) Sai — thẻ chỉ là dấu đánh dấu để mô tả cấu trúc; trình duyệt đọc thẻ để định dạng chứ không in các kí hiệu thẻ ra màn hình. (3) Đúng — `<h1>...</h1>` và `<p>...</p>` đều là cặp thẻ mở và đóng bao quanh nội dung. (4) Sai — `<br>` vốn là thẻ tự đóng hợp lệ, không hề gây lỗi; phần còn lại vẫn hiển thị bình thường."},{"id":"CC-tf-704","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trang web chỉ MỘT tài liệu đơn lẻ mà trình duyệt đọc và hiển thị, còn website chỉ CẢ tập hợp nhiều trang liên kết với nhau.","correct":true},{"text":"Một tập hợp phải gồm ít nhất năm trang web thì mới đủ điều kiện được gọi là một website.","correct":false},{"text":"Một trang web có thể chứa đường liên kết cho phép người xem bấm để nhảy sang một trang khác.","correct":true},{"text":"Việc quy định màu sắc và phông chữ cho trang cũng do chính HTML đảm nhận, không cần đến ngôn ngữ nào khác.","correct":false}],"explain":"(1) Đúng — \"trang web\" chỉ một tài liệu riêng lẻ, \"website\" chỉ tập hợp nhiều trang liên kết với nhau qua chung một địa chỉ gốc. (2) Sai — không có con số cố định nào; website chỉ cần gồm các trang liên kết với nhau, có thể nhiều hoặc ít. (3) Đúng — điểm đặc trưng của trang web là có thể chứa đường liên kết để bấm sang trang khác. (4) Sai — HTML chỉ dựng bộ khung và cấu trúc; việc trình bày màu sắc, phông chữ là nhiệm vụ của một ngôn ngữ khác (CSS)."},{"id":"CC-tf-802","type":"tf","topic":"E","grade":12,"level":"medium","question":"Xét cách dùng hai thẻ nhấn mạnh chữ bên trong đoạn văn:","statements":[{"text":"Thẻ `<strong>` làm cho phần chữ nằm giữa nó được in đậm, còn `<em>` làm cho phần chữ được in nghiêng.","correct":true},{"text":"Trong đoạn `<p>Hạn nộp là <strong>thứ Sáu</strong>, nhớ nhé.</p>`, chỉ có cụm chữ ‘thứ Sáu’ được in đậm, phần còn lại vẫn là chữ thường.","correct":true},{"text":"Vì `<strong>` và `<em>` bao ngoài phần chữ cần nhấn, nên cả một thẻ `<p>` phải được đặt bên trong `<strong>` thì chữ trong đoạn mới đậm lên.","correct":false},{"text":"Muốn cả một đoạn văn được tách riêng và nhấn mạnh, ta dùng thẻ `<em>` để tạo ra đoạn văn đó thay cho thẻ `<p>`.","correct":false}],"explain":"(1) Đúng — `<strong>` in đậm, `<em>` in nghiêng, cả hai chỉ tác động lên phần chữ nằm giữa thẻ mở và thẻ đóng. (2) Đúng — hai thẻ `<strong>` chỉ bao đúng cụm ‘thứ Sáu’, nên duy nhất cụm này in đậm, phần chữ ngoài cặp thẻ vẫn hiển thị bình thường. (3) Sai — ngược lại: `<strong>` và `<em>` nằm gọn bên trong `<p>` và chỉ ôm lấy phần chữ cần nhấn, chứ không bao trọn cả đoạn văn; đặt `<p>` vào trong `<strong>` là lồng sai. (4) Sai — `<em>` chỉ làm chữ in nghiêng để nhấn giọng, nó không có chức năng tạo đoạn văn; muốn tách một đoạn riêng vẫn phải dùng `<p>`."},{"id":"CC-tf-803","type":"tf","topic":"E","grade":12,"level":"medium","question":"Xét sự khác nhau giữa hai kiểu danh sách trong HTML:","statements":[{"text":"`<ol>` cho trình duyệt tự đánh số 1, 2, 3... cho các mục, còn `<ul>` đánh dấu mỗi mục bằng một chấm tròn phía trước.","correct":true},{"text":"Nếu giữ nguyên các mục nhưng đổi thẻ bao ngoài từ `<ol>` thành `<ul>`, các mục sẽ mất số thứ tự và chuyển sang hiển thị bằng dấu chấm tròn.","correct":true},{"text":"Khi liệt kê các bước pha một cốc trà theo đúng trình tự trước sau, nên dùng `<ul>` vì thứ tự các bước không quan trọng.","correct":false},{"text":"Điểm khác nhau giữa `<ul>` và `<ol>` là `<ul>` bọc mỗi mục bằng thẻ `<li>`, còn `<ol>` bọc mỗi mục bằng một loại thẻ mục con khác.","correct":false}],"explain":"(1) Đúng — đây chính là điểm phân biệt: `<ol>` là danh sách có thứ tự nên tự đánh số, `<ul>` là danh sách không thứ tự nên chỉ có dấu chấm tròn. (2) Đúng — thẻ bao ngoài quyết định cách hiển thị mục, nên đổi `<ol>` thành `<ul>` sẽ mất số thứ tự và chuyển sang chấm tròn, dù nội dung các mục không đổi. (3) Sai — các bước pha trà có trình tự bắt buộc nên thứ tự rất quan trọng; trường hợp này phải dùng `<ol>` để đánh số, không dùng `<ul>`. (4) Sai — cả hai kiểu danh sách đều dùng chung một loại thẻ mục con là `<li>`; khác biệt chỉ nằm ở thẻ bao ngoài `<ul>` hay `<ol>`, không phải ở thẻ mục con."},{"id":"CC-tf-804","type":"tf","topic":"E","grade":12,"level":"hard","question":"Xét cấu trúc khung của một trang HTML và quy tắc lồng thẻ:","statements":[{"text":"Chữ đặt trong thẻ `<title>` hiện trên thanh tab của trình duyệt, chứ không hiển thị trực tiếp trên thân trang.","correct":true},{"text":"Theo quy tắc lồng thẻ, thẻ nào mở sau thì phải được đóng trước thẻ đã mở trước nó.","correct":true},{"text":"Mọi nội dung mà người đọc nhìn thấy trên trang đều phải đặt bên trong `<head>`.","correct":false},{"text":"Cách viết `<p><strong>Chú ý</p></strong>` là lồng thẻ đúng quy tắc.","correct":false}],"explain":"(1) Đúng — `<title>` nằm trong `<head>`, phần này chứa thông tin không hiện trên thân trang; nội dung `<title>` chỉ hiển thị ở tab trình duyệt. (2) Đúng — thứ tự đóng phải ngược với thứ tự mở, nên thẻ mở sau luôn phải đóng trước, đây chính là nguyên tắc lồng thẻ. (3) Sai — nội dung người đọc nhìn thấy phải nằm trong `<body>`; `<head>` chỉ chứa thông tin không hiển thị trực tiếp như `<title>`. (4) Sai — ở đây `<strong>` mở sau `<p>` nhưng lại đóng sau `</p>`, vi phạm quy tắc ‘mở sau đóng trước’; viết đúng phải là `<p><strong>Chú ý</strong></p>`."},{"id":"CC-tf-902","type":"tf","topic":"E","grade":12,"level":"medium","question":"Xét các phát biểu về thẻ `<img>` và các thuộc tính của nó:","statements":[{"text":"Thuộc tính `src` chỉ được phép ghi tên một tệp ảnh nằm cùng thư mục với trang, không thể trỏ tới thư mục con hay một địa chỉ trên mạng.","correct":false},{"text":"Khi đường dẫn trong `src` bị sai và ảnh không tải được, trình duyệt sẽ hiển thị đoạn chữ ghi trong `alt` để thay cho tấm ảnh.","correct":true},{"text":"Thuộc tính `width` được tính bằng pixel, có thể dùng để thu nhỏ kích thước hiển thị của một ảnh gốc quá lớn cho vừa với trang.","correct":true},{"text":"Vì `<img>` là thẻ tự đóng nên bắt buộc phải có phần nội dung mô tả ảnh đặt giữa `<img>` và `</img>`.","correct":false}],"explain":"(1) Sai — `src` có thể là tên tệp cùng thư mục, đường dẫn tới một thư mục con, hoặc cả một địa chỉ đầy đủ trên mạng, không bị bó buộc trong cùng thư mục. (2) Đúng — đây chính là vai trò của `alt`: khi ảnh lỗi hoặc sai đường dẫn, đoạn chữ mô tả trong `alt` hiện ra thay cho ảnh. (3) Đúng — `width` tính theo pixel, dùng để chỉnh kích thước hiển thị, thường là thu nhỏ ảnh gốc quá lớn. (4) Sai — thẻ tự đóng nghĩa là không bao nội dung nào ở giữa và không có thẻ đóng `</img>`; mọi thông tin về ảnh nằm trong các thuộc tính."},{"id":"CC-tf-903","type":"tf","topic":"E","grade":12,"level":"hard","question":"Xét một bảng thi đua giữa các tổ được tạo như sau: bên trong `<table>` có ba cặp `<tr>`; hàng đầu gồm ba ô tiêu đề `<th>Tổ</th>`, `<th>Tuần 1</th>`, `<th>Tuần 2</th>`; mỗi hàng trong hai hàng còn lại gồm ba ô `<td>` ghi tên tổ và điểm hai tuần. Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Bảng trên có 3 hàng và 3 cột.","correct":true},{"text":"Bảng trên có 9 cột, vì đếm tổng cộng có 9 ô trong cả bảng.","correct":false},{"text":"Ba ô ở hàng đầu tiên dùng thẻ `<th>` nên thường được hiển thị chữ đậm, căn giữa và đóng vai trò tiêu đề cho từng cột bên dưới.","correct":true},{"text":"Nếu xoá bớt một cặp `<td>` ở hàng cuối, hàng đó vẫn thẳng cột với các hàng trên vì số cột đã được `<table>` cố định ngay từ đầu.","correct":false}],"explain":"(1) Đúng — số hàng bằng số cặp `<tr>` (3 hàng), số cột bằng số ô trong mỗi hàng (3 ô, tức 3 cột). (2) Sai — 9 là tổng số ô của cả bảng, không phải số cột; số cột chỉ đếm theo số ô trong một hàng, ở đây là 3. (3) Đúng — `<th>` là ô tiêu đề, mặc định chữ đậm và căn giữa, thường đặt ở hàng đầu để chú thích ý nghĩa mỗi cột. (4) Sai — số cột không được `<table>` cố định sẵn mà hình thành từ số ô trong mỗi hàng; xoá một `<td>` khiến hàng đó thiếu ô và bị lệch cột so với các hàng khác."},{"id":"CC-tf-904","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trong cấu trúc một bảng, thứ tự lồng đúng là ô `<td>` nằm trong `<tr>`, còn `<tr>` nằm trong `<table>`.","correct":true},{"text":"Có thể đặt trực tiếp một `<td>` ngay bên trong `<table>` mà không cần nằm trong một `<tr>` nào.","correct":false},{"text":"Hàng chứa các ô `<th>` thường được đặt làm hàng đầu tiên để người xem biết mỗi cột bên dưới mang ý nghĩa gì.","correct":true},{"text":"Muốn bảng có thêm nhiều cột hơn, ta chỉ cần viết thêm nhiều cặp `<tr>` vào trong `<table>`.","correct":false}],"explain":"(1) Đúng — bảng gồm ba lớp lồng nhau: `<table>` bao ngoài, `<tr>` là một hàng bên trong, `<td>`/`<th>` là một ô bên trong hàng. (2) Sai — mỗi ô phải nằm trong một `<tr>`; không thể đặt `<td>` trực tiếp trong `<table>` mà bỏ qua hàng. (3) Đúng — hàng `<th>` thường đặt ngay sau khi mở `<table>` để làm tiêu đề, giúp người xem hiểu ý nghĩa từng cột. (4) Sai — thêm cặp `<tr>` chỉ tạo thêm hàng; muốn thêm cột phải thêm ô `<th>`/`<td>` vào trong mỗi hàng."},{"id":"CC-tf-1002","type":"tf","topic":"E","grade":12,"level":"medium","question":"Xét cú pháp của một quy tắc CSS, cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trong một quy tắc CSS, các khai báo được đặt bên trong cặp ngoặc nhọn `{ }`.","correct":true},{"text":"Mỗi khai báo có dạng `thuộc-tính: giá-trị;` và kết thúc bằng dấu chấm phẩy.","correct":true},{"text":"Bên trong một quy tắc CSS chỉ được phép viết đúng một khai báo duy nhất.","correct":false},{"text":"Trong một khai báo, thuộc tính và giá trị được ngăn cách với nhau bởi dấu chấm phẩy.","correct":false}],"explain":"(1) Đúng — phần thân của quy tắc, tức các khai báo, luôn nằm giữa cặp ngoặc nhọn đứng sau bộ chọn. (2) Đúng — mỗi khai báo gồm thuộc tính, dấu hai chấm, giá trị và kết thúc bằng dấu chấm phẩy, ví dụ `color: blue;`. (3) Sai — một quy tắc có thể chứa nhiều khai báo, mỗi khai báo trên một dòng và cùng nằm trong cặp ngoặc nhọn, chẳng hạn vừa đặt `color` vừa đặt `font-size`. (4) Sai — thứ ngăn cách thuộc tính với giá trị là dấu hai chấm; dấu chấm phẩy chỉ dùng để kết thúc khai báo."},{"id":"CC-tf-1003","type":"tf","topic":"E","grade":12,"level":"hard","question":"Xét ba cách gắn CSS vào trang web, cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Viết CSS trong thuộc tính `style` ngay tại một thẻ thì chỉ ảnh hưởng đến đúng thẻ chứa nó.","correct":true},{"text":"Đặt các quy tắc trong cặp `<style>...</style>` ở phần `<head>` sẽ tự động áp dụng cho tất cả các trang của website.","correct":false},{"text":"Nhiều trang HTML có thể cùng liên kết tới một file `.css`; sửa file đó thì các trang cùng thay đổi theo.","correct":true},{"text":"Để liên kết một file `.css` bên ngoài vào trang, người ta đặt file đó vào bên trong cặp thẻ `<style>` ở `<head>`.","correct":false}],"explain":"(1) Đúng — CSS viết trực tiếp trong thuộc tính `style` (cách inline) chỉ tác động lên chính thẻ đó, không lan sang thẻ khác. (2) Sai — quy tắc trong `<style>` ở `<head>` chỉ áp dụng cho riêng trang chứa nó, muốn dùng cho nhiều trang phải tách ra file CSS riêng. (3) Đúng — đây chính là ưu điểm của cách dùng file `.css` ngoài: nhiều trang liên kết chung một file, sửa một chỗ là toàn bộ đổi theo, dễ bảo trì. (4) Sai — để nạp một file `.css` bên ngoài, ta dùng thẻ `<link rel='stylesheet' href='...'>` đặt trong `<head>`, không phải bỏ file vào cặp `<style>`."},{"id":"CC-tf-1004","type":"tf","topic":"E","grade":12,"level":"medium","question":"Xét vai trò của HTML và CSS trong một trang web, cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"HTML tạo ra cấu trúc và nội dung của trang, còn CSS lo phần trình bày như màu sắc, phông chữ, bố cục.","correct":true},{"text":"Với cùng một file HTML giữ nguyên nội dung, chỉ cần thay CSS là diện mạo trang có thể khác hẳn.","correct":true},{"text":"Việc xác định đâu là tiêu đề, đâu là đoạn văn, đâu là hình ảnh trên trang là do CSS quyết định.","correct":false},{"text":"Nếu gỡ bỏ toàn bộ CSS thì trang HTML sẽ không còn hiển thị được nội dung nào nữa.","correct":false}],"explain":"(1) Đúng — đây là sự phân vai cơ bản: HTML dựng cấu trúc và nội dung, CSS lo phần định kiểu trình bày. (2) Đúng — vì nội dung và cách trình bày tách rời nhau, giữ nguyên HTML mà đổi CSS thì giao diện có thể thay đổi hoàn toàn. (3) Sai — việc phân định đâu là tiêu đề, đoạn văn hay hình ảnh là nhiệm vụ của các thẻ HTML; CSS chỉ quyết định chúng trông ra sao. (4) Sai — không có CSS thì nội dung HTML vẫn hiển thị đầy đủ, chỉ là mất phần định dạng nên trông đơn điệu, thô sơ chứ không biến mất."},{"id":"CC-tf-1102","type":"tf","topic":"E","grade":12,"level":"medium","question":"Xét các phát biểu về màu sắc trong CSS:","statements":[{"text":"Mã màu `#ff0000` cho ra màu đỏ thuần vì thành phần đỏ ở mức cao nhất còn hai thành phần xanh lá và xanh dương ở mức thấp nhất.","correct":true},{"text":"Thuộc tính `color` chỉnh màu nền của phần tử, còn `background-color` chỉnh màu của chữ.","correct":false},{"text":"Trong mã màu `#RRGGBB`, mỗi cặp hai chữ số hex nhận giá trị chạy từ `00` đến `ff`.","correct":true},{"text":"Mã màu `#000000` biểu diễn màu trắng vì cả ba thành phần đỏ, xanh lá, xanh dương đều ở mức thấp nhất.","correct":false}],"explain":"(1) Đúng — trong `#RRGGBB`, cặp đầu là lượng đỏ; `ff0000` có đỏ ở mức cao nhất `ff`, còn xanh lá và xanh dương đều `00`, nên cho đỏ thuần. (2) Sai — đảo ngược vai trò: `color` mới là màu chữ, còn `background-color` mới là màu nền. (3) Đúng — mỗi cặp hex có 256 giá trị, viết từ `00` (thấp nhất) đến `ff` (cao nhất). (4) Sai — cả ba thành phần cùng ở mức thấp nhất cho ra màu đen; màu trắng là khi cả ba cùng ở mức cao nhất, tức `#ffffff`."},{"id":"CC-tf-1103","type":"tf","topic":"E","grade":12,"level":"medium","question":"Xét các phát biểu về thuộc tính chữ trong CSS:","statements":[{"text":"`font-family` là thuộc tính dùng để chọn họ phông chữ cho phần tử, ví dụ `Arial` hoặc `Georgia`.","correct":true},{"text":"Muốn canh chữ vào giữa phần tử chứa nó theo chiều ngang, ta đặt `text-align: right`.","correct":false},{"text":"`font-weight: bold` làm chữ hiển thị đậm hơn so với giá trị `normal`.","correct":true},{"text":"`font-size` quy định độ đậm của chữ, còn `font-weight` quy định cỡ chữ.","correct":false}],"explain":"(1) Đúng — `font-family` đúng là thuộc tính chọn họ phông, nhận các giá trị như `Arial`, `Georgia`. (2) Sai — `text-align: right` canh chữ sang phải; muốn canh vào giữa phải dùng giá trị `center`. (3) Đúng — `font-weight` quy định độ đậm, `bold` cho chữ đậm hơn `normal`. (4) Sai — đảo ngược hai vai trò: `font-size` mới là cỡ chữ (ví dụ `18px`), còn `font-weight` mới là độ đậm của chữ."},{"id":"CC-tf-1104","type":"tf","topic":"E","grade":12,"level":"hard","question":"Xét các phát biểu về ảnh hưởng của các lớp trong mô hình hộp:","statements":[{"text":"`padding` và `border` đều làm hộp hiển thị to lên vì cả hai đều nằm bên trong viền ngoài cùng của hộp.","correct":true},{"text":"`margin` cũng cộng thêm vào kích thước bên trong hộp đúng như cách `padding` làm.","correct":false},{"text":"Khi một khối trông to hơn dự kiến, nên kiểm tra `padding` và `border` trước tiên.","correct":true},{"text":"Khi hai khối đứng cạnh nhau trông xa nhau hơn dự kiến, nguyên nhân hầu như không bao giờ nằm ở `margin`.","correct":false}],"explain":"(1) Đúng — `padding` (đệm trong) và `border` (viền) đều nằm bên trong hộp nên đều cộng vào kích thước hiển thị của hộp. (2) Sai — `margin` không cộng vào bên trong hộp; nó là lề ngoài, chỉ đẩy các hộp lân cận ra xa chứ không làm chính hộp đó to lên. (3) Đúng — vì `padding` và `border` mới là hai lớp làm hộp phình to, nên khi khối to bất thường ta soát hai lớp này trước. (4) Sai — ngược lại, khoảng cách giữa hai hộp cạnh nhau chính do `margin` tạo ra, nên khi chúng trông xa nhau bất thường thì `margin` thường là thủ phạm."},{"id":"CC-tf-1202","type":"tf","topic":"E","grade":12,"level":"hard","question":"Xét các phát biểu về thuộc tính `display` trong CSS:","statements":[{"text":"Có thể gán `display: block` cho một `<span>` để nó chiếm trọn cả dòng như một phần tử khối.","correct":true},{"text":"Khi gán `display: none`, phần tử trở nên trong suốt nhưng vẫn chiếm đúng khoảng chỗ của nó trên trang.","correct":false},{"text":"Kiểu cư xử khối hay nội tuyến của một thẻ là cố định do trình duyệt quy định, CSS không thể thay đổi.","correct":false},{"text":"`block`, `inline`, `flex` và `none` đều là những giá trị hợp lệ của thuộc tính `display`.","correct":true}],"explain":"(1) Đúng — kiểu hiển thị do `display` quyết định nên có thể ép một `<span>` (vốn nội tuyến) chiếm trọn dòng bằng `display: block`. (2) Sai — `display: none` ẩn hẳn phần tử, coi như nó không tồn tại và không chiếm bất kỳ khoảng chỗ nào; muốn phần tử vẫn chiếm chỗ mà không thấy thì phải dùng cách khác. (3) Sai — kiểu cư xử này không bất biến; đó chính là điều `display` cho phép ta thay đổi bằng CSS. (4) Đúng — đây là bốn giá trị thường gặp của `display`."},{"id":"CC-tf-1203","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Để ba `<div>` con xếp thành một hàng ngang, ta gán `display: flex` cho `<div>` cha bao quanh chúng.","correct":true},{"text":"Thuộc tính `gap` quyết định cả hàng khối con dồn về đầu hàng, giữa hàng hay cuối hàng.","correct":false},{"text":"Thuộc tính `justify-content` sinh ra một khoảng trống đều nhau chen vào giữa từng cặp khối con.","correct":false},{"text":"Nếu bỏ khai báo `display: flex` ở khối cha, các `<div>` con sẽ quay lại xếp chồng lên nhau thành nhiều dòng.","correct":true}],"explain":"(1) Đúng — chỉ cần đặt `display: flex` cho phần tử cha là các con trực tiếp tự xếp thành hàng ngang, không phải khai báo gì cho từng con. (2) Sai — nhiệm vụ căn cả hàng dồn về đầu, giữa hay cuối là của `justify-content`, không phải `gap`. (3) Sai — tạo khoảng cách đều giữa các khối con là việc của `gap`; `justify-content` lo căn vị trí cả hàng. (4) Đúng — `<div>` mặc định là phần tử khối, nên khi mất `display: flex` chúng trở lại tự chiếm mỗi đứa một dòng."},{"id":"CC-tf-1204","type":"tf","topic":"E","grade":12,"level":"medium","question":"Một trang được chia thành ba vùng đầu trang, nội dung và chân trang, mỗi vùng là một `<div>`. Xét các phát biểu:","statements":[{"text":"Khi không vùng nào được gán `display: flex`, ba `<div>` tự xếp chồng lên nhau theo đúng thứ tự khai báo trong HTML.","correct":true},{"text":"Mỗi vùng `<div>` có thể tự định dạng độc lập mà không kéo theo thay đổi định dạng của các vùng còn lại.","correct":true},{"text":"Vì `<div>` mặc định là phần tử nội tuyến nên ba vùng sẽ tự nằm cạnh nhau trên cùng một hàng ngang.","correct":false},{"text":"Muốn các mục menu trong đầu trang xếp cạnh nhau, phải gán `display: flex` riêng cho từng mục menu.","correct":false}],"explain":"(1) Đúng — `<div>` là phần tử khối nên mặc định các vùng xếp chồng từ trên xuống theo thứ tự viết trong HTML, không cần khai báo thêm. (2) Đúng — chia trang thành các vùng riêng giúp mỗi vùng định dạng độc lập, không ảnh hưởng lẫn nhau. (3) Sai — `<div>` mặc định là phần tử khối chứ không phải nội tuyến, nên các vùng xếp chồng chứ không nằm cùng hàng. (4) Sai — chỉ cần gán `display: flex` cho phần tử cha bao quanh dãy mục menu, không phải gán cho từng mục một."},{"id":"CC-tf-1302","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Khi mới dựng xong khung HTML mà chưa thêm chút CSS nào, mở tệp trên trình duyệt trang vẫn hiển thị được, chỉ ở dạng chữ đen trên nền trắng, chưa có màu hay bố cục.","correct":true},{"text":"Nếu trang chưa có đoạn CSS nào thì trình duyệt sẽ báo lỗi và không thể mở được tệp HTML.","correct":false},{"text":"Với cùng một khung HTML, chỉ cần thay đổi phần CSS là có thể làm trang trông khác đi mà không phải sửa lại nội dung chữ.","correct":true},{"text":"Màu nền, cỡ chữ và khoảng cách giữa các phần đều do các thẻ HTML quy định.","correct":false}],"explain":"(1) Đúng — HTML lo phần nội dung, nên chỉ cần có khung HTML là trình duyệt đã hiển thị được, chỉ chưa được tô màu hay sắp bố cục nên trông rất 'mộc'. (2) Sai — CSS chỉ lo phần hình thức; thiếu CSS thì trang vẫn mở bình thường, không hề gây lỗi. (3) Đúng — nội dung nằm ở HTML còn hình thức nằm ở CSS, nên đổi CSS là đổi được diện mạo trang mà không đụng tới chữ. (4) Sai — màu sắc, cỡ chữ và khoảng cách là việc của CSS, còn thẻ HTML chỉ dựng khung nội dung."},{"id":"CC-tf-1303","type":"tf","topic":"E","grade":12,"level":"hard","question":"Xét các phát biểu về vai trò của CSS trong một trang web nhỏ:","statements":[{"text":"Trong một trang nhỏ, CSS thường đảm nhận ba việc: chọn màu, chọn phông chữ và cỡ chữ, sắp xếp khoảng cách giữa các phần.","correct":true},{"text":"Chọn màu nền và màu chữ tương phản rõ với nhau sẽ giúp văn bản dễ đọc hơn.","correct":true},{"text":"Việc canh lề và tạo khoảng cách giữa các phần không thuộc phạm vi CSS, muốn hai phần cách xa nhau phải gõ thêm nhiều dấu cách hoặc dòng trống trong HTML.","correct":false},{"text":"Cỡ chữ của văn bản do các thẻ HTML quyết định, nên muốn đổi cỡ chữ cho cả trang phải sửa lại thủ công từng thẻ một.","correct":false}],"explain":"(1) Đúng — trong một trang nhỏ, CSS chủ yếu lo ba nhóm việc: màu sắc, phông và cỡ chữ, cùng khoảng cách/canh lề giữa các phần. (2) Đúng — độ tương phản giữa màu nền và màu chữ đủ rõ giúp mắt đọc dễ chịu, đây là mục tiêu khi chọn màu. (3) Sai — canh lề và khoảng cách chính là việc của CSS; gõ thêm dấu cách hay dòng trống trong HTML không phải cách đúng đắn để dàn khoảng cách. (4) Sai — cỡ chữ do CSS quyết định, chỉ cần sửa ở phần CSS là đổi được cho toàn trang, không phải chỉnh từng thẻ HTML."},{"id":"CC-tf-1304","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trong đoạn mã ví dụ của trang giới thiệu, thẻ `<header>` đóng vai trò đầu trang, `<main>` chứa nội dung chính, còn `<footer>` là chân trang.","correct":true},{"text":"Toàn bộ nội dung lẫn phần định dạng màu sắc của trang ví dụ có thể được đặt gọn trong một tệp đuôi `.html` duy nhất.","correct":true},{"text":"Sau khi viết xong không nên mở trang bằng trình duyệt để xem thử, vì trang chỉ chạy đúng sau khi đã được đưa lên mạng.","correct":false},{"text":"Thẻ `<footer>` bắt buộc phải chứa ảnh đại diện và danh sách kĩ năng của người viết.","correct":false}],"explain":"(1) Đúng — ba thẻ khung này phân vai rõ ràng: `<header>` cho đầu trang, `<main>` cho phần nội dung chính, `<footer>` cho chân trang. (2) Đúng — với một trang nhỏ, cả HTML và toàn bộ CSS (viết trong thẻ `<style>`) đều gói gọn trong một tệp `.html` là được. (3) Sai — nên mở tệp ngay bằng trình duyệt để xem thử rồi chỉnh sửa dần; trang chạy được trên máy mà không cần đưa lên mạng. (4) Sai — chân trang thường chỉ cần vài dòng ngắn như thông tin liên hệ; ảnh và danh sách kĩ năng thuộc các phần khác chứ không bắt buộc nằm trong `<footer>`."},{"id":"CC-tf-1402","type":"tf","topic":"E","grade":12,"level":"medium","question":"Xét các phát biểu về các nhóm nghề trong ngành công nghệ thông tin:","statements":[{"text":"Nhóm khoa học và phân tích dữ liệu tập trung vào việc thu thập, xử lí và tìm quy luật ẩn trong những khối dữ liệu lớn, giúp tổ chức ra quyết định dựa trên số liệu.","correct":true},{"text":"Điểm khác biệt của nhóm trí tuệ nhân tạo và học máy là xây dựng những hệ thống có khả năng ‘học’ từ dữ liệu để tự đưa ra dự đoán, gợi ý.","correct":true},{"text":"Người làm ở nhóm phát triển phần mềm, web và ứng dụng chỉ được phép sử dụng duy nhất một ngôn ngữ lập trình là `Python`.","correct":false},{"text":"Trong một dự án công nghệ thực tế, thông thường chỉ cần một nhóm nghề duy nhất đảm nhận trọn vẹn mọi phần việc từ đầu đến cuối.","correct":false}],"explain":"(1) Đúng — đây đúng là công việc đặc trưng của nhóm khoa học và phân tích dữ liệu: khai thác dữ liệu lớn để hỗ trợ ra quyết định dựa trên số liệu thay vì phỏng đoán. (2) Đúng — nét riêng của nhóm trí tuệ nhân tạo và học máy chính là tạo ra hệ thống ‘học’ từ dữ liệu để tự dự đoán, gợi ý. (3) Sai — nhóm này thường dùng nhiều ngôn ngữ khác nhau như `Python`, `Java`, `JavaScript`, không giới hạn ở một ngôn ngữ duy nhất. (4) Sai — một dự án thực tế hiếm khi chỉ cần một nhóm nghề; các nhóm thường phải phối hợp chặt chẽ với nhau để cùng giải quyết vấn đề."},{"id":"CC-tf-1403","type":"tf","topic":"E","grade":12,"level":"hard","question":"Xét các phát biểu về những kĩ năng cần chuẩn bị cho nghề công nghệ thông tin:","statements":[{"text":"Tư duy giải quyết vấn đề bao gồm khả năng chia một vấn đề lớn, phức tạp thành những phần nhỏ hơn để dễ xử lí.","correct":true},{"text":"Vì công nghệ thay đổi rất nhanh nên kĩ năng quan trọng nhất là thuộc lòng càng nhiều công cụ, kĩ thuật đang có hiện nay càng tốt.","correct":false},{"text":"Đạo đức nghề nghiệp được coi trọng bởi người làm công nghệ thường được tiếp cận dữ liệu, hệ thống quan trọng nên cần trung thực và tôn trọng quyền riêng tư của người dùng.","correct":true},{"text":"Kĩ năng làm việc nhóm ít quan trọng, vì mỗi sản phẩm công nghệ thường chỉ do một người tự xây dựng trọn vẹn.","correct":false}],"explain":"(1) Đúng — chia nhỏ vấn đề lớn thành các phần dễ xử lí chính là cốt lõi của tư duy giải quyết vấn đề, nền tảng của hầu hết công việc trong ngành. (2) Sai — do công nghệ đổi mới liên tục, khả năng tự học cái mới mới là điều then chốt, chứ không phải thuộc lòng kiến thức, công cụ hiện tại vốn dễ lạc hậu. (3) Đúng — vì được tiếp cận dữ liệu và hệ thống quan trọng, người làm công nghệ cần có trách nhiệm, trung thực và tôn trọng quyền riêng tư. (4) Sai — hầu hết sản phẩm công nghệ do nhiều người cùng xây dựng, mỗi người một phần, nên làm việc nhóm và trao đổi rõ ràng rất quan trọng."},{"id":"CC-tf-1404","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Ngày nay công nghệ thông tin hiện diện trong hầu hết các lĩnh vực của đời sống, từ bệnh viện, ngân hàng cho tới cả nông nghiệp.","correct":true},{"text":"Vì ngành có một lộ trình định hướng ‘chuẩn’ duy nhất nên hai người cùng học tin học ở phổ thông bắt buộc phải đi theo cùng một hướng nghề.","correct":false},{"text":"Việc làm dự án thực tế giúp tích luỹ kinh nghiệm và tạo ra sản phẩm cụ thể để giới thiệu với nhà tuyển dụng về sau.","correct":true},{"text":"Chứng chỉ chuyên môn hầu như không có giá trị đối với người mới bắt đầu, vì lúc đó họ chưa có kinh nghiệm làm việc thực tế.","correct":false}],"explain":"(1) Đúng — công nghệ thông tin đã len lỏi vào hầu hết các ngóc ngách đời sống, kể cả những lĩnh vực tưởng chừng ít liên quan như nông nghiệp. (2) Sai — không có lộ trình ‘chuẩn’ cho tất cả; hai người có thể đi theo hai hướng khác nhau và cả hai đều đúng nếu phù hợp với sở thích, thế mạnh của mình. (3) Đúng — làm dự án thực tế giúp áp dụng kiến thức, tích luỹ kinh nghiệm và có sản phẩm để giới thiệu với nhà tuyển dụng. (4) Sai — chứng chỉ chuyên môn lại đặc biệt hữu ích với người mới bắt đầu, vì nó giúp xác nhận năng lực khi họ chưa có nhiều kinh nghiệm thực tế."},{"id":"CC-tf-1502","type":"tf","topic":"G","grade":12,"level":"medium","question":"Xét các phát biểu về lập trình truyền thống và phạm vi phù hợp của nó:","statements":[{"text":"Trong lập trình truyền thống, con người phải tự nghĩ ra và viết sẵn từng luật cụ thể để máy làm theo từng bước.","correct":true},{"text":"Với bài toán kiểm tra một số nguyên có chia hết cho 2 hay không, viết một luật cố định là cách xử lý gọn gàng và phù hợp hơn so với đi thu thập dữ liệu để dạy máy.","correct":true},{"text":"Lập trình truyền thống bắt buộc phải cho máy xem thật nhiều ví dụ mẫu trước, rồi máy mới thực hiện được luật đã viết.","correct":false},{"text":"Học máy ra đời để thay thế hoàn toàn lập trình truyền thống, khiến việc viết luật thủ công trở nên vô dụng trong mọi bài toán.","correct":false}],"explain":"(1) Đúng — đặc trưng của lập trình truyền thống là người viết chương trình tự nghĩ ra từng luật rõ ràng, cụ thể cho máy làm theo. (2) Đúng — bài toán chia hết cho 2 có luật rất rõ ràng, không ngoại lệ, nên chỉ cần viết đúng một luật là xong; đi gom dữ liệu để dạy máy sẽ tốn công vô ích. (3) Sai — đây mới là cách của học máy; lập trình truyền thống làm theo luật đã viết sẵn mà không cần xem ví dụ nào trước. (4) Sai — mỗi cách mạnh ở một loại bài toán khác nhau: với bài toán có luật rõ ràng, viết luật thủ công vẫn gọn và hiệu quả hơn, nên học máy không làm lập trình truyền thống trở nên vô dụng."},{"id":"CC-tf-1503","type":"tf","topic":"G","grade":12,"level":"medium","question":"Xét các phát biểu về những bài toán dưới đây, đâu là ứng dụng của học máy:","statements":[{"text":"Lọc thư rác là một ứng dụng của học máy: máy được cho xem nhiều email đã gắn nhãn ‘rác’ hoặc ‘không rác’ để tự nhận ra đặc điểm của thư rác rồi áp dụng cho email mới.","correct":true},{"text":"Gợi ý phim dựa trên học máy: hệ thống học từ lịch sử xem và đánh giá của nhiều người dùng để nhận ra ai có sở thích giống ai, từ đó đoán bộ phim một người có khả năng thích.","correct":true},{"text":"Nhận diện chữ số viết tay hoạt động được là nhờ lập trình viên viết sẵn một luật mô tả chính xác từng nét của mỗi chữ số.","correct":false},{"text":"Sắp xếp một danh sách số theo thứ tự tăng dần là một ứng dụng tiêu biểu của học máy.","correct":false}],"explain":"(1) Đúng — lọc thư rác là ví dụ điển hình: máy học từ dữ liệu email đã gắn nhãn để tự rút ra đặc điểm của thư rác. (2) Đúng — gợi ý phim học từ dữ liệu hành vi và đánh giá của nhiều người dùng, đúng tinh thần rút quy luật từ dữ liệu. (3) Sai — nhận diện chữ viết tay là ứng dụng của học máy: máy tự rút ra quy luật từ hàng nghìn ảnh đã gắn nhãn, chứ không có ai viết sẵn luật mô tả từng nét. (4) Sai — sắp xếp danh sách có luật rõ ràng, cố định (so sánh rồi đổi chỗ), thuộc lập trình truyền thống, không cần và không phải là học máy."},{"id":"CC-tf-1504","type":"tf","topic":"G","grade":12,"level":"hard","question":"Xét các phát biểu về ý nghĩa của việc máy ‘học’ và yếu tố quyết định độ chính xác:","statements":[{"text":"Ở giai đoạn đầu huấn luyện, mô hình thường dự đoán gần như ngẫu nhiên, rồi mới chính xác dần lên qua rất nhiều lần điều chỉnh.","correct":true},{"text":"Máy ‘học’ nghĩa là mỗi khi dự đoán sai so với nhãn đúng đã biết, mô hình tự điều chỉnh lại một chút, và lặp lại việc này qua rất nhiều ví dụ.","correct":true},{"text":"Chỉ cần chạy trên máy tính đủ mạnh thì mô hình sẽ luôn học đúng, bất kể dữ liệu huấn luyện nhiều hay ít, chính xác hay sai lệch.","correct":false},{"text":"Khi nói máy ‘học’, điều đó có nghĩa là mô hình thực sự hiểu và suy nghĩ về nội dung giống như con người.","correct":false}],"explain":"(1) Đúng — quá trình học bắt đầu từ những dự đoán gần như ngẫu nhiên, rồi cải thiện dần qua nhiều lần điều chỉnh, chứ không chính xác ngay từ đầu. (2) Đúng — bản chất của ‘học’ ở đây là điều chỉnh dần dần: sai thì sửa lại một chút, lặp lại qua rất nhiều ví dụ để chính xác hơn. (3) Sai — đây là hiểu lầm phổ biến; nếu dữ liệu huấn luyện quá ít hoặc bị sai lệch thì dù máy mạnh đến đâu, mô hình vẫn rút ra quy luật sai. Dữ liệu, chứ không chỉ sức mạnh tính toán, mới là yếu tố quyết định. (4) Sai — máy không thật sự hiểu hay suy nghĩ như con người; ‘học’ chỉ là quá trình điều chỉnh số liệu dựa trên dữ liệu để dự đoán ngày một đúng hơn."},{"id":"CC-tf-1602","type":"tf","topic":"G","grade":12,"level":"medium","question":"Xét việc xếp mỗi tình huống dưới đây vào đúng dạng bài toán học máy. Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Dựa vào dữ liệu bán hàng những ngày trước để ước lượng số cốc trà sữa một quán sẽ bán được trong ngày mai là bài toán **dự đoán số** (`regression`).","correct":true},{"text":"Đọc một bình luận trên mạng rồi cho biết nó mang thái độ tích cực hay tiêu cực là bài toán **phân loại** (`classification`).","correct":true},{"text":"Kết quả của một bài toán **dự đoán số** luôn là số nguyên, không bao giờ có phần thập phân.","correct":false},{"text":"Nhận diện một ảnh chụp chữ số viết tay xem đó là chữ số nào trong mười chữ số từ 0 đến 9 là bài toán **dự đoán số**, vì đáp án là một con số.","correct":false}],"explain":"(1) Đúng — kết quả cần tìm là một con số (số cốc bán được) ước lượng theo quy luật, nên đây là bài toán dự đoán số. (2) Đúng — đáp án là một trong hai nhãn cho trước (tích cực hoặc tiêu cực), tức chọn một tên nhóm hữu hạn, nên là bài toán phân loại. (3) Sai — con số dự đoán có thể mang giá trị bất kỳ trong một khoảng và hoàn toàn có thể có phần thập phân, chẳng hạn ước lượng nhiệt độ 27,5°C. (4) Sai — dù các đáp án trông giống con số, đây vẫn là phân loại: máy phải chọn đúng một nhãn trong mười nhãn cố định biết trước, chứ không ước lượng một giá trị tự do trong một khoảng."},{"id":"CC-tf-1603","type":"tf","topic":"G","grade":12,"level":"hard","question":"Xét quy trình chia dữ liệu để huấn luyện và kiểm tra một mô hình học máy. Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Phần dữ liệu **kiểm tra** (`test`) phải được giữ kín, không cho máy nhìn thấy trong lúc huấn luyện.","correct":true},{"text":"Thông thường phần dữ liệu **huấn luyện** chiếm phần lớn, còn phần **kiểm tra** chiếm phần nhỏ hơn trong toàn bộ dữ liệu.","correct":true},{"text":"Chỉ riêng dữ liệu **huấn luyện** mới cần biết trước câu trả lời đúng, còn dữ liệu **kiểm tra** thì không cần.","correct":false},{"text":"Nếu vô tình đưa một phần dữ liệu **kiểm tra** vào lúc huấn luyện, thì điểm chấm trên phần đó vẫn phản ánh trung thực năng lực thật của mô hình.","correct":false}],"explain":"(1) Đúng — chỉ khi phần kiểm tra hoàn toàn mới với máy thì điểm chấm mới cho biết mô hình có nắm được quy luật chung hay không. (2) Đúng — phần lớn dữ liệu dành cho huấn luyện để máy học đủ quy luật, phần nhỏ hơn để lại làm bài kiểm tra. (3) Sai — cả hai phần đều cần biết trước đáp án đúng: phần huấn luyện để máy học, phần kiểm tra để đối chiếu và chấm điểm. (4) Sai — nếu dữ liệu kiểm tra đã bị máy nhìn thấy lúc học, máy có thể ghi nhớ sẵn đáp án, nên điểm cao trên phần đó không còn phản ánh đúng năng lực trên dữ liệu thật sự mới."},{"id":"CC-tf-1604","type":"tf","topic":"G","grade":12,"level":"hard","question":"Xét cách đo **độ chính xác** (`accuracy`) và đánh giá chất lượng mô hình. Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Với bài toán **phân loại**, độ chính xác thường được tính bằng tỉ lệ phần trăm số lần máy đoán đúng nhãn trên tập kiểm tra.","correct":true},{"text":"Với bài toán **dự đoán số**, người ta cũng chấm điểm bằng đúng cách tính tỉ lệ phần trăm đoán trùng khít như ở phân loại.","correct":false},{"text":"Một mô hình phân loại đạt độ chính xác 100% trên tập kiểm tra nghĩa là nó đoán đúng nhãn cho mọi mẫu trong tập kiểm tra đó.","correct":true},{"text":"Độ chính xác đo trên tập kiểm tra luôn cao hơn độ chính xác đo trên tập huấn luyện.","correct":false}],"explain":"(1) Đúng — với phân loại, độ chính xác chính là tỉ lệ phần trăm số lần đoán trúng nhãn trên tổng số mẫu ở tập kiểm tra. (2) Sai — con số dự đoán rất hiếm khi trùng khít giá trị thật, nên người ta không đếm số lần đúng tuyệt đối mà đo mức chênh lệch trung bình giữa số máy đoán và số thật; chênh lệch càng nhỏ mô hình càng tốt. (3) Đúng — 100% nghĩa là không có mẫu nào trong tập kiểm tra bị đoán sai nhãn. (4) Sai — không có quy luật buộc điểm trên tập kiểm tra phải cao hơn; thực tế mô hình thường đạt điểm cao trên chính dữ liệu đã học và thấp hơn trên dữ liệu mới, nên phát biểu này không đúng."},{"id":"CC-tf-1702","type":"tf","topic":"G","grade":12,"level":"medium","question":"Xét các phát biểu về bước trực quan hoá trong quy trình khoa học dữ liệu:","statements":[{"text":"Trực quan hoá là việc thể hiện dữ liệu dưới dạng biểu đồ, bảng biểu để con người dễ nhận ra quy luật hơn so với đọc hàng nghìn con số rời rạc.","correct":true},{"text":"Trong năm bước xử lý dữ liệu, trực quan hoá thường được thực hiện sau khi đã phân tích và trước khi rút ra kết luận, khuyến nghị.","correct":true},{"text":"Bước rút kết luận và khuyến nghị là bước đầu tiên, được làm ngay khi vừa thu thập được dữ liệu thô.","correct":false},{"text":"Khi đã tính ra được các con số thống kê thì bước trực quan hoá là thừa và có thể bỏ qua hoàn toàn mà không ảnh hưởng gì.","correct":false}],"explain":"(1) Đúng — trực quan hoá biến dữ liệu thành hình ảnh như biểu đồ cột, đường... giúp mắt người nắm bắt quy luật nhanh hơn nhiều so với dò từng dòng số. (2) Đúng — thứ tự quen thuộc là thu thập, làm sạch, phân tích, trực quan hoá rồi mới rút kết luận; trực quan hoá đứng sau phân tích và trước bước kết luận. (3) Sai — rút kết luận và khuyến nghị là bước cuối cùng, dựa trên kết quả đã phân tích, không thể làm ngay khi mới có dữ liệu thô. (4) Sai — dù đã có con số thống kê, trực quan hoá vẫn giúp nhìn ra xu hướng, điểm bất thường dễ dàng hơn, nên là bước có giá trị chứ không thừa."},{"id":"CC-tf-1703","type":"tf","topic":"G","grade":12,"level":"hard","question":"Xét các phát biểu về dữ liệu thô và hiểu biết trong khoa học dữ liệu:","statements":[{"text":"Hiểu biết là quy luật hay xu hướng đã được rút ra từ dữ liệu, đủ rõ ràng để dựa vào đó mà ra quyết định.","correct":true},{"text":"Một tập gồm hàng nghìn hoá đơn bán hàng chưa qua xử lý đã được coi là hiểu biết, vì bản thân nó chứa rất nhiều thông tin.","correct":false},{"text":"Cùng một tập dữ liệu thô, nếu chưa qua xử lý thì tự nó thường không nói lên quy luật nào có thể dùng để hành động.","correct":true},{"text":"Mục tiêu cuối cùng của khoa học dữ liệu là thu thập được càng nhiều dữ liệu thô càng tốt.","correct":false}],"explain":"(1) Đúng — đó chính là bản chất của hiểu biết: một quy luật hoặc xu hướng đủ rõ để làm căn cứ ra quyết định, ví dụ 'áo khoác bán chạy vào mùa đông'. (2) Sai — dữ liệu chưa qua xử lý vẫn chỉ là dữ liệu thô dù có nhiều đến đâu; nó chỉ trở thành hiểu biết sau khi được làm sạch, phân tích để rút ra quy luật. (3) Đúng — nhìn qua một đống số liệu thô lộn xộn, con người thường không thấy được quy luật gì cho tới khi xử lý nó. (4) Sai — mục tiêu của khoa học dữ liệu là biến dữ liệu thô thành hiểu biết có ích để ra quyết định, chứ không phải gom dữ liệu càng nhiều càng tốt."},{"id":"CC-tf-1704","type":"tf","topic":"G","grade":12,"level":"medium","question":"Xét các phát biểu về bước làm sạch dữ liệu:","statements":[{"text":"Làm sạch dữ liệu bao gồm những việc như loại bỏ bản ghi bị trùng, bổ sung chỗ còn thiếu và sửa lại các số liệu ghi nhầm.","correct":true},{"text":"Nếu dùng công cụ phân tích đủ mạnh thì có thể bỏ qua bước làm sạch mà kết quả vẫn luôn chính xác.","correct":false},{"text":"Làm sạch dữ liệu thường tốn nhiều công sức nhưng lại là bước dễ bị xem nhẹ.","correct":true},{"text":"Việc bổ sung ngày tháng còn thiếu cho các hoá đơn là công việc của bước phân tích chứ không thuộc bước làm sạch.","correct":false}],"explain":"(1) Đúng — đây đều là các thao tác đặc trưng của bước làm sạch nhằm loại lỗi, trùng lặp và thiếu sót trong dữ liệu. (2) Sai — công cụ dù mạnh đến đâu cũng không cứu được dữ liệu đầu vào bị lỗi; đúng nguyên tắc 'rác vào thì rác ra', dữ liệu bẩn sẽ cho kết quả sai. (3) Đúng — làm sạch tốn công nhất nhưng hay bị coi nhẹ, trong khi bỏ qua nó sẽ làm sai lệch toàn bộ phân tích phía sau. (4) Sai — bổ sung ngày tháng còn thiếu là một phần của bước làm sạch, được thực hiện trước khi phân tích."},{"id":"CC-tf-1802","type":"tf","topic":"G","grade":12,"level":"medium","question":"Xét các phát biểu về bản chất và lợi ích của trực quan hoá dữ liệu:","statements":[{"text":"Trực quan hoá dữ liệu giúp người xem nhận ra xu hướng hay sự khác biệt giữa các nhóm nhanh hơn so với dò từng dòng trong một bảng số liệu dài.","correct":true},{"text":"Khi vẽ số liệu thành biểu đồ, trực quan hoá sẽ tạo ra những con số mới chính xác hơn số liệu gốc ban đầu.","correct":false},{"text":"Mắt và não người thường tiếp nhận độ cao, hình dạng và vị trí nhanh hơn là ghi nhớ hàng loạt con số rời rạc, nên biểu đồ phù hợp giúp nắm ý chính nhanh hơn.","correct":true},{"text":"Vì biểu đồ luôn trình bày số liệu một cách trung thực nên khi đã có biểu đồ thì không cần đối chiếu lại với số liệu gốc nữa.","correct":false}],"explain":"(1) Đúng — đây chính là lợi ích cốt lõi: biến số liệu thô thành hình ảnh để nhận ra nhanh xu hướng, phép so sánh hay tỉ lệ. (2) Sai — trực quan hoá chỉ trình bày lại đúng số liệu gốc dưới dạng hình ảnh, không hề tạo ra con số mới hay làm dữ liệu chính xác hơn. (3) Đúng — con người giỏi nhận ra hình dạng, độ cao, vị trí hơn là nhớ nhiều số rời rạc, nên biểu đồ phù hợp giúp nắm ý nhanh hơn dò bảng. (4) Sai — một biểu đồ có thể gây hiểu nhầm do trục bị cắt hoặc tỉ lệ bị phóng đại, nên khi nghi ngờ vẫn phải đối chiếu lại với số liệu gốc."},{"id":"CC-tf-1803","type":"tf","topic":"G","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Để so sánh doanh thu của bốn chi nhánh trong cùng một quý, biểu đồ cột phù hợp hơn biểu đồ đường.","correct":true},{"text":"Nối các điểm doanh thu của mười hai tháng trong năm thành một đường liền là cách hợp lí để thấy xu hướng tăng hay giảm của cả năm.","correct":true},{"text":"Muốn thể hiện tỉ lệ phần trăm học sinh chọn mỗi môn tự chọn trong tổng số học sinh của khối, biểu đồ đường là lựa chọn phù hợp nhất.","correct":false},{"text":"Việc chọn loại biểu đồ nào chỉ phụ thuộc vào biểu đồ nào trông bắt mắt hơn, không liên quan đến câu hỏi mà dữ liệu cần trả lời.","correct":false}],"explain":"(1) Đúng — câu hỏi ở đây là so sánh nhiều nhóm tại cùng một thời điểm, đúng mục đích của biểu đồ cột; biểu đồ đường dành cho xu hướng theo thời gian. (2) Đúng — doanh thu mười hai tháng là dữ liệu biến đổi theo thời gian, nối thành đường sẽ thấy ngay xu hướng, đúng mục đích của biểu đồ đường. (3) Sai — thể hiện tỉ lệ phần trăm của từng phần trong một tổng thể là việc của biểu đồ tròn, không phải biểu đồ đường. (4) Sai — chọn loại biểu đồ phải xuất phát từ câu hỏi cần trả lời (so sánh nhóm, xu hướng theo thời gian, hay tỉ lệ của tổng thể), chứ không dựa vào việc biểu đồ nào đẹp hơn."},{"id":"CC-tf-1804","type":"tf","topic":"G","grade":12,"level":"hard","question":"Xét các phát biểu về việc đọc-hiểu một biểu đồ và những cách trình bày dễ gây hiểu nhầm:","statements":[{"text":"Khi một biểu đồ có nhiều đường màu khác nhau vẽ chồng lên nhau, cần đọc chú giải để biết mỗi đường ứng với đối tượng nào trước khi kết luận.","correct":true},{"text":"Một biểu đồ cột được vẽ với trục đứng cắt bỏ phần từ 0 lên đã làm thay đổi luôn các con số gốc của dữ liệu.","correct":false},{"text":"Tiêu đề của biểu đồ cho biết biểu đồ đang nói về đối tượng nào và trong phạm vi hay khoảng thời gian nào.","correct":true},{"text":"Khi thấy một cột cao gấp nhiều lần cột bên cạnh thì chắc chắn giá trị thật của hai cột cũng chênh nhau gấp nhiều lần.","correct":false}],"explain":"(1) Đúng — với biểu đồ nhiều đường, bỏ qua chú giải rất dễ đọc nhầm đường này thành đường khác, nên phải xem chú giải trước khi kết luận. (2) Sai — cắt bớt trục chỉ thay đổi ấn tượng thị giác, các con số gốc đằng sau vẫn giữ nguyên; đó chính là điều khiến kiểu biểu đồ này nguy hiểm. (3) Đúng — kiểm tra tiêu đề là bước đầu tiên để biết biểu đồ nói về đối tượng nào, trong phạm vi hay thời gian nào. (4) Sai — nếu trục đứng bị cắt bớt hoặc phóng đại, một chênh lệch nhỏ có thể trông như rất lớn, nên chiều cao cột không phản ánh trung thực mức chênh của giá trị thật."},{"id":"CC-tf-1902","type":"tf","topic":"G","grade":12,"level":"medium","question":"Xét các phát biểu về mô hình trong một mô phỏng:","statements":[{"text":"Mô hình dùng trong mô phỏng là một phiên bản rút gọn của thực tế, chỉ giữ lại những yếu tố quan trọng đủ để trả lời câu hỏi đang đặt ra.","correct":true},{"text":"Một mô phỏng gồm hai phần gắn với nhau: dựng mô hình và cho mô hình đó chạy thử.","correct":true},{"text":"Một mô hình chỉ dùng được khi nó tái hiện đầy đủ, chính xác mọi chi tiết của hiện tượng thật.","correct":false},{"text":"Vì mô hình đã lược bỏ bớt chi tiết so với thực tế nên nó không thể dùng để dự đoán được điều gì.","correct":false}],"explain":"(1) Đúng — mô hình là bản đơn giản hoá của thực tế, chỉ cần giữ các yếu tố then chốt đủ để trả lời đúng câu hỏi, không cần chứa mọi chi tiết. (2) Đúng — một mô phỏng luôn có hai phần đi cùng nhau: xây dựng mô hình và chạy thử mô hình đó để quan sát diễn biến. (3) Sai — mô hình không cần và cũng không thể tái hiện mọi chi tiết; điều quan trọng là giữ đúng những yếu tố cần thiết, không phải là đầy đủ tuyệt đối. (4) Sai — chính vì được đơn giản hoá hợp lí mà mô hình vẫn tính toán và dự đoán được điều có thể xảy ra; lược bớt chi tiết không đồng nghĩa với vô dụng."},{"id":"CC-tf-1903","type":"tf","topic":"G","grade":12,"level":"hard","question":"Một mô hình mô phỏng một bệnh lây trong nhóm 100 người cho kết quả: nếu không đeo khẩu trang, số người mắc qua các ngày lần lượt là 1, 3, 9, 27, 81; nếu có đeo khẩu trang là 1, 2, 4, 8, 16. Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Ở kịch bản không đeo khẩu trang, số người mắc mỗi ngày tăng gấp ba lần so với ngày liền trước.","correct":true},{"text":"Ở kịch bản có đeo khẩu trang, số người mắc mỗi ngày tăng gấp đôi so với ngày liền trước.","correct":true},{"text":"Hai kết quả khác nhau vì máy tính đã chạy hai chương trình hoàn toàn khác nhau cho hai kịch bản.","correct":false},{"text":"Bảng số này chứng minh chắc chắn rằng ngoài đời thật, cứ đeo khẩu trang thì số người mắc mỗi ngày sẽ đúng bằng một nửa so với không đeo.","correct":false}],"explain":"(1) Đúng — dãy 1, 3, 9, 27, 81 cho thấy mỗi ngày số người mắc gấp ba lần ngày trước. (2) Đúng — dãy 1, 2, 4, 8, 16 cho thấy mỗi ngày gấp đôi ngày trước. (3) Sai — hai kịch bản dùng chung một mô hình, chỉ khác nhau ở một con số giả định đầu vào (số người bị lây mỗi ngày), chứ không phải hai chương trình khác nhau. (4) Sai — đây chỉ là kết quả của một mô hình đơn giản hoá, cho dự đoán gần đúng; nó gợi ý xu hướng lây chậm lại chứ không phải một khẳng định chắc chắn về con số thực tế, vốn còn phụ thuộc nhiều yếu tố khác."},{"id":"CC-tf-1904","type":"tf","topic":"G","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Nếu số liệu đầu vào bị sai lệch thì dù máy tính tính toán rất chính xác, kết quả mô phỏng vẫn có thể khác xa thực tế.","correct":true},{"text":"Kết quả của một mô phỏng nên được hiểu là một dự đoán có cơ sở, chứ không phải một khẳng định chắc chắn tuyệt đối.","correct":true},{"text":"Chỉ cần máy tính chạy mô phỏng đủ mạnh và tính toán đủ nhanh thì kết quả chắc chắn khớp hoàn toàn với thực tế.","correct":false},{"text":"Một mô hình bỏ sót một yếu tố quan trọng của thực tế vẫn luôn cho kết quả đáng tin, miễn là số liệu đầu vào chính xác.","correct":false}],"explain":"(1) Đúng — máy tính có thể tính rất chính xác về mặt con số, nhưng nếu dữ liệu đầu vào sai thì kết quả vẫn sai lệch so với thực tế (dữ liệu xấu vào thì kết quả xấu ra). (2) Đúng — mô phỏng luôn chỉ cho kết quả gần đúng, là dự đoán có cơ sở chứ không phải điều chắc chắn. (3) Sai — độ đúng của mô phỏng phụ thuộc vào mô hình có đúng và dữ liệu có tốt hay không, không phải vào sức mạnh của máy tính; máy mạnh chỉ tính nhanh hơn chứ không tự làm mô hình đúng hơn. (4) Sai — nếu mô hình bỏ sót một yếu tố quan trọng thì kết quả có thể sai lệch dù dữ liệu đầu vào chính xác, vì bản thân mô hình đã không phản ánh đúng thực tế."},{"id":"CC-tf-2002","type":"tf","topic":"G","grade":12,"level":"medium","question":"Xét các phát biểu về ba đặc điểm của dữ liệu lớn:","statements":[{"text":"Đặc điểm **đa dạng** (`variety`) nghĩa là dữ liệu lớn có thể gồm cả hình ảnh, âm thanh, video, vị trí địa lí... chứ không chỉ những con số hay dòng chữ xếp gọn trong một bảng.","correct":true},{"text":"Vì dữ liệu lớn nhấn mạnh yếu tố tốc độ, nên một khối dữ liệu chỉ được coi là “lớn” khi nó sinh ra nhanh, còn khối lượng nhiều hay ít thì không quan trọng.","correct":false},{"text":"Đặc điểm **khối lượng** (`volume`) thể hiện ở chỗ dữ liệu thường được đo bằng hàng triệu, hàng tỉ bản ghi, vượt xa khả năng lưu trữ của một máy tính cá nhân thông thường.","correct":true},{"text":"Để được xếp vào dữ liệu lớn, dữ liệu bắt buộc phải được sắp xếp gọn gàng thành các bảng có hàng và cột rõ ràng ngay từ đầu.","correct":false}],"explain":"(1) Đúng — `variety` chính là sự đa dạng về loại: dữ liệu lớn trộn lẫn hình ảnh, âm thanh, video, vị trí... chứ không gói gọn trong con số và văn bản. (2) Sai — tốc độ (`velocity`) chỉ là một trong ba đặc điểm; khối lượng khổng lồ (`volume`) cũng cốt lõi không kém, không thể bỏ qua yếu tố khối lượng. (3) Đúng — `volume` đo bằng hàng triệu, hàng tỉ bản ghi, vượt khả năng của một máy tính thông thường. (4) Sai — ngược lại, dữ liệu lớn phần nhiều ở dạng hỗn độn, chưa được xếp gọn thành bảng hàng–cột; chính sự đa dạng, thiếu ngăn nắp ấy khiến công cụ thông thường khó xử lí."},{"id":"CC-tf-2003","type":"tf","topic":"G","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Chỉ cần thu thập và lưu trữ được một khối dữ liệu khổng lồ là tổ chức đã có ngay giá trị, không cần phân tích thêm.","correct":false},{"text":"Phân tích dữ liệu lớn giúp phát hiện những xu hướng ẩn mà việc chỉ nhìn vào vài bản ghi riêng lẻ khó lòng nhận ra.","correct":true},{"text":"Một hệ thống học máy nói chung có cơ hội đưa ra dự đoán chính xác hơn khi được huấn luyện từ nhiều dữ liệu chất lượng.","correct":true},{"text":"Giá trị của việc phân tích dữ liệu lớn chỉ có ý nghĩa với doanh nghiệp bán hàng, còn bệnh viện hay cơ quan quản lí đô thị thì không tận dụng được.","correct":false}],"explain":"(1) Sai — tự thân một khối dữ liệu hỗn độn chưa nói lên điều gì; giá trị thật sự chỉ bộc lộ khi ta phân tích nó, chứ không nằm ở việc lưu trữ. (2) Đúng — gộp và phân tích hàng triệu bản ghi mới thấy được quy luật ẩn mà vài bản ghi lẻ không cho thấy. (3) Đúng — dữ liệu lớn là nguyên liệu huấn luyện; càng học từ nhiều dữ liệu chất lượng, hệ thống học máy càng có cơ hội dự đoán tốt hơn. (4) Sai — nhiều loại tổ chức đều hưởng lợi: bệnh viện, cơ quan quản lí đô thị... cũng dựa vào phân tích dữ liệu để ra quyết định, không riêng gì doanh nghiệp bán hàng."},{"id":"CC-tf-2004","type":"tf","topic":"G","grade":12,"level":"hard","question":"Xét vai trò của từng công nghệ khi kết hợp với dữ liệu lớn:","statements":[{"text":"**Điện toán đám mây** đóng vai trò cung cấp nơi lưu trữ đủ rộng và sức mạnh tính toán đủ lớn để chứa, xử lí khối dữ liệu khổng lồ.","correct":true},{"text":"Thiết bị `IoT` như cảm biến, camera chủ yếu đảm nhận việc phân tích dữ liệu để tìm ra quy luật, thay cho trí tuệ nhân tạo.","correct":false},{"text":"**Trí tuệ nhân tạo**, đặc biệt là học máy, đóng vai trò như “bộ não” phân tích dữ liệu lớn để tìm quy luật và đưa ra dự đoán.","correct":true},{"text":"Vì mỗi công nghệ đều đã mạnh, nên dữ liệu lớn luôn phát huy hết giá trị ngay cả khi đứng một mình, không cần kết hợp với công nghệ nào khác.","correct":false}],"explain":"(1) Đúng — điện toán đám mây lo phần lưu trữ và sức mạnh tính toán, thay cho việc bắt một máy đơn lẻ gánh vác khối dữ liệu lớn. (2) Sai — `IoT` là nguồn liên tục sinh ra dữ liệu (cảm biến, camera thu thập dữ liệu), còn việc phân tích tìm quy luật là vai trò của trí tuệ nhân tạo, không phải của thiết bị `IoT`. (3) Đúng — trí tuệ nhân tạo, nhất là học máy, giữ vai trò “bộ não” phân tích, tìm quy luật và dự đoán. (4) Sai — dữ liệu lớn hiếm khi phát huy hết giá trị nếu đứng một mình; giá trị bộc lộ rõ nhất khi kết hợp với `IoT`, điện toán đám mây và trí tuệ nhân tạo."},{"id":"CC-tf-2102","type":"tf","topic":"B","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Một địa chỉ dạng `192.168.1.5` chỉ có giá trị trong mạng nội bộ, nên hai gia đình khác nhau hoàn toàn có thể cùng dùng địa chỉ này mà không gây xung đột trên Internet.","correct":true},{"text":"Khi cùng ra Internet, mỗi thiết bị trong một nhà được nhà cung cấp dịch vụ cấp cho một địa chỉ IP công cộng riêng để phân biệt với các thiết bị còn lại.","correct":false},{"text":"Máy chủ ngoài Internet chỉ nhìn thấy địa chỉ IP công cộng chung của router, chứ không biết trong nhà đang có bao nhiêu thiết bị kết nối.","correct":true},{"text":"Địa chỉ IP riêng bắt buộc người dùng phải tự nhập bằng tay cho từng thiết bị thì mạng nội bộ mới hoạt động được.","correct":false}],"explain":"(1) Đúng — địa chỉ IP riêng chỉ có ý nghĩa bên trong mạng nội bộ, giống số phòng khách sạn, nên nhiều mạng khác nhau có thể trùng dãy này mà không xung đột ngoài Internet. (2) Sai — cả nhà cùng dùng chung một địa chỉ IP công cộng của router, chứ không phải mỗi thiết bị một địa chỉ công cộng riêng. (3) Đúng — router đứng ra làm người gác cổng, thế giới bên ngoài chỉ thấy địa chỉ công cộng chung nên không biết được số thiết bị bên trong. (4) Sai — địa chỉ riêng thường do máy chủ DHCP trong router cấp tự động, không bắt buộc phải đặt tay từng máy."},{"id":"CC-tf-2103","type":"tf","topic":"B","grade":12,"level":"medium","question":"Xét địa chỉ web `https://tuyensinh.thptleloi.edu.vn/khoi10/huong-dan.pdf`. Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Phần tên miền trong địa chỉ trên là `tuyensinh.thptleloi.edu.vn`, còn `/khoi10/huong-dan.pdf` là đường dẫn tới tài nguyên cụ thể trên máy chủ.","correct":true},{"text":"Tên miền và địa chỉ web đầy đủ (URL) chỉ là hai cách gọi của cùng một thứ, đều chỉ ra đúng một máy chủ.","correct":false},{"text":"Thành phần `https` cho biết giao thức dùng để trao đổi dữ liệu, không phải là một phần của tên miền.","correct":true},{"text":"Trình duyệt gửi cả phần đường dẫn `/khoi10/huong-dan.pdf` tới máy chủ DNS để DNS trả về đúng tệp cần lấy.","correct":false}],"explain":"(1) Đúng — một địa chỉ web đầy đủ tách thành giao thức, tên miền và đường dẫn; ở đây tên miền là phần chỉ ra máy chủ, còn phần sau dấu gạch chéo là đường dẫn tới tài nguyên. (2) Sai — tên miền chỉ là một phần của URL; URL còn gồm cả giao thức và đường dẫn, nên hai thứ này không đồng nhất. (3) Đúng — `https` là giao thức trao đổi dữ liệu, đứng tách khỏi tên miền chứ không thuộc tên miền. (4) Sai — DNS chỉ nhận phần tên miền để trả về địa chỉ IP; đường dẫn tới tệp được gửi tới máy chủ web sau khi đã kết nối, không gửi cho DNS."},{"id":"CC-tf-2104","type":"tf","topic":"B","grade":12,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Khi một trang web chuyển sang máy chủ mới và nhận địa chỉ IP mới, đơn vị chủ quản chỉ cần cập nhật bản ghi trong DNS, còn người dùng vẫn gõ tên miền quen thuộc như bình thường.","correct":true},{"text":"Nếu gõ tên miền thì báo không tìm thấy nhưng gõ thẳng địa chỉ IP thì trang vẫn hiện ra, thì chắc chắn máy tính đã mất hoàn toàn kết nối Internet.","correct":false},{"text":"Nhờ DNS tách cái tên dễ nhớ khỏi dãy số định tuyến, người ta có thể đổi địa chỉ IP của máy chủ mà không buộc người dùng phải ghi nhớ dãy số mới.","correct":true},{"text":"Vì tên miền đã được gắn cố định với một địa chỉ IP duy nhất ngay từ khi đăng ký nên địa chỉ IP tương ứng với một tên miền là không bao giờ thay đổi.","correct":false}],"explain":"(1) Đúng — việc tách tên miền khỏi địa chỉ IP cho phép chỉ cần sửa bản ghi DNS khi đổi máy chủ, người dùng không hề bị ảnh hưởng. (2) Sai — hiện tượng đó cho thấy đường truyền vẫn thông (vào thẳng IP được), chỉ khâu phân giải tên miền của DNS bị trục trặc, chứ không phải mất kết nối Internet. (3) Đúng — đây chính là lợi ích cốt lõi của DNS: con người giữ nguyên cái tên, còn dãy số phía sau có thể thay đổi tùy nhu cầu kỹ thuật. (4) Sai — địa chỉ IP ứng với một tên miền hoàn toàn có thể thay đổi, và chính khả năng đó là lý do người ta duy trì bản ghi DNS để cập nhật lại khi cần."},{"id":"CC-tf-2202","type":"tf","topic":"B","grade":12,"level":"medium","question":"Xét các phát biểu về hai mức quyền truy cập thư mục dùng chung:","statements":[{"text":"Được cấp quyền **chỉ đọc** với một thư mục dùng chung, người dùng vẫn sao chép được tệp trong đó về máy mình để dùng riêng.","correct":true},{"text":"Quyền **chỉ đọc** nghĩa là chỉ được mở xem tại chỗ chứ không thể tải hay sao chép tệp về máy của mình.","correct":false},{"text":"Quyền **đọc–ghi** cho phép người được cấp thêm tệp mới, sửa nội dung và xoá tệp ngay trong thư mục dùng chung.","correct":true},{"text":"Cấp quyền cho `Everyone` thay vì nêu đích danh từng tài khoản là cách làm an toàn hơn vì dễ quản lí danh sách người dùng.","correct":false}],"explain":"(1) Đúng — quyền chỉ đọc cho phép mở xem và tải tệp về máy mình bình thường; thứ duy nhất bị cấm là động vào bản gốc nằm trong thư mục dùng chung. (2) Sai — đây là nhầm lẫn hay gặp; chỉ đọc không hề cấm sao chép, nó chỉ chặn các thao tác làm thay đổi bản gốc như sửa, đổi tên, thêm hay xoá tệp. (3) Đúng — đọc–ghi là mức quyền cho phép thay đổi dữ liệu trong thư mục dùng chung: thêm, sửa, xoá đều được. (4) Sai — cấp cho `Everyone` là mở cửa cho bất kì máy nào trong mạng, kể cả máy của người không quen; muốn an toàn phải nêu đích danh đúng những tài khoản cần dùng."},{"id":"CC-tf-2203","type":"tf","topic":"B","grade":12,"level":"hard","question":"Máy tên `PC-GIAOVIEN` đã chia sẻ thư mục `TapSan2026` và một máy in cho cả phòng. Xét các phát biểu khi truy cập từ máy khác:","statements":[{"text":"Đường dẫn để mở thư mục là `\\\\PC-GIAOVIEN\\TapSan2026`, gồm hai dấu gạch chéo ngược, tên máy, rồi một dấu gạch chéo ngược và tên thư mục đã chia sẻ.","correct":true},{"text":"Sau khi ánh xạ thư mục thành ổ `Z:`, nếu `PC-GIAOVIEN` tắt máy thì ổ `Z:` vẫn mở được vì dữ liệu đã được chép sẵn sang máy người dùng.","correct":false},{"text":"Với máy in nối dây vào `PC-GIAOVIEN` rồi đem chia sẻ, muốn máy khác in được thì `PC-GIAOVIEN` phải đang bật và còn bật chia sẻ.","correct":true},{"text":"Nếu chiếc máy in có cổng mạng và được nối thẳng vào mạng thì việc in của các máy khác vẫn phải phụ thuộc vào `PC-GIAOVIEN` luôn bật.","correct":false}],"explain":"(1) Đúng — đây đúng là dạng đường dẫn tài nguyên trong mạng nội bộ: hai gạch chéo ngược mở đầu, tên máy, rồi gạch chéo ngược và tên thư mục dùng chung. (2) Sai — ổ đĩa mạng chỉ là một lối vào trỏ tới thư mục gốc còn nằm nguyên trên `PC-GIAOVIEN`, không hề có bản sao trên máy người dùng; máy nguồn tắt thì ổ `Z:` cũng không mở được. (3) Đúng — máy tính đang giữ máy in phải bật và còn bật chia sẻ thì các máy khác mới gửi lệnh in tới được, đây là nguyên nhân phổ biến khiến in mãi không ra giấy. (4) Sai — máy in có cổng mạng nối thẳng vào mạng thì phục vụ mọi người một cách độc lập, không phụ thuộc vào bất kì máy tính trung gian nào phải bật."},{"id":"CC-tf-2204","type":"tf","topic":"B","grade":12,"level":"medium","question":"Xét các phát biểu về rủi ro và cách phòng tránh khi chia sẻ tài nguyên trong mạng nội bộ:","statements":[{"text":"Chia sẻ càng rộng thì nguy cơ lộ dữ liệu càng lớn, vì bất kì máy nào trong mạng cũng đọc được thư mục đang mở.","correct":true},{"text":"Cấp quyền **đọc–ghi** cho càng đông người thì dữ liệu càng an toàn vì có nhiều người cùng trông coi.","correct":false},{"text":"Chỉ cần đặt mật khẩu truy cập thì có thể yên tâm đem cả ổ đĩa cá nhân chia sẻ cho toàn mạng mà không còn rủi ro nào.","correct":false},{"text":"Một thư mục dùng chung mà mọi máy đều ghi được có thể trở thành đường lây lan mã độc giữa các máy.","correct":true}],"explain":"(1) Đúng — mở một thư mục cho cả mạng nghĩa là ai ngồi trong mạng đó cũng đọc được, kể cả những tệp bạn quên là đã để lẫn trong đấy. (2) Sai — càng nhiều người có quyền đọc–ghi thì càng nhiều cơ hội cho một cái bấm nhầm làm sửa hỏng hoặc xoá mất dữ liệu; nên theo nguyên tắc cấp quyền tối thiểu đủ dùng chứ không phải cấp cho thật đông. (3) Sai — mật khẩu chỉ là một lớp chắn; vẫn phải chỉ chia sẻ đúng thư mục thật sự cần ở mức quyền thấp nhất, đem cả ổ đĩa cá nhân ra chia sẻ vẫn rất dễ lộ dữ liệu và xoá nhầm. (4) Đúng — thư mục dùng chung mà ai cũng ghi được là con đường thuận lợi để mã độc từ một máy đã nhiễm tự chép sang các máy còn lại."},{"id":"CC-tf-2302","type":"tf","topic":"E","grade":12,"level":"medium","question":"Xét các phát biểu về thẻ `<audio>`, `<video>` và các thuộc tính của chúng:","statements":[{"text":"Với thẻ `<video>`, nếu chỉ ghi `width` mà bỏ trống `height` thì trình duyệt tự tính chiều cao cho cân đối chứ không làm méo hình.","correct":true},{"text":"Bỏ thuộc tính `controls` khỏi thẻ `<audio>` thì thanh phát vẫn hiện đầy đủ nút bấm để người xem điều khiển như bình thường.","correct":false},{"text":"Thuộc tính `muted` thường được viết kèm `autoplay`, vì nhiều trình duyệt chặn việc tự phát khi đoạn phim còn tiếng.","correct":true},{"text":"Thuộc tính `loop` khiến đoạn phim tự phát ngay khi trang vừa mở mà người xem không cần bấm nút nào.","correct":false}],"explain":"(1) Đúng — khi chỉ cho một trong hai kích thước, trình duyệt tự suy ra giá trị còn lại theo tỉ lệ khung hình nên hình không bị méo. (2) Sai — không có `controls` thì thẻ `<audio>` gần như biến mất khỏi trang vì âm thanh không có gì để hiển thị; muốn có thanh nút bấm buộc phải viết `controls`. (3) Đúng — `muted` tắt tiếng thường đi cùng `autoplay` để vượt qua quy định chặn tự phát khi còn tiếng của nhiều trình duyệt. (4) Sai — làm phim tự phát khi mở trang là việc của `autoplay`; `loop` chỉ khiến phim hết lại quay về đầu chạy tiếp."},{"id":"CC-tf-2303","type":"tf","topic":"E","grade":12,"level":"hard","question":"Xét các phát biểu về khung nội tuyến `<iframe>`:","statements":[{"text":"Thuộc tính `src` của `<iframe>` nhận vào địa chỉ của cả một trang web, khác với `src` của `<video>` vốn nhận vào một tệp.","correct":true},{"text":"Trang được nhúng qua `<iframe>` chỉ là một ảnh chụp tĩnh của trang gốc nên người xem không thể bấm hay cuộn bên trong nó.","correct":false},{"text":"Có thể dùng `<iframe>` để đặt sẵn một biểu mẫu đăng kí trực tuyến vào giữa trang, giúp người xem điền và gửi ngay tại chỗ.","correct":true},{"text":"Giá trị `width` và `height` của `<iframe>` bắt buộc phải bằng đúng kích thước thật của trang được nhúng, nếu không trang sẽ không hiện ra.","correct":false}],"explain":"(1) Đúng — `src` của `<iframe>` trỏ tới nguyên một trang web đang chạy, trong khi `src` của `<video>` chỉ trỏ tới một tệp phim. (2) Sai — khung nội tuyến hiển thị trang thật đang chạy đầy đủ chứ không phải ảnh chụp; người xem bấm, cuộn, gõ chữ vào bên trong được. (3) Đúng — nhúng biểu mẫu trực tuyến để điền ngay tại chỗ là một công dụng điển hình của `<iframe>`. (4) Sai — `width` và `height` chỉ quy định kích thước ô cửa sổ mở trên trang của mình; đặt nhỏ hơn trang gốc thì phần dôi ra được cuộn xem, trang vẫn hiện bình thường."},{"id":"CC-tf-2304","type":"tf","topic":"E","grade":12,"level":"medium","question":"Xét các phát biểu về định dạng tệp và dung lượng khi đưa âm thanh, phim lên trang web:","statements":[{"text":"Định dạng `webm` thường cho tệp nhẹ hơn `mp4` ở cùng mức chất lượng, nhưng được ít trình duyệt hỗ trợ hơn.","correct":true},{"text":"Một đoạn phim dài vài phút có thể nặng gấp nhiều lần toàn bộ phần chữ của trang, khiến trang tải chậm, nhất là với người dùng mạng di động.","correct":true},{"text":"Vì định dạng tệp nhận ra được qua phần đuôi tên, nên cứ lấy thẳng tệp phim từ máy quay đưa lên trang là trình duyệt nào cũng mở được.","correct":false},{"text":"Đặt `autoplay` cho mọi đoạn phim nặng luôn là lựa chọn tốt nhất, vì phim hiện ra ngay sẽ giữ chân người xem.","correct":false}],"explain":"(1) Đúng — `webm` nén gọn hơn nên nhẹ hơn `mp4` ở cùng chất lượng, đổi lại mức hỗ trợ của trình duyệt chưa rộng bằng. (2) Đúng — tệp đa phương tiện rất nặng so với phần chữ, có thể làm trang tải chậm ì ạch, đặc biệt trên mạng di động. (3) Sai — nhìn đuôi tên chỉ biết được định dạng, không đảm bảo trình duyệt mở được; tệp lấy thẳng từ máy quay có thể ở định dạng không được hỗ trợ và cần chuyển đổi trước. (4) Sai — `autoplay` cho một đoạn phim nặng thường phản tác dụng vì trang tải lâu, nhiều người đóng trang trước khi phim kịp hiện; cần cân nhắc kĩ chứ không phải cứ dùng là tốt."},{"id":"CC-tf-2402","type":"tf","topic":"E","grade":12,"level":"hard","question":"Xét các phát biểu về cặp thẻ `<form>` và cách một biểu mẫu gửi dữ liệu đi:","statements":[{"text":"Với `method=\"get\"`, dữ liệu người dùng nhập được gắn vào phía sau địa chỉ trên thanh URL nên ai cũng có thể nhìn thấy.","correct":true},{"text":"Nếu để một ô nhập nằm ngoài cặp thẻ `<form>`, trình duyệt sẽ không vẽ ô đó ra và người dùng không gõ được vào nó.","correct":false},{"text":"Riêng phần HTML của biểu mẫu đã tự kiểm tra và lưu được dữ liệu vào nơi lưu trữ, không cần thêm chương trình xử lí nào khác.","correct":false},{"text":"Với dữ liệu riêng tư như mật khẩu, dùng `method=\"post\"` phù hợp hơn vì dữ liệu không hiện trên thanh địa chỉ.","correct":true}],"explain":"(1) Đúng — `get` gắn dữ liệu ngay sau địa chỉ trên thanh URL nên hiển thị công khai, chỉ hợp với dữ liệu ngắn và không nhạy cảm. (2) Sai — trình duyệt vẫn vẽ ô đó ra và người dùng vẫn gõ được bình thường; lỗi là khi bấm gửi thì dữ liệu trong ô nằm ngoài `<form>` không được gửi đi, nhìn bằng mắt rất khó phát hiện. (3) Sai — HTML chỉ dựng ra giao diện của biểu mẫu; việc kiểm tra và lưu dữ liệu là nhiệm vụ của chương trình đặt ở địa chỉ ghi trong thuộc tính `action`. (4) Đúng — `post` gói dữ liệu đi kèm yêu cầu chứ không hiện trên URL, nên hợp với dữ liệu dài hoặc riêng tư."},{"id":"CC-tf-2403","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"`required` là thuộc tính không cần giá trị; chỉ cần viết tên nó vào trong thẻ là ô đó trở thành bắt buộc phải điền mới gửi được biểu mẫu.","correct":true},{"text":"Với các nút `radio` và ô `checkbox`, thuộc tính `value` chính là nội dung được gửi đi khi mục đó được chọn.","correct":true},{"text":"Một ô nhập chỉ có tác dụng bắt buộc khi được gán đầy đủ dạng `required=\"yes\"`; nếu viết mỗi chữ `required` thì trình duyệt bỏ qua.","correct":false},{"text":"Nút gửi biểu mẫu bắt buộc phải viết bằng `<input type=\"submit\">`; thẻ `<button>` không thể làm nút gửi được.","correct":false}],"explain":"(1) Đúng — `required` là thuộc tính đặc biệt không cần gán giá trị, chỉ cần có mặt trong thẻ; ô nào có nó mà bỏ trống thì trình duyệt chặn lại và nhắc điền. (2) Đúng — với `radio` và `checkbox`, phần chữ hiển thị chỉ để người dùng nhìn, còn dữ liệu thật sự gửi đi khi mục được chọn chính là `value`. (3) Sai — chỉ cần viết mỗi tên `required` là đã có tác dụng, không bắt buộc phải gán `required=\"yes\"`. (4) Sai — nút gửi có thể viết bằng `<input type=\"submit\">` hoặc bằng cặp thẻ `<button type=\"submit\">...</button>`, cả hai đều gửi được biểu mẫu."},{"id":"CC-tf-2404","type":"tf","topic":"E","grade":12,"level":"hard","question":"Xét các phát biểu về việc chọn kiểu ô nhập phù hợp và quyền riêng tư khi thiết kế biểu mẫu:","statements":[{"text":"Dùng `checkbox` khi người dùng được chọn nhiều mục cùng lúc, còn `radio` khi chỉ được chọn đúng một mục trong nhóm.","correct":true},{"text":"Trong cặp thẻ `<select>`, phần chữ nằm giữa hai thẻ `<option>` là thứ người dùng nhìn thấy, còn thuộc tính `value` của nó mới là dữ liệu thật sự được gửi đi.","correct":true},{"text":"Muốn cho phép tích nhiều ô `checkbox` cùng lúc thì bắt buộc các ô đó phải có cùng một `name`, nếu để khác `name` sẽ không chọn được nhiều mục.","correct":false},{"text":"Một biểu mẫu đăng kí câu lạc bộ nên hỏi thêm số căn cước và địa chỉ nhà để hồ sơ đầy đủ hơn, dù các thông tin này không thật sự cần cho việc đăng kí.","correct":false}],"explain":"(1) Đúng — `checkbox` là ô vuông cho chọn nhiều mục cùng lúc, còn `radio` là nút tròn loại trừ lẫn nhau nên chỉ chọn được một mục trong nhóm. (2) Đúng — chữ giữa cặp `<option>` chỉ để người dùng đọc, còn dữ liệu gửi về nơi xử lí lấy từ thuộc tính `value` của `<option>` đó. (3) Sai — mỗi `checkbox` là một mục độc lập nên vẫn tích được nhiều ô bất kể đặt `name` giống hay khác nhau; quy tắc cùng `name` chỉ áp dụng cho nhóm `radio` để chúng loại trừ nhau. (4) Sai — nguyên tắc quyền riêng tư là chỉ hỏi những thông tin thật sự cần cho mục đích; thu thập thừa thông tin cá nhân không cần thiết là vi phạm quyền riêng tư của người điền."},{"id":"CC-tf-2502","type":"tf","topic":"E","grade":12,"level":"medium","question":"Xét các phát biểu về lớp giả trạng thái trong CSS:","statements":[{"text":"Lớp giả `:active` mô tả trạng thái phần tử đang bị nhấn giữ chuột xuống mà chưa thả ra.","correct":true},{"text":"Quy tắc `a:hover { color: red; }` làm chữ của liên kết chuyển sang đỏ khi có chuột rê lên và giữ nguyên màu đỏ đó ngay cả sau khi đã đưa chuột ra chỗ khác.","correct":false},{"text":"Lớp giả được viết bằng dấu hai chấm đặt ngay sau bộ chọn, không có dấu cách xen giữa, ví dụ `button:active`.","correct":true},{"text":"Khi rê chuột lên một liên kết đang áp `:hover`, nội dung văn bản của liên kết bị thay đổi theo trạng thái đó.","correct":false}],"explain":"(1) Đúng — `:active` là trạng thái phần tử đang bị tác động, tức khoảnh khắc người dùng bấm giữ chuột xuống mà chưa nhả, đúng như quy tắc `button:active` thường dùng để tạo cảm giác nút bị lún. (2) Sai — hiệu ứng `:hover` chỉ tồn tại trong đúng khoảng thời gian con trỏ còn nằm trên phần tử; rời chuột ra thì màu trở lại như cũ chứ không giữ lại màu đỏ. (3) Đúng — cú pháp lớp giả là bộ chọn viết liền với dấu hai chấm rồi tới tên trạng thái, tuyệt đối không chèn dấu cách, nếu không sẽ thành bộ chọn hậu duệ và mang nghĩa khác. (4) Sai — các lớp giả trạng thái chỉ đổi cách hiển thị (màu, nền...) trong đúng trạng thái đó, hoàn toàn không làm thay đổi nội dung văn bản của trang."},{"id":"CC-tf-2503","type":"tf","topic":"E","grade":12,"level":"hard","question":"Một phần tử đang chịu tác động của nhiều quy tắc CSS đặt cùng một thuộc tính với các giá trị khác nhau. Xét các phát biểu về việc quy tắc nào thắng:","statements":[{"text":"Nếu `body` đặt `color: navy` còn có thêm quy tắc `p { color: gray; }`, thì mọi đoạn văn hiển thị màu xám vì quy tắc nhắm thẳng vào `p` thắng màu kế thừa từ phần tử cha.","correct":true},{"text":"Bộ chọn lớp `.noibat` có mức ưu tiên cao hơn bộ chọn id `#tieude` vì tên lớp có thể gán cho nhiều phần tử nên tầm ảnh hưởng lớn hơn.","correct":false},{"text":"Khai báo viết thẳng trong thuộc tính `style` của thẻ mạnh hơn cả bộ chọn id lẫn bộ chọn lớp trong tệp CSS, chỉ chịu thua khai báo có gắn `!important`.","correct":true},{"text":"Bộ chọn phối hợp `p.ghichu` có cùng mức ưu tiên với bộ chọn tên thẻ `p` vì cả hai đều nhắm vào thẻ `p`.","correct":false}],"explain":"(1) Đúng — định dạng có được do kế thừa luôn yếu hơn một quy tắc viết trực tiếp cho phần tử, nên `p { color: gray; }` thắng màu navy chỉ truyền xuống từ `body`. (2) Sai — bậc thang ưu tiên xét theo phạm vi hẹp và cụ thể: bộ chọn id nhắm đúng một phần tử duy nhất nên thắng bộ chọn lớp, chứ không phải ngược lại; lí do đưa ra là bẫy đảo chiều. (3) Đúng — trong các mức thông thường, khai báo gắn tại chỗ trong thuộc tính `style` đứng trên mọi bộ chọn id và lớp; chỉ có `!important` mới vượt lên trên được mức này. (4) Sai — `p.ghichu` là bộ chọn phối hợp mang tính chất của bộ chọn lớp, nằm ở mức mạnh hơn bộ chọn theo tên thẻ đơn thuần như `p`, nên hai bộ chọn này không cùng mức ưu tiên."},{"id":"CC-tf-2504","type":"tf","topic":"E","grade":12,"level":"medium","question":"Xét các phát biểu về tính kế thừa của các thuộc tính CSS:","statements":[{"text":"Đặt `color` và `font-family` cho phần tử `body` thì các thuộc tính này tự động truyền xuống hầu hết phần tử con bên trong dù không viết quy tắc riêng cho chúng.","correct":true},{"text":"Đặt `background-color` cho một `div` thì màu nền đó tự động truyền xuống làm đổi màu nền của từng đoạn văn con nằm bên trong.","correct":false},{"text":"Nếu đặt `font-size` cho một phần tử `p`, cỡ chữ ấy sẽ được truyền ngược lên phần tử cha đang chứa `p`.","correct":false},{"text":"Thuộc tính `border` không có tính kế thừa, nên đặt viền cho một `div` không làm từng phần tử con bên trong tự mọc thêm viền riêng.","correct":true}],"explain":"(1) Đúng — các thuộc tính về chữ như `color`, `font-family`, `font-size` có tính kế thừa, nhờ vậy chỉ cần khai báo một lần ở `body` là gần như toàn bộ chữ trên trang đã đồng bộ. (2) Sai — `background-color` thuộc nhóm thuộc tính về khung bao quanh phần tử, không kế thừa; màu nền của `div` không tự lan xuống các đoạn văn con. (3) Sai — kế thừa chỉ truyền theo một chiều từ phần tử cha xuống phần tử con, không bao giờ truyền ngược từ con lên cha. (4) Đúng — `border` cùng nhóm khung với `margin`, `padding`, `background-color` nên không kế thừa; điều này hợp lí vì nếu viền cũng kế thừa thì mỗi phần tử con đều mọc thêm viền và trang sẽ rối tinh lên."},{"id":"CC-tf-2602","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Khai báo `width: 80%;` cho một khung nghĩa là khung đó rộng bằng 80% bề rộng của phần tử cha chứa nó, nên khung tự co giãn khi bề rộng phần tử cha thay đổi.","correct":true},{"text":"Để một trang web hiển thị vừa vặn như nhau trên cả điện thoại lẫn màn hình máy tính, nên ưu tiên đặt bề rộng bằng `px` thay vì `%` hay `em`.","correct":false},{"text":"Muốn canh một khối vào chính giữa theo chiều ngang bằng `margin: 0 auto;`, khối đó phải có `width` nhỏ hơn bề rộng của phần tử cha thì mới còn khoảng trống để chia đều hai bên.","correct":true},{"text":"Khai báo `margin: 0 auto;` và `text-align: center;` cho ra cùng một kết quả, vì cả hai đều đưa chiếc khung về chính giữa theo chiều ngang.","correct":false}],"explain":"(1) Đúng — `%` là đơn vị tương đối tính theo phần tử cha, nên `width: 80%` luôn bằng 80% bề rộng cha và tự thay đổi theo cha. (2) Sai — ngược lại mới đúng: `px` là đơn vị tuyệt đối, một khung đặt cứng bằng `px` sẽ tràn ra ngoài trên màn hình nhỏ; muốn co giãn vừa vặn phải ưu tiên đơn vị tương đối như `%` hoặc `em`. (3) Đúng — `auto` chia đều phần chỗ trống còn thừa cho lề trái và lề phải, nên nếu khối đã chiếm trọn bề ngang cha thì không còn chỗ để chia và kĩ thuật này vô hiệu. (4) Sai — `margin: 0 auto` canh giữa cả chiếc khung, còn `text-align: center` chỉ canh giữa dòng chữ nằm bên trong khung, hai thứ khác hẳn nhau."},{"id":"CC-tf-2603","type":"tf","topic":"E","grade":12,"level":"hard","question":"Một khung được khai báo `width: 200px; padding: 10px; border: 5px solid #333;`. Xét các phát biểu sau:","statements":[{"text":"Theo cách tính kích thước mặc định của trình duyệt, chiếc khung này thực sự chiếm bề rộng 230 px trên trang.","correct":true},{"text":"Nếu đổi khai báo đệm thành `padding: 5px 10px 15px 20px;` thì đệm trên là 5 px, đệm phải là 10 px, đệm dưới là 15 px và đệm trái là 20 px.","correct":true},{"text":"Nếu thêm `box-sizing: border-box;` cho khung này thì vùng chứa nội dung bên trong vẫn rộng đúng 200 px như con số khai báo ở `width`.","correct":false},{"text":"Viết `* { box-sizing: border-box; }` ở đầu tệp CSS sẽ áp cách tính kích thước đó cho mọi phần tử của trang.","correct":true}],"explain":"(1) Đúng — mặc định (`content-box`), `width` chỉ tính vùng nội dung, còn đệm và viền cộng thêm ra ngoài: 200 + 10 + 10 (đệm hai bên) + 5 + 5 (viền hai bên) = 230 px. (2) Đúng — cách viết bốn giá trị chạy theo thứ tự trên – phải – dưới – trái, nên lần lượt là 5, 10, 15, 20. (3) Sai — với `border-box`, `width: 200px` được hiểu là bề rộng cả khung kể cả đệm và viền, nên vùng nội dung phải tự co lại còn 200 − 20 (đệm) − 10 (viền) = 170 px, không còn là 200 px. (4) Đúng — dấu `*` là bộ chọn áp cho mọi phần tử, nên quy tắc này đặt `box-sizing: border-box` cho toàn trang, đó cũng là lí do nó hay được viết ngay đầu tệp CSS."},{"id":"CC-tf-2604","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Khai báo `border: 1px solid #333;` là cách viết gộp của ba thuộc tính `border-width`, `border-style` và `border-color` trên cùng một dòng.","correct":true},{"text":"Với một khung hình vuông, khai báo `border-radius: 50%;` sẽ bo bốn góc đến mức khung biến thành một hình tròn hoàn chỉnh.","correct":true},{"text":"Khai báo `overflow: hidden;` giữ lại toàn bộ nội dung tràn khung bằng cách tự động thêm thanh cuộn cho khung.","correct":false},{"text":"Trong khai báo `box-shadow: 0 2px 6px #cccccc;`, giá trị `6px` cho biết bóng bị đổ lệch xuống dưới 6 px.","correct":false}],"explain":"(1) Đúng — thứ tự viết gộp là độ dày, kiểu nét rồi màu, cách nhau bằng dấu cách, thay cho việc viết ba dòng riêng. (2) Đúng — với khung vuông, bán kính bo bằng 50% cạnh sẽ làm bốn góc gặp nhau thành đường tròn, đây là mẹo quen thuộc để tạo ảnh đại diện tròn. (3) Sai — `overflow: hidden` cắt bỏ hẳn phần nội dung tràn ra ngoài chứ không thêm thanh cuộn, nên người đọc mất luôn phần bị cắt; muốn có thanh cuộn khi cần thì dùng `overflow: auto`. (4) Sai — bốn phần của `box-shadow` theo thứ tự là độ dịch ngang, độ dịch dọc, độ nhoè rồi màu; ở đây `2px` mới là độ đổ xuống dưới, còn `6px` là độ nhoè của bóng."},{"id":"CC-tf-2702","type":"tf","topic":"G","grade":12,"level":"medium","question":"Xét các phát biểu về dữ liệu có nhãn và dữ liệu không nhãn:","statements":[{"text":"Dữ liệu không nhãn chỉ có phần mô tả đối tượng, còn thiếu phần đáp án đúng đi kèm.","correct":true},{"text":"Trong thực tế, dữ liệu có nhãn thường nhiều hơn dữ liệu không nhãn vì việc gắn nhãn diễn ra rất nhanh và gần như không tốn kém.","correct":false},{"text":"Muốn có một khối lượng lớn dữ liệu đã gắn nhãn thường phải bỏ ra nhiều công sức và chi phí cho việc con người xem xét, ghi chú từng mẫu.","correct":true},{"text":"Chuyện dữ liệu có nhãn hay không nhãn chỉ là chi tiết phụ, không phải căn cứ để chia học máy thành các nhóm phương pháp khác nhau.","correct":false}],"explain":"(1) Đúng — bản chất của dữ liệu không nhãn là chỉ giữ lại phần mô tả đối tượng (các con số, đặc điểm), còn phần đáp án đúng thì không có, nên máy không có gì để đối chiếu. (2) Sai — ngược lại mới đúng: gắn nhãn tốn nhiều công sức và tiền bạc nên trong thực tế dữ liệu không nhãn luôn nhiều hơn dữ liệu có nhãn rất nhiều lần. (3) Đúng — mỗi nhãn đều cần con người xác định và gán vào, ví dụ muốn có một triệu tấm ảnh ghi rõ nội dung thì phải có người ngồi xem và ghi chú từng tấm, vừa mất thời gian vừa tốn kém. (4) Sai — chính sự khác nhau giữa có nhãn và không nhãn mới là căn cứ quan trọng nhất để phân học máy thành học có giám sát, học không giám sát và học tăng cường."},{"id":"CC-tf-2703","type":"tf","topic":"G","grade":12,"level":"hard","question":"Xét các phát biểu về cách máy thực hiện phân cụm:","statements":[{"text":"Máy phân cụm dựa trên độ tương tự giữa các đối tượng: coi mỗi đối tượng như một điểm, hai điểm càng gần nhau thì càng dễ được xếp vào cùng một cụm.","correct":true},{"text":"Khi các cột số mô tả đối tượng chênh nhau rất nhiều về độ lớn, nên giữ nguyên để cột có giá trị lớn giữ vai trò quyết định khoảng cách.","correct":false},{"text":"Trong một kết quả phân cụm tốt, các đối tượng nằm cùng một cụm phải khác biệt rõ rệt, còn đối tượng ở hai cụm khác nhau lại gần giống nhau.","correct":false},{"text":"Điểm dữ liệu nằm lẻ loi, không chịu thuộc về cụm nào, có thể là dấu hiệu của một đối tượng bất thường đáng chú ý.","correct":true}],"explain":"(1) Đúng — phân cụm cần một cách đo độ tương tự; máy xem mỗi đối tượng là một điểm dựa trên các con số mô tả, rồi gom những điểm chụm lại gần nhau thành một cụm. (2) Sai — nếu để cột giá trị lớn (chẳng hạn chạy từ 10 đến 40) lấn át cột giá trị nhỏ (chạy từ 1 đến 5) thì khoảng cách sẽ bị méo; vì vậy trước khi phân cụm người ta thường đưa các cột về cùng một thang đo. (3) Sai — đảo ngược tiêu chí: một cụm tốt là các đối tượng trong cùng cụm thì gần giống nhau, còn đối tượng ở hai cụm khác nhau thì khác biệt rõ rệt. (4) Đúng — những điểm nằm tách hẳn khỏi mọi cụm thường báo hiệu điều bất thường, ví dụ một tài khoản có hành vi khác lạ so với số đông."},{"id":"CC-tf-2704","type":"tf","topic":"G","grade":12,"level":"hard","question":"Xét các phát biểu phân biệt phân cụm với phân loại:","statements":[{"text":"Nếu nhà trường quy định trước ba mức Tốt, Khá, Đạt rồi xếp mỗi học sinh vào đúng một mức trong ba mức đó, thì đây là bài toán phân loại và thuộc học có giám sát.","correct":true},{"text":"Vì phân loại và phân cụm đều cho ra kết quả là các nhóm đối tượng, nên thực chất chúng là cùng một bài toán, chỉ khác tên gọi.","correct":false},{"text":"Chạy phân cụm một lần yêu cầu chia thành 3 cụm rồi một lần chia thành 5 cụm, chắc chắn chỉ một trong hai cách chia là đúng còn cách kia là sai.","correct":false},{"text":"Ở phân cụm, sau khi máy tách xong các cụm thì con người mới nhìn lại từng cụm để tự đặt tên và giải thích ý nghĩa cho chúng.","correct":true}],"explain":"(1) Đúng — khi danh sách nhóm đã được con người định nghĩa và đặt tên từ trước, máy chỉ chọn trong đúng những nhãn ấy, đó là phân loại, mà phân loại luôn thuộc học có giám sát. (2) Sai — tuy kết quả trông giống nhau nhưng hai bài toán khác nhau ngay từ điểm xuất phát: phân loại có sẵn nhãn do người định nghĩa, còn phân cụm tự tách nhóm từ dữ liệu không nhãn. (3) Sai — không cách chia nào là sai cả; máy chỉ nói được những đối tượng nào nằm gần nhau, còn cách chia nào có ý nghĩa và dùng được thì do con người phán xét. (4) Đúng — máy không biết trước có mấy loại đối tượng cũng không biết gọi tên cụm là gì; việc hiểu ý nghĩa và đặt tên cho từng cụm là phần việc của con người, làm sau khi máy đã chia xong."},{"id":"CC-tf-2802","type":"tf","topic":"G","grade":12,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Khi một cột thời gian lẫn cả giá trị tính bằng phút và giá trị tính bằng giây, cần chuẩn hoá toàn cột về cùng một đơn vị trước khi tính giá trị trung bình.","correct":true},{"text":"Chỉ một số ít dòng ghi sai đơn vị, mỗi dòng lớn gấp hàng chục lần một dòng bình thường, cũng có thể kéo lệch đáng kể giá trị trung bình của cả một bảng lớn.","correct":true},{"text":"Một cột ngày tháng chỗ ghi `05/09/2025`, chỗ ghi `2025-09-06` thì vẫn được coi là cùng một định dạng nên không cần chuẩn hoá lại.","correct":false},{"text":"Một ô ghi bằng chữ như `khoảng 20` nằm trong cột số sẽ được máy tính tự động hiểu và chuyển thành số 20 khi tính toán.","correct":false}],"explain":"(1) Đúng — lẫn hai đơn vị trong cùng một cột thì mỗi con số không còn so sánh hay cộng gộp được với nhau; phải quy tất cả về một đơn vị (ví dụ đổi các giá trị tính bằng giây thành phút) rồi mới tính trung bình. (2) Đúng — trung bình rất nhạy với các giá trị quá lớn; chỉ mươi dòng ghi nhầm đơn vị, mỗi dòng lớn gấp mấy chục lần, đã đủ đẩy trung bình của hàng trăm dòng lệch đi vài lần. (3) Sai — `05/09/2025` và `2025-09-06` là hai định dạng ngày khác nhau (ngày/tháng/năm và năm-tháng-ngày); để lẫn như vậy máy sẽ hiểu sai, phải chuẩn hoá cả cột về một định dạng thống nhất. (4) Sai — một cột số chỉ nhận đúng các giá trị số; chữ như `khoảng 20` bị coi là sai kiểu, máy không tự suy ra được số, người làm dữ liệu phải sửa hoặc chuẩn hoá lại trước khi tính."},{"id":"CC-tf-2803","type":"tf","topic":"G","grade":12,"level":"medium","question":"Xét trách nhiệm khi thu thập dữ liệu về con người, cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Người tham gia một cuộc khảo sát cần được biết mình đang cung cấp dữ liệu và đồng ý tham gia.","correct":true},{"text":"Đã xin phép thu thập dữ liệu cho một mục đích thì về sau được tự do dùng lại dữ liệu đó cho bất kỳ mục đích nào khác.","correct":false},{"text":"Thay cột họ tên bằng một mã số vô nghĩa như `HS001`, `HS002` là cách ẩn danh thông tin định danh mà vẫn phân tích được dữ liệu.","correct":true},{"text":"Để phân tích cho chắc chắn, một khảo sát về phương tiện đi học nên thu thập càng nhiều thông tin cá nhân càng tốt, kể cả số điện thoại và địa chỉ nhà.","correct":false}],"explain":"(1) Đúng — nguyên tắc đầu tiên khi thu thập dữ liệu về con người là xin phép: người trả lời phải biết và đồng ý cung cấp dữ liệu của mình. (2) Sai — phải nêu rõ mục đích ngay từ đầu và về sau không được dùng dữ liệu sang một mục đích khác với điều đã thông báo; dùng lại tuỳ tiện là vi phạm cam kết với người cung cấp. (3) Đúng — khi phân tích số liệu chung, ta không cần biết ai trả lời dòng nào, nên thay họ tên bằng mã số vô nghĩa giúp ẩn danh thông tin định danh mà không ảnh hưởng đến kết quả phân tích. (4) Sai — nguyên tắc là chỉ thu thập vừa đủ cho mục đích đã nêu; hỏi thêm số điện thoại hay địa chỉ không giúp phân tích tốt hơn mà chỉ làm tăng rủi ro nếu tệp dữ liệu bị lộ."},{"id":"CC-tf-2804","type":"tf","topic":"G","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Dữ liệu từ cảm biến sinh ra khách quan và đều đặn, nhưng có thể bị gián đoạn khi thiết bị mất điện hoặc mất kết nối.","correct":true},{"text":"Với dữ liệu mở do cơ quan nhà nước công bố, người dùng có thể yêu cầu cơ quan đó đo thêm đúng những chỉ tiêu mà mình cần.","correct":false},{"text":"Nhật kí hoạt động của hệ thống thường có khối lượng rất lớn nhưng dễ lẫn nhiều dòng kĩ thuật không liên quan đến điều ta muốn tìm hiểu.","correct":true},{"text":"Vì khảo sát trực tuyến thu được đúng thứ cần hỏi nên kết quả luôn chính xác, không phụ thuộc vào việc người trả lời có nghiêm túc hay hiểu đúng câu hỏi hay không.","correct":false}],"explain":"(1) Đúng — cảm biến ghi số liệu đều đặn và ít bị ý muốn chủ quan chi phối, nhưng phụ thuộc vào tình trạng thiết bị nên có thể ngắt quãng khi mất điện, mất kết nối hoặc lệch chuẩn. (2) Sai — điểm hạn chế của dữ liệu mở là ta phải chấp nhận đúng những gì cơ quan đã công bố, không thể yêu cầu họ đo thêm chỉ tiêu riêng cho mình. (3) Đúng — nhật kí hệ thống rất lớn và trung thực, nhưng thường chứa nhiều dòng mang tính kĩ thuật không phục vụ trực tiếp câu hỏi phân tích, nên cần lọc bớt. (4) Sai — ưu điểm của khảo sát là hỏi đúng thứ cần, nhưng chất lượng phụ thuộc hoàn toàn vào việc người trả lời có nghiêm túc và hiểu đúng câu hỏi hay không, nên kết quả không mặc nhiên chính xác."},{"id":"CC-tf-2902","type":"tf","topic":"G","grade":12,"level":"medium","question":"Xét ba thao tác khai thác một bảng dữ liệu là lọc, sắp xếp và nhóm. Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Sắp xếp một cột theo thứ tự giảm dần giúp nhanh chóng nhận ra nhóm giá trị cao nhất vì chúng dồn lên đầu bảng.","correct":true},{"text":"Khi nhóm dữ liệu theo một cột rồi tính thống kê, mỗi nhóm được xử lí riêng và cho một kết quả thống kê riêng của nhóm đó.","correct":true},{"text":"Lọc, sắp xếp hay nhóm đều xoá bớt và làm mất dữ liệu gốc trong bảng, nên bắt buộc phải sao lưu bảng trước khi thực hiện.","correct":false},{"text":"Muốn biết mỗi loại món bán ra tổng cộng bao nhiêu suất trong ngày, cách đúng là lọc bảng lần lượt theo từng buổi sáng, trưa, chiều.","correct":false}],"explain":"(1) Đúng — sắp xếp giảm dần đưa các giá trị lớn nhất lên trên, nên chỉ cần nhìn vài dòng đầu là thấy ngay nhóm cao nhất. (2) Đúng — bản chất của nhóm dữ liệu là gom các dòng cùng giá trị ở một cột lại rồi tính thống kê cho từng gom, mỗi nhóm ra một con số riêng. (3) Sai — cả ba thao tác chỉ thay đổi cách ta nhìn vào bảng chứ không hề làm mất dữ liệu gốc; bảng ban đầu vẫn còn nguyên. (4) Sai — câu hỏi này cần nhóm theo cột Món rồi cộng cột số suất, chứ lọc theo buổi chỉ tách bảng theo thời điểm bán chứ không cho tổng của từng loại món."},{"id":"CC-tf-2903","type":"tf","topic":"G","grade":12,"level":"hard","question":"Số cuốn sách bảy bạn trong tổ mượn trong tuần lần lượt là: 2, 3, 3, 4, 4, 4, 22 (bạn cuối mượn cả bộ truyện dài). Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trung vị của dãy này bằng 4.","correct":true},{"text":"Vì dãy có giá trị 22 vượt trội nên trung bình cộng (bằng 6) mô tả mức mượn phổ biến của tổ trung thực hơn trung vị.","correct":false},{"text":"Tỉ lệ phần trăm cho biết một phần chiếm bao nhiêu so với tổng thể, điều mà một con số tuyệt đối đứng riêng không tự nói lên được.","correct":true},{"text":"Giá trị lớn nhất và nhỏ nhất của một cột luôn là các số liệu bất thường, cần loại bỏ trước khi tính bất kì đại lượng nào.","correct":false}],"explain":"(1) Đúng — dãy đã sắp tăng dần có 7 phần tử, giá trị đứng chính giữa là số thứ tư, tức là 4. (2) Sai — chính vì có giá trị 22 kéo lệch mà trung bình 6 cao hơn hẳn mức đa số các bạn mượn (2 đến 4 cuốn); ở trường hợp có giá trị đột biến thì trung vị mới phản ánh trung thực hơn. (3) Đúng — tỉ lệ phần trăm đặt phần đang xét bên cạnh tổng thể, cho biết nó chiếm bao nhiêu phần, điều mà một con số tuyệt đối một mình không diễn đạt được. (4) Sai — giá trị lớn nhất và nhỏ nhất cho biết khoảng biến động và giúp phát hiện điểm đáng ngờ, nhưng không phải cứ là hai đầu mút thì đều bất thường và phải bỏ đi."},{"id":"CC-tf-2904","type":"tf","topic":"G","grade":12,"level":"medium","question":"Xét việc dùng công cụ và quy trình để đọc một bảng dữ liệu. Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Một ưu điểm nổi bật của máy tính là khi thêm số liệu mới vào bảng thì mọi tổng, trung bình, tỉ lệ đều được tính lại gần như tức thì, không phải làm lại từ đầu.","correct":true},{"text":"Cách làm hợp lí là mở bảng ra tính hết mọi đại lượng có thể tính, sau đó mới chọn câu hỏi nào khớp với kết quả trông đẹp nhất.","correct":false},{"text":"Phần mềm bảng tính có sẵn các lệnh lọc, sắp xếp và tạo bảng tổng hợp theo nhóm trên thanh công cụ, nên có thể dùng mà không cần biết lập trình.","correct":true},{"text":"Một kết luận tốt chỉ cần nêu đúng con số kết quả, chẳng hạn ghi ‘75’, là đủ mà không cần diễn giải thành một câu có nghĩa.","correct":false}],"explain":"(1) Đúng — khả năng tính lại nhanh khi dữ liệu thay đổi là một thế mạnh lớn của máy tính so với tính tay, thêm một tháng số liệu là mọi kết quả tự cập nhật ngay. (2) Sai — quy trình đúng là xác định câu hỏi cụ thể trước, rồi mới chọn cột và phép tính phù hợp; tính lung tung mọi thứ rồi chọn câu hỏi theo kết quả đẹp là cách làm ngược và dễ dẫn tới kết luận khiên cưỡng. (3) Đúng — các thao tác lọc, sắp xếp, tổng hợp theo nhóm có sẵn trên giao diện phần mềm bảng tính, người dùng chỉ cần chọn vùng và bấm lệnh, không cần lập trình. (4) Sai — một con số trơ trọi chưa phải là kết luận; phải diễn giải thành một câu tiếng Việt có nghĩa và kèm con số làm bằng chứng thì mới trả lời được câu hỏi đặt ra."},{"id":"CC-tf-3002","type":"tf","topic":"G","grade":12,"level":"medium","question":"Xét các phát biểu về cách chạy kịch bản giả định ‘nếu... thì...’ trên một mô hình mô phỏng:","statements":[{"text":"Khi chạy một kịch bản giả định, ta giữ nguyên các quy tắc và cấu trúc của mô hình, mỗi lần chỉ thay đổi một tham số đầu vào rồi so sánh các đầu ra với nhau.","correct":true},{"text":"Muốn khảo sát cho nhanh, ta nên đổi đồng thời nhiều tham số đầu vào trong cùng một lần chạy để giảm bớt số lần thử.","correct":false},{"text":"Một kịch bản giả định chỉ đáng tin trong đúng phạm vi mà mô hình được xây dựng cho; ra ngoài phạm vi đó, con số máy trả về vẫn có nhưng không còn ý nghĩa.","correct":true},{"text":"Mỗi lần muốn thử một giá trị tham số mới, ta phải viết lại công thức của mô hình cho phù hợp thì kịch bản mới chạy được.","correct":false}],"explain":"(1) Đúng — bản chất của phép thử ‘nếu... thì...’ là cô lập một nguyên nhân: giữ nguyên toàn bộ mô hình, mỗi lần chỉ đổi đúng một tham số rồi đối chiếu đầu ra để biết tham số đó ảnh hưởng thế nào. (2) Sai — nếu đổi nhiều tham số cùng lúc mà kết quả có thay đổi thì không biết được thay đổi ấy do tham số nào gây ra, nên bắt buộc mỗi lần chỉ đổi một tham số. (3) Đúng — mô hình được dựng kèm các giả thiết chỉ có nghĩa trong một khoảng nhất định; vượt ra ngoài khoảng đó thì máy vẫn tính ra số nhưng con số đó không phản ánh điều gì đáng tin. (4) Sai — ưu điểm của cách bố trí ‘tham số ở trên, công thức tham chiếu ở dưới’ là ta chỉ cần sửa con số trong ô tham số, còn công thức và cấu trúc bảng giữ nguyên; không phải viết lại công thức mỗi lần thử."},{"id":"CC-tf-3003","type":"tf","topic":"G","grade":12,"level":"hard","question":"Một bạn dựng mô hình lan truyền tin trên bảng tính: ô `B1` chứa số người biết tin ban đầu, `B2` chứa số người mỗi người kể lại trong ngày, `B3` chứa sĩ số toàn trường; ô `B6` là số người biết ở dòng ngay trên, và công thức tại một dòng là `=MIN($B$3, B6*(1+$B$2))` rồi kéo xuống. Xét các phát biểu:","statements":[{"text":"Viết tham chiếu dạng `$B$3`, `$B$2` (có dấu đô la) giúp khi kéo công thức xuống, phần tham chiếu tới ô tham số không bị trượt theo, nên mọi dòng đều lấy đúng tham số ở đầu bảng.","correct":true},{"text":"Trong công thức, hàm `MIN` đóng vai trò một quy tắc chặn, bảo đảm số người biết tin không vượt quá sĩ số toàn trường dù phép nhân có cho ra con số lớn hơn.","correct":true},{"text":"Để đồng bộ với các ô tham số, phần tham chiếu `B6` cũng nên viết thành `$B$6` cho cố định thì công thức kéo xuống mới đúng.","correct":false},{"text":"Nếu gõ thẳng con số sĩ số vào từng công thức thay vì tham chiếu tới ô `B3`, thì khi muốn thử với một sĩ số khác ta vẫn chỉ cần sửa một ô là cả bảng tự cập nhật.","correct":false}],"explain":"(1) Đúng — dấu đô la tạo tham chiếu tuyệt đối, khoá cố định địa chỉ ô tham số nên mọi dòng phía dưới đều đọc đúng một giá trị ở đầu bảng khi kéo công thức. (2) Đúng — `MIN` lấy giá trị nhỏ hơn giữa sĩ số và kết quả phép nhân, nên khi phép nhân vượt sĩ số thì con số bị chặn lại ở sĩ số, đúng như thực tế không thể có nhiều người biết tin hơn tổng số học sinh. (3) Sai — `B6` phải là tham chiếu tương đối để khi kéo xuống nó trượt theo, luôn trỏ tới dòng ngay phía trên; nếu khoá thành `$B$6` thì mọi dòng đều lấy cùng một giá trị và mô hình tính sai. (4) Sai — nếu con số được gõ thẳng vào từng công thức thì muốn đổi sĩ số phải sửa lại tất cả các công thức đó; chỉ khi tham chiếu tới ô `B3` thì việc sửa một ô mới lan ra toàn bảng."},{"id":"CC-tf-3004","type":"tf","topic":"G","grade":12,"level":"medium","question":"Xét các phát biểu về mô phỏng ngẫu nhiên và về việc kiểm tra độ tin cậy của một mô hình:","statements":[{"text":"Với mô phỏng ngẫu nhiên, chỉ cần chạy một lần rồi kết luận là đủ, vì mỗi lần chạy đều phản ánh đúng bản chất của hệ thống.","correct":false},{"text":"Khi các lần chạy của một mô phỏng ngẫu nhiên cho kết quả lệch nhau, đó là bản chất của loại mô hình này chứ không phải dấu hiệu chương trình bị lỗi.","correct":true},{"text":"Để kiểm tra độ tin cậy, ta đối chiếu kết quả mô phỏng với số liệu thực đã biết; nếu lệch nhiều thì quay lại điều chỉnh tham số hoặc sửa quy tắc rồi thử lại.","correct":true},{"text":"Một mô hình đã cho kết quả khớp với số liệu thực ở một tình huống thì chắc chắn sẽ dự đoán đúng ở mọi tình huống khác.","correct":false}],"explain":"(1) Sai — mô phỏng ngẫu nhiên có yếu tố may rủi bên trong nên một lần chạy có thể rơi vào trường hợp may hoặc xui hiếm gặp; phải chạy nhiều lần rồi lấy trung bình thì con số mới đáng tin. (2) Đúng — kết quả lệch nhau giữa các lần chạy chính là đặc trưng của mô hình có yếu tố ngẫu nhiên, không phải là lỗi lập trình cần đi sửa. (3) Đúng — độ tin cậy được kiểm tra bằng cách cho mô hình chạy lại một tình huống đã biết kết quả thật rồi so khớp; lệch nhiều thì hiệu chỉnh tham số hoặc chính quy tắc của mô hình cho sát hơn. (4) Sai — khớp ở một tình huống chỉ cho thấy mô hình hợp lí trong phạm vi đó, không bảo đảm đúng ở mọi tình huống; các giả thiết đơn giản hoá có thể không còn phù hợp khi hoàn cảnh thay đổi."},{"id":"CC-mc-1891","type":"mc","topic":"E","grade":12,"level":"medium","question":"Trong một khối cha đã được gán `display: flex`, thuộc tính `justify-content: center` có tác dụng gì?","options":["Dồn cả hàng khối con về canh giữa theo chiều ngang của khối cha.","Tạo một khoảng cách đều đặn giữa các khối con để chúng không dính sát nhau.","Làm các khối con quay lại xếp chồng lên nhau thành từng dòng riêng.","Canh giữa phần chữ nằm bên trong mỗi khối con."],"answer":0,"explain":"Khi khối cha là `display: flex`, `justify-content` quyết định cả hàng khối con dồn về đâu — đầu hàng, giữa hàng, cuối hàng hay dàn đều ra hai bên; giá trị `center` đưa cả hàng vào giữa. Phương án thứ hai là việc của `gap`, không phải `justify-content`. Phương án thứ ba sai vì muốn các khối con xếp chồng trở lại thì phải bỏ `display: flex`, `justify-content` không làm điều đó. Phương án cuối nhầm giữa việc sắp xếp các khối con trong khối cha với việc canh chữ bên trong từng khối."},{"id":"CC-mc-1892","type":"mc","topic":"E","grade":12,"level":"medium","question":"Thẻ `<span>` mặc định là phần tử nội tuyến nên chỉ chiếm vừa đủ nội dung và nằm lọt trong dòng chữ. Muốn một thẻ `<span>` chiếm trọn cả một dòng riêng như thẻ `<div>`, bạn khai báo CSS nào cho nó?","options":["`display: inline;`","`justify-content: center;`","`display: none;`","`display: block;`"],"answer":3,"explain":"Kiểu cư xử khối hay nội tuyến do thuộc tính `display` quyết định và hoàn toàn đổi được bằng CSS: gán `display: block` cho một `<span>` sẽ khiến nó chiếm trọn cả dòng như một khối thật sự. `display: inline` giữ nguyên cách cư xử nội tuyến sẵn có nên không thay đổi gì. `display: none` ẩn hẳn phần tử đi, xem như nó không tồn tại trên trang — không phải điều ta muốn. `justify-content` chỉ có ý nghĩa với khối cha đã là `display: flex`, dùng để sắp xếp các khối con, không đổi được kiểu hiển thị của chính thẻ `<span>`."},{"id":"CC-mc-1893","type":"mc","topic":"E","grade":12,"level":"hard","question":"Cho đoạn mã sau. Khi mở trên trình duyệt, trang hiển thị ra sao?","code":"<style>\n  .hop { display: flex; gap: 10px; }\n  .o   { padding: 8px; border: 1px solid #333; }\n</style>\n\n<div class='hop'>\n  <div class='o'>A</div>\n  <div class='o'>B</div>\n</div>\n<div class='o'>C</div>","options":["Cả ba khối A, B, C nằm cạnh nhau trên cùng một hàng ngang, cách nhau 10px.","A và B nằm cạnh nhau trên một hàng ngang, cách nhau 10px; C nằm ở dòng riêng phía dưới.","Ba khối A, B, C xếp chồng lên nhau thành ba dòng riêng biệt, cách nhau 10px.","A và B nằm cạnh nhau nhưng dính sát nhau; C nằm cạnh B trên cùng hàng."],"answer":1,"explain":"`display: flex` chỉ tác động lên các phần tử con nằm trực tiếp bên trong khối cha mang nó. Ở đây khối cha `.hop` chứa đúng hai con là A và B, nên chỉ A và B xếp thành hàng ngang, cách nhau 10px nhờ `gap`. Khối C nằm ngoài `.hop`, là một `<div>` — vốn là phần tử khối — nên chiếm trọn cả dòng và nằm phía dưới. Phương án đầu sai vì C không phải con của `.hop` nên không chịu ảnh hưởng của `display: flex`. Phương án thứ ba sai vì A và B chắc chắn nằm ngang do khối cha đã là flex, hơn nữa `gap` không tạo khoảng cách cho các khối xếp chồng ngoài flex. Phương án cuối sai ở cả hai vế: `gap: 10px` có tác dụng nên A và B không dính sát, còn C thì xuống dòng."},{"id":"CC-tf-1891","type":"tf","topic":"E","grade":12,"level":"hard","question":"Bạn Khoa muốn ba mục menu nằm cạnh nhau thành một hàng ngang, canh giữa trang và cách đều nhau, nhưng đoạn mã dưới đây chưa cho ra kết quả đó. Cho biết mỗi phát biểu sau đúng hay sai:","code":"<style>\n  .thanh { gap: 24px; justify-content: center; }\n  .muc   { padding: 10px; border: 1px solid #333; }\n</style>\n\n<div class='thanh'>\n  <div class='muc'>Trang chu</div>\n  <div class='muc'>Gioi thieu</div>\n  <div class='muc'>Lien he</div>\n</div>","statements":[{"text":"Với đoạn mã đúng như trên, ba mục menu đã nằm cạnh nhau thành một hàng ngang.","correct":false},{"text":"Chỉ cần thêm `display: flex;` vào lớp `.thanh` là ba mục sẽ xếp thành một hàng ngang, canh giữa và cách nhau 24px.","correct":true},{"text":"Khi lớp `.thanh` chưa có `display: flex`, hai khai báo `gap: 24px` và `justify-content: center` không tạo ra được hàng ngang cho ba mục.","correct":true},{"text":"Có thể sửa bằng cách đặt `display: flex` cho lớp `.muc` thay vì cho lớp `.thanh`, kết quả vẫn là ba mục nằm trên một hàng ngang.","correct":false}],"explain":"Ý a sai: lớp `.thanh` chưa có `display: flex`, mà mỗi `<div>` mặc định là phần tử khối nên ba mục xếp chồng lên nhau thành ba dòng riêng. Ý b đúng: chỉ cần khai báo `display: flex` cho phần tử cha là các con trực tiếp tự xếp thành hàng ngang, khi đó `justify-content: center` và `gap: 24px` mới phát huy tác dụng canh giữa và tạo khoảng cách đều. Ý c đúng: `justify-content` và `gap` chỉ có ý nghĩa khi khối cha đã là flex; đứng một mình chúng không đổi được cách cư xử khối của ba `<div>` con. Ý d sai: `display: flex` phải đặt cho phần tử cha bao quanh. Đặt cho `.muc` chỉ biến từng mục thành một khối cha flex đối với nội dung bên trong nó, còn bản thân ba mục vẫn là khối nên vẫn xếp chồng lên nhau."},{"id":"CC-mc-2791","type":"mc","topic":"G","grade":12,"level":"medium","question":"Khảo sát phương tiện đến trường của một lớp 40 học sinh cho kết quả: đi bộ 10 bạn, xe đạp 18 bạn, xe buýt 8 bạn, được chở bằng xe máy 4 bạn. Muốn cho người xem thấy ngay mỗi nhóm chiếm bao nhiêu phần trong tổng số 40 học sinh của lớp thì nên chọn loại biểu đồ nào?","options":["Biểu đồ đường, vì bốn nhóm được nối tiếp nhau thành một đường liền.","Biểu đồ tròn, vì hình tròn chia thành các miếng thể hiện tỉ lệ của từng phần so với tổng thể.","Biểu đồ cột, vì chiều cao mỗi cột cho biết ngay tỉ lệ phần trăm của nhóm đó trong tổng số.","Không loại biểu đồ nào phù hợp, dữ liệu này chỉ nên để nguyên dạng bảng."],"answer":1,"explain":"Câu hỏi cần trả lời ở đây là “mỗi phần chiếm bao nhiêu trong một tổng thể”, đúng với mục đích của biểu đồ tròn: chia hình tròn thành các miếng, mỗi miếng ứng với một nhóm. Biểu đồ đường dùng để thể hiện xu hướng biến đổi theo thời gian, mà bốn phương tiện không phải là các mốc thời gian nên nối chúng thành đường là vô nghĩa. Biểu đồ cột dùng để so sánh giá trị giữa các nhóm — nó cho thấy nhóm nào nhiều hơn nhóm nào, nhưng không cho thấy trực tiếp phần đóng góp của mỗi nhóm trong tổng thể như biểu đồ tròn. Phương án cuối sai vì đây chính là trường hợp trực quan hoá giúp nắm thông tin nhanh hơn nhìn bảng số."},{"id":"CC-mc-2792","type":"mc","topic":"G","grade":12,"level":"medium","question":"Một biểu đồ đường thể hiện doanh thu của hai cửa hàng trong 12 tháng, vẽ bằng hai đường màu xanh và màu cam nhưng lại thiếu chú giải (`legend`). Người xem sẽ gặp khó khăn nào?","options":["Không biết đường màu nào ứng với cửa hàng nào, rất dễ đọc nhầm số liệu của cửa hàng này thành của cửa hàng kia.","Không biết doanh thu được tính bằng triệu đồng hay nghìn đồng.","Không biết biểu đồ đang nói về doanh thu hay về số lượng khách hàng.","Không xác định được tháng nào có doanh thu cao nhất trong 12 tháng."],"answer":0,"explain":"Chú giải chính là phần cho biết mỗi màu, mỗi đường tương ứng với đối tượng nào; thiếu nó thì hai đường vẫn hiện đủ hình dạng nhưng không thể gán chúng cho đúng cửa hàng. Phương án thứ hai là việc của đơn vị ghi kèm trục, không phải của chú giải. Phương án thứ ba là việc của tiêu đề biểu đồ. Phương án cuối sai vì đỉnh cao nhất của mỗi đường vẫn nhìn thấy được bình thường — chỉ có điều ta không biết đỉnh đó thuộc về cửa hàng nào, và đó lại chính là nội dung của phương án đúng."},{"id":"CC-mc-2793","type":"mc","topic":"G","grade":12,"level":"hard","question":"Số học sinh đăng kí hai câu lạc bộ của một trường trong ba năm như sau — năm 2023: CLB Tin học 20, CLB Bóng rổ 60; năm 2024: Tin học 30, Bóng rổ 66; năm 2025: Tin học 45, Bóng rổ 72. Một bạn vẽ biểu đồ cột với trục tung bắt đầu từ 0 rồi kết luận: “CLB Bóng rổ phát triển mạnh hơn hẳn CLB Tin học, vì cột của Bóng rổ năm nào cũng cao hơn hẳn.” Nhận xét nào sau đây đúng?","options":["Kết luận đúng, vì cột cao hơn ở cả ba năm chứng tỏ câu lạc bộ đó phát triển mạnh hơn.","Kết luận sai, vì biểu đồ cột không dùng được cho dữ liệu trải theo nhiều năm, phải chuyển sang biểu đồ tròn mới so sánh được.","Không thể nhận xét gì cho tới khi biết chắc trục tung của biểu đồ có bị cắt bớt hay không.","Kết luận sai, vì chiều cao cột chỉ cho biết số lượng của từng năm: xét mức tăng thì Tin học đi từ 20 lên 45 (hơn gấp đôi), còn Bóng rổ chỉ đi từ 60 lên 72 (tăng khoảng 20%)."],"answer":3,"explain":"Đối chiếu lại với số liệu gốc sẽ thấy hai câu hỏi khác nhau đang bị trộn làm một: “câu lạc bộ nào đông hơn” và “câu lạc bộ nào phát triển nhanh hơn”. Chiều cao cột trả lời câu hỏi thứ nhất — Bóng rổ luôn đông hơn. Nhưng về mức tăng, Tin học đi từ 20 lên 45, tức tăng 25 người và gấp 2,25 lần; Bóng rổ đi từ 60 lên 72, chỉ tăng 12 người và gấp 1,2 lần, nên Tin học mới là bên phát triển nhanh hơn. Phương án đầu chính là lỗi suy luận cần tránh. Phương án thứ hai sai vì biểu đồ cột hoàn toàn dùng được để so sánh các nhóm qua từng năm, còn biểu đồ tròn chỉ hợp khi cần thể hiện tỉ lệ của một tổng thể. Phương án thứ ba sai vì đề đã nói rõ trục tung bắt đầu từ 0, tức biểu đồ vẽ trung thực — vấn đề nằm ở cách đọc, không nằm ở cách vẽ."},{"id":"CC-tf-2791","type":"tf","topic":"G","grade":12,"level":"hard","question":"Cho bảng lượng mưa trung bình tại một thành phố trong sáu tháng đầu năm (đơn vị mm) — tháng 1: 20; tháng 2: 15; tháng 3: 45; tháng 4: 90; tháng 5: 180; tháng 6: 240. Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Vì đây là dữ liệu biến đổi theo thời gian nên biểu đồ đường là lựa chọn phù hợp để thấy xu hướng lượng mưa qua sáu tháng.","correct":true},{"text":"Biểu đồ tròn là lựa chọn tốt nhất nếu muốn thấy lượng mưa thay đổi ra sao qua từng tháng.","correct":false},{"text":"Nếu vẽ biểu đồ cột với trục tung bắt đầu từ 0 thì cột tháng 6 cao gấp 12 lần cột tháng 2.","correct":false},{"text":"Nếu trục tung bị cắt, chỉ bắt đầu từ mốc 50 mm, thì ba tháng đầu sẽ không hiện cột, khiến người xem dễ tưởng ba tháng đó hoàn toàn không có mưa.","correct":true}],"explain":"Ý a đúng: sáu tháng là các mốc thời gian nối tiếp nhau, đúng với mục đích của biểu đồ đường — nối các điểm lại sẽ thấy ngay đường dốc lên rõ rệt từ tháng 3 trở đi. Ý b sai: biểu đồ tròn thể hiện tỉ lệ của từng phần so với tổng thể, không thể hiện được diễn biến theo thời gian; muốn thấy thay đổi qua từng tháng phải dùng biểu đồ đường. Ý c sai: 240 chia 15 bằng 16, nên cột tháng 6 cao gấp 16 lần cột tháng 2 chứ không phải 12 lần. Ý d đúng: cắt trục tung là kiểu trình bày dễ gây hiểu nhầm — tháng 1 (20 mm), tháng 2 (15 mm) và tháng 3 (45 mm) đều dưới mốc 50 mm nên bị mất khỏi biểu đồ, trong khi số liệu thật cho thấy ba tháng đó vẫn có mưa."},{"id":"CC-mc-2291","type":"mc","topic":"G","grade":12,"level":"medium","question":"Một mô hình học từ ba căn nhà: 40 m² → 800 triệu đồng, 60 m² → 1200 triệu đồng, 80 m² → 1600 triệu đồng. Theo quy luật rút ra từ dữ liệu đó, căn nhà 70 m² được ước lượng khoảng bao nhiêu, và đây là dạng bài toán nào?","options":["Khoảng 1400 triệu đồng; đây là bài toán dự đoán số.","Khoảng 1400 triệu đồng; đây là bài toán phân loại, vì máy phải chọn ra một mức giá.","Khoảng 1200 triệu đồng; đây là bài toán dự đoán số, vì máy chỉ được phép trả lại một giá trị đã xuất hiện trong dữ liệu học.","Không ước lượng được, vì trong dữ liệu học không có căn nhà nào rộng đúng 70 m²."],"answer":0,"explain":"Ba mẫu đều cho cùng một tỉ lệ 20 triệu đồng mỗi mét vuông (800/40 = 1200/60 = 1600/80 = 20), nên 70 m² ứng với 70 × 20 = 1400 triệu đồng. Đầu ra là một con số bất kì trong một khoảng, vậy đây là dự đoán số chứ không phải phân loại — phân loại chỉ chọn một nhãn trong danh sách hữu hạn nhãn có sẵn, nên phương án B gọi sai tên dạng bài toán. Phương án C sai ở chỗ mô hình dự đoán số không hề bị bó buộc vào các giá trị đã thấy. Phương án D đi ngược mục đích của học máy: máy học quy luật chung chính là để trả lời được cho dữ liệu mới chưa từng gặp."},{"id":"CC-mc-2292","type":"mc","topic":"G","grade":12,"level":"medium","question":"Mô hình lọc thư rác đã học từ ba thư mẫu: hai thư gán nhãn “Rác”, một thư gán nhãn “Không rác”. Nay đưa vào một thư mới — quảng cáo giảm giá, có đường link lạ, không rõ người gửi. Đầu ra của mô hình có dạng thế nào?","options":["Một nhãn chọn trong hai nhãn có sẵn — “Rác” hoặc “Không rác”; ở đây các dấu hiệu giống các thư rác đã học nên nhãn nhiều khả năng là “Rác”.","Một con số bất kì trong khoảng từ 0 đến 100, cho biết bức thư dài bao nhiêu chữ.","Một nhãn hoàn toàn mới do mô hình tự nghĩ ra, ví dụ “Quảng cáo”, vì thư này không giống hẳn thư nào trong ba thư đã học.","Không có đầu ra nào, vì bức thư mới chưa được con người gán nhãn sẵn nên mô hình không xử lí được."],"answer":0,"explain":"Lọc thư rác là bài toán phân loại: đầu ra luôn là MỘT nhãn lấy trong tập nhãn hữu hạn đã biết trước lúc huấn luyện, ở đây là “Rác” và “Không rác”. Phương án B mô tả đầu ra của bài toán dự đoán số, và số chữ trong thư còn là dữ liệu đầu vào chứ không phải kết quả cần tìm. Phương án C sai vì mô hình phân loại không tự sinh thêm nhãn mới. Phương án D lẫn lộn hai vai: dữ liệu HUẤN LUYỆN mới cần có nhãn sẵn, còn nhãn của dữ liệu mới chính là thứ mô hình phải tự đưa ra."},{"id":"CC-mc-2293","type":"mc","topic":"G","grade":12,"level":"hard","question":"Một nhóm huấn luyện mô hình phân loại thư rác. Đo xong, mô hình đạt độ chính xác 99% trên tập huấn luyện nhưng chỉ 62% trên tập kiểm tra. Kết luận nào hợp lí nhất?","options":["Mô hình nhiều khả năng chỉ “học vẹt” — ghi nhớ máy móc các mẫu đã thấy — nên làm việc kém với dữ liệu mới; chưa thể đem dùng mà phải xem lại.","Mô hình rất tốt: 99% đo trên phần dữ liệu nhiều hơn nên đáng tin hơn, còn 62% chỉ là chuyện xui rủi ngẫu nhiên.","Chỉ cần gộp luôn tập kiểm tra vào tập huấn luyện rồi đo lại; độ chính xác sẽ lên gần 99% và mô hình coi như đạt.","Hai con số này không so sánh được với nhau, vì độ chính xác chỉ dùng cho bài toán dự đoán số chứ không dùng cho phân loại."],"answer":0,"explain":"Điều đáng chú ý không phải từng con số mà là khoảng cách giữa chúng: giỏi trên dữ liệu đã học nhưng kém hẳn trên dữ liệu chưa từng thấy đúng là dấu hiệu máy nhớ vẹt các mẫu cũ thay vì nắm quy luật chung. Phương án B lấy nhầm thước đo: con số duy nhất phản ánh năng lực thật là con số trên dữ liệu mới, tức 62%. Phương án C phá hỏng phép đánh giá — gộp tập kiểm tra vào huấn luyện thì không còn dữ liệu mới nào để kiểm tra, con số cao thu được chỉ là ảo. Phương án D sai ngay từ khái niệm: độ chính xác (tỉ lệ dự đoán đúng) chính là thước đo của bài toán phân loại."},{"id":"CC-tf-2291","type":"tf","topic":"G","grade":12,"level":"hard","question":"Một trường học có 1000 hồ sơ học sinh; mỗi hồ sơ ghi số giờ tự học mỗi tuần, số buổi vắng và điểm thi cuối kì (một số từ 0 đến 10) đã biết. Nhà trường dùng 800 hồ sơ để huấn luyện và giữ lại 200 hồ sơ để kiểm tra. Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Nếu mục tiêu là ước lượng điểm thi cuối kì của một học sinh mới thì đây là bài toán dự đoán số.","correct":true},{"text":"Nếu đổi mục tiêu thành xếp mỗi học sinh vào một trong ba mức Giỏi / Khá / Trung bình thì đây là bài toán phân loại.","correct":true},{"text":"Nên đưa nốt 200 hồ sơ kiểm tra vào phần huấn luyện để máy học được nhiều hơn; độ chính xác đo sau đó sẽ đáng tin hơn.","correct":false},{"text":"Vì cả 1000 hồ sơ đều đã biết sẵn điểm thi nên không thể dùng chúng để huấn luyện mô hình.","correct":false}],"explain":"a) Đúng: kết quả cần tìm là một con số bất kì trong khoảng 0 đến 10, đúng đặc điểm của dự đoán số. b) Đúng: lúc này kết quả cần tìm là một nhãn trong ba nhãn có sẵn, đúng đặc điểm của phân loại — cùng một bộ dữ liệu vẫn có thể phục vụ hai dạng bài toán khác nhau tuỳ câu hỏi đặt ra. c) Sai: học nhiều hơn thì được, nhưng khi đó không còn hồ sơ nào là “mới” để đánh giá, con số đo được chỉ nói lên khả năng nhớ bài chứ không nói lên khả năng làm việc thật. d) Sai: ngược lại, có sẵn kết quả đúng chính là điều kiện để máy học ra quy luật; phần kết quả đã biết đó cũng là căn cứ để chấm xem mô hình đoán đúng bao nhiêu phần trăm."},{"id":"CC-mc-891","type":"mc","topic":"D","grade":12,"level":"medium","question":"Để tiện liên lạc, lớp trưởng lập một bảng gồm họ tên, số điện thoại và địa chỉ nhà của toàn bộ học sinh trong lớp, rồi chụp lại và đăng lên trang cá nhân ở chế độ công khai. Nhận định nào sau đây là đúng nhất?","options":["Không sao, vì đó là thông tin do chính các bạn tự cung cấp cho lớp.","Chỉ cần che số nhà là được, còn họ tên và số điện thoại thì công khai thoải mái vì đâu phải bí mật gì.","Đây là việc đưa dữ liệu cá nhân của người khác ra ngoài mục đích ban đầu khi chưa được họ đồng ý, tức là xâm phạm quyền riêng tư.","Chỉ bị coi là vi phạm nếu sau đó thật sự có bạn trong lớp bị làm phiền hoặc bị lừa đảo."],"answer":2,"explain":"Quyền riêng tư là quyền của mỗi người được quyết định ai được xem, lưu và chia sẻ dữ liệu cá nhân của mình, nên C đúng: các bạn đưa số điện thoại và địa chỉ để lớp liên lạc nội bộ, chứ không đồng ý cho đăng công khai. A sai vì đồng ý cung cấp cho một mục đích không có nghĩa là đồng ý với mọi mục đích khác. B sai vì họ tên gắn với số điện thoại đã là dữ liệu cá nhân, và bộ đôi này thừa sức để kẻ xấu nhắm tới từng người. D sai vì hành vi chia sẻ trái phép đã là vi phạm ngay khi thực hiện; hậu quả nếu xảy ra chỉ làm mức độ nặng thêm chứ không phải điều kiện để xác định vi phạm."},{"id":"CC-mc-892","type":"mc","topic":"D","grade":12,"level":"hard","question":"Nhóm của Bình dùng một công cụ AI để viết toàn bộ bài thuyết trình môn Địa lí, trong đó có mấy con số thống kê do AI đưa ra mà nhóm không kiểm chứng lại, rồi nộp bài và ghi tên cả nhóm là người thực hiện. Đánh giá và cách làm nào là đúng đắn nhất?","options":["Không có vấn đề gì, AI cũng chỉ là một công cụ, dùng công cụ nào để làm bài là quyền của nhóm.","Nhóm chỉ thiếu sót ở chỗ chưa ghi rõ là có dùng AI; còn số liệu do AI đưa ra thì mặc nhiên đáng tin vì AI tổng hợp từ rất nhiều nguồn.","Chỉ cần diễn đạt lại toàn bộ câu chữ cho khác đi là có thể coi bài viết là sản phẩm của nhóm.","Nhóm cần nói rõ phần nào có sự hỗ trợ của AI và phải tự kiểm chứng các số liệu ở nguồn đáng tin cậy trước khi đưa vào bài."],"answer":3,"explain":"Văn hoá ứng xử số đòi hỏi trung thực và trách nhiệm, đặc biệt khi dùng công cụ AI: phải minh bạch về mức độ hỗ trợ và không lan truyền thông tin sai — nên D đúng. A sai vì nộp sản phẩm của công cụ dưới danh nghĩa công sức của mình là thiếu trung thực, khác hẳn việc dùng công cụ để hỗ trợ. B sai ở vế sau, và đây là lầm tưởng nguy hiểm nhất: AI có thể đưa ra số liệu nghe rất thuyết phục nhưng không có thật, người dùng vẫn phải chịu trách nhiệm về những gì mình phát ngôn. C sai vì viết lại câu chữ không tạo ra hiểu biết hay công sức nào của nhóm, và cũng không làm cho các số liệu chưa kiểm chứng trở nên đáng tin."},{"id":"CC-tf-891","type":"tf","topic":"D","grade":12,"level":"hard","question":"Trong nhóm chat của khối lan ra tin đồn rằng bạn T đã lấy tiền quỹ lớp. Chưa ai kiểm chứng, nhưng nhiều người chia sẻ tiếp sang các nhóm khác, một bạn còn ghép ảnh T kèm dòng chữ chế giễu. Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Ghép ảnh T kèm nội dung chế giễu rồi phát tán là hành vi xúc phạm danh dự người khác, thuộc nhóm hành vi bị pháp luật về an ninh mạng nghiêm cấm.","correct":true},{"text":"Những người chỉ bấm chia sẻ lại, không tự viết ra nội dung đó, thì không phải chịu trách nhiệm gì.","correct":false},{"text":"Vì nội dung chỉ lưu hành trong các nhóm chat của học sinh chứ không đăng công khai nên không thể coi là lan truyền thông tin sai sự thật.","correct":false},{"text":"Cách ứng xử có trách nhiệm là không chia sẻ tiếp, đề nghị gỡ nội dung xuống và báo với giáo viên hoặc người có trách nhiệm để xác minh.","correct":true}],"explain":"a) Đúng: xúc phạm danh dự, nhân phẩm và vu khống người khác trên mạng nằm trong nhóm hành vi bị nghiêm cấm, người vi phạm có thể bị xử lí. b) Sai: mỗi lượt chia sẻ đều góp phần đẩy thông tin chưa kiểm chứng đi xa hơn, nên người chia sẻ cũng có phần trách nhiệm với hậu quả. c) Sai: phạm vi kín hay công khai chỉ ảnh hưởng tới tốc độ lan truyền; nội dung sai sự thật về một người cụ thể vẫn gây tổn hại thật, và chỉ cần một ảnh chụp màn hình là nó ra khỏi nhóm. d) Đúng: dừng chuỗi chia sẻ, đề nghị gỡ nội dung và chuyển việc xác minh cho người có trách nhiệm vừa bảo vệ T, vừa làm rõ sự việc đúng cách."},{"id":"CC-mc-893","type":"mc","topic":"D","grade":12,"level":"medium","question":"Giờ ra chơi, Hùng quay được đoạn video một bạn cùng lớp trượt ngã, quần áo lấm lem, trông rất buồn cười. Cách ứng xử phù hợp với quyền riêng tư và văn hoá ứng xử số là gì?","options":["Đăng lên trang cá nhân nhưng đặt chế độ “chỉ bạn bè xem”, như vậy không tính là công khai.","Hỏi ý kiến bạn ấy trước; chỉ chia sẻ nếu bạn đồng ý, còn nếu bạn không đồng ý thì xoá và không gửi cho ai.","Gửi riêng cho vài người bạn thân trong nhóm chat kín, vì nhóm kín thì không ảnh hưởng gì đến bạn ấy.","Đăng kèm dòng chú thích “mình không có ý gì đâu nhé” để thể hiện thiện chí."],"answer":1,"explain":"Đáp án B đúng: hình ảnh của một người là dữ liệu cá nhân của chính người đó, nên họ có quyền quyết định ai được xem, được lưu và được chia sẻ; hỏi trước và tôn trọng câu trả lời là cách ứng xử đúng. A sai: chế độ “chỉ bạn bè” vẫn là chia sẻ cho hàng trăm người, và nội dung có thể bị chụp màn hình rồi lan ra ngoài — thu hẹp phạm vi không xoá được việc chưa xin phép. C sai: gửi vào nhóm kín cũng là chia sẻ dữ liệu của người khác khi chưa được đồng ý, mà tin nhắn thì rất dễ bị chuyển tiếp. D sai: một dòng chú thích thiện chí không phải là sự cho phép của người trong video, và tổn thương cho bạn ấy vẫn xảy ra."},{"id":"CC-mc-894","type":"mc","topic":"D","grade":12,"level":"hard","question":"Duy được nhờ làm giấy khen cho khối 12 nên đang giữ một tệp gồm họ tên, ngày sinh và số căn cước của 40 học sinh. Để tiết kiệm thời gian, Duy định dán toàn bộ tệp đó vào một công cụ AI trực tuyến miễn phí và nhờ nó định dạng lại cho đẹp. Nhận định nào sau đây đúng nhất?","options":["Không sao, vì Duy chỉ nhờ máy sắp xếp chứ có đăng dữ liệu đó công khai ở đâu đâu.","Vì thầy cô và ban cán sự cũng đang giữ tệp này nên nó đã là thông tin công khai, Duy được toàn quyền sử dụng.","Duy đang đưa dữ liệu cá nhân của 40 người cho một dịch vụ bên thứ ba khi chưa được họ đồng ý; nên tự làm bằng phần mềm soạn thảo, hoặc bỏ bớt các trường nhạy cảm trước khi nhờ công cụ AI.","Chỉ cần Duy xoá đoạn hội thoại với công cụ AI sau khi dùng xong thì coi như dữ liệu chưa từng bị chia sẻ."],"answer":2,"explain":"Đáp án C đúng: họ tên, ngày sinh và nhất là số căn cước đều là dữ liệu cá nhân, mà chủ của dữ liệu là 40 bạn kia chứ không phải Duy — Duy chỉ được giao giữ để làm một việc cụ thể. Gửi trọn tệp cho một dịch vụ bên ngoài là chia sẻ dữ liệu khi chưa được đồng ý; cách an toàn là xử lí ngay trên máy hoặc chỉ đưa phần dữ liệu đã lược bỏ thông tin nhạy cảm. A sai: “không đăng công khai” không có nghĩa là không chia sẻ — gửi cho một dịch vụ bên thứ ba đã là chia sẻ, và dữ liệu có thể được lưu lại trên máy chủ của họ. B sai: việc vài người được giao giữ dữ liệu để làm nhiệm vụ không biến dữ liệu đó thành thông tin công khai; mỗi người chỉ được dùng đúng mục đích được giao. D sai: xoá đoạn hội thoại ở phía người dùng không thu hồi được bản đã gửi đi, cũng không xoá được bản lưu phía dịch vụ."},{"id":"CC-mc-895","type":"mc","topic":"D","grade":12,"level":"hard","question":"Bực vì bị điểm kém, Tú lập một tài khoản mạng xã hội lấy tên và ảnh của cô giáo chủ nhiệm rồi đăng vài dòng trạng thái châm biếm “cho vui”. Nhận định nào sau đây đúng nhất?","options":["Mạo danh người khác và đăng nội dung xúc phạm danh dự trên mạng là hành vi bị pháp luật nghiêm cấm; mọi hoạt động trên mạng đều để lại dấu vết nên vẫn truy ra được người thực hiện để xử lí.","Vì Tú không dùng tên thật của mình và cũng không gây thiệt hại tiền bạc nào nên hành vi này không bị coi là vi phạm.","Chỉ khi cô giáo chứng minh được mình bị mất việc hoặc thiệt hại tài chính thì hành vi mới bị xử lí.","Nếu Tú xoá tài khoản sau vài giờ thì coi như chưa có chuyện gì xảy ra và cũng không còn bằng chứng."],"answer":0,"explain":"Đáp án A đúng: pháp luật về an ninh mạng nghiêm cấm việc mạo danh, xúc phạm, vu khống người khác trên không gian mạng, và người vi phạm có thể bị xử lí theo quy định; mặt khác mỗi lần đăng kí, đăng nhập hay đăng bài đều để lại dấu vết kĩ thuật nên việc “ẩn danh” không hề bảo vệ được người vi phạm. B sai: hành vi bị đánh giá qua chính việc mạo danh và xúc phạm danh dự, không phụ thuộc người thực hiện có giấu tên hay không. C sai: thiệt hại tài chính không phải điều kiện bắt buộc — xâm phạm danh dự, uy tín của người khác đã là hành vi bị cấm. D sai: nội dung đã đăng có thể bị người khác chụp màn hình và chia sẻ lại, nhà cung cấp dịch vụ vẫn lưu nhật kí hoạt động, nên xoá tài khoản không xoá được hậu quả lẫn bằng chứng."},{"id":"CC-tf-892","type":"tf","topic":"D","grade":12,"level":"hard","question":"Nhóm của Khuê làm một video dự thi “Trường em xanh — sạch — đẹp” rồi đăng công khai lên kênh của trường, không nhằm mục đích kinh doanh. Cho biết mỗi việc làm sau là đúng hay sai:","statements":[{"text":"Lấy ảnh tìm được qua công cụ tìm kiếm chèn thẳng vào video mà không kiểm tra điều kiện sử dụng, vì ảnh đã ở trên mạng thì ai cũng được dùng.","correct":false},{"text":"Ưu tiên chọn ảnh và nhạc có nhãn cho phép dùng lại (ví dụ Creative Commons), dùng đúng điều kiện của giấy phép và ghi nguồn đầy đủ.","correct":true},{"text":"Nhờ công cụ AI viết bản nháp lời bình, nhóm tự kiểm tra và biên tập lại, đồng thời ghi rõ trong phần mô tả rằng lời bình có sự hỗ trợ của AI.","correct":true},{"text":"Quay cận mặt các bạn học sinh khác rồi đưa vào video công khai mà không hỏi, vì video có mục đích tốt nên không cần xin ý kiến các bạn.","correct":false}],"explain":"Ý a SAI: nội dung dễ tải về không có nghĩa là được dùng tự do — ảnh trên mạng vẫn thuộc về tác giả, dùng tuỳ tiện là xâm phạm bản quyền, kể cả khi video không kinh doanh. Ý b ĐÚNG: đây chính là cách sử dụng hợp pháp — chọn nguồn cho phép dùng lại, làm đúng điều kiện mà giấy phép nêu ra và ghi nguồn đầy đủ. Ý c ĐÚNG: dùng AI như công cụ hỗ trợ là chấp nhận được nếu nhóm tự kiểm chứng nội dung và trung thực nói rõ phần nào có AI hỗ trợ, thay vì nhận toàn bộ là sản phẩm của mình. Ý d SAI: hình ảnh khuôn mặt là dữ liệu cá nhân của người được quay; mục đích tốt không thay thế được sự đồng ý của họ, nên phải hỏi trước khi đưa lên kênh công khai."}]);
  LESSONS.push(
    {"id":"C12-01","stage":22,"order":1,"topic":"G","grade":12,"minutes":10,"title":"Trí tuệ nhân tạo là gì?","intro":"Bài học giới thiệu khái niệm trí tuệ nhân tạo (AI): AI là gì, vì sao phần lớn hệ thống AI hiện nay học từ dữ liệu thay vì theo quy tắc cố định, và AI đã xuất hiện ở đâu trong đời sống hằng ngày.","sections":[{"t":"story","text":"Hãy tưởng tượng bạn cầm điện thoại lên và nói: “Đặt báo thức lúc sáu giờ sáng mai”. Chỉ vài giây sau, điện thoại đáp lại bằng giọng nói: “Đã đặt báo thức lúc sáu giờ sáng mai”, và một mục báo thức mới xuất hiện trong ứng dụng.\n\nĐể làm được việc này, thiết bị phải hoàn thành liên tiếp mấy việc: nghe và nhận ra từng từ trong câu nói, hiểu ý nghĩa của cả câu (đây là một yêu cầu đặt báo thức, không phải một câu hỏi về thời tiết), rồi thực hiện đúng thao tác tương ứng. Trước đây, những việc như “nghe hiểu” và “ra quyết định” gần như chỉ con người mới làm được. Khả năng khiến máy tính làm được những việc như vậy chính là điều bài học này gọi tên: **trí tuệ nhân tạo**."},{"t":"h","text":"Trí tuệ nhân tạo là gì?"},{"t":"text","text":"**Trí tuệ nhân tạo** (tiếng Anh: Artificial Intelligence, viết tắt `AI`) là một nhánh của khoa học máy tính, hướng tới việc làm cho máy tính thực hiện được những việc mà bình thường cần đến trí thông minh của con người: nhận ra một khuôn mặt trong ảnh, nghe hiểu một câu nói, đọc hiểu một đoạn văn bản, cân nhắc nhiều yếu tố để đưa ra quyết định, hoặc gợi ý một lựa chọn phù hợp cho một người.\n\nVới một chương trình máy tính theo cách viết thông thường, người viết chương trình liệt kê sẵn từng quy tắc bằng các câu lệnh điều kiện (`if`, `else`): gặp trường hợp này thì làm thế này, gặp trường hợp khác thì làm thế khác. Cách làm đó phù hợp với những việc có quy tắc rõ ràng, chẳng hạn tính tổng hai số hoặc sắp xếp một danh sách theo thứ tự tăng dần.\n\nNhưng với việc nhận ra khuôn mặt hay nghe hiểu một câu nói, số trường hợp có thể xảy ra gần như vô hạn — mỗi khuôn mặt, mỗi giọng nói, mỗi cách diễn đạt đều khác nhau, không ai liệt kê hết được bằng quy tắc viết tay. Đây là điểm mấu chốt để hiểu AI hiện nay: phần lớn hệ thống AI không được lập trình cứng từng luật, mà **học từ dữ liệu**. Hệ thống được cho tiếp xúc với rất nhiều ví dụ có sẵn (ảnh đã gắn nhãn, câu nói đã ghi âm, văn bản đã phân loại...), tự tìm ra quy luật chung từ những ví dụ đó, rồi áp dụng quy luật ấy cho các trường hợp mới chưa từng gặp."},{"t":"example","text":"Hãy so sánh hai cách để phân loại một email là thư rác hay thư bình thường.","code":"Cách 1 — quy tắc cố định do người lập trình đặt ra:\nNếu tiêu đề chứa từ “trúng thưởng” → đánh dấu là thư rác.\nNếu tiêu đề chứa từ “miễn phí” → đánh dấu là thư rác.\n(Muốn bắt thêm trường hợp mới, người lập trình phải tự thêm quy tắc mới.)\n\nCách 2 — học từ dữ liệu:\nHệ thống được cho xem hàng trăm nghìn email đã được đánh dấu sẵn là “rác” hoặc “bình thường”.\nHệ thống tự nhận ra các đặc điểm thường gặp ở thư rác — không chỉ vài từ khoá, mà cả cách hành văn, địa chỉ gửi, tần suất gửi...\nKhi gặp một email hoàn toàn mới, hệ thống dựa vào các đặc điểm đã học để đưa ra dự đoán.","output":"Cách 1 dễ bỏ sót khi người gửi thư rác đổi cách dùng từ; cách 2 linh hoạt hơn vì không phụ thuộc vào một danh sách từ khoá cố định, mà dựa trên quy luật tự rút ra từ dữ liệu."},{"t":"list","text":"Trong sinh hoạt hằng ngày, AI đã có mặt ở nhiều nơi mà có thể bạn chưa để ý, chẳng hạn:","items":["Trợ lí ảo trên điện thoại hoặc loa thông minh, trả lời câu hỏi hoặc thực hiện yêu cầu bằng giọng nói","Hệ thống gợi ý video, bài hát hoặc sản phẩm nên xem, nghe hoặc mua tiếp theo, dựa trên lịch sử sử dụng","Tính năng nhận diện khuôn mặt để mở khoá điện thoại hoặc gắn tên trong ảnh","Công cụ dịch tự động, chuyển văn bản hoặc lời nói từ ngôn ngữ này sang ngôn ngữ khác","Bộ lọc thư rác, tự động phân loại email đáng ngờ trước khi email đến hộp thư đến"]},{"t":"h","text":"AI “thông minh” đến mức nào?"},{"t":"text","text":"Nghe tên gọi **trí tuệ nhân tạo**, có người hình dung một cỗ máy có thể suy nghĩ và hiểu mọi thứ như con người. Thực tế hiện nay khác khá xa hình dung đó.\n\nPhần lớn hệ thống AI đang được sử dụng chỉ giỏi trong một việc hẹp mà nó được huấn luyện để làm: một hệ thống nhận diện khuôn mặt không tự nhiên chuyển sang dịch được ngôn ngữ; một hệ thống dịch thuật không tự dưng biết lái xe. Mỗi hệ thống hoạt động tốt trong phạm vi đã được huấn luyện, và có thể sai lệch khi gặp tình huống quá khác với dữ liệu đã học — chẳng hạn một hệ thống nhận diện khuôn mặt quen với ảnh đủ ánh sáng có thể nhận nhầm trong điều kiện thiếu sáng.\n\nQuan trọng hơn, các hệ thống này không có ý thức, không tự nhận biết bản thân, không có cảm xúc hay mong muốn như con người. Khi trợ lí ảo “trả lời” một câu hỏi, nó đang thực hiện một phép tính dựa trên dữ liệu đã học, chứ không phải đang suy nghĩ theo nghĩa mà con người vẫn hiểu về việc suy nghĩ."},{"t":"note","text":"Cần phân biệt hai điều dễ bị nhầm lẫn. Thứ nhất, một hệ thống AI làm tốt một việc cụ thể không đồng nghĩa với việc nó hiểu mọi vấn đề liên quan — một hệ thống gợi ý phim không “biết” bạn là ai, nó chỉ nhận ra một số hình mẫu trong hành vi xem phim trước đó. Thứ hai, “học từ dữ liệu” không có nghĩa là AI luôn đúng — nếu dữ liệu dùng để huấn luyện có sai lệch hoặc thiếu đa dạng, kết quả dự đoán của hệ thống cũng sẽ mang theo sai lệch đó."}],"keypoints":["**Trí tuệ nhân tạo (AI)** là việc làm cho máy tính thực hiện những việc thường cần đến trí thông minh của con người, như nhận dạng hình ảnh, hiểu giọng nói hay đưa ra quyết định.","Phần lớn hệ thống AI hiện nay **học từ dữ liệu** — tự tìm quy luật từ rất nhiều ví dụ có sẵn — thay vì được lập trình cứng từng quy tắc.","AI đã có mặt trong nhiều việc quen thuộc: trợ lí ảo, gợi ý video hoặc mua hàng, nhận diện khuôn mặt, dịch tự động, lọc thư rác.","AI hiện nay chỉ “thông minh” trong phạm vi hẹp đã được huấn luyện, không có ý thức hay hiểu biết toàn diện như con người."],"quiz":["CC-mc-101","CC-mc-102","CC-mc-103","CC-mc-104","CC-mc-105","CC-tf-101","CC-tf-102","CC-tf-103","CC-tf-104","G-mc-15","G-mc-16","G-mc-17","G-mc-1","G-mc-44"]},
    {"id":"C12-02","stage":22,"order":2,"topic":"G","grade":12,"minutes":11,"title":"Ứng dụng và giới hạn của trí tuệ nhân tạo","intro":"Trí tuệ nhân tạo đã có mặt trong rất nhiều lĩnh vực của đời sống, từ y tế đến giải trí. Bài học này giúp bạn nhìn rõ cả mặt mạnh lẫn giới hạn của AI, để sử dụng công cụ này một cách hiệu quả và có trách nhiệm.","sections":[{"t":"story","text":"Hãy tưởng tượng bạn thuê được một trợ lý làm việc nhanh đến kinh ngạc: đọc xong một chồng hồ sơ dày trong vài giây, trả lời câu hỏi gần như ngay lập tức, không bao giờ than mệt hay đòi nghỉ. Nghe có vẻ hoàn hảo, nhưng trợ lý này có hai điểm đáng chú ý mà bạn cần biết trước khi giao việc quan trọng.\n\nThứ nhất, mọi hiểu biết của trợ lý này đến từ những hồ sơ cũ mà bạn từng đưa cho xem qua. Nếu đống hồ sơ đó có sai sót, hoặc vô tình thiên vị một nhóm nào đó, trợ lý sẽ học theo y hệt — mà không hề tự nhận ra mình đang lặp lại cái sai. Thứ hai, dù không chắc chắn, trợ lý vẫn trả lời với giọng điệu rất tự tin, hiếm khi chịu nói ‘tôi không biết’.\n\nTrí tuệ nhân tạo mà ta gặp hằng ngày — trên điện thoại, trong bệnh viện, trên đường phố — vận hành theo cách khá giống vị trợ lý ấy: mạnh mẽ đến mức có thể thay đổi cả cách con người làm việc, nhưng mạnh đến đâu thì cũng có giới hạn đi kèm đến đó. Bài học này giúp bạn nhìn rõ cả hai mặt, để biết lúc nào nên tin dùng, lúc nào cần thận trọng."},{"t":"h","text":"1) AI đang có mặt ở những đâu trong đời sống?"},{"t":"list","text":"**Trí tuệ nhân tạo** (tiếng Anh: `Artificial Intelligence`, viết tắt `AI`) là khả năng máy tính thực hiện những việc vốn cần đến trí thông minh của con người, chẳng hạn: nhận diện hình ảnh, hiểu ngôn ngữ, tìm ra quy luật trong dữ liệu để dự đoán hoặc đề xuất. Ngày nay, AI thường đứng phía sau, âm thầm hỗ trợ con người ra quyết định ở rất nhiều lĩnh vực:","items":["**Y tế**: hỗ trợ bác sĩ chẩn đoán qua phân tích ảnh chụp X-quang, ảnh nội soi, kết quả xét nghiệm — giúp phát hiện sớm những dấu hiệu bất thường mà mắt thường dễ bỏ sót.","**Giao thông**: xe tự lái nhận diện làn đường, biển báo, chướng ngại vật; hệ thống đèn tín hiệu thông minh tự điều chỉnh thời gian đèn theo mật độ xe thực tế để giảm ùn tắc.","**Giáo dục**: phần mềm học thích ứng (`adaptive learning`) theo dõi năng lực của từng người học, tự động điều chỉnh độ khó bài tập, gợi ý đúng nội dung cần ôn lại.","**Nông nghiệp**: phân tích ảnh vệ tinh hoặc dữ liệu cảm biến để phát hiện sớm sâu bệnh, dự báo thời điểm tưới nước, bón phân hợp lí.","**Giải trí**: hệ thống gợi ý (`recommendation`) trên các nền tảng xem phim, nghe nhạc, mua sắm trực tuyến — phân tích thói quen để đề xuất nội dung phù hợp với từng người.","**Dịch thuật**: các công cụ dịch tự động chuyển văn bản hoặc giọng nói giữa nhiều ngôn ngữ gần như tức thời."]},{"t":"text","text":"Nhìn qua những ứng dụng trên, có thể thấy AI mang lại ba lợi ích lớn, lặp lại ở hầu hết mọi lĩnh vực. Một là **tốc độ**: AI xử lí một khối lượng công việc trong vài giây, điều mà con người có thể mất hàng giờ hoặc hàng ngày. Hai là khả năng **xử lí dữ liệu lớn**: AI có thể quét qua hàng triệu ảnh, hàng triệu dòng dữ liệu để tìm ra quy luật mà con người khó lòng tự tổng hợp bằng mắt thường. Ba là **hỗ trợ con người ra quyết định**: AI đưa ra gợi ý, dự đoán, cảnh báo sớm — giúp con người có thêm căn cứ để quyết định nhanh và chính xác hơn, chứ không nhất thiết phải tự làm mọi bước từ đầu.\n\nChính vì những lợi ích đó, AI ngày càng được tin dùng. Nhưng ‘tin dùng’ không có nghĩa là ‘tin tuyệt đối’ — phần tiếp theo sẽ cho thấy vì sao."},{"t":"example","text":"Để thấy rõ ranh giới giữa ‘AI hỗ trợ’ và ‘AI quyết định thay’, hãy xét một tình huống ở phòng khám: bác sĩ đưa ảnh chụp X-quang phổi của một người bệnh vào một phần mềm hỗ trợ chẩn đoán dựa trên AI.","code":"① Phần mềm so sánh ảnh vừa nhận với hàng trăm nghìn ảnh X-quang đã có nhãn (bình thường / có dấu hiệu bất thường) mà nó từng được huấn luyện\n② Phần mềm đưa ra một con số ước lượng, ví dụ ‘khả năng có dấu hiệu viêm phổi: 82%’, kèm khoanh vùng vị trí nghi ngờ trên ảnh\n③ Bác sĩ xem kết quả đó như một gợi ý tham khảo, đối chiếu thêm với triệu chứng và tiền sử bệnh của người bệnh\n④ Bác sĩ là người đưa ra kết luận và quyết định điều trị cuối cùng, không phải phần mềm","output":"Nhờ gợi ý từ AI, bác sĩ xử lí ảnh nhanh hơn và ít bỏ sót dấu hiệu nhỏ hơn. Nhưng quyết định cuối cùng vẫn cần con người, vì phần mềm chỉ đưa ra một khả năng ước lượng, không phải một sự thật chắc chắn tuyệt đối."},{"t":"h","text":"2) Vì sao AI cũng có giới hạn?"},{"t":"text","text":"Giới hạn gốc rễ của AI nằm ở chỗ: các hệ thống AI phổ biến hiện nay hình thành mọi ‘hiểu biết’ của nó hoàn toàn từ **dữ liệu huấn luyện** — tức là kho dữ liệu mẫu được đưa cho nó học trước đó. Nếu dữ liệu huấn luyện đầy đủ, đa dạng, được gán nhãn chính xác, AI sẽ hoạt động tốt. Nhưng nếu dữ liệu đó bị lệch — chẳng hạn chỉ thu thập từ một nhóm đối tượng nhất định, thiếu đa dạng, hoặc bản thân dữ liệu cũ đã mang sẵn định kiến — thì kết quả AI đưa ra cũng lệch theo, dẫn tới **thiên lệch** hoặc sai mà nhiều khi người dùng khó nhận ra ngay. Nói ngắn gọn: AI không tự nghĩ ra tri thức mới, nó phản chiếu lại những gì có trong dữ liệu mà nó từng thấy, kể cả những sai sót có sẵn trong đó.\n\nMột hệ quả khác đi kèm: AI không thật sự ‘hiểu’ theo nghĩa con người vẫn hiểu. Nó nhận diện **khuôn mẫu** (`pattern`) lặp lại trong dữ liệu, chứ không suy luận có ý thức như con người. Vì vậy khi gặp tình huống khác lạ so với dữ liệu đã học, AI vẫn có thể đưa ra câu trả lời — với giọng điệu rất chắc chắn, tự tin — dù câu trả lời đó hoàn toàn sai. Đây là điều khiến AI trở nên rủi ro nếu người dùng tin tưởng tuyệt đối mà không kiểm chứng lại."},{"t":"list","text":"Ngoài giới hạn về dữ liệu và khả năng ‘hiểu’, AI khi được đưa vào đời sống rộng rãi còn kéo theo một số rủi ro cần lưu tâm:","items":["**Có thể bị lạm dụng để tạo tin giả**: công nghệ tạo ảnh, video, giọng nói giả bằng AI (`deepfake`) ngày càng khó phân biệt với thật, có thể bị dùng để lừa đảo hoặc lan truyền thông tin sai lệch.","**Nguy cơ xâm phạm quyền riêng tư**: nhiều hệ thống AI cần thu thập lượng lớn dữ liệu cá nhân (hình ảnh, thói quen, vị trí...) để hoạt động, tiềm ẩn rủi ro dữ liệu bị sử dụng sai mục đích hoặc bị rò rỉ.","**Ảnh hưởng đến việc làm**: một số công việc có tính lặp lại, quy trình rõ ràng (nhập liệu, phân loại, một phần công việc kiểm tra chất lượng...) có nguy cơ dần được AI đảm nhận thay con người.","**Dễ khiến người dùng phụ thuộc quá mức**: nếu luôn dựa hoàn toàn vào gợi ý của AI mà không tự kiểm tra lại, con người có thể dần mất thói quen tự suy luận, tự xác minh thông tin."]},{"t":"note","text":"Từ những giới hạn trên, nguyên tắc để dùng AI có trách nhiệm là: xem kết quả AI đưa ra như một **gợi ý để tham khảo**, không phải một kết luận cuối cùng; luôn đối chiếu, kiểm chứng lại — đặc biệt với những việc quan trọng như sức khoẻ, tiền bạc, pháp lí; và không dùng AI để tạo hoặc lan truyền nội dung sai sự thật."}],"keypoints":["AI đang được ứng dụng rộng rãi trong y tế (hỗ trợ chẩn đoán), giao thông (xe tự lái, đèn tín hiệu thông minh), giáo dục (học thích ứng), nông nghiệp, giải trí (hệ thống gợi ý) và dịch thuật.","Lợi ích chung của AI là xử lí nhanh, xử lí được lượng dữ liệu lớn và hỗ trợ con người ra quyết định — nhưng AI chỉ nên đóng vai trò hỗ trợ, quyết định cuối cùng vẫn cần con người.","AI hình thành ‘hiểu biết’ hoàn toàn từ dữ liệu huấn luyện; dữ liệu lệch hoặc thiếu đa dạng khiến kết quả AI đưa ra cũng thiên lệch hoặc sai theo, trong khi AI không thật sự ‘hiểu’ mà có thể trả lời sai một cách rất tự tin.","AI có thể bị lạm dụng (tạo tin giả, xâm phạm quyền riêng tư) và ảnh hưởng đến việc làm, nên cần dùng AI có trách nhiệm: xem kết quả là gợi ý tham khảo và luôn kiểm chứng lại."],"quiz":["CC-mc-201","CC-mc-202","CC-mc-203","CC-mc-204","CC-mc-205","CC-tf-201","CC-tf-202","CC-tf-203","CC-tf-204","G-mc-18","G-tf-2","G-mc-3","G-mc-4","G-tf-5","G-mc-46","G-mc-49"]},
    {"id":"C12-03","stage":22,"order":3,"topic":"B","grade":12,"minutes":11,"title":"Kiến trúc mạng và giao thức truyền thông","intro":"Bài học giúp bạn hiểu cách các thiết bị trò chuyện được với nhau qua mạng, thông qua mô hình khách – chủ và những bộ quy tắc chung gọi là giao thức. Bạn cũng sẽ biết vì sao dữ liệu luôn được chia nhỏ thành từng gói tin trước khi gửi đi, và nhờ đâu các thiết bị khác hãng sản xuất vẫn hiểu được nhau.","sections":[{"t":"story","text":"Hãy hình dung một người cần gửi một lá thư quan trọng đến một người bạn ở tỉnh khác. Trước khi bỏ thư vào thùng, người này phải ghi đúng theo quy định chung của ngành bưu chính: tên người nhận, số nhà, tên đường, phường/xã, tỉnh/thành — viết theo đúng thứ tự, đúng định dạng mà bất kỳ bưu điện nào trên cả nước cũng đọc hiểu được. Thư được cho vào phong bì, dán tem, rồi mới bỏ vào thùng thư.\n\nTừ lúc đó, lá thư đi qua rất nhiều bàn tay: người đưa thư gom thư ở khu vực, bưu điện địa phương phân loại theo nơi thư cần đến, xe chuyển thư đưa thư sang bưu điện ở tỉnh, thành khác, rồi một người đưa thư khác mang đến tận nhà người nhận. Không ai trong số những người và bưu điện tham gia hành trình đó quen biết nhau từ trước, cũng chẳng ai cần biết toàn bộ chặng đường còn lại lá thư sẽ đi qua đâu. Tất cả chỉ cần làm đúng một việc: đọc đúng địa chỉ theo đúng quy định chung, rồi chuyển tiếp đúng hướng. Nếu địa chỉ ghi tuỳ tiện, sai với định dạng mà mọi người đã thống nhất, lá thư gần như chắc chắn sẽ thất lạc giữa đường.\n\nMạng máy tính hoạt động theo đúng nguyên tắc đó. Hàng tỉ thiết bị trên khắp thế giới — máy tính, điện thoại, máy chủ — trao đổi dữ liệu qua lại với nhau mỗi giây, mà phần lớn trong số đó chưa từng “gặp” nhau trước đó. Chúng làm được điều này vì cùng tuân theo một bộ quy tắc chung, giống hệt quy định viết địa chỉ của ngành bưu chính. Bài học này sẽ giới thiệu bộ quy tắc ấy, và cách dữ liệu thật sự di chuyển qua mạng."},{"t":"h","text":"Mô hình khách – chủ (client-server)"},{"t":"text","text":"Khi một người mở trình duyệt và truy cập một trang web, thực chất đang có hai bên tham gia vào một cuộc trao đổi. Bên chủ động gửi yêu cầu — muốn xem một trang, tải một tệp, hay xem một đoạn video — gọi là **máy khách** (`client`). Bên tiếp nhận yêu cầu đó, xử lý rồi gửi lại đúng thứ máy khách cần, gọi là **máy chủ** (`server`).\n\nMáy chủ thường là một máy tính cấu hình mạnh, gần như luôn bật, chuyên lưu trữ dữ liệu hoặc cung cấp một dịch vụ nhất định — chẳng hạn lưu toàn bộ nội dung của một trang web, hoặc lưu trữ hộp thư điện tử của nhiều người dùng. Một máy chủ không chỉ phục vụ một máy khách duy nhất: cùng một lúc, nó có thể tiếp nhận và trả lời hàng nghìn, thậm chí hàng triệu yêu cầu từ vô số máy khách khác nhau, miễn là đủ khả năng xử lý.\n\nQuan hệ khách – chủ không gắn cố định với một loại thiết bị. Cùng một chiếc máy tính, khi truy cập trang web thì nó đang đóng vai máy khách; nhưng nếu chiếc máy tính đó được cài đặt để chia sẻ một thư mục cho các máy khác trong nhà truy cập, ngay lúc ấy nó lại đóng vai trò máy chủ. Vai trò được xác định bởi việc ai đang gửi yêu cầu, ai đang đáp ứng yêu cầu — không phải bởi bản thân loại thiết bị."},{"t":"example","text":"Xét lại tình huống mở đầu ở một mức cụ thể hơn: một người gõ địa chỉ một trang web vào trình duyệt rồi nhấn Enter. Phía sau thao tác tưởng chừng đơn giản ấy là một cuộc trao đổi giữa máy khách và máy chủ:","code":"Máy khách gửi yêu cầu: “Cho tôi xem trang chủ tại vidu.edu.vn”\nMáy chủ tại vidu.edu.vn phản hồi: gửi trả toàn bộ nội dung trang chủ (chữ, hình ảnh, cách trình bày...)","output":"Trình duyệt — lúc này đang đóng vai máy khách — nhận phần phản hồi rồi dựng lại thành trang web hoàn chỉnh để hiển thị. Toàn bộ quá trình chỉ diễn ra trong một khoảnh khắc, dù máy chủ có thể đang đặt tại một quốc gia cách nơi người dùng ngồi hàng nghìn ki-lô-mét."},{"t":"h","text":"Giao thức — bộ quy tắc chung để các máy hiểu nhau"},{"t":"text","text":"Muốn máy khách và máy chủ trao đổi được với nhau như ví dụ trên, cả hai phải cùng tuân theo một bộ quy tắc, quy định rõ cách gửi yêu cầu, cách trả lời, và trình tự các bước thực hiện. Bộ quy tắc chung đó gọi là **giao thức** (`protocol`) — vai trò của nó trong mạng máy tính cũng giống hệt quy định viết địa chỉ của ngành bưu chính trong câu chuyện mở đầu: nhờ mọi bưu điện, dù ở tỉnh nào, do ai quản lý, đều đọc địa chỉ theo đúng một cách, lá thư mới đến đúng nơi cần đến.\n\nTrên mạng máy tính có rất nhiều giao thức, mỗi loại phụ trách một công việc riêng. `HTTP` là giao thức quy định cách trình duyệt và máy chủ web trao đổi nội dung trang web với nhau, đúng như ví dụ ở trên. Còn `TCP/IP` là giao thức nền tảng của Internet, quy định cách mỗi thiết bị được đánh địa chỉ và cách dữ liệu được truyền đi giữa các thiết bị với nhau, không riêng cho việc xem trang web mà cho hầu hết mọi hoạt động trao đổi dữ liệu qua mạng.\n\nChính nhờ có giao thức chung mà một chiếc điện thoại của hãng này vẫn kết nối bình thường với một máy chủ web đặt ở một quốc gia khác, chạy phần mềm của một hãng hoàn toàn khác — miễn là cả hai cùng tuân theo đúng `TCP/IP` và `HTTP`. Nếu không có bộ quy tắc chung, mỗi hãng thiết bị có thể tự đặt ra một cách trao đổi riêng, hai thiết bị của hai hãng khác nhau sẽ không thể hiểu được nhau, và Internet sẽ không thể trở thành một mạng lưới thống nhất, kết nối toàn cầu như hiện nay."},{"t":"h","text":"Gói tin — cách dữ liệu di chuyển qua mạng"},{"t":"text","text":"Một trang web, một bức ảnh hay một đoạn video thường có dung lượng khá lớn. Nếu gửi nguyên khối dữ liệu đó đi trong một lần, chỉ cần một đoạn đường truyền bị nghẽn hoặc gặp lỗi, toàn bộ dữ liệu có nguy cơ phải gửi lại từ đầu. Vì vậy, trước khi gửi đi, dữ liệu được chia nhỏ thành nhiều phần, gọi là **gói tin** (`packet`) — có thể hình dung giống như việc chia một lá thư dài thành nhiều tấm bưu thiếp nhỏ, đánh số thứ tự, mỗi tấm gửi đi riêng.\n\nMỗi gói tin mang theo một phần dữ liệu gốc, cùng với một số thông tin đi kèm — quan trọng nhất là **địa chỉ nơi gửi** và **địa chỉ nơi nhận**, để các thiết bị trung gian trên đường truyền biết cần chuyển gói tin đó tiếp về hướng nào. Các gói tin của cùng một dữ liệu gốc có thể đi qua những đường khác nhau, đến nơi nhận không theo đúng thứ tự ban đầu; nhờ mỗi gói còn mang theo số thứ tự, thiết bị nhận vẫn ghép lại được đúng dữ liệu gốc, đúng trình tự."},{"t":"list","text":"Tóm lại, mỗi gói tin thường mang theo:","items":["**Một phần dữ liệu gốc**: dữ liệu ban đầu (trang web, tệp, video...) được chia nhỏ thành nhiều gói, mỗi gói chỉ mang một phần.","**Địa chỉ nơi gửi và nơi nhận**: giúp các thiết bị trung gian trên đường truyền biết cần chuyển gói tin này tiếp tục về hướng nào.","**Số thứ tự**: cho biết gói tin này là phần thứ mấy trong toàn bộ dữ liệu gốc, để nơi nhận ghép lại đúng trình tự.","Khả năng **đi theo những đường khác nhau**: các gói tin của cùng một dữ liệu không nhất thiết đi chung một đường, và có thể đến nơi nhận không theo đúng thứ tự ban đầu."]},{"t":"note","text":"Quay lại câu chuyện gửi thư ở đầu bài: một lá thư dài có thể phải chia thành nhiều phong bì nếu vượt quá khối lượng cho phép gửi một lần, mỗi phong bì vẫn phải ghi đúng địa chỉ và đánh số để người nhận biết cách ghép lại đúng thứ tự. Gói tin trên mạng máy tính hoạt động theo đúng tinh thần đó — chỉ khác là mọi việc diễn ra tự động, trong chưa đầy một giây, và hoàn toàn dựa trên giao thức chung mà mọi thiết bị đã cùng thống nhất tuân theo."}],"keypoints":["Trong mô hình **khách – chủ** (`client-server`), **máy khách** (`client`) gửi yêu cầu; **máy chủ** (`server`) tiếp nhận, xử lý và trả lại dữ liệu hoặc dịch vụ được yêu cầu; một máy chủ có thể phục vụ rất nhiều máy khách cùng lúc.","**Giao thức** (`protocol`) là bộ quy tắc chung, quy định cách gửi, cách nhận và trình tự trao đổi giữa các thiết bị; ví dụ `HTTP` (trao đổi trang web) và `TCP/IP` (nền tảng truyền dữ liệu trên Internet).","Dữ liệu lớn được chia thành nhiều **gói tin** (`packet`) trước khi gửi; mỗi gói mang theo địa chỉ nơi gửi, nơi nhận và số thứ tự, để nơi nhận ghép lại đúng dữ liệu gốc dù các gói có thể đến không theo thứ tự.","Nhờ mọi thiết bị — bất kể hãng sản xuất hay hệ điều hành — cùng tuân theo một giao thức chung, các thiết bị khác nhau vẫn hiểu và trao đổi được với nhau, giúp Internet hoạt động như một mạng lưới thống nhất trên toàn cầu."],"quiz":["CC-mc-301","CC-mc-302","CC-mc-303","CC-mc-304","CC-mc-305","CC-tf-301","CC-tf-302","CC-tf-303","CC-tf-304","B-mc-20","B-mc-21","B-mc-22","B-tf-4","B-mc-27","B-tf-6","B-mc-1","B-tf-2","B-mc-41","B-tf-8"]},
    {"id":"C12-04","stage":22,"order":4,"topic":"B","grade":12,"minutes":11,"title":"Thiết bị mạng và đường truyền","intro":"Bài học giới thiệu các thiết bị mạng thường gặp — modem, router, switch, điểm phát wifi — và vai trò dẫn đường của từng thiết bị đối với gói tin. Bạn cũng sẽ biết đường truyền có dây và không dây khác nhau ra sao, và vì sao băng thông quyết định tốc độ tải dữ liệu nhanh hay chậm.","sections":[{"t":"story","text":"Hãy hình dung một khu vực có nhiều cụm dân cư, mỗi cụm có các con đường nội bộ nối những ngôi nhà với nhau. Muốn đi từ nhà mình sang một cụm dân cư khác, hay xa hơn là sang một tỉnh khác, một chiếc xe phải lần lượt đi qua: con đường nhỏ trong cụm, một vài ngã tư có đèn tín hiệu hoặc biển chỉ dẫn để rẽ đúng hướng, rồi ra tới đường lớn nối liền nhiều tỉnh, thành. Tại mỗi ngã tư, xe không tự biết đường — phải dựa vào đèn tín hiệu, biển báo để biết nên rẽ trái, rẽ phải hay đi thẳng. Và một con đường lớn, nhiều làn xe bao giờ cũng giúp xe cộ lưu thông nhanh hơn một con hẻm nhỏ chỉ vừa một chiếc.\n\nMạng máy tính cũng có một ‘hệ thống đường sá’ tương tự như vậy. Ở bài trước, ta đã biết dữ liệu được chia thành từng gói tin, mỗi gói mang theo địa chỉ nơi gửi và nơi nhận. Nhưng tự thân một gói tin không biết đường đi — nó cần đi qua một số thiết bị đóng vai trò như những ngã tư, để được dẫn đúng hướng tới đích; đồng thời nó cần một con đường — có thể là dây dẫn hoặc sóng vô tuyến — đủ ‘rộng’ để di chuyển nhanh. Bài học này giới thiệu các thiết bị dẫn đường đó, và các loại đường truyền mà gói tin có thể đi qua."},{"t":"h","text":"Thiết bị mạng — những ‘trạm’ dẫn đường cho gói tin"},{"t":"list","text":"Trên hành trình từ máy tính hay điện thoại của một người ra tới Internet, gói tin thường phải lần lượt đi qua một vài thiết bị mạng khác nhau, mỗi thiết bị đảm nhiệm đúng một việc. Bốn thiết bị dưới đây thường gặp nhất trong một mạng nhỏ, ở nhà hay ở một văn phòng nhỏ:","items":["**Modem** — nối ngôi nhà (hay văn phòng) với nhà cung cấp dịch vụ Internet (`ISP`); chuyển đổi tín hiệu giữa đường truyền của nhà mạng và dữ liệu mà các thiết bị trong nhà dùng được. Không có modem, mạng trong nhà sẽ không có đường ra Internet.","**Bộ định tuyến** (`router`) — đọc địa chỉ đích của mỗi gói tin để quyết định hướng chuyển tiếp giữa các mạng khác nhau, chẳng hạn giữa mạng trong nhà và Internet; vai trò này giống hệt một ngã tư có đèn tín hiệu, quyết định cho xe rẽ trái, rẽ phải hay đi thẳng.","**Bộ chuyển mạch** (`switch`) — nối nhiều máy tính lại với nhau trong cùng một mạng nội bộ, chẳng hạn các máy tính bàn trong một phòng; thường được thêm vào khi số máy cần nối dây nhiều hơn số cổng có sẵn trên router.","**Điểm phát wifi** (`access point`) — phát sóng không dây, giúp điện thoại, laptop hay máy tính bảng kết nối vào mạng mà không cần cắm dây; nhiều router hiện nay đã tích hợp sẵn chức năng này."]},{"t":"example","text":"Hãy hình dung một người ở nhà, mở điện thoại và truy cập một trang web qua wifi. Đường đi của gói tin lúc này lần lượt qua các thiết bị mạng như sau:","code":"1. Điện thoại gửi gói tin qua sóng, tới điểm phát wifi (thường tích hợp sẵn trong router).\n2. Router nhận gói tin, đọc địa chỉ đích, thấy đích nằm ngoài mạng nhà nên chuyển tiếp gói tin về hướng modem.\n3. Modem chuyển gói tin sang dạng tín hiệu phù hợp với đường truyền của nhà cung cấp dịch vụ Internet, rồi gửi đi tiếp.\n4. Gói tin tiếp tục hành trình qua nhiều thiết bị mạng khác của nhà cung cấp dịch vụ, cho tới khi tới đúng máy chủ web cần đến.\n\n(Nếu trong nhà còn có máy tính bàn nối dây, gói tin từ máy đó sẽ đi qua switch trước, rồi mới tới router — đúng vai trò nối nhiều máy trong cùng một mạng nội bộ của switch.)","output":"Chỉ trong chưa đầy một giây, gói tin đã đi qua ba, bốn thiết bị khác nhau, mỗi thiết bị làm đúng một việc: điểm phát wifi và switch nối các thiết bị trong nhà lại với nhau, còn router và modem lo phần dẫn đường ra Internet. Người dùng không thấy quá trình này diễn ra, chỉ thấy trang web hiện lên trên màn hình."},{"t":"h","text":"Đường truyền — con đường để dữ liệu di chuyển"},{"t":"text","text":"Có thiết bị dẫn đường thôi chưa đủ — gói tin còn cần một con đường vật lý để di chuyển giữa các thiết bị đó. Đường truyền mạng chia thành hai nhóm chính: có dây và không dây.\n\nVới đường truyền **có dây**, phổ biến nhất là **cáp xoắn đôi bằng đồng** — thường thấy trong dây mạng nối máy tính bàn với switch hoặc router — giá rẻ, dễ lắp đặt, nhưng tín hiệu yếu dần khi đi qua khoảng cách xa. Hiện đại hơn là **cáp quang** — truyền dữ liệu bằng ánh sáng đi trong sợi thuỷ tinh mảnh, cho tốc độ rất cao và truyền xa hơn nhiều so với cáp đồng mà tín hiệu ít bị suy hao, nên thường được nhà cung cấp dịch vụ dùng làm đường trục chính, kéo tới từng khu vực, từng ngôi nhà.\n\nVới đường truyền **không dây**, quen thuộc nhất là `wifi` — dùng sóng vô tuyến để nối các thiết bị trong phạm vi một ngôi nhà hay một văn phòng mà không cần dây. Ở phạm vi rộng hơn, ngoài trời, điện thoại còn kết nối qua **mạng di động** như `4G` hay `5G`, nhờ các cột phát sóng của nhà mạng viễn thông dựng khắp khu vực — đây là lý do một người vẫn lướt web được trên điện thoại dù đang ngồi trên xe khách, cách xa mọi điểm phát wifi."},{"t":"h","text":"Băng thông — con đường ấy rộng hay hẹp"},{"t":"text","text":"Cùng là một con đường, đường hai làn xe và đường tám làn xe chở được lượng xe rất khác nhau trong cùng một khoảng thời gian. Đường truyền mạng cũng vậy — khái niệm đo độ ‘rộng’ của một đường truyền gọi là **băng thông** (`bandwidth`): lượng dữ liệu tối đa có thể truyền qua đường truyền đó trong mỗi giây, thường đo bằng đơn vị `Mbps` (triệu bit mỗi giây) hoặc `Gbps` (tỉ bit mỗi giây).\n\nBăng thông càng lớn, lượng dữ liệu di chuyển được trong một giây càng nhiều, nên các thao tác cần truyền nhiều dữ liệu — tải một tệp nặng, xem video chất lượng cao, hay nhiều thiết bị dùng chung một đường truyền cùng lúc — sẽ diễn ra nhanh hơn, ít bị giật, chờ tải. Một đường truyền băng thông thấp vẫn lướt web, nhắn tin bình thường được, nhưng sẽ đuối sức ngay khi nhiều thiết bị cùng xem video hay tải tệp lớn cùng lúc — giống hệt một con hẻm nhỏ bỗng phải chịu lượng xe của giờ cao điểm."},{"t":"note","text":"Không phải lúc nào cũng cần thiết bị mạnh nhất hay đường truyền băng thông cao nhất. Một người chỉ lướt web, nhắn tin thì một gói cước băng thông vừa phải, cùng một router có wifi tích hợp, đã là đủ dùng. Ngược lại, một văn phòng nhiều máy cùng truyền tệp nặng, họp trực tuyến liên tục thì cần đường truyền băng thông cao hơn — tốt nhất là cáp quang — cùng thêm switch để đủ cổng nối dây cho tất cả máy. Việc chọn thiết bị và đường truyền, vì vậy, luôn nên bắt đầu từ nhu cầu sử dụng thực tế, thay vì chọn theo thứ đắt tiền hay quảng cáo nghe hấp dẫn nhất."}],"keypoints":["Bốn thiết bị mạng thường gặp: **modem** (nối nhà với nhà cung cấp dịch vụ Internet), **bộ định tuyến** (`router`, dẫn đường gói tin giữa các mạng), **bộ chuyển mạch** (`switch`, nối nhiều máy trong một mạng nội bộ), và **điểm phát wifi** (`access point`, phát sóng không dây).","Đường truyền mạng gồm hai nhóm: **có dây** (cáp xoắn đôi bằng đồng — giá rẻ nhưng suy hao theo khoảng cách; cáp quang — nhanh và truyền xa hơn nhiều) và **không dây** (`wifi` trong phạm vi hẹp, mạng di động `4G`/`5G` ở phạm vi rộng hơn).","**Băng thông** (`bandwidth`) là lượng dữ liệu tối đa truyền được qua một đường truyền trong mỗi giây, đo bằng `Mbps` hoặc `Gbps`; băng thông càng lớn, việc tải dữ liệu, xem video hay dùng chung mạng cho nhiều thiết bị càng nhanh, ít bị giật, chờ tải.","Việc chọn thiết bị mạng và đường truyền cần dựa trên **nhu cầu sử dụng thực tế** — số thiết bị, mục đích dùng, có cần tốc độ cao hay không — chứ không nhất thiết chọn loại đắt tiền hay hiện đại nhất."],"quiz":["CC-mc-401","CC-mc-402","CC-mc-403","CC-mc-404","CC-mc-405","CC-tf-401","CC-tf-402","CC-tf-403","CC-tf-404","B-mc-14","B-mc-15","B-mc-8","B-mc-34","B-mc-23","B-mc-24","B-mc-26","B-tf-5","B-mc-29","B-mc-10","B-mc-43","B-tf-9","B-mc-47","B-mc-49"]},
    {"id":"C12-21","stage":22,"order":5,"topic":"B","grade":12,"minutes":12,"title":"Từ tên miền đến địa chỉ IP: máy tính tìm nhau thế nào?","intro":"Bạn gõ một cái tên bằng chữ vào trình duyệt, còn máy tính thì chỉ làm việc được với những dãy số. Bài học này giải thích **địa chỉ IP** là gì, vì sao mỗi thiết bị lại có thể mang nhiều kiểu địa chỉ khác nhau, và **DNS** đã âm thầm làm cầu nối giữa cái tên bạn gõ với dãy số máy cần như thế nào.","sections":[{"t":"story","text":"Chủ nhật, lớp 12A5 tổ chức quyên góp sách cũ cho thư viện xã. Bạn lớp trưởng nhắn vào nhóm chat: “Cả lớp mang sách tới nhà bà Tám bán tạp hoá đầu ngõ 5 nhé.” Không ai thắc mắc gì cả, vì trong xóm ấy ai cũng biết nhà bà Tám ở chỗ nào.\n\nĐến chiều, cả lớp gom được hai thùng sách quá nặng, phải đặt xe ba gác chở giúp. Lúc này thì câu “nhà bà Tám đầu ngõ 5” trở nên vô dụng: bác tài không phải người trong xóm, bác cần một thứ chính xác hơn hẳn — số 27, ngõ 5, đường Lê Lợi. Bạn lớp trưởng phải chạy sang tổ dân phố, giở cuốn sổ ghi tên chủ hộ kèm số nhà, tra ra đúng con số ấy rồi nhắn lại cho bác tài.\n\nĐiều thú vị là hai cách gọi này không hề mâu thuẫn nhau. Người trong xóm quen dùng cái tên vì nó dễ nhớ; bác tài xe ba gác cần con số vì nó không thể nhầm lẫn. Cuốn sổ ở tổ dân phố chính là chiếc cầu nối: hễ ai chỉ biết cái tên mà cần con số, cứ tra sổ là ra. Thậm chí nếu bà Tám dọn sang căn nhà khác, người ta chỉ cần sửa lại con số trong cuốn sổ, còn cả xóm vẫn gọi “nhà bà Tám” như cũ.\n\nCâu chuyện nhỏ này mô tả gần như trọn vẹn cách hàng tỉ máy tính tìm được nhau trên Internet. Chỉ khác một chút: cuốn sổ tra cứu kia không nằm ở tổ dân phố, mà nằm rải rác trên khắp thế giới và trả lời trong chưa tới một phần mười giây."},{"t":"h","text":"1) Địa chỉ IP — số hiệu nhận dạng mỗi thiết bị trong mạng"},{"t":"text","text":"Mỗi thiết bị khi tham gia vào một mạng máy tính đều được gán một **địa chỉ IP** (`IP address`) — dãy số đóng vai trò định danh cho riêng thiết bị đó trong mạng. Đây chính là “số nhà” mà dữ liệu dựa vào để đi đúng chỗ: thiếu nó, dữ liệu gửi ra sẽ không biết phải tới đâu, mà dữ liệu trả về cũng chẳng biết đường quay lại máy nào.\n\nKiểu địa chỉ phổ biến nhất từ trước tới nay là **IPv4**: gồm đúng bốn nhóm số ngăn cách bởi dấu chấm, mỗi nhóm nhận giá trị từ 0 đến 255, chẳng hạn `203.113.45.7`. Con số 255 không phải ngẫu nhiên — mỗi nhóm được lưu bằng 8 bit nên chỉ biểu diễn được 256 giá trị khác nhau, đánh số từ 0 đến 255. Vì vậy một dãy như `172.16.300.5` chắc chắn sai, và `192.168.1` cũng sai vì thiếu mất một nhóm.\n\nBốn nhóm 8 bit ghép lại cho tổng cộng khoảng 4,3 tỉ địa chỉ. Nghe thì nhiều, nhưng khi mỗi người đã có điện thoại, máy tính, tivi thông minh, đồng hồ, camera... thì kho địa chỉ ấy cạn dần rồi cạn hẳn. Đó là lý do **IPv6** ra đời với độ dài 128 bit, viết thành tám nhóm ký tự thập lục phân ngăn bởi dấu hai chấm, ví dụ `2001:0db8:85a3:0000:0000:8a2e:0370:7334`. Kho địa chỉ của IPv6 lớn đến mức trong thực tế có thể coi là dùng mãi không hết."},{"t":"h","text":"2) Địa chỉ riêng trong nhà, địa chỉ công cộng ngoài Internet"},{"t":"text","text":"Ở nhà bạn, chiếc router wifi cấp cho mỗi thiết bị một địa chỉ chỉ có giá trị bên trong mạng nội bộ của gia đình — người ta gọi đó là **địa chỉ IP riêng** (`private IP`). Bạn sẽ hay gặp những dãy quen thuộc như `192.168.1.5`, `192.168.1.12` hoặc `10.0.0.8`. Chúng giống hệt số phòng trong một khách sạn: nói “phòng 305” thì rất rõ ràng với nhân viên khách sạn ấy, nhưng đưa ra ngoài đường thì chẳng ai biết phòng 305 nằm ở đâu, bởi khách sạn nào cũng có một phòng 305.\n\nĐể liên lạc được với thế giới bên ngoài, cả gia đình dùng chung một **địa chỉ IP công cộng** (`public IP`) do nhà cung cấp dịch vụ Internet cấp cho router. Mọi máy chủ ngoài Internet chỉ nhìn thấy đúng địa chỉ công cộng đó, chứ không hề biết trong nhà bạn có bao nhiêu thiết bị. Router đóng vai trò người gác cổng: nó ghi nhớ thiết bị nội bộ nào vừa gửi yêu cầu ra ngoài, để khi dữ liệu trả về thì chuyển tiếp đúng cho thiết bị ấy.\n\nHiểu điều này sẽ giải thích được một hiện tượng nhiều bạn thấy lạ: nếu điện thoại, máy tính và tivi trong nhà cùng vào một trang web tra cứu “địa chỉ IP của bạn là gì”, cả ba đều hiện ra cùng một dãy số giống hệt nhau. Không có gì mâu thuẫn cả — dãy số đó là địa chỉ công cộng chung của cả nhà, còn địa chỉ riêng của từng máy thì trang web ngoài Internet không nhìn thấy được."},{"t":"h","text":"3) IP tĩnh, IP động và địa chỉ MAC gắn cứng vào thiết bị"},{"t":"text","text":"Một địa chỉ IP có thể được gán theo hai cách. **IP tĩnh** là địa chỉ do người quản trị tự tay nhập vào phần thiết lập mạng và cố định luôn ở đó, không thay đổi cho tới khi có người sửa. Cách này thường dùng cho những máy mà người khác luôn phải tìm đến đúng chỗ: máy chủ của trường, máy in dùng chung trong phòng máy, camera giám sát — nếu địa chỉ của chúng cứ đổi liên tục thì mỗi lần muốn dùng lại phải đi dò lại từ đầu.\n\n**IP động** thì ngược lại: mỗi lần một thiết bị kết nối vào mạng, một chương trình gọi là máy chủ **DHCP** — thường được tích hợp sẵn ngay trong router — sẽ tự chọn một địa chỉ còn trống trong dải cho phép và cấp cho thiết bị đó, kèm một thời hạn sử dụng. Hôm nay điện thoại của bạn nhận `192.168.1.14`, tắt wifi rồi mai bật lại có thể nhận `192.168.1.21` mà bạn chẳng cần biết. Cách này tiện ở chỗ không ai phải đặt tay từng máy và cũng không lo hai máy trùng địa chỉ nhau.\n\nCần phân biệt thật rõ địa chỉ IP với **địa chỉ MAC** — mã số do nhà sản xuất ghi sẵn vào card mạng ngay từ khi xuất xưởng, gồm sáu cặp ký tự thập lục phân, chẳng hạn `3C:5A:B4:0F:22:9E`. Địa chỉ IP mô tả việc thiết bị đang nằm ở đâu trong mạng nên đổi mạng là đổi theo; còn địa chỉ MAC gắn liền với chính phần cứng nên mang máy đi khắp nơi nó vẫn thế. Nói nôm na, IP giống địa chỉ chỗ trọ hiện tại của bạn, còn MAC giống số căn cước công dân — chuyển nhà thì địa chỉ đổi, số căn cước thì không."},{"t":"h","text":"4) Tên miền và hệ thống phân giải DNS"},{"t":"list","text":"**Tên miền** (`domain name`) là cái tên viết bằng chữ, được đặt tương ứng với địa chỉ IP của một máy chủ, để con người khỏi phải nhớ những dãy số vô nghĩa. Tên miền chia thành nhiều cấp ngăn cách bởi dấu chấm và phải đọc theo chiều từ phải sang trái, mỗi lần lùi sang trái là hẹp thêm một cấp. Hãy thử bóc tách tên miền `thuvien.thpthungvuong.edu.vn`:","items":["`vn` — thành phần ngoài cùng bên phải, gọi là **tên miền cấp cao nhất**, cho biết đây là tên miền đăng ký theo mã quốc gia Việt Nam. Những đuôi quen thuộc khác cùng cấp này là `com`, `org`, `net`.","`edu` — **tên miền cấp hai**, cho biết chủ sở hữu thuộc lĩnh vực giáo dục. Cùng nhóm này còn có `gov.vn` dành cho cơ quan nhà nước hay `com.vn` dành cho tổ chức kinh doanh. Đừng nhầm `com.vn` (cấp hai, nằm dưới đuôi Việt Nam) với `com` đứng một mình ở vị trí cấp cao nhất — chữ giống nhau nhưng ở hai cấp khác nhau.","`thpthungvuong` — **tên miền cấp ba**, là phần tên riêng do nhà trường tự chọn rồi đăng ký; đây mới là thứ giúp phân biệt trường này với hàng nghìn đơn vị khác cũng mang đuôi `edu.vn`.","`thuvien` — **tên miền con** (`subdomain`), do chính chủ sở hữu tự đặt thêm ở phía trước để tách riêng một bộ phận, ở đây là trang thư viện của trường."]},{"t":"text","text":"Con người nhớ chữ giỏi hơn nhớ số, còn máy tính thì chỉ định tuyến được theo số. **DNS** (`Domain Name System`) chính là hệ thống làm cầu nối giữa hai thế giới ấy: bạn đưa cho nó một tên miền, nó tra cứu và trả về địa chỉ IP tương ứng. Đúng vai trò của cuốn sổ ghi tên chủ hộ kèm số nhà ở tổ dân phố trong câu chuyện đầu bài, chỉ khác là cuốn sổ này được đặt trên vô số máy chủ khắp thế giới.\n\nQuá trình xảy ra khi bạn gõ một địa chỉ web lạ vào trình duyệt gồm hai chặng rõ rệt. Chặng thứ nhất: trình duyệt tách lấy phần tên miền rồi gửi câu hỏi tới một máy chủ DNS (thường là máy chủ DNS của nhà mạng bạn đang dùng) với nội dung đại ý “tên miền này ứng với địa chỉ IP nào?”, và nhận về một dãy số, chẳng hạn `118.70.24.19`. Chặng thứ hai mới thật sự là lấy nội dung: trình duyệt gửi yêu cầu tới máy chủ mang đúng dãy số đó và nhận trang web về hiển thị. Thứ tự này không bao giờ đảo ngược — phải có địa chỉ IP trong tay thì mới gửi yêu cầu đi được.\n\nViệc tách rời tên miền khỏi địa chỉ IP mang lại một lợi ích rất lớn: khi một đơn vị chuyển trang web sang máy chủ khác và nhận địa chỉ IP mới, họ chỉ cần cập nhật lại bản ghi trong DNS, còn người dùng vẫn gõ cái tên quen thuộc như chưa hề có chuyện gì xảy ra. Ngược lại, nếu máy chủ DNS gặp trục trặc, sẽ có tình huống nghe khá kỳ lạ: gõ tên miền thì báo không tìm thấy, nhưng gõ thẳng địa chỉ IP thì trang vẫn hiện ra — dấu hiệu cho thấy mạng không hề mất, chỉ khâu phân giải tên miền bị hỏng."},{"t":"example","text":"Một địa chỉ web đầy đủ — thường gọi là URL — không chỉ có mỗi tên miền, mà còn cho biết dùng giao thức nào và lấy đúng tài nguyên nào trên máy chủ. Hãy bóc tách địa chỉ mà bạn lớp trưởng gửi cho cả lớp:","code":"https://thuvien.thpthungvuong.edu.vn/tai-lieu/on-tin12/de-cuong.pdf\n\nBa thành phần tách ra:\n  https                            -> giao thức (cách trao đổi, có mã hoá)\n  thuvien.thpthungvuong.edu.vn     -> tên miền (hỏi máy chủ nào)\n  /tai-lieu/on-tin12/de-cuong.pdf  -> đường dẫn tới tài nguyên cần lấy","output":"Trình duyệt lấy phần tên miền thuvien.thpthungvuong.edu.vn hỏi DNS để nhận về địa chỉ IP, kết nối tới máy chủ mang địa chỉ IP đó theo giao thức https, rồi yêu cầu đúng tệp de-cuong.pdf nằm trong thư mục /tai-lieu/on-tin12/ và tải về hiển thị."},{"t":"note","text":"Ba lỗi rất hay gặp trong đề thi. Thứ nhất, nhầm rằng chuyển sang mạng wifi khác thì địa chỉ MAC cũng đổi theo — sai, chỉ địa chỉ IP đổi, còn MAC gắn cứng vào card mạng. Thứ hai, đảo ngược định nghĩa IP tĩnh và IP động: hãy nhớ **tĩnh là do người đặt tay và giữ nguyên**, **động là do máy chủ DHCP cấp tự động mỗi lần kết nối**. Thứ ba, tưởng tên miền và URL là một: tên miền chỉ là phần chỉ ra máy chủ, còn URL là địa chỉ đầy đủ gồm cả giao thức và đường dẫn tới đúng tài nguyên."}],"keypoints":["**Địa chỉ IP** là định danh của mỗi thiết bị trong mạng; một địa chỉ **IPv4** gồm bốn nhóm số từ 0 đến 255 ngăn cách bởi dấu chấm, còn **IPv6** ra đời vì kho địa chỉ IPv4 đã cạn kiệt trước số lượng thiết bị ngày càng lớn.","**Địa chỉ IP riêng** (thường dạng `192.168.x.x`) chỉ có giá trị trong mạng nội bộ, còn mọi thiết bị trong nhà cùng ra Internet qua chung một **địa chỉ IP công cộng** của router.","**IP tĩnh** do người dùng đặt cố định bằng tay, **IP động** do máy chủ **DHCP** của router cấp tự động mỗi lần thiết bị kết nối; khác cả hai, **địa chỉ MAC** được gắn cứng vào card mạng nên không đổi khi chuyển mạng.","**Tên miền** được đọc từ phải sang trái theo cấp (cấp cao nhất, cấp hai, tên miền con), và **DNS** làm nhiệm vụ phân giải tên miền thành địa chỉ IP trước khi trình duyệt gửi yêu cầu tới máy chủ."],"quiz":["CC-mc-2101","CC-mc-2102","CC-mc-2103","CC-mc-2104","CC-mc-2105","CC-tf-2101","CC-tf-2102","CC-tf-2103","CC-tf-2104","B-mc-16","B-mc-17","B-mc-18","B-tf-3","B-mc-3","B-sa-1","B-mc-37","B-mc-46"]},
    {"id":"C12-05","stage":22,"order":6,"topic":"B","grade":12,"minutes":12,"title":"Thiết kế một mạng LAN đơn giản","intro":"Một mạng LAN (mạng máy tính cục bộ) không tự nhiên mà có — nó cần được lên kế hoạch cẩn thận trước khi lắp đặt. Bài học này trình bày năm bước cơ bản để thiết kế một mạng LAN nhỏ, gọn và đủ dùng, áp dụng được cho một phòng máy tính hay một hộ gia đình.","sections":[{"t":"story","text":"Hãy tưởng tượng bạn chuẩn bị dọn vào một căn phòng làm việc mới, dự định kê hai chiếc máy tính bàn, một máy in, và muốn cả điện thoại cũng vào được mạng qua wifi. Nếu bạn đợi đến khi kê xong bàn ghế mới nghĩ đến chuyện đi dây mạng, rất có thể bạn sẽ phải đi dây nổi vòng vèo trên sàn nhà, hoặc phát hiện ra ổ cắm mạng đặt sai chỗ, cách xa bàn làm việc cả mấy mét. Ngược lại, nếu bạn phác thảo trước: bàn đặt ở đâu, máy nào cần nối dây, chỗ nào cần đặt ổ cắm mạng, thì việc lắp đặt sẽ gọn gàng và đủ dùng ngay từ đầu, không phải sửa đi sửa lại.\n\nThiết kế một **mạng LAN** (mạng cục bộ, chỉ hoạt động trong phạm vi nhỏ như một phòng, một nhà, một cơ quan) cũng theo đúng tinh thần đó: cần được tính toán trước, chứ không phải cắm đại dây rồi tính sau."},{"t":"h","text":"Các bước thiết kế một mạng LAN nhỏ"},{"t":"text","text":"**Bước 1 – Xác định nhu cầu sử dụng.** Trước khi mua bất cứ thiết bị nào, bạn cần trả lời rõ: có bao nhiêu thiết bị sẽ nối mạng, các thiết bị đó chủ yếu dùng để làm gì, và có cần kết nối không dây (wifi) hay không. Đây là bước quan trọng nhất, vì mọi quyết định sau đó — mua thiết bị gì, đi dây ra sao — đều dựa trên câu trả lời ở bước này.\n\n**Bước 2 – Chọn thiết bị phù hợp.** Một mạng LAN nhỏ thường liên quan đến ba loại thiết bị: `modem`/`router` (nhận đường truyền Internet từ nhà cung cấp dịch vụ và phân phối cho mạng nội bộ), `switch` (chia thêm cổng dây khi số máy cần nối dây nhiều hơn số cổng có sẵn trên router), và điểm phát wifi hay `access point` (phủ sóng không dây — nhiều router hiện nay đã tích hợp sẵn chức năng này). Không phải mạng nào cũng cần đủ cả ba loại; một hộ gia đình vài thiết bị có thể chỉ cần một `router` có wifi tích hợp là đủ."},{"t":"list","text":"Khi xác định nhu cầu, bạn có thể tự trả lời các câu hỏi cụ thể sau:","items":["Có bao nhiêu thiết bị cần nối mạng (máy tính bàn, laptop, điện thoại, máy in...)?","Các thiết bị đó chủ yếu dùng để làm gì — soạn thảo văn bản và lướt web, hay truyền file nặng, chơi game trực tuyến, chạy dịch vụ cần đường truyền ổn định?","Có cần kết nối không dây cho các thiết bị hay di chuyển như điện thoại, laptop không?","Trong thời gian tới có khả năng thêm thiết bị mới không, để chừa dư một chút cổng hoặc dung lượng?"]},{"t":"example","text":"Xét hai tình huống cụ thể để thấy việc chọn thiết bị luôn gắn với nhu cầu thực tế, không phải cứ đắt tiền là tốt:","code":"Tình huống 1: Một hộ gia đình có 2 máy tính bàn, 1 laptop, 3 điện thoại; nhu cầu chính là lướt web, học trực tuyến.\n-> Chỉ cần 1 router tích hợp modem và wifi, có đủ cổng LAN cho 2 máy bàn; laptop và điện thoại nối wifi.\n\nTình huống 2: Một phòng máy tính có 20 máy tính bàn cố định, cần đường truyền ổn định cho tất cả.\n-> Cần 1 modem/router, cộng thêm 1 switch nhiều cổng (vì router thường chỉ có 4 cổng LAN, không đủ cho 20 máy); có thể thêm điểm phát wifi nếu phòng cũng cần sóng không dây.","output":"Tình huống 1 tốn ít chi phí vì nhu cầu nhỏ; tình huống 2 cần đầu tư thêm switch vì số máy nối dây vượt quá số cổng có sẵn trên router — đúng tinh thần chọn thiết bị theo nhu cầu, không thừa không thiếu."},{"t":"h","text":"Vẽ sơ đồ kết nối và cấu hình cơ bản"},{"t":"list","text":"Trước khi đi dây thật, bạn nên phác thảo sơ đồ đường đi của tín hiệu mạng, thường theo thứ tự sau:","items":["Đường truyền Internet từ nhà cung cấp dịch vụ đi vào `modem`","`Modem` nối với `router` bằng dây mạng (nhiều thiết bị hiện nay gộp chung modem và router làm một)","`Router` nối tới `switch` nếu số máy cần nối dây nhiều hơn số cổng có sẵn trên router","`Switch` chia dây tới từng máy tính bàn ở các vị trí cố định trong phòng","`Router` (hoặc `access point` riêng) phát sóng wifi cho điện thoại, laptop di chuyển trong phạm vi phòng, nhà"]},{"t":"text","text":"**Bước 4 – Cấu hình cơ bản.** Sau khi lắp đặt xong phần cứng, mỗi thiết bị trong mạng cần một địa chỉ để nhận diện lẫn nhau, và địa chỉ này thường được `router` tự động cấp phát cho từng thiết bị. Với phần wifi, bạn cần đặt tên mạng (`SSID`) dễ nhận biết và đặt mật khẩu để chỉ những thiết bị được phép mới kết nối được.\n\n**Bước 5 – Kiểm tra kết nối và bảo đảm an toàn.** Sau khi cấu hình xong, hãy kiểm tra từng máy xem đã vào được Internet chưa, tốc độ có ổn định không, và sóng wifi có phủ đều các vị trí trong phòng hay bị yếu ở góc xa. Nếu phát hiện vấn đề — chẳng hạn dây lỗi, hoặc điểm phát wifi đặt quá xa — đây là lúc điều chỉnh, trước khi đưa mạng vào sử dụng lâu dài."},{"t":"note","text":"Một mạng LAN cấu hình xong mà bỏ qua an toàn thì vẫn dễ bị lợi dụng: hãy đặt mật khẩu wifi đủ mạnh (kết hợp chữ, số, ký tự đặc biệt, tránh các dãy số dễ đoán), đổi mật khẩu quản trị mặc định của router (thường in sẵn trên nhãn thiết bị, ai xem cũng biết được), và cập nhật `firmware` (phần mềm điều khiển thiết bị) định kỳ để vá các lỗ hổng bảo mật mới phát hiện. Đồng thời, luôn nhớ **cân đối chi phí và nhu cầu**: thiết bị đắt tiền, nhiều tính năng không có nghĩa là phù hợp — quan trọng là đủ dùng cho nhu cầu hiện tại và chừa dư một chút cho tương lai gần."}],"keypoints":["Thiết kế mạng LAN gồm năm bước: xác định nhu cầu, chọn thiết bị, vẽ sơ đồ kết nối, cấu hình cơ bản, rồi kiểm tra và bảo đảm an toàn.","Ba loại thiết bị cốt lõi: `modem`/`router` kết nối ra Internet và phân phối mạng nội bộ; `switch` dùng khi cần nhiều cổng dây hơn router có sẵn; `access point` (hoặc router có wifi) phát sóng không dây.","Cấu hình an toàn tối thiểu gồm: đặt `SSID` dễ nhận biết, đặt mật khẩu wifi đủ mạnh, đổi mật khẩu quản trị mặc định của router, và cập nhật `firmware` định kỳ.","Khi thiết kế, cần cân đối chi phí và nhu cầu thực tế: không mua thừa thiết bị đắt tiền cho nhu cầu nhỏ, nhưng cũng nên chừa dư một chút cổng hay dung lượng để dễ mở rộng về sau."],"quiz":["CC-mc-501","CC-mc-502","CC-mc-503","CC-mc-504","CC-mc-505","CC-tf-501","CC-tf-502","CC-tf-503","CC-tf-504","B-mc-25","B-mc-28","B-mc-40","B-mc-42","B-mc-44","B-tf-10","B-mc-50","B-mc-51"]},
    {"id":"C12-22","stage":22,"order":7,"topic":"B","grade":12,"minutes":11,"title":"Dùng chung thư mục, máy in và phân quyền trong mạng nội bộ","intro":"Khi các máy tính đã được nối vào cùng một mạng nội bộ, chúng không chỉ cùng ra Internet mà còn có thể **dùng chung tài nguyên** của nhau: thư mục dữ liệu, máy in, thậm chí cả một ổ đĩa. Bài học này chỉ ra cách chia sẻ một thư mục, cách **phân quyền** cho từng người, cách mở tài nguyên đã chia sẻ từ máy khác qua đường dẫn dạng `\\\\tên-máy\\tên-thư-mục`, và những rủi ro phải lường trước khi chia sẻ.","sections":[{"t":"story","text":"Cuối tháng ba, lớp 12A5 nhận nhiệm vụ làm tập san chia tay mái trường. Sáu bạn trong ban biên tập ngồi ở sáu máy khác nhau trong phòng thực hành, mỗi người phụ trách một trang: trang ảnh kỉ niệm, trang phỏng vấn thầy cô, trang thơ, trang trò chơi ô chữ...\n\nRắc rối bắt đầu từ khâu gom bài. Cả nhóm dùng đúng một chiếc thẻ nhớ chuyền tay: bạn thứ nhất chép bài của mình vào rồi đưa cho bạn thứ hai, bạn thứ hai chép tiếp rồi đưa cho bạn thứ ba. Đến vòng thứ ba thì không ai còn chắc bản nào mới nhất nữa. Có bạn mở nhầm bản cũ ra sửa, công sức cả buổi chiều thành ra vô ích. Tệ hơn, một bạn trong lúc dọn thẻ nhớ cho gọn đã xoá mất nguyên thư mục ảnh gốc mà bạn khác vừa cất công quét từ album cũ.\n\nĐến lúc in thử cũng chẳng dễ chịu hơn. Cả phòng chỉ có duy nhất một chiếc máy in đặt ở góc, nối dây vào chiếc máy tính kê sát tường. Muốn in một trang, các bạn lại phải chép ra thẻ nhớ, bê ghế sang góc phòng, mở tệp trên máy đó rồi mới bấm in. Sáu người in sáu trang là sáu lượt đứng lên ngồi xuống.\n\nThấy vậy, thầy phụ trách phòng máy chỉ nói một câu ngắn: các máy trong phòng này vốn đã nối với nhau sẵn rồi, sao các em không để bài ở một chỗ chung để ai cũng mở được, người nào được phép thì mới sửa, còn máy in thì cứ ngồi tại chỗ mà bấm in? Buổi hôm sau, chiếc thẻ nhớ nằm yên trong cặp suốt cả tiết."},{"t":"h","text":"1) Trong mạng nội bộ, những gì có thể dùng chung?"},{"t":"list","text":"Khi các máy đã nằm trong cùng một mạng nội bộ (mạng `LAN`), mỗi máy có thể đem một phần tài nguyên của mình ra phục vụ những máy còn lại. Bốn nhóm tài nguyên thường được chia sẻ nhất là:","items":["**Thư mục và tệp dữ liệu**: một thư mục trên máy này được mở ra cho các máy khác cùng xem hoặc cùng sửa — đây là cách chia sẻ phổ biến nhất, thay hẳn cho việc chuyền thẻ nhớ qua lại.","**Máy in**: chỉ cần một chiếc máy in cho cả phòng, mọi người ngồi tại máy của mình vẫn gửi được lệnh in tới nó.","**Ổ đĩa mạng** (`network drive`): một thư mục dùng chung được gán cho một tên ổ đĩa (chẳng hạn ổ `Z:`) trên máy người dùng, để mở nhanh như mở một ổ đĩa có sẵn trong máy.","**Kết nối Internet**: cả mạng nội bộ cùng đi ra ngoài qua một đường truyền chung, thay vì mỗi máy phải có một đường riêng."]},{"t":"h","text":"2) Bốn bước để chia sẻ một thư mục"},{"t":"text","text":"Bước đầu tiên là bật **tính năng khám phá mạng** (`network discovery`) trên máy sẽ đem thư mục ra chia sẻ. Đây là công tắc quyết định máy của bạn có cho phép các máy khác trong cùng mạng “nhìn thấy” mình hay không. Rất nhiều trường hợp học sinh làm đúng hết các bước sau nhưng máy bạn bên cạnh vẫn không tìm ra tài nguyên, lí do chỉ đơn giản là công tắc này đang tắt.\n\nBước thứ hai là chọn đúng thư mục cần chia sẻ. Nguyên tắc ở đây là chọn hẹp nhất có thể: nếu chỉ cần đưa các bài viết cho ban biên tập, hãy tạo riêng một thư mục `TapSan2026` rồi chia sẻ đúng thư mục đó, đừng vì tiện tay mà đem chia sẻ cả thư mục tài liệu cá nhân hay cả một ổ đĩa. Sau khi chọn, bạn mở phần thiết lập chia sẻ của thư mục (thường nằm trong mục thuộc tính, thẻ `Sharing`) và bật chế độ chia sẻ lên.\n\nHai bước còn lại đi liền với nhau: **chỉ định người hoặc nhóm được truy cập**, rồi **cấp quyền** cho từng người hoặc nhóm đó. Chỉ định nghĩa là nêu đích danh những tài khoản người dùng được phép mở thư mục này — có thể là từng tài khoản một, cũng có thể là cả một nhóm đã lập sẵn, ví dụ nhóm `BanBienTap`. Cấp quyền nghĩa là nói rõ mỗi đối tượng ấy được làm gì với dữ liệu bên trong, và đây chính là nội dung của mục tiếp theo."},{"t":"h","text":"3) Chỉ đọc hay đọc–ghi: cấp quyền vừa đủ dùng"},{"t":"text","text":"Có hai mức quyền truy cập cơ bản mà bạn cần phân biệt thật rõ. Mức **chỉ đọc** (`read`) cho phép người được cấp mở xem nội dung và sao chép tệp về máy mình, nhưng mọi thao tác làm thay đổi bản gốc — sửa nội dung, đổi tên, thêm tệp mới, xoá tệp — đều bị từ chối. Ở đây có một nhầm lẫn rất hay gặp: nhiều bạn tưởng “chỉ đọc” nghĩa là không sao chép được, thực ra vẫn tải về máy mình bình thường, thứ bị cấm chỉ là động vào bản gốc nằm trong thư mục dùng chung. Mức **đọc–ghi** (`read/write`) thì cho phép làm tất cả những việc đó: thêm, sửa, xoá tệp ngay trong thư mục dùng chung.\n\nQuay lại chuyện tập san của lớp 12A5. Thư mục `AnhGoc` chứa những tấm ảnh quét từ album cũ, quét lại rất mất công, nên chỉ cần cấp quyền chỉ đọc cho cả nhóm: ai cũng xem và tải về được, nhưng không ai xoá nhầm hay ghi đè lên bản gốc. Ngược lại, thư mục `BaiNop` là nơi sáu bạn phải liên tục bỏ bài mới vào và chỉnh sửa, nên phải cấp quyền đọc–ghi cho đúng sáu tài khoản của ban biên tập.\n\nCách làm trên chính là **nguyên tắc cấp quyền tối thiểu đủ dùng**: mỗi người chỉ nên được cấp đúng mức quyền cần thiết để hoàn thành phần việc của mình, không hơn. Cấp thừa quyền không giúp công việc chạy nhanh hơn chút nào, nhưng lại mở thêm đúng bấy nhiêu cơ hội cho sự cố — mà trong đa số trường hợp, sự cố đến từ một cái bấm nhầm chứ chẳng phải từ ý xấu của ai. Cũng vì lẽ đó, đừng vì tiện tay mà cấp quyền cho `Everyone` (mọi người) thay vì nêu đích danh từng tài khoản: làm vậy là mở cửa cho bất kì máy nào trong mạng, kể cả máy của người bạn không hề quen biết."},{"t":"h","text":"4) Mở thư mục và dùng máy in đã chia sẻ từ một máy khác"},{"t":"example","text":"Giả sử máy của thầy phụ trách có tên là `PC-GIAOVIEN`, trên đó thư mục `TapSan2026` và chiếc máy in của phòng đã được chia sẻ. Ngồi ở bất kì máy nào khác trong phòng, bạn có ba cách quen thuộc để với tới chúng:","code":"Cách 1 — Tìm trong mục Network của cửa sổ quản lí tệp:\n  Network\n   ├─ PC-BIENTAP-01\n   ├─ PC-BIENTAP-05\n   └─ PC-GIAOVIEN            ← máy đang chia sẻ tài nguyên\n        ├─ TapSan2026        (thư mục dùng chung)\n        └─ MayIn-PhongTH     (máy in dùng chung)\n\nCách 2 — Gõ thẳng đường dẫn mạng vào ô địa chỉ:\n  \\\\PC-GIAOVIEN\\TapSan2026\n\nCách 3 — Ánh xạ thư mục đó thành một ổ đĩa mạng để lần sau khỏi gõ lại:\n  Ổ  Z:   ←   \\\\PC-GIAOVIEN\\TapSan2026","output":"Thư mục TapSan2026 mở ra và dùng y như một thư mục trong máy mình (được sửa hay không là do quyền đã cấp); sau khi ánh xạ, nó hiện thêm thành ổ Z: bên cạnh ổ C:, còn máy in dùng chung xuất hiện trong danh sách máy in để chọn mỗi khi bấm lệnh in."},{"t":"text","text":"Hãy chú ý dạng đường dẫn ở cách 2: hai dấu gạch chéo ngược, rồi tên máy, rồi lại một dấu gạch chéo ngược và tên thư mục đã chia sẻ — `\\\\PC-GIAOVIEN\\TapSan2026`. Đây là cách gọi tên tài nguyên trong mạng nội bộ, rất hữu ích khi mục `Network` liệt kê ra quá nhiều máy hoặc vì lí do nào đó không hiện đủ. Còn **ổ đĩa mạng** ở cách 3 chỉ là một lối vào cho tiện: dữ liệu vẫn nằm nguyên trên `PC-GIAOVIEN` chứ không hề được sao chép sang máy bạn, nên nếu máy kia tắt thì ổ `Z:` cũng không mở được nữa.\n\nVới **máy in dùng chung**, nguyên lí hoàn toàn tương tự. Chiếc máy in vật lí có thể được nối vào một máy tính rồi máy tính ấy đem nó ra chia sẻ, hoặc bản thân máy in có cổng mạng và được nối thẳng vào mạng để phục vụ mọi người mà không phụ thuộc máy nào. Ở trường hợp thứ nhất, cần nhớ một điều: máy tính đang “giữ” máy in phải bật và phải còn bật chia sẻ thì các máy khác mới in được — đây là lí do phổ biến nhất khiến lệnh in gửi đi rồi mà tờ giấy vẫn nằm im trong khay."},{"t":"h","text":"5) Chia sẻ bừa bãi: rủi ro và cách phòng tránh"},{"t":"text","text":"Chia sẻ càng rộng thì rủi ro càng lớn, và có ba rủi ro cần nhớ. Một là **lộ dữ liệu**: một thư mục mở cho cả mạng nghĩa là bất kì ai ngồi trong mạng đó cũng đọc được, kể cả những tệp bạn quên mất là mình từng để lẫn trong đấy. Hai là **bị sửa hoặc xoá nhầm**: khi quyền đọc–ghi được phát cho quá nhiều người, chỉ một thao tác bất cẩn cũng đủ làm mất công sức của cả nhóm — đúng như chuyện thư mục ảnh gốc ở đầu bài. Ba là **lây lan mã độc**: một thư mục dùng chung mà ai cũng ghi được là con đường thuận lợi để mã độc từ một máy đã nhiễm tự chép sang tất cả các máy còn lại.\n\nBa biện pháp phòng tránh cũng rất dễ nhớ. Thứ nhất, **đặt mật khẩu truy cập** — nghĩa là chỉ cho phép những tài khoản có tên và mật khẩu hợp lệ mở được tài nguyên, thay vì để ngỏ cho mọi người. Thứ hai, **chỉ chia sẻ đúng thư mục thật sự cần**, đặt ở mức quyền thấp nhất mà công việc vẫn chạy được. Thứ ba, **tắt chia sẻ khi không còn dùng đến**: tập san in xong rồi thì thư mục `TapSan2026` không có lí do gì phải tiếp tục mở cửa cho cả phòng suốt phần còn lại của năm học.\n\nTắt chia sẻ không hề làm mất dữ liệu — tệp vẫn nằm nguyên trên máy đã đem nó ra chia sẻ, chỉ là cánh cửa dẫn từ mạng vào đã được khép lại. Thói quen mở khi cần và đóng khi xong này đơn giản nhưng loại bỏ được phần lớn sự cố mà một mạng nội bộ trong trường học thường gặp phải."}],"keypoints":["Trong mạng nội bộ có thể chia sẻ **thư mục và tệp dữ liệu**, **máy in**, **ổ đĩa mạng** và **kết nối Internet**; chia sẻ thư mục là cách dùng chung phổ biến nhất, thay cho việc chuyền thẻ nhớ.","Chia sẻ một thư mục gồm bốn việc: bật **tính năng khám phá mạng**, chọn đúng thư mục cần chia sẻ, chỉ định người hoặc nhóm được truy cập, rồi **cấp quyền** cho từng đối tượng.","Quyền **chỉ đọc** cho xem và sao chép nhưng không cho sửa hay xoá bản gốc; quyền **đọc–ghi** cho thêm, sửa, xoá — hãy theo **nguyên tắc cấp quyền tối thiểu đủ dùng**.","Truy cập tài nguyên đã chia sẻ qua mục `Network` hoặc đường dẫn `\\\\tên-máy\\tên-thư-mục`, có thể **ánh xạ thành ổ đĩa mạng**; chia sẻ bừa bãi dễ dẫn tới lộ dữ liệu, xoá nhầm và lây mã độc."],"quiz":["CC-mc-2201","CC-mc-2202","CC-mc-2203","CC-mc-2204","CC-mc-2205","CC-tf-2201","CC-tf-2202","CC-tf-2203","CC-tf-2204","B-mc-19","B-mc-35","B-mc-36","B-mc-39"]},
    {"id":"C12-06","stage":22,"order":8,"topic":"D","grade":12,"minutes":12,"title":"Đạo đức, pháp luật và văn hoá trong môi trường số","intro":"Không gian mạng nhìn qua có vẻ là một nơi tự do tuyệt đối, muốn làm gì cũng được, nhưng thực chất đó vẫn là một môi trường có luật lệ và chuẩn mực ứng xử riêng, không khác gì bất kỳ cộng đồng nào ngoài đời thực. Bài học này trình bày bốn mảng cốt lõi mà một người dùng có trách nhiệm cần nắm vững: quyền riêng tư, bản quyền số, một số quy định pháp luật cơ bản, và văn hoá ứng xử — đặc biệt trong bối cảnh trí tuệ nhân tạo và mạng xã hội ngày càng phổ biến.","sections":[{"t":"story","text":"Hãy tưởng tượng bạn chuyển đến sống ở một khu dân cư mới. Không ai phát cho bạn một cuốn sổ tay ghi rõ luật lệ ngay từ ngày đầu, nhưng bạn vẫn hiểu ngầm rằng: không tự ý vào nhà người khác khi chưa được cho phép, không nghe lén chuyện riêng của hàng xóm rồi đem kể khắp nơi, không dựng chuyện bịa đặt làm mất uy tín của ai đó, và nếu mượn hay dùng đồ của người khác thì ít nhất cũng phải hỏi qua hoặc ghi nhận công sức của họ. Những quy tắc ấy đến từ hai nguồn: một phần là pháp luật (vi phạm thì bị xử lý), một phần là phép lịch sự bất thành văn mà cả cộng đồng cùng tuân theo để sống chung êm đẹp.\n\nMôi trường số — internet, mạng xã hội, các ứng dụng bạn dùng hằng ngày — cũng là một dạng cộng đồng như vậy, chỉ khác là mọi người không nhìn thấy mặt nhau. Chính vì không nhìn thấy mặt nhau, nhiều người dễ lầm tưởng rằng ở đó không có luật, không ai biết, không ai phải chịu trách nhiệm. Thực tế hoàn toàn ngược lại: hành vi trên mạng vẫn để lại dấu vết, vẫn ảnh hưởng đến những con người thật, và vẫn phải tuân theo các quy tắc pháp luật lẫn đạo đức tương tự ngoài đời — thậm chí cần cẩn trọng hơn, vì một hành động sai trên mạng có thể lan xa và gây hậu quả nhanh hơn rất nhiều so với ngoài đời thực."},{"t":"h","text":"Quyền riêng tư và bảo vệ dữ liệu cá nhân"},{"t":"text","text":"**Dữ liệu cá nhân** là những thông tin gắn liền với một con người cụ thể: họ tên, ngày sinh, số điện thoại, số căn cước, địa chỉ nhà, hình ảnh khuôn mặt, thông tin sức khoẻ, hay thậm chí là vị trí bạn đang đứng. Về nguyên tắc, dữ liệu cá nhân thuộc quyền quyết định của chính người đó — họ có quyền chọn ai được xem, được lưu, được chia sẻ thông tin của mình, và có quyền từ chối nếu không muốn. Đó chính là **quyền riêng tư**.\n\nTrong môi trường số, dữ liệu cá nhân dễ bị thu thập hơn rất nhiều so với trước đây: mỗi lần đăng ký tài khoản, cài đặt ứng dụng, hay chỉ đơn giản là lướt một trang web, thông tin của bạn đã có thể được ghi lại. Dữ liệu cũng dễ phát tán hơn: một tấm ảnh, một đoạn video có thể được chia sẻ lại hàng nghìn lần chỉ trong vài phút, vượt xa khả năng kiểm soát của người xuất hiện trong đó. Chính vì vậy, nguyên tắc bảo vệ quyền riêng tư cần được áp dụng theo hai chiều: bảo vệ dữ liệu của chính mình (cân nhắc trước khi cung cấp thông tin, kiểm tra lại cài đặt riêng tư trên các ứng dụng), và tôn trọng dữ liệu của người khác (không tự ý thu thập, lưu trữ, hay phát tán thông tin, hình ảnh của người khác khi chưa được họ đồng ý)."},{"t":"list","text":"Một số việc làm cụ thể thể hiện sự tôn trọng quyền riêng tư — của mình lẫn của người khác:","items":["Không đăng ảnh, video quay cảnh người khác (đặc biệt là những khoảnh khắc riêng tư, kém may mắn) lên mạng xã hội khi chưa hỏi ý kiến họ.","Không chia sẻ số điện thoại, địa chỉ, điểm số hay thông tin sức khoẻ của bạn bè, người quen vào nhóm chat hay nơi công khai nếu họ không đồng ý.","Cân nhắc kỹ trước khi điền thông tin cá nhân vào các biểu mẫu, ứng dụng lạ; đọc sơ qua chính sách quyền riêng tư nếu có thể.","Kiểm tra và giới hạn ai được xem bài đăng, hình ảnh của mình trên mạng xã hội, thay vì để chế độ công khai theo mặc định."]},{"t":"h","text":"Bản quyền số và sở hữu trí tuệ"},{"t":"text","text":"Một bức ảnh, một bản nhạc, một bài viết, hay một phần mềm — dù chỉ là tệp tin có thể sao chép bằng một cú nhấp chuột — vẫn là kết quả của công sức, thời gian và chất xám mà một người (hoặc một nhóm người) đã bỏ ra để tạo nên. **Bản quyền** là quyền của người tạo ra sản phẩm đó, cho phép họ quyết định ai được sử dụng, sao chép, chỉnh sửa, hay phân phối lại sản phẩm của mình.\n\nMột hiểu lầm khá phổ biến là: cái gì tìm thấy được trên mạng, tải xuống được, thì mặc nhiên là miễn phí và muốn dùng sao cũng được. Thực tế, việc một nội dung dễ sao chép về mặt kỹ thuật không đồng nghĩa với việc nó được phép sử dụng tự do về mặt pháp lý. Vi phạm bản quyền — ví dụ dùng phần mềm bẻ khoá (`crack` — bản chỉnh sửa trái phép nhằm vượt qua cơ chế kiểm tra bản quyền của phần mềm), tải nhạc hay phim từ nguồn không phép rồi đăng lại để thu hút lượt xem, hay chép nguyên bài viết của người khác rồi đứng tên mình — đều là hành vi xâm phạm sở hữu trí tuệ, có thể bị xử lý theo pháp luật, chưa kể phủ nhận công sức của người tạo ra sản phẩm gốc."},{"t":"example","text":"Xét hai cách xử lý khác nhau khi cần dùng một tấm ảnh tìm thấy trên mạng cho một bài thuyết trình ở trường:","code":"Cách 1: Tìm ảnh bất kỳ qua công cụ tìm kiếm, tải về, chèn thẳng vào bài thuyết trình - không ghi nguồn, không kiểm tra ảnh có được phép dùng lại hay không.\n\nCách 2: Ưu tiên ảnh từ nguồn cho phép sử dụng lại (ảnh gắn nhãn `Creative Commons` - giấy phép cho phép người khác dùng lại nội dung theo một số điều kiện nhất định) hoặc tự chụp, tự vẽ; nếu dùng ảnh của người khác thì ghi rõ tên tác giả hoặc nguồn ảnh bên dưới.","output":"Cách 1 tiềm ẩn rủi ro vi phạm bản quyền dù bài thuyết trình chỉ dùng trong lớp học, vì sử dụng không phép vẫn là sử dụng không phép, bất kể có mục đích thương mại hay không. Cách 2 vừa an toàn về pháp lý, vừa thể hiện sự tôn trọng công sức của người tạo ra bức ảnh gốc — một thói quen nên rèn từ khi còn ngồi trên ghế nhà trường."},{"t":"h","text":"Pháp luật về an ninh mạng: những hành vi bị nghiêm cấm"},{"t":"list","text":"Bên cạnh quyền riêng tư và bản quyền, pháp luật về an ninh mạng còn quy định rõ một số nhóm hành vi bị cấm khi sử dụng không gian mạng, vì chúng gây hại trực tiếp đến người khác hoặc đến trật tự chung; vi phạm có thể bị xử phạt hành chính hoặc truy cứu trách nhiệm hình sự tuỳ mức độ nghiêm trọng. Một số nhóm hành vi tiêu biểu:","items":["Lừa đảo chiếm đoạt tài sản hoặc thông tin cá nhân — ví dụ giả danh ngân hàng, cơ quan chức năng để yêu cầu chuyển tiền hoặc cung cấp mã `OTP` (mã xác thực dùng một lần).","Tạo ra hoặc phát tán mã độc (`virus`, `ransomware`...) nhằm phá hoại dữ liệu hoặc chiếm quyền điều khiển thiết bị của người khác.","Xúc phạm danh dự, nhân phẩm, vu khống hoặc bôi nhọ người khác bằng lời lẽ, hình ảnh, video đăng công khai.","Xâm nhập trái phép vào tài khoản, hệ thống của người khác khi không được cho phép, kể cả khi chỉ ‘thử cho vui’ và không gây thiệt hại rõ rệt.","Phát tán tin giả, thông tin sai sự thật gây hoang mang hoặc ảnh hưởng đến trật tự, an toàn xã hội."]},{"t":"h","text":"Văn hoá ứng xử trong môi trường số"},{"t":"text","text":"Không phải mọi hành vi thiếu chuẩn mực trên mạng đều bị pháp luật xử lý ngay lập tức, nhưng điều đó không có nghĩa là muốn làm gì cũng được. Bên cạnh luật, còn có **văn hoá ứng xử số** — những chuẩn mực đạo đức mà một người dùng có trách nhiệm nên tự giác tuân theo: trung thực (không giả mạo danh tính, không dựng chuyện), tôn trọng (không công kích, không phân biệt đối xử với người khác), và trách nhiệm (cân nhắc hậu quả trước khi đăng hay chia sẻ bất cứ điều gì).\n\nChuẩn mực này càng trở nên quan trọng khi các công cụ trí tuệ nhân tạo (AI) ngày càng phổ biến. AI có thể tạo ra văn bản, hình ảnh, thậm chí video trông rất thật chỉ trong vài giây — bao gồm cả `deepfake` (hình ảnh, video giả mạo khuôn mặt hoặc giọng nói của một người có thật, do AI tạo ra, trông như thật). Dùng AI để tạo ra nội dung sai sự thật rồi lan truyền trên mạng xã hội — dù với mục đích trêu đùa, câu lượt tương tác, hay cố ý bôi nhọ — đều là hành vi vi phạm nghiêm trọng cả về đạo đức lẫn pháp luật, vì nạn nhân là người thật, và thiệt hại về danh dự, tâm lý mà họ gánh chịu cũng là thật."},{"t":"note","text":"Mạng xã hội trao cho mỗi người một ‘chiếc micro’ có thể được hàng trăm, hàng nghìn người nghe thấy chỉ sau một cú nhấn nút chia sẻ. Sức lan toả càng lớn thì trách nhiệm kiểm chứng thông tin trước khi chia sẻ càng cao — một tin đồn sai sự thật hay một đoạn `deepfake`, một khi đã phát tán, gần như không thể thu hồi lại hoàn toàn. Trước khi đăng hay chia sẻ bất cứ điều gì, hãy tự hỏi: thông tin này có đúng không, mình có đang xâm phạm quyền riêng tư hay bản quyền của ai không, và mình có sẵn sàng chịu trách nhiệm nếu bị truy ra là người phát tán đầu tiên hay không."}],"keypoints":["**Quyền riêng tư** là quyền quyết định ai được xem, lưu, chia sẻ dữ liệu cá nhân (họ tên, hình ảnh, số điện thoại, vị trí...); cần tôn trọng dữ liệu của chính mình lẫn của người khác, không tự ý thu thập hay phát tán khi chưa được đồng ý.","**Bản quyền số** bảo vệ công sức của người tạo ra nội dung, phần mềm; nội dung dễ tải về không có nghĩa là được dùng tự do — cần sử dụng hợp pháp (nguồn được phép, phần mềm có bản quyền) và ghi rõ nguồn khi dùng lại.","Pháp luật về an ninh mạng nghiêm cấm các hành vi như lừa đảo, phát tán mã độc, xúc phạm hoặc vu khống người khác, xâm nhập trái phép hệ thống — vi phạm có thể bị xử phạt hành chính hoặc truy cứu trách nhiệm hình sự.","**Văn hoá ứng xử số** đòi hỏi sự trung thực, tôn trọng và trách nhiệm, đặc biệt khi dùng mạng xã hội và công cụ AI — không tạo hay lan truyền tin giả, `deepfake`, vì hậu quả gây ra cho nạn nhân là hoàn toàn có thật."],"quiz":["CC-mc-601","CC-mc-602","CC-mc-603","CC-mc-604","CC-mc-605","CC-tf-601","CC-tf-602","CC-tf-603","CC-tf-604","D-mc-15","D-mc-18","D-mc-4","D-mc-5","D-mc-7","D-mc-27","D-mc-32","D-tf-11","CC-mc-891","CC-mc-892","CC-tf-891","CC-mc-893","CC-mc-894","CC-mc-895","CC-tf-892"]},
    {"id":"C12-07","stage":22,"order":9,"topic":"E","grade":12,"minutes":10,"title":"Trang web và ngôn ngữ HTML","intro":"Mọi trang web bạn từng mở qua trình duyệt đều được dựng trên một bộ khung có cấu trúc rõ ràng, viết bằng ngôn ngữ HTML. Bài này giới thiệu trang web và website là gì, cùng cách HTML dùng các thẻ để tạo nên bộ khung ấy.","sections":[{"t":"story","text":"Hãy hình dung bạn được giao dựng một ngôi nhà từ đầu. Trước khi nghĩ đến sơn tường màu gì, lát sàn gỗ hay gạch, hay treo rèm cửa kiểu nào, việc đầu tiên bao giờ cũng là dựng xong phần khung: móng ở đâu, cột chịu lực ở đâu, phòng khách nằm ở vị trí nào, phòng ngủ ở đâu, cửa chính mở về hướng nào. Phần khung ấy chưa đẹp, nhưng nó quyết định ngôi nhà có hình dạng và cấu trúc rõ ràng để sau đó mới trang trí lên trên.\n\nMột trang web cũng được dựng theo đúng tinh thần đó. Trước khi trang có màu sắc bắt mắt, phông chữ dễ nhìn, hay cách sắp xếp gọn gàng (đó là việc của một ngôn ngữ khác, tên **CSS**, ta sẽ học ở bài sau), trang cần có một bộ khung xác định rõ: đâu là tiêu đề, đâu là đoạn văn bản, đâu là hình ảnh. Ngôn ngữ dùng để dựng bộ khung ấy gọi là **HTML** — nhân vật chính của bài học này."},{"t":"h","text":"Trang web và website"},{"t":"text","text":"Khi bạn mở một trình duyệt (như Chrome, Firefox, Edge, Cốc Cốc...) và truy cập vào một địa chỉ, thứ hiện ra trên màn hình — gồm chữ, hình ảnh, các đường liên kết để bấm sang nơi khác — được gọi là một **trang web** (tiếng Anh: `web page`). Nói đơn giản, trang web là một tài liệu mà trình duyệt đọc được và hiển thị ra cho bạn xem, giống như một trang giấy trong một cuốn sách — chỉ khác là đây là “trang giấy điện tử”, có thể chứa đường liên kết để nhảy sang trang khác chỉ bằng một cú bấm chuột.\n\nTrên thực tế, một tổ chức hiếm khi chỉ có đúng một trang đứng riêng lẻ. Một trang giới thiệu thường đi kèm thêm trang “Sản phẩm”, trang “Liên hệ”, trang “Tin tức”... và các trang này liên kết qua lại với nhau. Tập hợp nhiều trang web có liên kết với nhau, thường dùng chung một địa chỉ gốc, được gọi là một **website**. Vậy, “trang web” chỉ MỘT tài liệu đơn lẻ, còn “website” chỉ CẢ TẬP HỢP nhiều trang — dù trong lời nói hằng ngày, người ta hay dùng lẫn hai từ này cho nhau."},{"t":"h","text":"HTML — ngôn ngữ đánh dấu, không phải ngôn ngữ lập trình"},{"t":"text","text":"**HTML** (viết tắt của `HyperText Markup Language`) là một **ngôn ngữ đánh dấu** (markup language), không phải một ngôn ngữ lập trình. “Đánh dấu” ở đây nghĩa là gắn nhãn cho từng phần nội dung: chỗ này là tiêu đề, chỗ kia là một đoạn văn, chỗ khác nữa là một tấm ảnh... HTML làm việc đó bằng cách bao nội dung trong các **thẻ** (tag), có dạng `<tên>...</tên>`. Ví dụ, `<h1>Giới thiệu</h1>` có nghĩa là: chữ “Giới thiệu” đóng vai trò một tiêu đề lớn.\n\nCần phân biệt rõ HTML với một ngôn ngữ lập trình thật sự (như `Python`). Một ngôn ngữ lập trình có phép tính, có điều kiện rẽ nhánh (nếu... thì...), có vòng lặp (lặp lại nhiều lần) để xử lí logic. HTML không có gì như vậy — nó chỉ **mô tả cấu trúc** của nội dung, giống như việc dán nhãn “Chương 1”, “Mục a”, “Ghi chú” lên các phần của một tài liệu giấy, chứ không hề tính toán hay ra quyết định gì cả.\n\nPhần lớn thẻ HTML đi theo từng cặp: một thẻ mở `<tên>` và một thẻ đóng `</tên>` (thêm dấu gạch chéo phía trước tên). Toàn bộ nội dung nằm giữa hai thẻ này chịu sự quản lí của thẻ đó — ví dụ, mọi thứ đặt giữa `<h1>` và `</h1>` được hiểu là một tiêu đề lớn, còn mọi thứ giữa `<p>` và `</p>` được hiểu là một đoạn văn. Tuy nhiên, một số thẻ đặc biệt không bao nội dung gì cả nên chỉ cần viết một lần duy nhất, gọi là thẻ **tự đóng**; chẳng hạn `<br>` (yêu cầu xuống dòng) hay `<img>` (chèn một tấm ảnh) không cần — và cũng không có — thẻ đóng đi kèm."},{"t":"h","text":"Bộ khung cơ bản của một trang HTML"},{"t":"text","text":"Mọi trang HTML, dù đơn giản hay phức tạp, đều bắt đầu từ cùng một bộ khung gồm bốn phần cố định. Đầu tiên là `<!DOCTYPE html>` — đây thực chất là một **lời khai báo** đặt ở dòng đầu tiên, báo cho trình duyệt biết “tài liệu này viết theo chuẩn HTML5”, để trình duyệt hiểu và hiển thị đúng cách; nó không phải một cặp thẻ mở/đóng như phần còn lại.\n\nTiếp theo là thẻ `<html>`, bao trùm toàn bộ nội dung còn lại của trang — mọi thẻ khác đều nằm bên trong cặp `<html>...</html>` này. Bên trong `<html>` lại chia làm hai phần rõ rệt, nối tiếp nhau: `<head>` rồi đến `<body>`.\n\n**`<head>`** chứa các thông tin “hậu trường” của trang — những thứ trình duyệt cần biết nhưng KHÔNG hiển thị trực tiếp giữa nội dung trang. Quan trọng nhất trong `<head>` là thẻ `<title>`, quy định dòng chữ hiển thị trên tab của trình duyệt. **`<body>`** thì ngược lại — đây là nơi chứa toàn bộ nội dung thực sự hiển thị ra cho người xem: tiêu đề, đoạn văn, hình ảnh, danh sách, đường liên kết... Nếu `<head>` giống như hồ sơ nội bộ, thì `<body>` chính là mặt tiền mà bất kì ai ghé thăm trang cũng nhìn thấy."},{"t":"example","text":"Hãy xem một trang HTML tối giản — đủ bốn phần vừa nêu — và hình dung nó hiện ra như thế nào trên trình duyệt:","code":"<!DOCTYPE html>\n<html>\n<head>\n  <title>Trang giới thiệu</title>\n</head>\n<body>\n  <h1>Xin chào!</h1>\n  <p>Đây là trang web đầu tiên của tôi, được viết bằng HTML.</p>\n</body>\n</html>","output":"Trên tab của trình duyệt hiện dòng chữ “Trang giới thiệu” — lấy đúng từ nội dung thẻ `<title>`. Trong khung nội dung chính của trang, dòng “Xin chào!” hiện ra to và đậm (vì đây là thẻ `<h1>` — cấp tiêu đề lớn nhất), ngay phía dưới là dòng “Đây là trang web đầu tiên của tôi, được viết bằng HTML.” hiển thị theo kiểu chữ thường của một đoạn văn (thẻ `<p>`). Chữ “Trang giới thiệu” bên trong `<title>` KHÔNG xuất hiện giữa trang — nó chỉ nằm trên tab, vì `<title>` thuộc `<head>`."},{"t":"note","text":"Bạn không cần cài phần mềm đặc biệt nào để viết HTML — chỉ cần một trình soạn thảo văn bản thuần (như Notepad), gõ đúng nội dung như ví dụ trên, rồi lưu tệp với đuôi `.html` (thay vì `.txt`) là có thể mở bằng bất kì trình duyệt nào để xem thử. Một lỗi khá phổ biến của người mới học là lồng thẻ sai thứ tự — chẳng hạn mở `<head>` rồi mở tiếp `<body>` trước khi `<head>` kịp đóng lại. Các cặp thẻ cần lồng đúng thứ tự, giống như đóng ngoặc đúng cặp trong toán học (mở `(` rồi mở `[` thì phải đóng `]` trước rồi mới đóng `)`) — lồng sai, trang có thể vẫn hiện ra thứ gì đó (trình duyệt khá dễ tính, cố đoán ý), nhưng cấu trúc thật sự đã sai và dễ gây lỗi hiển thị khó lường về sau."}],"keypoints":["**Trang web** là một tài liệu được trình duyệt đọc và hiển thị ra màn hình; nhiều trang web liên kết với nhau tạo thành một **website**.","**HTML** (`HyperText Markup Language`) là một **ngôn ngữ đánh dấu**, dùng các thẻ `<tên>...</tên>` để tạo cấu trúc cho nội dung — KHÔNG phải ngôn ngữ lập trình (không có phép tính, điều kiện, vòng lặp).","Bộ khung cơ bản của một trang HTML gồm bốn phần: `<!DOCTYPE html>` (lời khai báo chuẩn), `<html>` (bao trùm toàn trang), `<head>` chứa `<title>` (không hiển thị giữa trang, chỉ hiện trên tab), và `<body>` (chứa nội dung hiển thị thực sự).","Phần lớn thẻ HTML đi theo cặp mở `<tên>` và đóng `</tên>`; một số thẻ không bao nội dung nên **tự đóng**, ví dụ `<br>`, `<img>`."],"quiz":["CC-mc-701","CC-mc-702","CC-mc-703","CC-mc-704","CC-mc-705","CC-tf-701","CC-tf-702","CC-tf-703","CC-tf-704","E-mc-18","E-mc-19","E-mc-20","E-tf-4"]},
    {"id":"C12-08","stage":22,"order":10,"topic":"E","grade":12,"minutes":12,"title":"HTML: văn bản, tiêu đề, danh sách và liên kết","intro":"Bài này giới thiệu năm loại thẻ HTML thường dùng nhất để trình bày chữ trên một trang web: tiêu đề, đoạn văn, chữ đậm/nghiêng, danh sách và liên kết. Nắm chắc năm loại thẻ này, bạn đã đủ khả năng dựng một trang thông tin đơn giản, đọc hiểu được và đúng cấu trúc.","sections":[{"t":"story","text":"Hãy tưởng tượng bạn cần dán một tờ thông báo lên bảng tin của một khu chung cư: khu vực sẽ mất nước vào thứ Bảy, mọi người cần chuẩn bị trước. Khi viết tay tờ thông báo đó, bạn tự nhiên phân chia rất rõ ràng: dòng chữ ‘THÔNG BÁO’ được viết to nhất ở trên cùng để ai đi ngang cũng thấy; bên dưới là vài đoạn giải thích lý do và thời gian; tiếp theo là một danh sách gạch đầu dòng liệt kê những việc cần chuẩn bị; cuối tờ thông báo có một dòng nhỏ: ‘Xem lịch cúp nước chi tiết tại bảng tin cổng B’ – tức là chỉ sang một nơi khác để đọc thêm. Một trang web cũng được dựng theo đúng cách đó: thay vì to nhỏ bằng nét bút, HTML dùng các cặp thẻ để nói cho trình duyệt biết đoạn nào là tiêu đề, đoạn nào là văn bản thường, đoạn nào là danh sách, và đoạn nào là một liên kết dẫn sang trang khác."},{"t":"h","text":"Tiêu đề và đoạn văn: những khối chữ cơ bản nhất"},{"t":"text","text":"HTML cung cấp sáu mức tiêu đề: `<h1>`, `<h2>`, `<h3>`, `<h4>`, `<h5>` và `<h6>`. Số đứng sau chữ h càng nhỏ, tiêu đề càng lớn và càng quan trọng – `<h1>` là tiêu đề lớn nhất, thường chỉ dùng **một lần duy nhất** cho tên chính của cả trang; `<h6>` là mức tiêu đề nhỏ nhất, dùng cho những đề mục phụ nằm sâu bên trong. Cách viết rất đơn giản: mở thẻ, gõ nội dung, rồi đóng thẻ bằng dấu gạch chéo, ví dụ `<h1>Thông báo</h1>`.\n\nNội dung viết thành câu, thành đoạn – giống như những gì bạn đang đọc trong phần này – được đặt trong thẻ `<p>` (viết tắt của **paragraph**, nghĩa là đoạn văn). Mỗi cặp `<p>...</p>` tạo ra một đoạn riêng biệt; trình duyệt tự để một khoảng cách nhỏ giữa các đoạn với nhau, giúp trang chữ dễ đọc hơn nhiều so với việc dồn hết vào một khối liền mạch.\n\nBên trong một đoạn văn, khi muốn một cụm chữ nổi bật hơn phần còn lại, ta dùng thêm hai thẻ nhỏ: `<strong>` làm chữ **in đậm**, thường đánh dấu nội dung quan trọng cần chú ý ngay; `<em>` làm chữ *in nghiêng*, thường dùng để nhấn mạnh giọng điệu của một từ, tương tự như khi ta lên giọng lúc nói. Cả hai đều được lồng bên trong `<p>`, chỉ bao quanh đúng phần chữ cần làm nổi bật, ví dụ: `<p>Hạn nộp là <strong>thứ Sáu</strong>, đừng nộp trễ.</p>`."},{"t":"h","text":"Danh sách: gom các ý thành từng dòng gọn gàng"},{"t":"list","text":"HTML có hai kiểu danh sách chính, cả hai đều chứa các mục con nằm trong thẻ `<li>` (viết tắt của **list item**):","items":["`<ul>` – danh sách không thứ tự: mỗi mục được đánh dấu bằng một dấu chấm tròn phía trước; dùng khi các ý ngang hàng nhau, thứ tự trước sau không quan trọng, ví dụ danh sách vật dụng cần chuẩn bị.","`<ol>` – danh sách có thứ tự: trình duyệt tự động đánh số 1, 2, 3... cho từng mục; dùng khi thứ tự có ý nghĩa, ví dụ các bước thực hiện một công việc theo đúng trình tự.","Dù chọn `<ul>` hay `<ol>`, mỗi ý đều phải nằm trong một cặp thẻ `<li>` riêng, và toàn bộ các thẻ `<li>` đó phải nằm gọn bên trong cặp thẻ `<ul>` hoặc `<ol>` bao ngoài."]},{"t":"h","text":"Liên kết: đưa người đọc sang một trang khác"},{"t":"text","text":"Muốn cho người đọc nhảy từ trang này sang một trang khác (hoặc một vị trí khác), ta dùng thẻ `<a>` (viết tắt của **anchor**, nghĩa là điểm neo). Thẻ này có cấu trúc: `<a href=\"địa-chỉ-đích\">chữ hiển thị</a>`. Thuộc tính `href` (viết tắt của **hypertext reference**) ghi địa chỉ trang muốn dẫn tới; phần nội dung nằm giữa thẻ mở và thẻ đóng là dòng chữ người đọc thật sự nhìn thấy và có thể bấm vào. Hai phần này không nhất thiết phải giống nhau, giống như tấm biển ghi ‘Xem tiếp trang sau’ trong khi địa chỉ thật sự phía sau có thể là một đường dẫn dài, khó nhớ."},{"t":"example","text":"Hãy xem một đoạn HTML ngắn gộp đủ những gì vừa học: tiêu đề, đoạn văn có chữ đậm và chữ nghiêng, một danh sách không thứ tự, và một liên kết.","code":"<!DOCTYPE html>\n<html>\n<head>\n<title>Thông báo cúp nước</title>\n</head>\n<body>\n<h1>Thông báo cúp nước</h1>\n<p>Khu vực sẽ <strong>tạm ngừng cấp nước</strong> vào thứ Bảy này để bảo trì đường ống. Đây là việc <em>bắt buộc</em> theo lịch của công ty cấp nước.</p>\n<ul>\n<li>Trữ đủ nước dùng cho cả ngày</li>\n<li>Tắt van tổng trước khi cúp nước</li>\n<li>Không xả nước thải xuống đường ống trong thời gian này</li>\n</ul>\n<p><a href=\"lich-cup-nuoc.html\">Xem lịch cúp nước chi tiết</a></p>\n</body>\n</html>","output":"Trên màn hình trình duyệt: dòng ‘Thông báo cúp nước’ hiện to và đậm nhất trang vì nằm trong `<h1>`; tiếp đến là một đoạn văn bình thường, trong đó cụm ‘tạm ngừng cấp nước’ in đậm còn từ ‘bắt buộc’ in nghiêng; sau đó là ba dòng liệt kê, mỗi dòng có một dấu chấm tròn phía trước; cuối cùng là dòng chữ ‘Xem lịch cúp nước chi tiết’ hiển thị dạng liên kết – bấm vào đó trình duyệt sẽ mở trang `lich-cup-nuoc.html`."},{"t":"text","text":"Đi từng phần trong ví dụ trên: `<!DOCTYPE html>` khai báo đây là một tài liệu HTML; cặp `<html>...</html>` bao trọn toàn bộ trang; phần `<head>` chứa thông tin không hiển thị trực tiếp trên trang, ở đây là `<title>` – chữ hiện trên tab của trình duyệt chứ không phải trên trang; toàn bộ nội dung người đọc nhìn thấy nằm trong `<body>`.\n\nBên trong `<body>`: `<h1>` đặt tiêu đề lớn nhất của trang. Thẻ `<p>` đầu tiên là một đoạn văn, bên trong nó `<strong>` làm đậm cụm từ quan trọng còn `<em>` làm nghiêng từ cần nhấn giọng – cả hai lồng gọn bên trong `<p>`, đóng trước khi `<p>` đóng. Ba thẻ `<li>` chứa ba việc cần làm, tất cả cùng nằm trong một cặp `<ul>` nên hiển thị thành danh sách gạch đầu dòng. Cuối cùng, thẻ `<a href=\"lich-cup-nuoc.html\">` biến dòng chữ ‘Xem lịch cúp nước chi tiết’ thành một liên kết có thể bấm để mở trang khác; thẻ `<a>` này lại được đặt trong một cặp `<p>` để nó nằm gọn thành một đoạn riêng."},{"t":"note","text":"Một lỗi rất dễ gặp khi mới học là **lồng thẻ sai thứ tự**: thẻ nào mở sau phải đóng trước. Viết `<p><strong>chữ đậm</p></strong>` là sai, vì `<strong>` mở sau `<p>` nhưng lại đóng sau `</p>` luôn – thứ tự đóng phải ngược với thứ tự mở, tức là `<p><strong>chữ đậm</strong></p>` mới đúng. Ngoài ra, thẻ `<li>` chỉ có ý nghĩa khi nằm bên trong `<ul>` hoặc `<ol>`; đặt `<li>` một mình bên ngoài hai thẻ đó, trình duyệt sẽ không hiểu đấy là một mục danh sách."}],"keypoints":["`<h1>` đến `<h6>` tạo tiêu đề với sáu mức to nhỏ khác nhau (`<h1>` lớn nhất); `<p>` tạo đoạn văn; `<strong>` (đậm) và `<em>` (nghiêng) nhấn mạnh một phần chữ bên trong đoạn.","`<ul>` tạo danh sách không thứ tự (dấu chấm tròn), `<ol>` tạo danh sách có thứ tự (đánh số tự động); mỗi mục trong cả hai đều nằm trong một thẻ `<li>` riêng.","`<a href=\"địa-chỉ\">chữ hiển thị</a>` tạo liên kết: `href` xác định trang đích, còn phần chữ nằm giữa hai thẻ là nội dung người đọc nhìn thấy và bấm vào.","Các thẻ phải lồng đúng thứ tự: thẻ nào mở sau phải đóng trước; `<li>` phải nằm trong `<ul>` hoặc `<ol>`, còn `<strong>`/`<em>` phải đóng trước khi thẻ `<p>` chứa nó đóng lại."],"quiz":["CC-mc-801","CC-mc-802","CC-mc-803","CC-mc-804","CC-mc-805","CC-tf-801","CC-tf-802","CC-tf-803","CC-tf-804","E-mc-20","E-mc-29","E-mc-3","E-mc-4","E-mc-21","E-mc-22","E-mc-44","E-mc-7","E-mc-62","E-mc-67","E-mc-69"]},
    {"id":"C12-09","stage":22,"order":11,"topic":"E","grade":12,"minutes":10,"title":"HTML: chèn hình ảnh và tạo bảng","intro":"Một trang web chỉ toàn chữ khó truyền tải được nhiều loại thông tin. Bài học này giới thiệu hai công cụ giúp trang web sinh động và rõ ràng hơn: thẻ `<img>` để chèn hình ảnh, và bộ ba thẻ `<table>`, `<tr>`, `<th>`/`<td>` để trình bày dữ liệu theo hàng và cột.","sections":[{"t":"story","text":"Hãy tưởng tượng bạn đang làm một tờ báo tường cho lớp. Trên tờ giấy, bạn cần làm hai việc: dán một tấm ảnh chụp hoạt động của lớp vào một góc, và kẻ một bảng ô vuông ở góc khác để ghi kết quả thi đua giữa các tổ theo từng tuần. Dán ảnh và kẻ bảng là hai thao tác rất khác nhau — một bên là gắn nguyên một tấm ảnh có sẵn vào đúng chỗ, một bên là tự tay kẻ từng ô, từng hàng, từng cột sao cho thẳng thớm.\n\nTrên một trang HTML, ta cũng có đúng hai công cụ tương ứng cho hai việc đó: thẻ `<img>` lo phần “dán ảnh”, còn bộ ba thẻ `<table>`, `<tr>`, `<th>`/`<td>` lo phần “kẻ bảng”. Bài học này sẽ đi qua cách dùng cả hai."},{"t":"h","text":"Chèn hình ảnh: thẻ <img>"},{"t":"text","text":"Những thẻ đã gặp trước đây như `<h1>` hay `<p>` đều có một cặp mở và đóng, bao lấy nội dung ở giữa. Thẻ `<img>` khác hẳn: đây là một **thẻ tự đóng** — không bao nội dung nào ở giữa, và cũng không có thẻ đóng riêng đi kèm. Toàn bộ thông tin về tấm ảnh cần chèn được ghi ngay trong các thuộc tính, nằm gọn giữa `<img` và dấu `>` kết thúc.\n\nHai thuộc tính quan trọng nhất là `src` và `alt`. Thuộc tính `src` — viết tắt của source (nguồn) — cho trình duyệt biết tấm ảnh nằm ở đâu: có thể là tên một tệp trong cùng thư mục, đường dẫn tới một thư mục con, hoặc một địa chỉ đầy đủ trên mạng. Thuộc tính `alt` — viết tắt của alternative text (chữ thay thế) — là một đoạn mô tả ngắn cho biết ảnh đó chụp hay vẽ gì; đoạn chữ này hiện ra thay cho ảnh khi đường dẫn sai hoặc ảnh không tải được, đồng thời được phần mềm đọc màn hình dành cho người khiếm thị đọc to lên. Vì vậy `alt` không phải phần có cũng được, không có cũng được — nên luôn mô tả đúng nội dung ảnh, thay vì bỏ trống hoặc viết qua loa.\n\nNgoài ra, nếu ảnh gốc quá lớn so với trang, có thể thêm thuộc tính `width` (tính bằng pixel) để thu nhỏ kích thước hiển thị lại cho vừa mắt. Cách viết đầy đủ của cả ba thuộc tính này được trình bày rõ trong ví dụ ở phần sau."},{"t":"h","text":"Tạo bảng: thẻ <table>, <tr>, <th>, <td>"},{"t":"text","text":"Một bảng trong HTML được ghép từ ba loại thẻ lồng vào nhau, giống như ba lớp hộp: `<table>` là khung bao ngoài cùng, đánh dấu “toàn bộ phần này là một cái bảng”. Bên trong `<table>`, mỗi hàng ngang của bảng là một cặp `<tr>` — có bao nhiêu hàng thì viết bấy nhiêu cặp `<tr>`. Bên trong mỗi `<tr>`, từng ô nhỏ lại được đánh dấu bằng `<th>` (ô tiêu đề — mặc định chữ đậm, căn giữa) hoặc `<td>` (ô dữ liệu bình thường).\n\nNói gọn lại: `<table>` giữ cả cái bảng, `<tr>` giữ một hàng bên trong bảng đó, còn `<th>`/`<td>` giữ một ô bên trong hàng đó."},{"t":"list","text":"Số hàng và số cột của bảng không được khai báo riêng ở đâu — chúng hình thành từ chính cách bạn sắp xếp các thẻ:","items":["Mỗi cặp `<tr>...</tr>` viết thêm là một hàng mới được tạo ra.","Trong một hàng, mỗi cặp `<th>` hoặc `<td>` viết thêm là một ô mới, ứng với một cột tại vị trí đó.","Để các cột thẳng hàng với nhau, mọi `<tr>` trong cùng một bảng nên có cùng số ô — hàng nào cũng nên có đúng chừng ấy `<th>`/`<td>`, không hàng nhiều ô hơn hàng khác.","Hàng chứa `<th>` thường được đặt làm hàng đầu tiên, ngay sau khi mở `<table>`, để người xem biết mỗi cột bên dưới mang ý nghĩa gì."]},{"t":"example","text":"Dưới đây là một trang nhỏ kết hợp cả hai thẻ vừa học: thẻ `<img>` chèn một tấm ảnh ở đầu trang (với `src` trỏ tới tệp ảnh, `alt` mô tả nội dung ảnh, `width` thu nhỏ ảnh còn 300 pixel); ngay bên dưới, thẻ `<table>` cùng các thẻ `<tr>`, `<th>`, `<td>` bên trong dựng nên một bảng điểm gồm 2 cột, 3 hàng.","code":"<!DOCTYPE html>\n<html>\n<head>\n  <title>Kết quả kiểm tra</title>\n</head>\n<body>\n  <h1>Bảng điểm kiểm tra môn Tin học</h1>\n\n  <img src=\"anh-lop-hoc.jpg\" alt=\"Ảnh lớp học đang làm bài kiểm tra\" width=\"300\">\n\n  <table>\n    <tr>\n      <th>Họ tên</th>\n      <th>Điểm</th>\n    </tr>\n    <tr>\n      <td>Nguyễn Văn A</td>\n      <td>9</td>\n    </tr>\n    <tr>\n      <td>Trần Thị B</td>\n      <td>8</td>\n    </tr>\n  </table>\n</body>\n</html>","output":"Trên trang hiển thị: dòng tiêu đề lớn “Bảng điểm kiểm tra môn Tin học”; ngay bên dưới là tấm ảnh lớp học đang làm bài, được thu nhỏ còn rộng 300 pixel (nếu tệp `anh-lop-hoc.jpg` không tồn tại hoặc sai đường dẫn, trình duyệt sẽ hiện dòng chữ “Ảnh lớp học đang làm bài kiểm tra” thay cho ảnh — đúng vai trò của thuộc tính `alt`). Cuối trang là một bảng 2 cột, 3 hàng: hàng đầu ghi tiêu đề cột in đậm “Họ tên” và “Điểm”; hai hàng còn lại liệt kê tên và điểm của hai học sinh, mỗi giá trị nằm đúng dưới cột tiêu đề tương ứng. Lưu ý: nhiều trình duyệt mặc định không hiển thị đường viền rõ giữa các ô — muốn có khung kẻ rõ ràng, người thiết kế web thường bổ sung thêm một chút định dạng khác, nằm ngoài phạm vi bài này."},{"t":"note","text":"Bảng trong HTML sinh ra để trình bày **dữ liệu có hàng, có cột** — danh sách điểm, lịch học, bảng giá... Một số người mới học có xu hướng lạm dụng `<table>` để dàn cả trang web (chia cột trái-phải, đặt menu, đặt hình...), vì cách này từng phổ biến ở giai đoạn Internet sơ khai. Ngày nay, việc dàn bố cục trang nên để cho các công cụ khác đảm nhiệm; dùng bảng để dàn trang khiến mã nguồn rối, khó đọc, khó sửa, và gây khó khăn cho phần mềm đọc màn hình. Ghi nhớ đơn giản: thấy dữ liệu thật sự có hàng có cột thì dùng `<table>`; còn muốn sắp xếp bố cục trang, hãy để dành việc đó cho công cụ khác."}],"keypoints":["Thẻ `<img>` là thẻ tự đóng dùng để chèn ảnh; thuộc tính `src` trỏ tới nguồn ảnh, `alt` là chữ mô tả hiện ra khi ảnh lỗi và được phần mềm đọc màn hình đọc lên, `width` dùng để thu nhỏ hoặc phóng to kích thước hiển thị.","Một bảng được dựng từ ba loại thẻ lồng nhau: `<table>` bao ngoài cùng, `<tr>` tạo ra một hàng, `<th>`/`<td>` tạo ra một ô tiêu đề hoặc ô dữ liệu bên trong hàng đó.","Số hàng do số cặp `<tr>` quyết định, số cột do số ô `<th>`/`<td>` trong mỗi hàng quyết định; các hàng nên có cùng số ô để cột thẳng hàng, và hàng chứa `<th>` thường đặt lên đầu.","Bảng nên dùng để trình bày dữ liệu thật sự có hàng có cột; không nên lạm dụng `<table>` để dàn bố cục trang, vì việc đó nên để cho công cụ khác đảm nhiệm."],"quiz":["CC-mc-901","CC-mc-902","CC-mc-903","CC-mc-904","CC-mc-905","CC-tf-901","CC-tf-902","CC-tf-903","CC-tf-904","E-mc-24","E-mc-25","E-mc-5","E-mc-6"]},
    {"id":"C12-23","stage":22,"order":12,"topic":"E","grade":12,"minutes":11,"title":"Đưa âm thanh, phim và khung nội tuyến lên trang web","intro":"Một trang web chỉ có chữ thì vẫn còn im lặng. Bài học này chỉ cách cho trang cất tiếng và chuyển động bằng hai thẻ `<audio>`, `<video>`, rồi mở thêm một **khung nội tuyến** `<iframe>` để đặt nguyên một trang web khác — bản đồ, biểu mẫu, video trực tuyến — vào ngay giữa trang của mình.","sections":[{"t":"story","text":"Câu lạc bộ Phát thanh của trường vừa làm xong số đầu tiên: một bản tin dài bảy phút, có nhạc nền, có đoạn phỏng vấn bác bảo vệ và cả tiếng cười của mấy bạn lớp 10 lúc thu hỏng phải quay lại. Cả nhóm quyết định làm một trang giới thiệu để bạn bè trong trường ai cũng biết đến.\n\nBan đầu, các bạn định làm theo cách đơn giản nhất: chụp lại dàn máy thu âm, viết vài dòng kể về bản tin, rồi thêm câu ‘bạn nào muốn nghe thì nhắn tin cho nhóm mình nhé’. Nhưng làm vậy thì trang chỉ kể lại chứ chẳng cho ai nghe thấy gì. Người vào xem đọc xong vẫn không biết bản tin hay dở ra sao.\n\nĐiều cả nhóm thật sự muốn là: mở trang lên, thấy ngay một thanh nhỏ có nút bấm — bấm vào là bản tin phát ra. Bên dưới là một khung hình chữ nhật, bấm nút tam giác thì xem được đoạn phim quay hậu trường buổi thu âm. Và ở cuối trang, thay vì dán một dòng địa chỉ dài ngoằng, các bạn muốn có sẵn một tấm bản đồ chỉ đường tới phòng sinh hoạt, kéo qua kéo lại được ngay tại chỗ, không phải mở sang nơi khác.\n\nBa mong muốn ấy — nghe được, xem được, và đặt sẵn một thứ vốn nằm ở nơi khác vào ngay trang của mình — chính là ba việc mà bài học này sẽ chỉ cách làm."},{"t":"h","text":"1) Hai thẻ đưa âm thanh và phim vào trang: <audio> và <video>"},{"t":"text","text":"Để trang web phát được tiếng, HTML có sẵn thẻ `<audio>`. Cách dùng gọn nhất chỉ cần hai thuộc tính: `src` cho biết tệp âm thanh nằm ở đâu (tên tệp hoặc địa chỉ đầy đủ), còn `controls` yêu cầu trình duyệt vẽ ra thanh điều khiển quen thuộc gồm nút phát, nút tạm dừng, thanh chạy thời gian và nút chỉnh âm lượng. Chỉ cần viết `<audio src=\"bantin.mp3\" controls></audio>` là trang đã phát được bản tin.\n\nVới phim, mọi thứ gần như y hệt, chỉ đổi tên thẻ thành `<video>`: `src` vẫn chỉ nguồn tệp, `controls` vẫn tạo thanh điều khiển. Điểm khác là `<video>` còn phải dành ra một khung hình để chiếu, nên nó có thêm những thuộc tính về kích thước mà `<audio>` không cần tới.\n\nCó một chi tiết rất dễ quên: nếu bỏ `controls` đi, khung phim vẫn nằm đó nhưng người xem chẳng có nút nào để bấm, còn thẻ `<audio>` thì gần như biến mất khỏi trang, vì bản thân âm thanh có gì để hiển thị đâu. Vì vậy trong hầu hết trường hợp, hãy nhớ viết `controls`."},{"t":"h","text":"2) Các thuộc tính thường dùng của thẻ <video>"},{"t":"list","text":"Ngoài `src` và `controls`, thẻ `<video>` còn có mấy thuộc tính rất hay được dùng:","items":["`width` và `height` — đặt **chiều rộng** và **chiều cao** của khung hình, tính bằng điểm ảnh. Nếu chỉ ghi một trong hai, trình duyệt sẽ tự tính giá trị còn lại cho cân đối chứ không làm méo hình.","`autoplay` — đoạn phim **tự phát** ngay khi trang vừa mở, người xem không phải bấm nút nào cả.","`loop` — **phát lặp lại**: hết phim thì tự quay về đầu và chạy tiếp, cứ thế cho đến khi người xem rời trang.","`muted` — **tắt tiếng** đoạn phim. Thuộc tính này thường phải đi kèm `autoplay`, vì đa số trình duyệt hiện nay chặn việc tự phát khi còn tiếng, tránh cho trang web bất ngờ kêu ầm lên.","**Nội dung viết giữa cặp thẻ** `<video>` và `</video>` — chỉ hiện ra khi trình duyệt không mở được đoạn phim, để báo cho người xem biết chuyện gì đang xảy ra thay vì bỏ mặc họ nhìn một khoảng trống."]},{"t":"example","text":"Đây là phần thân trang giới thiệu của Câu lạc bộ Phát thanh, có cả bản tin để nghe lẫn đoạn phim hậu trường để xem:","code":"<h2>Câu lạc bộ Phát thanh Măng Non</h2>\n\n<p>Bản tin sáng thứ Hai (7 phút):</p>\n<audio src=\"bantin-thu2.mp3\" controls></audio>\n\n<p>Hậu trường buổi thu âm đầu tiên:</p>\n<video src=\"hautruong.mp4\" width=\"480\" controls loop muted>\n  Trình duyệt của bạn chưa mở được đoạn phim này. Bạn có thể tải tệp về máy để xem.\n</video>","output":"Trang hiện tiêu đề và hai dòng mô tả; dưới dòng thứ nhất là thanh phát âm thanh có nút bấm và nút chỉnh âm lượng, dưới dòng thứ hai là khung phim rộng 480 điểm ảnh (chiều cao tự tính cho cân đối), có thanh điều khiển, phát xong lại tự lặp và không có tiếng; dòng chữ viết giữa cặp thẻ video không hiện ra vì trình duyệt mở được tệp mp4."},{"t":"h","text":"3) Định dạng tệp và chuyện trình duyệt có hỗ trợ hay không"},{"t":"text","text":"Một tệp âm thanh hay tệp phim không phải chỉ là ‘một đống dữ liệu’; nó được đóng gói theo một **định dạng** nhất định, thường nhận ra qua phần đuôi của tên tệp. Trên web, ba định dạng phổ biến nhất là `mp3` cho âm thanh, `mp4` và `webm` cho phim. Mỗi định dạng có cách nén dữ liệu riêng, nên cùng một đoạn phim mà lưu theo hai định dạng khác nhau thì dung lượng và chất lượng cũng khác nhau.\n\nVấn đề nằm ở chỗ: trình duyệt chỉ mở được những định dạng mà nó biết cách giải mã. Bạn có thể viết thẻ `<video>` đúng đến từng dấu ngoặc kép, đường dẫn `src` chính xác tuyệt đối, mà người xem vẫn chỉ thấy một khung đen im lìm — đơn giản vì tệp bạn đưa vào có định dạng trình duyệt của họ không hỗ trợ. Đây là lỗi rất hay gặp khi ta lấy thẳng một tệp phim từ máy quay hoặc phần mềm dựng phim rồi đưa lên trang mà quên chuyển đổi định dạng trước.\n\nNguyên tắc an toàn cho bài thực hành: dùng `mp3` cho âm thanh và `mp4` cho phim, vì đây là hai định dạng gần như mọi trình duyệt phổ thông hiện nay đều mở được. Định dạng `webm` cho tệp nhẹ hơn ở cùng mức chất lượng nên rất được ưa chuộng, nhưng mức hỗ trợ chưa rộng bằng `mp4`."},{"t":"h","text":"4) Khung nội tuyến <iframe>: đặt nguyên một trang khác vào trang của mình"},{"t":"text","text":"Đến đây ta chuyển sang một thẻ có ý tưởng khác hẳn. Thẻ `<iframe>` tạo ra một **khung nội tuyến** — hãy hình dung như bạn khoét một ô cửa sổ hình chữ nhật ngay giữa trang của mình, và qua ô cửa ấy người xem nhìn thẳng vào **một trang web khác** đang chạy đầy đủ bên trong. Không phải ảnh chụp lại trang đó, mà là trang thật: bấm được, cuộn được, gõ chữ vào được.\n\nCú pháp gồm ba thuộc tính chính. `src` là địa chỉ của trang được nhúng vào, còn `width` và `height` quy định ô cửa sổ ấy rộng bao nhiêu, cao bao nhiêu điểm ảnh. Hãy để ý một khác biệt quan trọng: `src` của `<video>` nhận vào một **tệp**, còn `src` của `<iframe>` nhận vào cả **một trang web**.\n\nTrong thực tế, khung nội tuyến giải quyết rất nhiều việc. Nó cho phép nhúng một đoạn phim đang nằm trên nền tảng chia sẻ video mà bạn không hề có tệp gốc trong máy; đặt một tấm bản đồ chỉ đường kéo–thả được ngay giữa trang liên hệ; hoặc gắn thẳng một biểu mẫu đăng kí trực tuyến vào trang câu lạc bộ để người xem điền luôn tại chỗ. Điểm chung của cả ba: phần khó nhất do một trang khác lo, trang của bạn chỉ việc mượn chỗ đặt vào."},{"t":"example","text":"Trang liên hệ của câu lạc bộ, dùng hai khung nội tuyến cho hai việc khác nhau:","code":"<h2>Liên hệ và đăng kí</h2>\n\n<p>Phòng sinh hoạt của câu lạc bộ nằm ở đây:</p>\n<iframe src=\"bando-phong-sinh-hoat.html\" width=\"600\" height=\"400\"></iframe>\n\n<p>Điền phiếu để tham gia số phát thanh tuần sau:</p>\n<iframe src=\"phieu-dangki.html\" width=\"600\" height=\"500\"></iframe>","output":"Trang hiện hai ô cửa sổ hình chữ nhật xếp dọc: ô trên rộng 600 cao 400 điểm ảnh chứa nguyên trang bản đồ kéo–thả được, ô dưới rộng 600 cao 500 điểm ảnh chứa nguyên trang phiếu đăng kí; người xem điền và gửi phiếu ngay trong khung mà không phải rời khỏi trang liên hệ."},{"t":"note","text":"Hai điều phải nhớ khi làm trang có âm thanh, phim và khung nội tuyến.\n\nThứ nhất, tệp đa phương tiện rất nặng. Một đoạn phim vài phút có thể lớn gấp hàng trăm lần toàn bộ chữ trên trang, khiến trang tải chậm ì ạch, nhất là với người dùng mạng di động. Hãy nén tệp lại, cắt bớt phần thừa, và cân nhắc thật kỹ trước khi đặt `autoplay` cho một đoạn phim nặng — nhiều người sẽ đóng trang trước khi nó kịp hiện ra.\n\nThứ hai, quan trọng hơn: một bản nhạc, một đoạn phim hay một tấm ảnh đều có tác giả và có **bản quyền**. Việc tệp có sẵn trên mạng, tải về dễ dàng, hoàn toàn không đồng nghĩa với việc bạn được phép đưa lên trang của mình. Hãy dùng sản phẩm do chính nhóm mình làm ra, hoặc tài nguyên có giấy phép cho phép sử dụng, và ghi rõ nguồn — đó vừa là quy định của pháp luật, vừa là phép lịch sự tối thiểu với người đã bỏ công sáng tạo."}],"keypoints":["Thẻ `<audio>` chèn **âm thanh**, thẻ `<video>` chèn **phim** vào trang web; thuộc tính `src` chỉ nguồn tệp, còn `controls` hiển thị thanh điều khiển phát, tạm dừng và chỉnh âm lượng.","Các thuộc tính hay dùng của `<video>`: `width`, `height` đặt **kích thước khung hình**; `autoplay` cho **tự phát**, `loop` cho **phát lặp lại**, `muted` để **tắt tiếng**; phần chữ viết giữa cặp thẻ chỉ hiện khi trình duyệt không mở được phim.","Tệp phải có **định dạng mà trình duyệt hỗ trợ** thì mới nghe/xem được — an toàn nhất là `mp3` cho âm thanh và `mp4` cho phim, còn `webm` nhẹ hơn nhưng mức hỗ trợ hẹp hơn.","Thẻ `<iframe>` tạo **khung nội tuyến**, nhúng nguyên một trang web khác vào trang hiện tại (`src` là trang được nhúng, `width` và `height` là kích thước khung) — dùng để nhúng video trực tuyến, bản đồ, biểu mẫu; luôn nhớ cân nhắc dung lượng tệp và tôn trọng **bản quyền**."],"quiz":["CC-mc-2301","CC-mc-2302","CC-mc-2303","CC-mc-2304","CC-mc-2305","CC-tf-2301","CC-tf-2302","CC-tf-2303","CC-tf-2304","E-mc-23","E-mc-26","E-mc-47","E-mc-8"]},
    {"id":"C12-24","stage":22,"order":13,"topic":"E","grade":12,"minutes":12,"title":"Nhận thông tin từ người dùng với thẻ form và input","intro":"Các thẻ HTML đã học đều dùng để đưa nội dung ra cho người xem đọc. Bài này đi theo chiều ngược lại: dùng cặp thẻ `<form>` cùng các thẻ `<input>`, `<label>`, `<textarea>`, `<select>` để tạo **biểu mẫu** — nơi người xem gõ dữ liệu vào và gửi đi.","sections":[{"t":"story","text":"Câu lạc bộ Tin học của trường tuyển thành viên mới. Bạn lớp trưởng dán lên bảng tin một tờ giấy A4 kẻ sẵn mấy cột: họ tên, lớp, số điện thoại, buổi rảnh, lí do muốn tham gia. Ai muốn vào thì ra ghi tên.\n\nMới được hai ngày mà tờ giấy đã thành một mớ hỗn độn. Có bạn viết chữ nhỏ quá, đọc mãi không ra là 12A1 hay 12A4. Có bạn quên hẳn cột số điện thoại, đến lúc cần gọi thì chịu. Có bạn ghi lí do dài quá, chữ tràn sang cả dòng của người khác. Đến chiều thứ Sáu thì một cơn mưa tạt vào hành lang, nửa tờ giấy nhoè mực, coi như mất trắng danh sách.\n\nCô giáo chủ nhiệm gợi ý: sao các em không làm hẳn một trang đăng kí trên mạng? Trên đó, mỗi thông tin có một ô riêng biệt, ai cũng gõ vào đúng chỗ của mình. Ô nào bắt buộc mà bỏ trống thì máy nhắc ngay, không cho gửi. Cột lớp thì làm thành một danh sách bấm vào chọn, khỏi lo viết sai. Ô lí do thì cho rộng ra vài dòng để viết thoải mái.\n\nCả nhóm làm theo. Chỉ cần một địa chỉ trang web dán lên nhóm chat của trường, tối hôm đó đã có hơn bốn mươi bạn điền xong, dữ liệu về gọn gàng một chỗ, không nhoè, không thiếu, không đọc nhầm. Bài học hôm nay sẽ chỉ cho bạn cách dựng đúng trang đăng kí như vậy."},{"t":"h","text":"1) Biểu mẫu là gì và vì sao phải có cặp thẻ <form>"},{"t":"text","text":"**Biểu mẫu** (`form`) là phần của trang web dành riêng cho việc **nhận dữ liệu người dùng nhập vào**: ô gõ họ tên, ô chọn lớp, ô tích chọn đồng ý, nút gửi... Nói cách khác, các thẻ đã học ở những bài trước đưa thông tin từ trang web đến mắt người đọc, còn biểu mẫu làm chiều ngược lại — đưa thông tin từ người đọc trở về nơi cần thu thập.\n\nQuy tắc đầu tiên và quan trọng nhất: **toàn bộ các ô nhập của một biểu mẫu phải nằm trong cặp thẻ** `<form>` và `</form>`. Nếu bạn viết vài ô nhập rải rác ngoài cặp thẻ này, trình duyệt vẫn vẽ ra các ô đó bình thường, người dùng vẫn gõ được, nhưng khi bấm nút gửi thì dữ liệu trong những ô đó chẳng đi đâu cả. Đây là lỗi rất hay gặp và cũng rất khó phát hiện, vì nhìn bằng mắt thì trang trông hoàn toàn ổn.\n\nThẻ `<form>` có hai thuộc tính cần nhớ. `action` ghi địa chỉ của nơi sẽ tiếp nhận và xử lí dữ liệu sau khi người dùng bấm gửi. `method` chọn cách gửi, với hai giá trị quen thuộc: `get` gắn dữ liệu ngay vào phía sau địa chỉ trên thanh URL nên ai cũng nhìn thấy — hợp với dữ liệu ngắn, không nhạy cảm như từ khoá tìm kiếm; còn `post` gói dữ liệu đi kèm yêu cầu, không hiện trên thanh địa chỉ — hợp với dữ liệu dài hoặc riêng tư như mật khẩu, số điện thoại. Cần nhớ rằng HTML chỉ dựng ra giao diện của biểu mẫu; việc kiểm tra và lưu dữ liệu vào đâu là nhiệm vụ của chương trình đặt ở địa chỉ trong `action`."},{"t":"h","text":"2) Thẻ <input>: một thẻ nhưng rất nhiều kiểu ô nhập"},{"t":"list","text":"`<input>` là thẻ tự đóng (không có `</input>`) và là thẻ dựng nên gần hết các ô nhập. Điều thú vị là chỉ một thẻ này thôi nhưng cho ra rất nhiều kiểu ô khác nhau, tuỳ vào giá trị của thuộc tính `type`:","items":["`text` — ô gõ chữ thông thường một dòng, dùng cho họ tên, biệt danh, địa chỉ nhà; còn `password` cũng là ô gõ chữ một dòng nhưng mỗi kí tự hiện ra thành một dấu chấm tròn để người ngồi cạnh không đọc trộm được.","`number` — ô chỉ nhận số, thường có thêm hai mũi tên nhỏ để tăng giảm; hợp với số buổi tham gia, số tuổi.","`email` — ô gõ địa chỉ thư điện tử; trình duyệt tự nhắc nếu người dùng gõ thiếu dấu @.","`date` — ô chọn ngày tháng, thường bật lên một cuốn lịch nhỏ cho người dùng bấm chọn.","`checkbox` — ô vuông tích chọn, dùng khi người dùng được chọn **nhiều mục cùng lúc**, chẳng hạn chọn các môn thể thao yêu thích.","`radio` — nút tròn, dùng khi chỉ được **chọn đúng một mục**; các nút thuộc cùng một nhóm phải đặt cùng một giá trị `name` thì trình duyệt mới hiểu chúng loại trừ lẫn nhau."]},{"t":"h","text":"3) Bốn thuộc tính phải thuộc lòng: name, value, placeholder, required"},{"t":"text","text":"Có một ô nhập rồi vẫn chưa đủ, vì khi dữ liệu được gửi về nơi xử lí thì nơi đó cần biết con số hay dòng chữ vừa nhận được là của thông tin nào. Đó là việc của thuộc tính **`name`**: nó đặt tên cho từng dữ liệu gửi đi, giống như cái nhãn dán trên từng chiếc hộp trong một thùng hàng. Một ô nhập không có `name` thì dù người dùng gõ gì vào, dữ liệu đó cũng bị bỏ lại và không được gửi đi — đây là lỗi kinh điển của người mới học.\n\nBa thuộc tính còn lại phục vụ trải nghiệm của người điền. **`value`** đặt sẵn một giá trị cho ô; với ô `text` thì giá trị này hiện ra như chữ đã gõ sẵn, còn với `radio` và `checkbox` thì `value` chính là nội dung sẽ được gửi đi khi mục đó được chọn. **`placeholder`** viết một dòng chữ mờ gợi ý bên trong ô, ví dụ gợi ý cách ghi số điện thoại; chữ này biến mất ngay khi người dùng bắt đầu gõ và **không bao giờ được gửi đi** — nó chỉ để nhìn cho dễ hiểu.\n\nCuối cùng, **`required`** là một thuộc tính đặc biệt vì nó không cần giá trị, chỉ cần viết tên nó vào trong thẻ. Ô nào có `required` mà bị bỏ trống thì trình duyệt sẽ chặn lại, hiện lời nhắc ngay tại ô đó và không cho gửi biểu mẫu. Nhờ vậy mới tránh được tình cảnh như tờ giấy đăng kí trong câu chuyện mở đầu: có bạn ghi tên nhưng quên hẳn số điện thoại."},{"t":"note","text":"Ba lỗi hay bị hỏi trong đề thi: (1) Nhầm `placeholder` với `name` — chữ mờ gợi ý chỉ để người dùng nhìn, tên dữ liệu gửi đi luôn lấy từ `name`. (2) Quên `name` ở một ô, khiến ô đó vẫn hiện ra đẹp đẽ nhưng dữ liệu không hề được gửi. (3) Cho các nút `radio` trong cùng một nhóm những giá trị `name` khác nhau — khi đó người dùng tích được cả mấy nút cùng lúc, hỏng hẳn ý nghĩa 'chỉ chọn một'."},{"t":"h","text":"4) Nhãn <label>, ô nhiều dòng <textarea> và danh sách thả xuống <select>"},{"t":"text","text":"Một ô nhập trơ trọi thì người dùng không biết phải điền gì vào. Thẻ **`<label>`** dùng để gắn một dòng nhãn mô tả cho ô nhập, chẳng hạn 'Họ và tên:'. Nhưng `<label>` còn hay hơn một dòng chữ thường: nếu bạn đặt cho ô nhập một `id`, rồi cho thẻ `<label>` thuộc tính **`for`** mang đúng giá trị `id` ấy, thì hai bên được nối với nhau — người dùng bấm vào dòng nhãn là con trỏ nhảy thẳng vào đúng ô tương ứng. Với ô `checkbox` hay `radio` vốn rất nhỏ, việc này giúp bấm trúng dễ hơn hẳn, đặc biệt là trên điện thoại; ngoài ra phần mềm đọc màn hình dành cho người khiếm thị cũng nhờ mối nối `for`–`id` mà đọc đúng nhãn cho từng ô.\n\nThẻ `<input>` chỉ cho gõ một dòng, nên khi cần một đoạn dài — lí do muốn tham gia câu lạc bộ, lời nhắn góp ý — ta dùng cặp thẻ **`<textarea>`**. Đây là cặp thẻ mở và đóng chứ không tự đóng, và có thể đặt thêm `rows`, `cols` để chỉnh sẵn chiều cao, chiều rộng của khung nhập. Nội dung viết giữa hai thẻ sẽ hiện ra như chữ có sẵn trong ô, nên thường ta để trống hoàn toàn.\n\nCòn khi muốn người dùng chọn một mục trong một danh sách đã biết trước — chọn lớp, chọn khối, chọn tỉnh thành — thì dùng cặp thẻ **`<select>`**, bên trong chứa nhiều thẻ **`<option>`**, mỗi `<option>` là một dòng trong danh sách thả xuống. Chữ nằm giữa cặp thẻ `<option>` là thứ người dùng nhìn thấy, còn thuộc tính `value` của nó mới là dữ liệu thật sự được gửi đi. So với việc bắt người dùng tự gõ, danh sách thả xuống hạn chế được rất nhiều lỗi chính tả và cách ghi lộn xộn."},{"t":"h","text":"5) Nút gửi và một biểu mẫu đăng kí hoàn chỉnh"},{"t":"example","text":"Biểu mẫu nào cũng cần một nút để người dùng bấm gửi. Có hai cách viết: `<input type=\"submit\" value=\"Gửi đăng kí\">` — thẻ tự đóng, chữ trên nút lấy từ `value`; hoặc `<button type=\"submit\">Gửi đăng kí</button>` — cặp thẻ, chữ trên nút nằm giữa hai thẻ nên có thể chèn thêm biểu tượng hay chữ được định dạng. Bấm nút này là trình duyệt gom hết dữ liệu của các ô có `name` rồi gửi tới địa chỉ ghi trong `action`.\n\nDưới đây là trọn vẹn biểu mẫu đăng kí câu lạc bộ Tin học trong câu chuyện đầu bài. Bạn có thể chép đoạn này vào trong `<body>` của một tệp `.html` rồi mở bằng trình duyệt để xem thử ngay:","code":"<form action=\"dangki.php\" method=\"post\">\n  <label for=\"hoten\">Họ và tên:</label>\n  <input type=\"text\" id=\"hoten\" name=\"hoten\" placeholder=\"Ví dụ: Trần Bảo An\" required>\n\n  <label for=\"lop\">Lớp:</label>\n  <select id=\"lop\" name=\"lop\">\n    <option value=\"12A1\">12A1</option>\n    <option value=\"12A2\">12A2</option>\n    <option value=\"12A3\">12A3</option>\n  </select>\n\n  <label for=\"mail\">Thư điện tử:</label>\n  <input type=\"email\" id=\"mail\" name=\"mail\" placeholder=\"ten@example.com\" required>\n\n  <p>Buổi sinh hoạt mong muốn:</p>\n  <input type=\"radio\" id=\"b3\" name=\"buoi\" value=\"thu3\">\n  <label for=\"b3\">Chiều thứ Ba</label>\n  <input type=\"radio\" id=\"b6\" name=\"buoi\" value=\"thu6\">\n  <label for=\"b6\">Chiều thứ Sáu</label>\n\n  <label for=\"lido\">Lí do muốn tham gia:</label>\n  <textarea id=\"lido\" name=\"lido\" rows=\"3\" cols=\"40\"></textarea>\n\n  <input type=\"checkbox\" id=\"dongy\" name=\"dongy\" value=\"co\" required>\n  <label for=\"dongy\">Tôi đồng ý cho câu lạc bộ lưu các thông tin trên.</label>\n\n  <button type=\"submit\">Gửi đăng kí</button>\n</form>","output":"Trình duyệt hiện ra một ô gõ họ tên có chữ mờ gợi ý, một danh sách thả xuống ba lớp, một ô thư điện tử, hai nút tròn loại trừ nhau (vì cùng name là buoi), một khung nhập cao 3 dòng, một ô tích đồng ý và nút Gửi đăng kí; nếu bỏ trống ô họ tên, ô thư điện tử hoặc ô đồng ý rồi bấm gửi, trình duyệt chặn lại và nhắc phải điền vì các ô đó có required."},{"t":"note","text":"Biểu mẫu càng dễ làm thì càng phải cẩn thận về **quyền riêng tư**. Nguyên tắc là chỉ hỏi những thông tin thật sự cần cho mục đích của mình: một biểu mẫu đăng kí câu lạc bộ thì không có lí do gì phải hỏi số căn cước, địa chỉ nhà hay ảnh chụp thẻ học sinh. Ngoài ra, phải nói rõ dữ liệu được dùng vào việc gì và hỏi ý kiến người điền — chẳng hạn bằng một ô `checkbox` xin đồng ý như trong ví dụ trên. Thu thập dữ liệu cá nhân của người khác khi họ chưa đồng ý là hành vi vi phạm quyền riêng tư, chứ không đơn thuần là 'viết thêm vài dòng HTML'."}],"keypoints":["**Biểu mẫu** là phần trang web dùng để nhận dữ liệu người dùng nhập; mọi ô nhập phải nằm trong cặp thẻ `<form>`, với `action` chỉ nơi xử lí dữ liệu và `method` chọn cách gửi (`get` hiện trên thanh địa chỉ, `post` thì không).","`<input>` là **thẻ tự đóng**, kiểu ô nhập do thuộc tính `type` quyết định: `text`, `password`, `number`, `email`, `date`, `checkbox` (chọn nhiều), `radio` (chọn một, các nút cùng nhóm phải trùng `name`).","**`name`** đặt tên cho dữ liệu gửi đi (thiếu `name` là mất dữ liệu), **`value`** đặt giá trị sẵn có, **`placeholder`** chỉ là chữ mờ gợi ý không được gửi, **`required`** bắt buộc phải điền.","`<label>` dùng `for` trùng `id` của ô để bấm nhãn là nhảy vào đúng ô; `<textarea>` cho ô nhiều dòng, `<select>` cùng các `<option>` cho danh sách thả xuống; nút gửi viết bằng `<input type=\"submit\">` hoặc `<button>`, và chỉ nên hỏi những thông tin thật sự cần thiết."],"quiz":["CC-mc-2401","CC-mc-2402","CC-mc-2403","CC-mc-2404","CC-mc-2405","CC-tf-2401","CC-tf-2402","CC-tf-2403","CC-tf-2404","E-mc-27","E-mc-28","E-tf-5","E-tf-1","E-mc-66"]},
    {"id":"C12-10","stage":22,"order":14,"topic":"E","grade":12,"minutes":12,"title":"CSS là gì và cách áp dụng","intro":"Bài này giúp bạn hiểu CSS là gì, vì sao nó tách rời khỏi HTML, và cách viết một quy tắc CSS để đổi màu chữ, cỡ chữ, cách sắp xếp cho một trang web.","sections":[{"t":"story","text":"Hãy tưởng tượng bạn vừa xây xong một ngôi nhà. Tường đã dựng, cột đã đổ, phòng khách, phòng ngủ, nhà bếp đã ngăn vách rõ ràng. Nhưng đó mới chỉ là **nhà thô**: tường trần xi măng, chưa sơn, chưa lát sàn, chưa có món nội thất nào. Ngôi nhà đã dùng được về mặt cấu trúc, nhưng nhìn qua rất khô khan.\n\nCác thẻ HTML mà bạn đã học ở những bài trước — `<h1>`, `<p>`, `<img>` và nhiều thẻ khác — chính là công đoạn “xây thô” đó: dựng lên cấu trúc và nội dung của trang web. Còn việc sơn tường màu gì, chọn phông chữ cho biển hiệu, kê bàn ghế sao cho cân đối — đó là việc của một ngôn ngữ khác, gọi là **CSS**. Điều đáng chú ý: cùng một ngôi nhà, tức cùng một cấu trúc HTML, chỉ cần đổi cách trang trí — đổi CSS — là diện mạo có thể khác hẳn mà không cần xây lại từ đầu."},{"t":"h","text":"CSS lo phần trình bày, HTML lo phần cấu trúc"},{"t":"text","text":"**HTML** (đã học ở các bài trước) có nhiệm vụ tạo ra **cấu trúc và nội dung** của trang: đâu là tiêu đề, đâu là đoạn văn, đâu là hình ảnh, đâu là danh sách. Nhưng bản thân HTML không quyết định tiêu đề đó màu gì, chữ to cỡ nào, các khối nằm cạnh nhau hay xếp chồng lên nhau.\n\n**CSS** (viết tắt của “Cascading Style Sheets”, tạm hiểu là các quy tắc định kiểu có thể xếp chồng lên nhau) là ngôn ngữ đảm nhiệm phần **trình bày**: màu sắc, phông chữ, kích thước, khoảng cách, và cách sắp xếp các khối trên trang, tức bố cục. Cùng một file HTML với nội dung y nguyên, chỉ cần thay đổi CSS là giao diện trang có thể biến đổi hoàn toàn."},{"t":"h","text":"Cú pháp một quy tắc CSS"},{"t":"text","text":"Một quy tắc CSS luôn có dạng chung:\n\n`bộ-chọn { thuộc-tính: giá-trị; }`\n\nTrong đó:\n- **Bộ chọn** (selector) đứng trước dấu ngoặc nhọn, cho biết quy tắc này áp dụng cho thẻ HTML nào.\n- Bên trong cặp **ngoặc nhọn** `{ }` là một hoặc nhiều **khai báo** (declaration), mỗi khai báo có dạng `thuộc-tính: giá-trị;` — thuộc tính nhận giá trị đứng sau dấu hai chấm, kết thúc bằng dấu chấm phẩy.\n\nVí dụ quy tắc `p { color: blue; }` có nghĩa là: với mọi thẻ `<p>`, đặt thuộc tính `color` (màu chữ) bằng giá trị `blue` (xanh dương)."},{"t":"list","text":"CSS cho phép chọn thẻ để áp dụng quy tắc theo ba cách cơ bản:","items":["Theo **tên thẻ**: viết đúng tên thẻ, ví dụ `p` hoặc `h1` — áp dụng cho mọi thẻ cùng loại trên trang.","Theo **lớp** (class): thêm dấu chấm trước tên lớp, ví dụ `.tenlop` — khớp với thẻ có thuộc tính `class='tenlop'`. Một lớp có thể gắn cho nhiều thẻ khác nhau, và một thẻ cũng có thể mang nhiều lớp cùng lúc.","Theo **id**: thêm dấu thăng trước tên id, ví dụ `#tenid` — khớp với thẻ có thuộc tính `id='tenid'`. Mỗi `id` chỉ nên đặt cho đúng một thẻ duy nhất trên cả trang, không dùng lại cho thẻ khác."]},{"t":"example","text":"Dưới đây là một trang HTML nhỏ có gắn `<style>` ngay trong phần `<head>`. Trang này dùng cả ba loại bộ chọn vừa học:\n\n- `h1` (theo tên thẻ) đặt thuộc tính `color` bằng `darkblue`.\n- `p` (theo tên thẻ) đặt thuộc tính `font-size` bằng `18px`, áp dụng cho mọi đoạn văn.\n- `.canh-bao` (theo lớp) chỉ áp dụng cho thẻ mang `class='canh-bao'`, đặt `color` bằng `crimson`.\n- `#ket-luan` (theo id) chỉ áp dụng cho đúng thẻ mang `id='ket-luan'`, đặt riêng cả `color` và `font-size` cho thẻ đó.\n\nHãy đối chiếu từng quy tắc với phần `<body>` bên dưới để thấy quy tắc nào áp dụng cho thẻ nào.","code":"<!DOCTYPE html>\n<html>\n<head>\n  <style>\n    h1 {\n      color: darkblue;\n    }\n    p {\n      font-size: 18px;\n    }\n    .canh-bao {\n      color: crimson;\n    }\n    #ket-luan {\n      color: darkgreen;\n      font-size: 22px;\n    }\n  </style>\n</head>\n<body>\n  <h1>Bảng tin lớp học</h1>\n  <p>Tuần này lớp có bài kiểm tra giữa kì môn Tin học.</p>\n  <p class='canh-bao'>Nhớ mang theo máy tính cầm tay, không mang điện thoại.</p>\n  <p id='ket-luan'>Chúc cả lớp ôn tập tốt.</p>\n</body>\n</html>","output":"Dòng “Bảng tin lớp học” hiện thành tiêu đề lớn, màu xanh dương đậm, theo quy tắc `h1`. Cả ba dòng văn bản bên dưới đều to hơn bình thường, cỡ chữ 18px, theo quy tắc `p`. Riêng dòng “Nhớ mang theo máy tính...” có thêm màu đỏ vì mang lớp `canh-bao`. Dòng cuối “Chúc cả lớp ôn tập tốt.” nổi bật nhất: chữ to 22px và màu xanh lá đậm, vì thẻ này mang `id='ket-luan'` nên cỡ chữ 22px của quy tắc `#ket-luan` thắng cỡ chữ 18px của quy tắc `p`."},{"t":"h","text":"Ba cách gắn CSS vào trang HTML"},{"t":"list","text":"Có ba cách để đưa các quy tắc CSS vào một trang HTML:","items":["**Trực tiếp trong thẻ** (inline): viết CSS ngay trong thuộc tính `style` của thẻ đó, ví dụ `<p style='color: red;'>...</p>`. Chỉ ảnh hưởng đúng thẻ đang chứa nó, ít dùng vì phải lặp lại ở từng thẻ.","**Trong phần `<head>`** (internal): đặt các quy tắc trong cặp thẻ `<style>...</style>` ở phần `<head>` của trang, như ví dụ ở trên. Áp dụng cho toàn bộ trang đó, nhưng chỉ trang đó.","**Từ một file `.css` riêng** (external): viết toàn bộ CSS trong một file riêng, ví dụ `style.css`, rồi liên kết vào trang HTML bằng thẻ `<link rel='stylesheet' href='style.css'>` đặt trong `<head>`. Đây là cách nên dùng nhất: nhiều trang HTML có thể cùng liên kết đến một file CSS, sửa một chỗ là toàn bộ các trang cùng đổi theo, giúp mã nguồn gọn và dễ bảo trì."]},{"t":"note","text":"Khi một thẻ được nhiều quy tắc cùng nhắm tới — chẳng hạn vừa khớp bộ chọn theo tên thẻ, vừa khớp theo lớp, vừa khớp theo id — và các quy tắc đó cùng quy định một thuộc tính, quy tắc theo `id` thường được ưu tiên hơn quy tắc theo lớp, và quy tắc theo lớp lại được ưu tiên hơn quy tắc theo tên thẻ. Đây cũng là lí do phần `font-size` ở ví dụ trên đổi thành 22px khi thẻ mang `id='ket-luan'`, dù quy tắc `p` đã đặt `font-size` là 18px."}],"keypoints":["**HTML** tạo cấu trúc và nội dung của trang; **CSS** lo phần trình bày: màu sắc, phông chữ, kích thước, bố cục.","Một quy tắc CSS có dạng `bộ-chọn { thuộc-tính: giá-trị; }`, các khai báo bên trong dấu ngoặc nhọn kết thúc bằng dấu chấm phẩy.","Ba bộ chọn cơ bản: theo **tên thẻ** (`p`, `h1`...) áp dụng cho mọi thẻ cùng loại; theo **lớp** (`.tenlop`) dùng lại được cho nhiều thẻ; theo **id** (`#tenid`) chỉ dùng cho đúng một thẻ duy nhất.","Có ba cách gắn CSS: trong thuộc tính `style` của thẻ, trong cặp thẻ `<style>` ở `<head>`, hoặc tách ra file `.css` riêng rồi liên kết bằng `<link>` — cách tách riêng được khuyên dùng vì dễ bảo trì và dùng lại cho nhiều trang."],"quiz":["CC-mc-1001","CC-mc-1002","CC-mc-1003","CC-mc-1004","CC-mc-1005","CC-tf-1001","CC-tf-1002","CC-tf-1003","CC-tf-1004","E-mc-30","E-mc-31","E-mc-32","E-tf-8","E-tf-12"]},
    {"id":"C12-11","stage":22,"order":15,"topic":"E","grade":12,"minutes":12,"title":"CSS: màu sắc, phông chữ và mô hình hộp","intro":"Bài học này giới thiệu cách dùng CSS để đổi màu chữ, màu nền và chọn phông chữ cho trang web, đồng thời giải thích mô hình hộp (box model) — nguyên tắc mà trình duyệt dùng để tính khoảng cách quanh mọi phần tử trên trang.","sections":[{"t":"story","text":"Hãy tưởng tượng một phòng triển lãm tranh. Mỗi bức tranh treo trên tường không chỉ là phần hình vẽ ở giữa: sát mép tranh luôn có một khoảng đệm trắng để bức tranh không bị chật chội, bao quanh khoảng đệm đó là một cái khung gỗ hoặc khung kim loại, và xa hơn nữa là khoảng trống trên tường tách khung tranh này ra khỏi khung tranh bên cạnh. Bốn lớp ấy — hình vẽ, khoảng đệm, khung, khoảng cách với tranh khác — cùng nhau quyết định một bức tranh ‘chiếm’ bao nhiêu chỗ trên tường và trông cách biệt hay san sát với những bức tranh xung quanh.\n\nMột phần tử trên trang web cũng được trình duyệt dựng lên đúng theo cách đó. Chữ hoặc hình bên trong đóng vai trò như bức tranh; CSS gọi khoảng đệm quanh nó là `padding`, cái khung là `border`, và khoảng cách với phần tử bên cạnh là `margin`. Trước khi tìm hiểu kĩ bốn lớp này, ta xem qua hai việc đơn giản và quen mắt hơn trước đã: đổi màu và chọn phông chữ."},{"t":"h","text":"Đổi màu chữ, màu nền và chọn phông chữ"},{"t":"text","text":"CSS dùng các **thuộc tính (property)** để chỉnh diện mạo của chữ. Hai thuộc tính về màu thường gặp nhất là `color` — quy định màu của chữ, và `background-color` — quy định màu nền phía sau phần tử.\n\nGiá trị màu có thể viết theo **tên màu** dựng sẵn (ví dụ `red`, `blue`, `white`) hoặc theo **mã màu** dạng `#RRGGBB`, trong đó `RR`, `GG`, `BB` là hai chữ số hệ thập lục phân (hex, chạy từ `00` đến `ff`) lần lượt cho lượng đỏ, lượng xanh lá và lượng xanh dương trộn vào màu đó. Ví dụ `#ff0000` là đỏ thuần vì phần đỏ ở mức cao nhất còn hai phần kia ở mức thấp nhất; `#000000` là đen (cả ba phần đều ở mức thấp nhất); `#ffffff` là trắng (cả ba phần đều ở mức cao nhất). Viết theo mã cho phép chọn chính xác trong hàng triệu sắc độ, còn viết theo tên chỉ có vài chục lựa chọn quen thuộc.\n\nVề chữ, ba thuộc tính hay dùng là `font-family` (họ phông chữ, ví dụ `Arial`, `Georgia`), `font-size` (cỡ chữ, ví dụ `18px` nghĩa là 18 điểm ảnh) và `font-weight` (độ đậm, thường là `normal` hoặc `bold`). Muốn canh chữ sang trái, vào giữa hay sang phải trong phần tử chứa nó, ta dùng `text-align` với giá trị `left`, `center` hoặc `right`."},{"t":"h","text":"Mô hình hộp: bốn lớp bao quanh nội dung"},{"t":"text","text":"Trình duyệt không vẽ một phần tử như một vệt phẳng duy nhất. Nó luôn xem mỗi phần tử là một cái **hộp (box)** gồm bốn lớp lồng vào nhau, tính từ trong ra ngoài.\n\n**Nội dung (content)** là phần chữ hoặc hình bạn thật sự nhìn thấy. Bao quanh nội dung là `padding` — đệm trong, khoảng trống giữa nội dung và viền của hộp; đệm càng lớn thì nội dung càng đỡ bị dồn sát mép. Bao quanh lớp đệm là `border` — viền của hộp, có thể chỉnh độ dày, kiểu nét và màu riêng. Ngoài cùng là `margin` — lề ngoài, khoảng trống nằm bên ngoài viền, dùng để tách hộp này ra khỏi hộp đứng cạnh nó.\n\nBốn lớp này chính là bốn lớp của bức tranh trong khung ở ví dụ mở đầu: nội dung là bức tranh, `padding` là khoảng đệm sát mép tranh, `border` là cái khung, còn `margin` là khoảng cách giữa khung này với khung tranh bên cạnh trên tường. Nắm đúng thứ tự bốn lớp — nội dung, rồi `padding`, rồi `border`, rồi `margin` — giúp bạn căn khoảng cách trên trang đúng ý, thay vì chỉnh số liệu một cách mò mẫm."},{"t":"example","text":"Đoạn mã dưới đây dựng một trang có tiêu đề và một khối chữ được đổi màu, đổi phông, đồng thời áp dụng `padding`, `border`, `margin` để minh hoạ mô hình hộp.","code":"<!DOCTYPE html>\n<html>\n<head>\n<meta charset='UTF-8'>\n<style>\n  body {\n    font-family: Arial;\n  }\n  h1 {\n    color: #1a5276;\n    text-align: center;\n  }\n  .thong-bao {\n    background-color: #d6eaf8;\n    color: #154360;\n    font-size: 18px;\n    font-weight: bold;\n    padding: 20px;\n    border: 3px solid #1a5276;\n    margin: 30px;\n  }\n</style>\n</head>\n<body>\n  <h1>Trang luyen tap CSS</h1>\n  <p class='thong-bao'>Day la khoi van ban duoc trang tri bang CSS, co du padding, border va margin.</p>\n</body>\n</html>","output":"Trang hiển thị nền trắng mặc định của `body`, toàn bộ chữ dùng phông Arial. Dòng tiêu đề ‘Trang luyen tap CSS’ hiện màu xanh lam đậm và canh giữa trang nhờ `text-align: center`. Bên dưới là một khối chữ nền xanh nhạt, chữ màu xanh đậm hơn, cỡ 18px và in đậm; khối này có đệm (`padding`) 20px nên chữ không bị dồn sát mép, có viền (`border`) xanh đậm dày 3px bao quanh phần đệm đó, và có lề ngoài (`margin`) 30px nên toàn bộ khối tách hẳn ra khỏi tiêu đề phía trên cũng như mép các cạnh của trang."},{"t":"list","text":"Tóm lại, bốn lớp của mô hình hộp — xếp đúng theo thứ tự từ trong ra ngoài — là:","items":["**Nội dung (content)** — phần chữ hoặc hình thật sự hiển thị, nằm trong cùng.","`padding` — đệm trong, khoảng trống giữa nội dung và viền.","`border` — viền, đường bao quanh phần đệm, có thể có độ dày và màu riêng.","`margin` — lề ngoài, khoảng trống bên ngoài viền, ngăn cách hộp này với hộp bên cạnh."]},{"t":"note","text":"`padding` và `border` đều làm hộp hiển thị to hơn so với khi chỉ tính riêng phần nội dung, vì cả hai đều nằm bên trong viền ngoài cùng của hộp. Trong khi đó, `margin` không cộng thêm vào bên trong hộp mà chỉ đẩy các hộp lân cận ra xa hộp hiện tại. Vì vậy, khi một khối trông ‘to hơn’ dự kiến, hãy kiểm tra `padding` và `border` trước; còn khi hai khối trông ‘xa nhau hơn’ dự kiến, nguyên nhân thường nằm ở `margin`."}],"keypoints":["`color` chỉnh màu chữ, `background-color` chỉnh màu nền; giá trị màu viết bằng tên dựng sẵn hoặc mã `#RRGGBB` gồm ba cặp số hex cho đỏ, xanh lá, xanh dương.","`font-family`, `font-size`, `font-weight` lần lượt chỉnh họ phông, cỡ chữ và độ đậm của chữ; `text-align` canh chữ trái, giữa hoặc phải.","Mỗi phần tử là một **hộp** gồm bốn lớp lồng nhau tính từ trong ra ngoài: nội dung → `padding` (đệm trong) → `border` (viền) → `margin` (lề ngoài).","Hiểu đúng mô hình hộp giúp bạn căn khoảng cách quanh mỗi phần tử theo đúng ý muốn, thay vì chỉnh số liệu một cách mò mẫm."],"quiz":["CC-mc-1101","CC-mc-1102","CC-mc-1103","CC-mc-1104","CC-mc-1105","CC-tf-1101","CC-tf-1102","CC-tf-1103","CC-tf-1104","E-mc-33","E-tf-6","E-mc-11","E-mc-12","E-mc-34","E-mc-40","E-mc-13","E-tf-2","E-tf-11","E-mc-65"]},
    {"id":"C12-26","stage":22,"order":16,"topic":"E","grade":12,"minutes":11,"title":"CSS: kích thước khung, đường viền và khoảng cách","intro":"Bạn đã biết mỗi phần tử trên trang web là một chiếc khung có nội dung, đệm, viền và lề. Bài học này đi vào những con số cụ thể: đặt bề rộng bằng `width`, vẽ viền bằng `border`, bo tròn góc bằng `border-radius`, viết gọn `padding` và `margin`, và hiểu vì sao một khung khai báo **300 px** lại chiếm chỗ rộng hơn 300 px trên trang.","sections":[{"t":"story","text":"Cuối năm học, lớp 12A5 làm một bảng tin mang tên ‘Góc kỉ niệm’ treo ở cuối lớp. Mỗi bạn được phát một tấm bìa nhỏ để viết lời nhắn, trang trí rồi dán lên bảng. Nghe thì đơn giản, nhưng khi bắt tay vào làm mới lộ ra đủ chuyện rắc rối.\n\nNam cắt tấm bìa của mình đúng 10 xăng-ti-mét mỗi cạnh, theo đúng kích thước cả nhóm đã thống nhất. Nhưng rồi bạn ấy dán thêm một nẹp giấy màu chạy quanh mép cho đẹp, lại chừa một khoảng trắng khá rộng bên trong để chữ không bị sát mép. Lúc mang lên bảng, tấm bìa ấy chiếm chỗ rộng hơn 10 xăng-ti-mét kha khá. Kế hoạch xếp sáu tấm một hàng thế là đổ bể: đến tấm thứ sáu thì thò hẳn ra khỏi bảng.\n\nLan làm theo cách khác. Bạn ấy đo chiều ngang tấm bảng trước, chia thành sáu phần bằng nhau, rồi cắt bìa của mình đúng bằng một phần sáu đó. Sang năm nhà trường có đổi sang bảng to hơn hay nhỏ hơn thì cách chia ấy vẫn đúng, chỉ cần đo lại rồi chia lại là xong.\n\nCòn Minh thì gặp rắc rối kiểu khác: bạn ấy viết quá nhiều chữ, viết đến gần hết tấm bìa vẫn chưa hết ý, chữ cuối cùng lấn cả ra ngoài mép giấy trông rất lôi thôi. Ba tình huống nho nhỏ ấy — khung to hơn dự tính, khung đo theo tỉ lệ, và nội dung tràn ra ngoài khung — chính là ba câu chuyện chúng ta sẽ gặp lại trong bài học hôm nay, chỉ khác là trên màn hình thay vì trên tấm bảng gỗ."},{"t":"h","text":"1) Kích thước khung: width, height và chuyện chọn đơn vị"},{"t":"text","text":"Mỗi phần tử HTML hiển thị ra màn hình như một chiếc khung hình chữ nhật. Nếu ta không nói gì, trình duyệt tự quyết định kích thước: một phần tử khối như `<div>` hay `<p>` sẽ trải hết bề ngang dòng, còn chiều cao thì vừa đủ ôm lấy nội dung bên trong. Muốn tự mình quyết định, ta dùng hai thuộc tính **`width`** (bề rộng) và **`height`** (chiều cao).\n\nĐiều đáng bàn không phải là viết `width` thế nào, mà là viết con số kèm **đơn vị** nào. Đơn vị `px` (pixel, điểm ảnh) là **đơn vị tuyệt đối**: `width: 320px` nghĩa là khung rộng đúng 320 điểm ảnh, dù trang được xem trên màn hình nào cũng vậy. Ngược lại, `%` và `em` là **đơn vị tương đối**: `width: 80%` nghĩa là rộng bằng 80% bề rộng của phần tử cha chứa nó, còn `1em` bằng đúng cỡ chữ đang dùng của chính phần tử đó, nên `width: 20em` sẽ tự nở ra khi cỡ chữ tăng lên.\n\nVì sao nên ưu tiên đơn vị tương đối? Hãy nghĩ đến việc một trang web được xem trên đủ loại màn hình: điện thoại chỉ rộng chừng 360 điểm ảnh, còn màn hình máy tính để bàn có thể rộng gấp bốn lần. Một khung đặt cứng `width: 900px` sẽ đẹp trên máy tính nhưng khi mở bằng điện thoại thì thò hẳn ra ngoài, buộc người đọc phải kéo ngang mới xem hết. Khung đặt `width: 90%` thì luôn vừa vặn, giống hệt cách Lan chia bảng thành sáu phần trong câu chuyện trên. Với `height` thì lời khuyên còn mạnh hơn: hạn chế đặt cứng chiều cao, cứ để nội dung dài bao nhiêu thì khung cao bấy nhiêu, tránh cảnh chữ tràn ra ngoài khung."},{"t":"h","text":"2) Đường viền và bo tròn góc khung"},{"t":"text","text":"Một đường viền được mô tả đầy đủ bằng ba thuộc tính. **`border-width`** cho biết viền dày bao nhiêu, thường viết bằng `px`. **`border-style`** cho biết viền vẽ theo kiểu nét nào: `solid` là nét liền, `dashed` là nét đứt từng gạch dài, `dotted` là nét chấm tròn, còn `none` nghĩa là không vẽ viền. **`border-color`** cho biết viền mang màu gì.\n\nCó một cái bẫy rất hay gặp ở đây: nếu bạn khai báo độ dày và màu nhưng quên mất kiểu nét, trình duyệt vẫn coi kiểu nét là `none` và **không vẽ gì cả**. Nhiều bạn ngồi dò mãi không hiểu vì sao viền không hiện ra, hoá ra chỉ vì thiếu đúng một từ `solid`. Trong ba thuộc tính, `border-style` mới là thuộc tính quyết định viền có xuất hiện hay không.\n\nViết ba dòng cho một đường viền khá dài dòng, nên CSS cho phép **viết gộp** cả ba vào một dòng duy nhất, các giá trị cách nhau bằng dấu cách, chẳng hạn `border: 1px solid #333;`. Ngoài ra, thuộc tính **`border-radius`** giúp bo tròn bốn góc khung: giá trị càng lớn thì góc càng tròn, `border-radius: 0` giữ nguyên góc vuông sắc cạnh, còn với một khung vuông thì `border-radius: 50%` sẽ bo đến mức khung biến thành một hình tròn hoàn chỉnh — mẹo quen thuộc để làm ảnh đại diện tròn."},{"t":"example","text":"Giả sử ta viết CSS cho các thẻ thành viên của câu lạc bộ Tin học trong trang giới thiệu lớp. Mỗi thẻ là một khung có viền và góc bo, bên trong có một ảnh đại diện tròn; riêng khung ghi chú nhắc nhở thì để viền đỏ nét đứt cho nổi bật:","code":".the-thanh-vien {\n  width: 90%;\n  max-width: 320px;\n  border: 2px solid #2d6cdf;\n  border-radius: 12px;\n  background-color: #f4f8ff;\n}\n\n.anh-dai-dien {\n  width: 80px;\n  height: 80px;\n  border: 3px solid #ffffff;\n  border-radius: 50%;\n}\n\n.ghi-chu {\n  border-width: 1px;\n  border-style: dashed;\n  border-color: #d9534f;\n  border-radius: 0;\n}","output":"Thẻ thành viên hiện ra với viền xanh dày 2 px, bốn góc bo tròn nhẹ, phần nội dung rộng 90% khung cha và bị chặn ở mức 320 px (theo cách tính mặc định, hai đường viền còn cộng thêm 4 px nữa vào bề rộng thật); ô ảnh đại diện 80×80 px viền trắng 3 px bị bo thành hình tròn hoàn chỉnh nhờ border-radius: 50%; còn khung ghi chú có viền đỏ nét đứt mảnh và giữ nguyên bốn góc vuông."},{"t":"h","text":"3) Viết gọn padding, margin và canh giữa khối bằng margin: auto"},{"t":"text","text":"Phần đệm bên trong và phần lề bên ngoài đều có bốn phía, nên nếu viết đầy đủ ta sẽ phải khai báo tới bốn dòng riêng cho mỗi loại. May thay, `padding` và `margin` đều có **cách viết gọn**, và quy tắc đọc các giá trị này giống hệt nhau cho cả hai.\n\nKhi viết **một giá trị**, chẳng hạn `padding: 12px;`, cả bốn phía đều được đặt bằng 12 px. Khi viết **hai giá trị**, chẳng hạn `padding: 8px 20px;`, giá trị đầu áp cho **trên và dưới**, giá trị sau áp cho **trái và phải** — cách viết này rất hay dùng cho nút bấm, vì nút thường cần đệm ngang rộng hơn đệm dọc. Khi viết **bốn giá trị**, chẳng hạn `margin: 10px 16px 24px 16px;`, thứ tự chạy theo chiều kim đồng hồ bắt đầu từ đỉnh: **trên – phải – dưới – trái**. Nhớ đúng thứ tự này là tránh được rất nhiều lỗi lệch khoảng cách khó hiểu.\n\nMột kĩ thuật nhỏ nhưng cực kì hữu dụng là **`margin: 0 auto;`**. Giá trị `auto` bảo trình duyệt: hãy tự tính lề trái và lề phải sao cho phần chỗ trống còn thừa được chia đều hai bên. Kết quả là khối nằm chính giữa theo chiều ngang. Có hai điều kiện cần nhớ: khối phải là phần tử khối và phải có `width` nhỏ hơn bề rộng phần tử cha, vì nếu khối đã chiếm trọn bề ngang thì chẳng còn chỗ trống nào để chia. Cũng đừng nhầm `margin: 0 auto` với `text-align: center` — cái trước canh giữa cả chiếc khung, cái sau chỉ canh giữa dòng chữ nằm bên trong khung."},{"t":"h","text":"4) box-sizing: vì sao khung phình to hơn con số bạn đặt"},{"t":"text","text":"Đây chính là rắc rối của Nam trong câu chuyện mở đầu, chuyển sang phiên bản màn hình. Theo cách tính **mặc định** của trình duyệt (tương ứng với `box-sizing: content-box`), giá trị `width` bạn khai báo **chỉ tính riêng vùng nội dung**; phần đệm và đường viền được cộng thêm ra bên ngoài. Nghĩa là chiếc khung thực sự chiếm trên trang luôn rộng hơn con số bạn viết.\n\nHãy tính thử với một khung khai báo `width: 300px; padding: 20px; border: 2px solid #333;`. Bề rộng thật sẽ là 300 cộng 20 bên trái cộng 20 bên phải cộng 2 viền trái cộng 2 viền phải, tổng cộng **344 px** chứ không phải 300 px. Chuyện này gây rắc rối nhất khi ta chia cột: ba cột mỗi cột `width: 33%` cộng lại vừa đúng gần 100%, nhưng chỉ cần thêm một chút `padding` cho dễ nhìn là tổng vượt quá bề ngang phần tử cha, và cột thứ ba bị đẩy xuống dòng dưới.\n\nCách chữa gọn gàng là đặt **`box-sizing: border-box;`**. Khi đó `width` được hiểu là bề rộng **của cả chiếc khung tính cả đệm và viền**; phần nội dung sẽ tự động co lại cho vừa. Với ví dụ trên, khung vẫn rộng đúng 300 px, còn vùng chứa chữ chỉ còn 300 trừ 40 trừ 4, tức 256 px. Vì cách tính này dễ kiểm soát hơn hẳn, người làm web thường đặt ngay từ đầu tệp CSS một quy tắc áp cho mọi phần tử: `* { box-sizing: border-box; }`, rồi từ đó cứ khai báo bề rộng là biết chắc khung sẽ rộng đúng bấy nhiêu."},{"t":"h","text":"5) Nội dung tràn khung và bóng đổ nhẹ cho khung"},{"t":"text","text":"Khi bạn đặt cứng chiều cao cho một khung mà nội dung bên trong lại dài hơn, chuyện của Minh sẽ xảy ra: theo mặc định, phần chữ thừa **tràn hẳn ra ngoài khung**, đè lên nội dung phía dưới và làm trang trông rất lộn xộn. Thuộc tính **`overflow`** sinh ra để bạn nói cho trình duyệt biết phải xử lí phần thừa đó thế nào.\n\nGiá trị `overflow: hidden` cắt bỏ hẳn phần vượt ra ngoài — trang trông gọn nhưng người đọc mất luôn phần nội dung bị cắt, nên chỉ dùng khi phần thừa thật sự không quan trọng. Giá trị `overflow: scroll` luôn chừa sẵn thanh cuộn cho khung, kể cả khi nội dung ngắn và chẳng cần cuộn, đôi khi trông thừa thãi. Giá trị `overflow: auto` thông minh hơn cả: chỉ khi nào nội dung thật sự dài hơn khung thì thanh cuộn mới hiện ra. Vì vậy `auto` thường là lựa chọn hợp lí nhất cho những vùng như bảng điểm dài hay ô bình luận.\n\nCuối cùng, một chi tiết trang trí nhỏ giúp khung trông có chiều sâu: **`box-shadow`** tạo bóng đổ. Cách viết thường gặp gồm bốn phần theo thứ tự — độ dịch ngang, độ dịch dọc, độ nhoè và màu bóng — ví dụ `box-shadow: 0 2px 6px #c9c9c9;` nghĩa là bóng không lệch ngang, đổ xuống dưới 2 px, nhoè trong phạm vi 6 px và mang màu xám nhạt. Kết quả là chiếc khung như hơi nhấc lên khỏi nền trang. Hãy giữ bóng thật nhẹ: bóng quá to và quá đậm sẽ khiến trang rối mắt chứ không sang hơn chút nào."}],"keypoints":["**`width`** và **`height`** đặt kích thước khung; nên ưu tiên **đơn vị tương đối** (`%`, `em`) thay vì `px` để trang co giãn vừa vặn trên mọi cỡ màn hình.","Đường viền gồm **`border-width`**, **`border-style`** và **`border-color`**, viết gộp thành `border: 1px solid #333;`; thiếu `border-style` thì viền không hiện, còn **`border-radius`** bo tròn góc và đủ lớn (`50%`) sẽ biến khung vuông thành hình tròn.","**`padding`** và **`margin`** viết gọn với 1 giá trị (cả bốn phía), 2 giá trị (trên-dưới rồi trái-phải) hoặc 4 giá trị theo thứ tự **trên – phải – dưới – trái**; **`margin: 0 auto`** canh giữa một khối theo chiều ngang.","Mặc định `width` chỉ tính vùng nội dung nên đệm và viền làm khung phình to; đặt **`box-sizing: border-box`** để `width` tính cả đệm và viền, đồng thời dùng **`overflow`** (`hidden`, `auto`, `scroll`) để xử lí nội dung tràn khung."],"quiz":["CC-mc-2601","CC-mc-2602","CC-mc-2603","CC-mc-2604","CC-mc-2605","CC-tf-2601","CC-tf-2602","CC-tf-2603","CC-tf-2604","E-mc-35","E-mc-36","E-tf-7","E-mc-46","E-mc-70"]},
    {"id":"C12-25","stage":22,"order":17,"topic":"E","grade":12,"minutes":13,"title":"Bộ chọn CSS mở rộng và luật ưu tiên khi các quy tắc chồng nhau","intro":"Bạn đã biết viết một quy tắc CSS và ba bộ chọn cơ bản. Nhưng khi trang web lớn dần, sẽ có lúc **nhiều quy tắc cùng nhắm vào một phần tử** và chúng mâu thuẫn nhau. Bài này mở rộng cách viết bộ chọn (bộ chọn nhóm, bộ chọn hậu duệ, `:hover`), giải thích **tính kế thừa** và chỉ rõ **thứ tự ưu tiên** để bạn biết chắc quy tắc nào sẽ thắng.","sections":[{"t":"story","text":"Trường của Minh có một bản nội quy chung dán ở bảng tin ngay cổng: học sinh mặc đồng phục, đi giày, đến trước bảy giờ kém mười lăm. Bản nội quy ấy áp dụng cho tất cả mọi người, từ khối 10 đến khối 12, không trừ ai.\n\nRiêng lớp 12A1 của Minh lại có thêm một tờ quy định nhỏ dán ở cuối lớp, do cô chủ nhiệm và tập thể lớp thống nhất: thứ Tư hằng tuần cả lớp mặc áo đồng phục của lớp thay cho áo trắng. Vậy sáng thứ Tư, bạn Minh nên mặc gì? Cả lớp không ai lúng túng một giây nào: tờ quy định của lớp dành riêng cho lớp mình, nói cụ thể hơn bản nội quy chung, nên nó được nghe theo.\n\nRồi có một trường hợp đặc biệt hơn nữa. Bạn Ngọc bị bong gân cổ chân, cô chủ nhiệm dặn riêng: Ngọc cứ đi dép quai hậu cho đến khi khỏi hẳn. Lời dặn này chỉ dành cho đúng một người, cụ thể hơn cả tờ quy định của lớp, nên với Ngọc thì nó thắng cả hai thứ ở trên.\n\nCuối cùng, giả sử tối thứ Ba cô nhắn vào nhóm lớp: thứ Tư này mặc áo trắng vì sáng mai có đoàn về thăm trường. Lời nhắn mới nhất, ở cùng một cấp với tờ quy định của lớp, sẽ ghi đè lời dặn cũ. Chuyện quần áo tưởng vụn vặt ấy lại mô tả gần như chính xác cách một trang web chọn ra cách hiển thị cuối cùng cho từng phần tử."},{"t":"h","text":"1) Gộp bộ chọn thành nhóm và chọn theo vị trí bên trong"},{"t":"text","text":"Khi nhiều loại phần tử cần chung một kiểu định dạng, viết đi viết lại từng quy tắc rất mất công và dễ sai sót về sau. CSS cho phép dùng **bộ chọn nhóm**: liệt kê nhiều bộ chọn cách nhau bởi **dấu phẩy**, rồi đặt chung một cặp ngoặc nhọn. Chẳng hạn `h1, h2, p { font-family: Arial; }` có nghĩa là mọi tiêu đề cấp 1, mọi tiêu đề cấp 2 và mọi đoạn văn đều dùng phông Arial. Muốn đổi phông cho cả ba loại, bạn chỉ phải sửa đúng một chỗ.\n\nMột kiểu bộ chọn rất hay dùng nữa là **bộ chọn hậu duệ**: hai bộ chọn viết cách nhau bởi **dấu cách**. Ví dụ `div p` chọn mọi đoạn văn `p` nằm bên trong một `div` nào đó, còn những đoạn `p` nằm ngoài `div` thì không bị đụng tới. Hãy để ý sự khác biệt cực kỳ quan trọng: `h1, p` (có dấu phẩy) nghĩa là **cả hai loại**, còn `h1 p` (chỉ có dấu cách) nghĩa là **`p` nằm bên trong `h1`**. Chỉ thừa hay thiếu một dấu phẩy là kết quả đã khác hẳn nhau.\n\nCuối cùng là **bộ chọn phối hợp** giữa tên thẻ và tên lớp, viết **dính liền không có dấu cách**, ví dụ `p.ghichu`. Bộ chọn này chỉ chọn những phần tử thoả mãn đồng thời hai điều kiện: vừa đúng là thẻ `p`, vừa có gắn lớp `ghichu`. Nếu trên trang còn một thẻ `span` cũng mang lớp `ghichu` thì thẻ `span` đó nằm ngoài phạm vi của `p.ghichu`."},{"t":"h","text":"2) Lớp giả trạng thái: :hover và :active"},{"t":"text","text":"Có những định dạng ta không muốn áp dụng lúc nào cũng như lúc nào, mà chỉ muốn xuất hiện trong một **trạng thái** nhất định của phần tử. Để làm việc đó, CSS cung cấp các **lớp giả** (`pseudo-class`) — viết bằng dấu hai chấm ngay sau bộ chọn, không có dấu cách.\n\nQuen thuộc nhất là `:hover`, nghĩa là trạng thái đang có con trỏ chuột rê lên phần tử. Quy tắc `a:hover { color: red; }` được hiểu là: bình thường liên kết giữ nguyên màu cũ, nhưng hễ người dùng đưa chuột lên trên nó thì chữ chuyển sang màu đỏ, rời chuột ra thì trở lại như cũ. Đây là cách đơn giản nhất để trang web phản hồi lại người dùng, giúp họ biết mình đang trỏ vào đúng chỗ nào.\n\nCòn `:active` là trạng thái phần tử **đang bị tác động**, tức là khoảnh khắc người dùng nhấn giữ chuột xuống mà chưa thả ra. Ví dụ `button:active { background-color: #cccccc; }` sẽ khiến nút hơi tối lại đúng lúc bị bấm, tạo cảm giác nút thật sự bị lún xuống. Cả `:hover` lẫn `:active` đều không làm thay đổi nội dung trang, chúng chỉ đổi cách hiển thị trong đúng khoảng thời gian trạng thái đó còn diễn ra."},{"t":"h","text":"3) Tính kế thừa: thuộc tính nào tự truyền xuống phần tử con"},{"t":"text","text":"Trong tài liệu HTML, các phần tử lồng vào nhau tạo thành quan hệ cha – con: một `div` chứa vài `p`, mỗi `p` lại có thể chứa `a` hay `span`. **Tính kế thừa** là hiện tượng một số thuộc tính CSS đặt cho phần tử cha sẽ **tự động truyền xuống** cho các phần tử con bên trong, dù bạn không hề viết quy tắc riêng nào cho chúng.\n\nNhững thuộc tính liên quan đến **chữ viết** thường có tính kế thừa: `color` (màu chữ), `font-family` (họ phông), `font-size` (cỡ chữ), `text-align` (canh lề chữ). Nhờ vậy, chỉ cần đặt `body { color: navy; font-family: Arial; }` một lần là gần như toàn bộ chữ trên trang đã đồng bộ, khỏi phải khai báo cho từng thẻ. Ngược lại, các thuộc tính mô tả **khung bao quanh** phần tử thì **không kế thừa**: `border` (viền), `margin` (lề ngoài), `padding` (đệm trong), `background-color` (màu nền). Điều này rất hợp lí — nếu viền cũng kế thừa thì đặt viền cho một `div` sẽ khiến từng đoạn văn, từng liên kết bên trong đều mọc thêm viền riêng, trang web sẽ rối tinh lên.\n\nMột điểm cần nhớ kỹ: định dạng có được **do kế thừa luôn yếu hơn** một quy tắc viết trực tiếp cho phần tử đó. Nếu `body` đặt `color: navy` mà lại có thêm quy tắc `p { color: gray; }`, thì mọi đoạn văn sẽ hiện màu xám chứ không phải xanh navy, bởi quy tắc nhắm thẳng vào `p` luôn thắng thứ màu chỉ truyền xuống từ phần tử cha."},{"t":"h","text":"4) Thứ tự ưu tiên khi nhiều quy tắc cùng tác động lên một phần tử"},{"t":"text","text":"Bây giờ đến tình huống rắc rối nhất: cùng một phần tử bị nhiều quy tắc nhắm vào, và các quy tắc ấy đặt **cùng một thuộc tính** với những giá trị khác nhau. Trình duyệt không hề bối rối, vì nó có sẵn một **bậc thang ưu tiên** dựa trên nguyên tắc đơn giản: bộ chọn nào nhắm vào phạm vi **hẹp hơn, cụ thể hơn** thì tiếng nói của nó có trọng lượng lớn hơn — hệt như lời cô dặn riêng bạn Ngọc thắng tờ quy định của cả lớp, và tờ quy định của lớp lại thắng bản nội quy chung của trường.\n\nKhi hai quy tắc rơi vào **cùng một mức ưu tiên**, bậc thang không phân xử được nữa. Lúc đó trình duyệt áp dụng luật thứ hai: **quy tắc viết sau ghi đè quy tắc viết trước**. Nếu bạn viết `.canhbao { color: orange; }` rồi bên dưới lại viết `.canhbao { color: purple; }`, kết quả cuối cùng là màu tím, vì nó được đọc sau. Đây chính là lí do nhiều bạn sửa CSS mãi mà không thấy đổi: quy tắc mới bị một quy tắc cũ viết ở phía dưới đè lên mất.\n\nNgoài ra bạn sẽ gặp một thứ đặc biệt là `!important`, viết ngay trước dấu chấm phẩy, ví dụ `color: red !important;`. Khai báo mang nhãn này được đẩy lên trên tất cả các mức của bậc thang, kể cả khai báo trong thuộc tính `style` của thẻ. Nghe thì tiện, nhưng nó **phá vỡ trật tự ưu tiên thông thường**, khiến trang web trở nên khó đoán và rất khó sửa về sau, nên chỉ dùng khi thật sự không còn cách nào khác."},{"t":"list","text":"Bậc thang ưu tiên của các quy tắc CSS, xếp từ mạnh nhất xuống yếu nhất, là:","items":["Khai báo viết thẳng trong thuộc tính `style` của thẻ HTML — mạnh nhất trong các mức thông thường, vì nó gắn vào đúng một thẻ cụ thể ngay tại chỗ; chỉ khai báo có gắn `!important` mới đứng trên được mức này.","Bộ chọn **id** (`#tenid`) — mỗi id chỉ được dùng cho đúng một phần tử trên trang nên phạm vi rất hẹp, thắng cả bộ chọn lớp lẫn bộ chọn thẻ.","Bộ chọn **lớp** (`.tenlop`), kể cả các bộ chọn phối hợp như `p.ghichu` và lớp giả như `:hover` — mạnh hơn bộ chọn theo tên thẻ.","Bộ chọn theo **tên thẻ** (`p`, `h2`, `li`) — phạm vi rộng nhất, ai cũng dính, nên tiếng nói yếu nhất trong nhóm bộ chọn.","Định dạng có được do **kế thừa** từ phần tử cha — yếu nhất, chỉ có tác dụng khi phần tử con không có bất kỳ quy tắc nào nhắm trực tiếp vào thuộc tính đó."]},{"t":"example","text":"Hãy đọc trang web nhỏ dưới đây — bảng phân công trực nhật của một lớp — rồi tự xác định định dạng cuối cùng của từng phần tử trước khi xem phần kết quả:","code":"<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n<style>\n  body { color: navy; font-size: 16px; }\n  h2, p, li { font-family: Arial, sans-serif; }\n  #tieude { color: crimson; }\n  .noibat { color: green; }\n  p { color: gray; }\n  .khung p { border: 1px solid #999999; }\n  p.ghichu { color: orange; font-size: 13px; }\n  a { color: teal; }\n  a:hover { color: red; }\n</style>\n</head>\n<body>\n  <h2 id=\"tieude\" class=\"noibat\">Lịch trực nhật tuần này</h2>\n  <div class=\"khung\">\n    <p>Thứ Hai: tổ 1 lau bảng và quét lớp.</p>\n    <p class=\"ghichu\">Nhắc nhở: tổ trực có mặt trước 10 phút. <a href=\"lich.html\">Xem lịch đầy đủ</a></p>\n  </div>\n  <p class=\"noibat\">Thứ Sáu: cả lớp tổng vệ sinh sân trường.</p>\n  <p class=\"noibat\" style=\"color: brown;\">Thứ Bảy: nghỉ, không phải trực.</p>\n</body>\n</html>","output":"Tiêu đề hiện màu đỏ thẫm chứ không phải xanh lá, vì bộ chọn id #tieude thắng bộ chọn lớp .noibat; hai đoạn nằm trong div.khung đều có viền xám bao quanh nhờ bộ chọn hậu duệ .khung p, trong đó đoạn thứ nhất màu xám (quy tắc p thắng màu navy kế thừa từ body) còn đoạn ghi chú màu cam cỡ 13px vì p.ghichu mạnh hơn p; đoạn Thứ Sáu màu xanh lá do bộ chọn lớp thắng bộ chọn thẻ, đoạn Thứ Bảy màu nâu vì khai báo trong thuộc tính style đứng trên tất cả; hai đoạn cuối không có viền vì nằm ngoài div.khung; rê chuột lên liên kết thì chữ đổi từ xanh mòng két sang đỏ."},{"t":"note","text":"Ba cái bẫy hay gặp nhất khi làm bài. Thứ nhất, nhầm dấu phẩy với dấu cách: `ul, li` là hai loại phần tử độc lập, còn `ul li` là những `li` nằm bên trong `ul` — đọc nhanh rất dễ lẫn. Thứ hai, tưởng rằng quy tắc viết sau thì luôn thắng: điều đó **chỉ đúng khi hai quy tắc cùng mức ưu tiên**; nếu quy tắc viết trước dùng bộ chọn id còn quy tắc viết sau chỉ dùng tên thẻ thì id vẫn thắng, dù nằm ở tận đầu tệp CSS. Thứ ba, quên rằng `!important` đứng trên cả khai báo trong thuộc tính `style` — nên câu hỏi có `!important` thì phải xét nó trước tiên, đừng vội trả lời theo bậc thang quen thuộc."}],"keypoints":["**Bộ chọn nhóm** dùng dấu phẩy để áp một khai báo cho nhiều loại phần tử; **bộ chọn hậu duệ** dùng dấu cách (`div p`) để chọn phần tử nằm bên trong phần tử khác; **bộ chọn phối hợp** viết liền (`p.ghichu`) chỉ chọn phần tử vừa đúng thẻ vừa đúng lớp.","**Lớp giả trạng thái** như `:hover` (chuột rê lên) và `:active` (đang bị nhấn giữ) chỉ đổi cách hiển thị trong đúng trạng thái đó, không làm thay đổi nội dung trang.","**Tính kế thừa** truyền các thuộc tính về chữ (`color`, `font-family`, `font-size`) từ phần tử cha xuống con, nhưng **không truyền** các thuộc tính về khung (`border`, `margin`, `padding`, `background-color`).","**Thứ tự ưu tiên** từ mạnh xuống yếu: khai báo trong thuộc tính `style` > bộ chọn id > bộ chọn lớp > bộ chọn tên thẻ > định dạng kế thừa; khi **cùng mức ưu tiên** thì quy tắc **viết sau thắng**, còn `!important` đứng trên tất cả nên cần rất thận trọng."],"quiz":["CC-mc-2501","CC-mc-2502","CC-mc-2503","CC-mc-2504","CC-mc-2505","CC-tf-2501","CC-tf-2502","CC-tf-2503","CC-tf-2504","E-mc-37","E-mc-38","E-mc-39","E-mc-43","E-mc-45","E-tf-10","E-mc-68"]},
    {"id":"C12-12","stage":22,"order":18,"topic":"E","grade":12,"minutes":12,"title":"CSS: bố cục trang cơ bản","intro":"Bài học này giới thiệu hai kiểu cư xử cơ bản của một phần tử HTML — khối và nội tuyến — cùng thuộc tính `display`, từ đó chỉ ra cách xếp nhiều khối cạnh nhau bằng `display: flex` và cách chia một trang web thành các vùng lớn bằng những thẻ `<div>` đơn giản.","sections":[{"t":"story","text":"Hãy tưởng tượng bạn vừa dọn vào một căn phòng còn trống và cần sắp xếp đồ đạc: một chiếc giường, một kệ sách, một bàn làm việc cùng chiếc ghế. Có những món bạn để chiếm trọn một bức tường — chiếc giường kê sát tường, chẳng có gì đứng chung hàng với nó, cả khoảng tường đó coi như dành riêng cho nó. Nhưng có những món nhỏ hơn, bạn lại muốn đặt cạnh nhau thành một hàng ngang — chẳng hạn bàn làm việc và chiếc ghế kê sát nhau để tiện với tay, hoặc vài chiếc ghế xếp thành một dãy dọc theo bức tường đối diện.\n\nMột trang web cũng được dựng lên theo cách tương tự. Có phần tử luôn tự chiếm trọn cả một dòng, có phần tử chỉ nằm gọn trong dòng chữ, và nhiều lúc ta muốn vài khối đứng cạnh nhau thành một hàng thay vì xếp chồng lên nhau từ trên xuống dưới. Bài này sẽ chỉ ra cách trình duyệt tự quyết định cách cư xử đó, và cách bạn chủ động sắp đặt các khối trên trang theo đúng ý mình."},{"t":"h","text":"Phần tử khối (block) và phần tử nội tuyến (inline)"},{"t":"text","text":"Mỗi thẻ HTML khi trình duyệt hiển thị đều cư xử theo một trong hai kiểu cơ bản. **Phần tử khối** (tiếng Anh gọi là `block`) luôn chiếm trọn cả chiều ngang đang có — giống chiếc giường chiếm cả bức tường: dù nội dung bên trong ngắn hay dài, nó vẫn đẩy phần tử đứng ngay sau nó xuống dòng mới. Các thẻ quen thuộc như `<div>`, `<p>`, `<h1>`, `<ul>`, `<li>` đều mặc định là phần tử khối.\n\nNgược lại, **phần tử nội tuyến** (`inline`) chỉ chiếm đúng khoảng không gian mà nội dung của nó cần, và nằm lọt vào giữa dòng chữ xung quanh chứ không tự xuống dòng — giống như một vật nhỏ đặt gọn trên giường mà không choán thêm chỗ nào khác. Các thẻ như `<a>`, `<span>`, `<strong>`, `<em>` mặc định là phần tử nội tuyến; nhờ vậy một liên kết `<a>` có thể nằm ngay giữa câu văn mà không làm gãy dòng chữ."},{"t":"h","text":"Thuộc tính `display`"},{"t":"text","text":"Việc một phần tử cư xử theo kiểu khối hay nội tuyến không phải là quy tắc bất biến — nó do thuộc tính CSS tên là `display` quyết định, và ta hoàn toàn có thể thay đổi. Gán `display: inline` cho một `<div>` sẽ khiến nó chỉ chiếm vừa đủ nội dung như một phần tử nội tuyến; ngược lại gán `display: block` cho một `<span>` sẽ khiến nó chiếm trọn cả dòng như một khối thật sự. Còn `display: none` sẽ ẩn hẳn phần tử đi, xem như nó không tồn tại trên trang.\n\nCó một giá trị khác của `display` rất hữu ích khi cần xếp nhiều phần tử cạnh nhau: `display: flex`. Phần này ta sẽ tìm hiểu kĩ ngay sau đây."},{"t":"h","text":"Xếp các khối cạnh nhau bằng `display: flex`"},{"t":"text","text":"Khi bạn gán `display: flex` cho một phần tử — gọi là **khối cha** — mọi phần tử con nằm trực tiếp bên trong nó sẽ tự động xếp thành một hàng ngang, đứng cạnh nhau, thay vì mỗi đứa chiếm một dòng riêng như mặc định. Bạn không cần khai báo gì thêm cho từng phần tử con — chỉ cần đặt `display: flex` cho phần tử cha là đủ.\n\nKhi khối cha đã là `display: flex`, có hai thuộc tính thường dùng thêm để sắp xếp cho gọn gàng: `justify-content` quyết định cả hàng khối con dồn về đâu (đầu hàng, giữa hàng, cuối hàng, hoặc dàn đều ra hai bên), còn `gap` tạo một khoảng cách đều đặn giữa các khối con, giúp chúng không dính sát vào nhau."},{"t":"example","text":"Đoạn mã dưới đây tạo ba khối nội dung — ‘Trang chu’, ‘Bai hoc’, ‘Lien he’ — và xếp chúng cạnh nhau thành một hàng ngang, canh giữa trang, cách đều nhau:","code":"<!DOCTYPE html>\n<html>\n<head>\n<meta charset='UTF-8'>\n<style>\n  .hang {\n    display: flex;\n    justify-content: center;\n    gap: 20px;\n  }\n  .khoi {\n    padding: 16px;\n    border: 1px solid #333;\n  }\n</style>\n</head>\n<body>\n  <div class='hang'>\n    <div class='khoi'>Trang chu</div>\n    <div class='khoi'>Bai hoc</div>\n    <div class='khoi'>Lien he</div>\n  </div>\n</body>\n</html>","output":"Ba khối ‘Trang chu’, ‘Bai hoc’, ‘Lien he’ hiển thị cạnh nhau trên cùng một hàng ngang, mỗi khối có viền mỏng bao quanh và một khoảng đệm bên trong; cả hàng được canh giữa theo chiều ngang của trang nhờ `justify-content: center`, và giữa các khối có một khoảng trống đều nhau 20px nhờ `gap`.\n\nNếu bỏ `display: flex` ở `.hang`, ba khối này sẽ tự động xếp chồng lên nhau thành ba dòng riêng biệt, vì `<div>` vốn là phần tử khối."},{"t":"h","text":"Chia trang thành các vùng bằng `<div>`"},{"t":"list","text":"Một trang web đơn giản thường được chia thành ba vùng lớn, mỗi vùng là một `<div>` riêng để dễ định dạng và quản lý:","items":["Đầu trang (ví dụ đặt lớp `header`): chứa tên trang hoặc logo, và menu điều hướng — các mục menu có thể xếp cạnh nhau bằng `display: flex` như ví dụ ở trên.","Phần nội dung chính (ví dụ đặt lớp `noidung`): chứa bài viết, hình ảnh, hay nội dung chính mà người xem quan tâm nhất — thường chiếm phần lớn diện tích trang.","Chân trang (ví dụ đặt lớp `footer`): đặt ở cuối trang, chứa thông tin liên hệ, bản quyền, hoặc các liên kết phụ."]},{"t":"note","text":"Mặc định, mỗi `<div>` là một phần tử khối nên tự xếp chồng lên nhau theo đúng thứ tự khai báo trong HTML — vùng đầu trang ở trên cùng, tiếp đến nội dung, rồi chân trang ở dưới cùng, mà không cần làm gì thêm. Chỉ khi nào muốn nhiều khối con đứng cạnh nhau thành hàng ngang bên trong một vùng — như dãy mục menu trong đầu trang — bạn mới cần khai báo `display: flex` cho phần tử cha bao quanh chúng."}],"keypoints":["**Phần tử khối** (`block`) chiếm trọn cả dòng và luôn đẩy phần tử phía sau xuống dòng mới (`<div>`, `<p>`, `<h1>`,…); **phần tử nội tuyến** (`inline`) chỉ chiếm đúng phần nội dung và nằm lọt trong dòng chữ (`<a>`, `<span>`,…).","Thuộc tính `display` quyết định kiểu hiển thị của một phần tử và có thể thay đổi bằng CSS, với các giá trị thường gặp: `block`, `inline`, `flex`, `none`.","Đặt `display: flex` cho phần tử cha khiến các phần tử con trực tiếp tự động xếp thành một hàng ngang; `justify-content` căn vị trí cả hàng, còn `gap` tạo khoảng cách đều giữa các khối.","Có thể chia một trang web thành các vùng (đầu trang, nội dung, chân trang) bằng nhiều `<div>` riêng biệt, mỗi vùng tự định dạng độc lập."],"quiz":["CC-mc-1201","CC-mc-1202","CC-mc-1203","CC-mc-1204","CC-mc-1205","CC-tf-1201","CC-tf-1202","CC-tf-1203","CC-tf-1204","CC-mc-1891","CC-mc-1892","CC-mc-1893","CC-tf-1891"]},
    {"id":"C12-13","stage":22,"order":19,"topic":"E","grade":12,"minutes":12,"title":"Thực hành: xây dựng một trang web nhỏ","intro":"Bài này ta sẽ gộp những gì đã học về HTML và CSS thành một sản phẩm hoàn chỉnh: một trang web nhỏ giới thiệu bản thân, đi từ việc phác thảo ý tưởng đến khi xem được kết quả trên trình duyệt.","sections":[{"t":"story","text":"Hãy hình dung bạn vừa học xong cách xây từng viên gạch (các thẻ HTML như `<h1>`, `<p>`, `<img>`, `<ul>`) và cách sơn phết, trang trí (CSS với màu sắc, phông chữ, khoảng cách). Nhưng một đống gạch rời cùng vài hộp sơn thì chưa phải là một căn nhà. Muốn ở được, ta phải lắp gạch theo đúng thứ tự — nền trước, tường sau, mái trên cùng — rồi mới sơn hoàn thiện. Xây một trang web cũng vậy: cần đi theo từng bước rõ ràng, từ việc nghĩ trước xem trang có những gì, đến việc dựng khung, rồi mới tô màu và chỉnh sửa lại cho vừa ý. Bài thực hành này sẽ dẫn bạn đi hết các bước đó, để tự tay dựng nên một trang web nhỏ — trang giới thiệu về bản thân hoặc một sản phẩm mà bạn thích."},{"t":"h","text":"Bước 1 — Phác thảo nội dung trước khi viết code"},{"t":"text","text":"Sai lầm thường gặp khi mới học là mở trình soạn thảo code lên và gõ ngay, vừa gõ vừa nghĩ xem nên viết gì tiếp theo. Cách làm hiệu quả hơn nhiều là dành vài phút **phác thảo** trước, trên giấy hoặc chỉ trong đầu, trước khi chạm vào bàn phím.\n\nHãy tự hỏi: trang này nói về điều gì? Cần những phần nào? Phần nào lên trước, phần nào xuống sau? Giả sử bạn muốn làm một trang giới thiệu bản thân, có thể phác thảo nhanh: trên cùng là tên và một tiêu đề ngắn; tiếp theo là đoạn văn kể về bản thân; sau đó là danh sách sở thích hoặc kĩ năng; cuối cùng là vài dòng thông tin liên hệ. Phác thảo xong, việc viết HTML chỉ còn là ‘dịch’ từng phần đó sang thẻ tương ứng — nhanh và ít sai sót hơn hẳn so với vừa gõ vừa nghĩ."},{"t":"h","text":"Bước 2 và 3 — Dựng khung HTML rồi thêm CSS"},{"t":"text","text":"Có phác thảo trong tay, bạn bắt đầu viết **khung HTML**: mỗi phần trong phác thảo trở thành một thẻ hoặc một nhóm thẻ. Tên và tiêu đề dùng `<h1>`, đoạn giới thiệu dùng `<p>`, ảnh đại diện (nếu có) dùng `<img>`, danh sách sở thích hay kĩ năng dùng `<ul>` cùng các `<li>` bên trong. Ở giai đoạn này trang còn rất ‘mộc’ — chỉ có chữ đen trên nền trắng, chưa có màu sắc hay bố cục gì cả. Điều đó bình thường: **HTML** lo phần ‘có những gì’, còn **CSS** mới lo phần ‘trông ra sao’.\n\nBước tiếp theo là thêm CSS để trang dễ nhìn, dễ đọc hơn. Ba việc CSS hay đảm nhận nhất trong một trang nhỏ là: chọn **màu** (nền, chữ, đường viền) sao cho tương phản rõ và dễ chịu cho mắt; chọn **phông chữ** và cỡ chữ giúp văn bản dễ đọc; và sắp xếp **khoảng cách**, canh lề giữa các phần để trang không bị dồn cục vào nhau. Với một trang chỉ có một tệp, cách gọn nhất là viết CSS ngay trong thẻ `<style>` đặt ở phần `<head>`."},{"t":"list","text":"Một trang giới thiệu bản thân đơn giản thường chia thành các phần sau:","items":["**Phần đầu trang**: tên hoặc tiêu đề của trang, thường nổi bật nhất","**Phần giới thiệu**: một hoặc vài đoạn văn kể về bản thân (hoặc về sản phẩm)","**Phần danh sách**: liệt kê sở thích, kĩ năng hoặc thông tin nổi bật","**Chân trang**: thông tin liên hệ hoặc một dòng ghi chú nhỏ ở cuối trang"]},{"t":"example","text":"Dưới đây là một trang giới thiệu bản thân hoàn chỉnh, gộp đủ các phần vừa phác thảo. Bạn có thể lưu đoạn này thành một tệp đuôi `.html` rồi mở bằng trình duyệt để xem thử ngay:","code":"<!DOCTYPE html>\n<html lang='vi'>\n<head>\n<meta charset='UTF-8'>\n<title>Trang giới thiệu</title>\n<style>\n  body {\n    font-family: Arial, sans-serif;\n    background-color: #f4f4f4;\n    color: #333;\n    margin: 0;\n    padding: 0;\n  }\n  header {\n    background-color: #2c3e50;\n    color: white;\n    text-align: center;\n    padding: 20px;\n  }\n  main {\n    max-width: 600px;\n    margin: 20px auto;\n    background-color: white;\n    padding: 20px;\n    border-radius: 8px;\n  }\n  h2 {\n    color: #2c3e50;\n  }\n  ul {\n    line-height: 1.6;\n  }\n  footer {\n    text-align: center;\n    padding: 10px;\n    color: #777;\n    font-size: 14px;\n  }\n</style>\n</head>\n<body>\n  <header>\n    <h1>Nguyễn Văn A</h1>\n  </header>\n  <main>\n    <h2>Giới thiệu</h2>\n    <p>Mình là học sinh lớp 12, thích tìm hiểu về máy tính và lập trình. Đây là trang web nhỏ mình tự tay xây dựng để luyện tập HTML và CSS.</p>\n    <h2>Sở thích và kĩ năng</h2>\n    <ul>\n      <li>Lập trình Python cơ bản</li>\n      <li>Thiết kế trang web đơn giản</li>\n      <li>Đọc sách khoa học</li>\n    </ul>\n  </main>\n  <footer>\n    <p>Liên hệ: vidu@email.com</p>\n  </footer>\n</body>\n</html>","output":"Trang hiện dải màu xanh đậm ở đầu, bên trong là tên ‘Nguyễn Văn A’ bằng chữ trắng, canh giữa. Bên dưới là một khối nền trắng, bo góc, nằm giữa trang: trước tiên là đoạn giới thiệu bản thân, sau đó là danh sách ba gạch đầu dòng nêu sở thích và kĩ năng. Cuối trang là một dòng chữ nhỏ màu xám ghi thông tin liên hệ, cũng canh giữa."},{"t":"text","text":"Nhìn lại đoạn mã trên, các phần khớp với phác thảo ban đầu như sau. Trong `<head>`, thẻ `<style>` gom toàn bộ CSS của trang: quy tắc cho `body` đặt phông chữ và màu nền chung cho cả trang; quy tắc cho `header` tạo dải màu đậm ở đầu trang kèm chữ trắng nổi bật; quy tắc cho `main` giới hạn chiều rộng nội dung bằng `max-width` rồi canh nó vào giữa trang bằng `margin: 20px auto` — cách canh giữa quen thuộc cho một khối nội dung.\n\nTrong `<body>`, thẻ `<header>` chứa `<h1>` là tên hiển thị nổi bật ở đầu trang — đúng phần ‘đầu trang’ đã phác thảo. Thẻ `<main>` chứa phần nội dung chính: đoạn `<p>` giới thiệu bản thân, rồi danh sách `<ul>`/`<li>` liệt kê sở thích, kĩ năng — đúng hai phần ‘giới thiệu’ và ‘danh sách’. Cuối cùng, thẻ `<footer>` đóng vai trò chân trang, chỉ cần một dòng thông tin liên hệ ngắn gọn. Tất cả nội dung và màu sắc nằm gọn trong một tệp `.html` duy nhất."},{"t":"note","text":"Khi tự làm trang của mình, đừng cố nhồi quá nhiều màu, phông chữ hay hiệu ứng. Một trang **đơn giản, gọn gàng, dễ đọc** — ít màu chủ đạo (chừng 2–3 màu là đủ), chữ đủ lớn để đọc thoải mái, khoảng cách hợp lý giữa các phần — luôn dễ nhìn hơn một trang rối mắt. Sau khi viết xong, hãy mở tệp bằng trình duyệt để xem thử, rồi quay lại chỉnh sửa: thấy chỗ nào chưa ưng thì sửa ngay, không cần đúng hoàn hảo ngay từ lần đầu."}],"keypoints":["Trước khi viết code, nên **phác thảo nội dung**: trang cần những phần nào, phần nào trước, phần nào sau.","**HTML** dựng khung nội dung bằng các thẻ như `<h1>`, `<p>`, `<ul>`; **CSS** quyết định màu sắc, phông chữ, khoảng cách và bố cục.","Một trang giới thiệu bản thân thường được tổ chức thành **bốn phần**: đầu trang, giới thiệu, danh sách sở thích/kĩ năng và chân trang.","Nên xem thử trang trên trình duyệt sau khi viết rồi chỉnh sửa dần; ưu tiên sự **đơn giản, gọn gàng, dễ đọc** hơn là nhồi nhét nhiều chi tiết."],"quiz":["CC-mc-1301","CC-mc-1302","CC-mc-1303","CC-mc-1304","CC-mc-1305","CC-tf-1301","CC-tf-1302","CC-tf-1303","CC-tf-1304","E-mc-32","E-mc-30","E-mc-50","E-mc-51"]},
    {"id":"C12-14","stage":22,"order":20,"topic":"E","grade":12,"minutes":12,"title":"Hướng nghiệp trong ngành công nghệ thông tin","intro":"Học xong phần Tin học ở phổ thông, phía trước có rất nhiều hướng đi khác nhau trong ngành công nghệ thông tin. Bài học này giúp bạn hình dung bức tranh chung của ngành, các nhóm nghề phổ biến, những kĩ năng cần chuẩn bị và một lộ trình gợi ý để từng bước tiến vào ngành này.","sections":[{"t":"story","text":"Hãy hình dung nền tảng tin học mà bạn học ở phổ thông giống như một quảng trường trung tâm, nơi có rất nhiều con đường toả ra các hướng khác nhau. Một con đường dẫn tới nơi người ta xây dựng phần mềm, trang web, ứng dụng di động. Một con đường khác dẫn tới nơi người ta khai thác những kho dữ liệu khổng lồ để tìm ra quy luật ẩn bên trong. Có con đường dẫn tới nơi người ta huấn luyện máy tính ‘học’ để tự đưa ra dự đoán, và có con đường dẫn tới nơi người ta ngày đêm canh giữ hệ thống trước những cuộc tấn công mạng.\n\nTất cả những con đường đó đều xuất phát từ cùng một quảng trường — những kiến thức nền tảng về máy tính, dữ liệu và thuật toán mà bạn đã và đang học. Vấn đề không phải là con đường nào ‘tốt nhất’, vì mỗi con đường phù hợp với một kiểu người khác nhau. Muốn chọn đúng đường cho mình, trước tiên bạn cần biết tấm bản đồ đó có những đường nào."},{"t":"h","text":"Một ngành đang lớn nhanh từng ngày"},{"t":"text","text":"Công nghệ thông tin (thường gọi tắt là CNTT) không còn là một lĩnh vực tách biệt, chỉ dành riêng cho những người ‘giỏi máy tính’. Ngày nay, hầu như lĩnh vực nào cũng cần đến công nghệ: bệnh viện dùng phần mềm quản lí hồ sơ bệnh nhân, cửa hàng dùng ứng dụng bán hàng trực tuyến, ngân hàng dùng hệ thống xử lí giao dịch, và ngay cả nông nghiệp cũng bắt đầu dùng cảm biến, dữ liệu để theo dõi mùa vụ.\n\nChính vì công nghệ len lỏi vào hầu hết các ngóc ngách của đời sống, nhu cầu tuyển dụng nhân lực công nghệ thông tin luôn ở mức cao và có xu hướng tiếp tục tăng trong nhiều năm tới. Đây cũng là lí do ngành này có rất nhiều **nhóm nghề** khác nhau, mỗi nhóm phù hợp với một kiểu sở thích và thế mạnh riêng — không phải ai làm công nghệ thông tin cũng ngồi viết mã suốt ngày như nhiều người vẫn hình dung."},{"t":"h","text":"Các nhóm nghề nổi bật trong công nghệ thông tin"},{"t":"list","text":"Dưới đây là một số nhóm nghề đang phổ biến và có xu hướng phát triển mạnh:","items":["**Phát triển phần mềm, web và ứng dụng**: viết chương trình, xây dựng trang web, ứng dụng di động mà mọi người dùng hằng ngày, thường dùng các ngôn ngữ lập trình như `Python`, `Java` hay `JavaScript`.","**Khoa học và phân tích dữ liệu**: thu thập, xử lí và tìm quy luật ẩn trong những khối dữ liệu lớn, giúp tổ chức ra quyết định dựa trên số liệu thay vì phỏng đoán.","**Trí tuệ nhân tạo và học máy**: xây dựng hệ thống có khả năng ‘học’ từ dữ liệu để nhận diện hình ảnh, hiểu ngôn ngữ hoặc đưa ra dự đoán, gợi ý — nền tảng của nhiều sản phẩm công nghệ mới.","**An ninh mạng**: bảo vệ hệ thống, dữ liệu và người dùng khỏi các cuộc tấn công hay rò rỉ thông tin; chủ động tìm và vá lỗ hổng bảo mật trước khi bị kẻ xấu khai thác.","**Quản trị hệ thống và điện toán đám mây**: vận hành, giám sát máy chủ và hạ tầng công nghệ (thường gọi là `Cloud`) để các dịch vụ như web, ứng dụng, cơ sở dữ liệu luôn chạy ổn định."]},{"t":"example","text":"Để thấy rõ sự khác nhau giữa các nhóm nghề, hãy hình dung một cửa hàng trực tuyến đang gặp sự cố: trang chủ tải rất chậm, đồng thời có dấu hiệu ai đó đang cố truy cập trái phép vào hệ thống. Mỗi nhóm nghề sẽ đảm nhận một phần khác nhau của vấn đề:","code":"Phát triển phần mềm/web -> kiểm tra lại mã nguồn trang web, tìm đoạn xử lí chậm\nQuản trị hệ thống/đám mây -> kiểm tra máy chủ, xem tài nguyên (bộ nhớ, băng thông) có quá tải không\nAn ninh mạng -> rà soát nhật kí truy cập, xác định dấu hiệu tấn công\nKhoa học dữ liệu -> xem lại số liệu lượt truy cập, tìm thời điểm bất thường","output":"Bốn phần việc trên khác nhau hoàn toàn, nhưng đều bắt nguồn từ nền tảng công nghệ thông tin và phối hợp chặt chẽ với nhau để giải quyết cùng một sự cố. Đây cũng là lí do vì sao một dự án công nghệ thực tế hiếm khi chỉ cần một nhóm nghề duy nhất."},{"t":"h","text":"Kĩ năng cần chuẩn bị cho tương lai"},{"t":"list","text":"Dù chọn nhóm nghề nào, một số kĩ năng sau gần như luôn cần thiết:","items":["**Tư duy giải quyết vấn đề**: khả năng chia một vấn đề lớn, phức tạp thành những phần nhỏ hơn, dễ xử lí hơn — nền tảng của gần như mọi công việc trong ngành.","**Tự học suốt đời**: công nghệ thay đổi rất nhanh, công cụ và kiến thức học hôm nay có thể lạc hậu chỉ sau vài năm, nên khả năng tự tìm hiểu cái mới quan trọng hơn cả việc thuộc lòng kiến thức cũ.","**Ngoại ngữ** (đặc biệt là tiếng Anh): phần lớn tài liệu kĩ thuật, diễn đàn trao đổi và công cụ mới thường xuất hiện bằng tiếng Anh trước tiên.","**Làm việc nhóm**: hầu hết sản phẩm công nghệ do nhiều người cùng xây dựng, mỗi người phụ trách một phần, nên khả năng phối hợp và trao đổi rõ ràng với người khác rất quan trọng.","**Đạo đức nghề nghiệp**: người làm công nghệ thường được tiếp cận dữ liệu và hệ thống quan trọng, nên cần có trách nhiệm, trung thực và tôn trọng quyền riêng tư của người dùng."]},{"t":"h","text":"Lộ trình định hướng nghề nghiệp"},{"t":"list","text":"Để từng bước tiến vào ngành công nghệ thông tin, bạn có thể hình dung một lộ trình gồm bốn bước:","items":["**Chọn hướng theo sở thích và thế mạnh**: thử tìm hiểu xem bản thân hứng thú với việc xây dựng sản phẩm, phân tích số liệu hay bảo vệ hệ thống — không cần chọn đúng ngay từ đầu.","**Học tiếp lên đại học, cao đẳng hoặc các khoá học chuyên sâu**: đây là nơi bạn được trang bị kiến thức nền tảng bài bản, có hệ thống hơn so với tự học rời rạc.","**Làm dự án thực tế**: áp dụng kiến thức đã học vào những sản phẩm cụ thể, dù nhỏ, để tích luỹ kinh nghiệm và có thứ để giới thiệu với nhà tuyển dụng sau này.","**Lấy chứng chỉ chuyên môn**: các chứng chỉ về lập trình, `Cloud` hay an ninh mạng giúp xác nhận năng lực của bạn, đặc biệt khi mới bắt đầu và chưa có nhiều kinh nghiệm làm việc thực tế."]},{"t":"note","text":"Không có một lộ trình ‘chuẩn’ áp dụng cho tất cả mọi người. Hai người cùng học tin học ở phổ thông hoàn toàn có thể đi theo hai hướng khác nhau, và cả hai đều đúng nếu hướng đó phù hợp với sở thích, thế mạnh của họ. Vì ngành công nghệ thông tin thay đổi rất nhanh, điều quan trọng nhất không phải là ghi nhớ chính xác mọi kĩ thuật hiện tại, mà là hiểu bản thân và duy trì thói quen tự học lâu dài."}],"keypoints":["Ngành công nghệ thông tin rất rộng và đang phát triển mạnh, hiện diện trong hầu hết các lĩnh vực của đời sống chứ không chỉ dừng ở việc viết phần mềm.","Có nhiều **nhóm nghề** khác nhau trong ngành, tiêu biểu là **phát triển phần mềm/web/ứng dụng**, **khoa học và phân tích dữ liệu**, **trí tuệ nhân tạo/học máy**, **an ninh mạng** và **quản trị hệ thống/đám mây**.","Bên cạnh kiến thức chuyên môn, các kĩ năng như **tư duy giải quyết vấn đề**, **tự học suốt đời**, ngoại ngữ, làm việc nhóm và đạo đức nghề nghiệp đều rất cần thiết cho tương lai.","Lộ trình định hướng nghề nghiệp gợi ý gồm bốn bước: chọn hướng theo sở thích/thế mạnh, học tiếp lên cao hơn, làm dự án thực tế và lấy chứng chỉ chuyên môn."],"quiz":["CC-mc-1401","CC-mc-1402","CC-mc-1403","CC-mc-1404","CC-mc-1405","CC-tf-1401","CC-tf-1402","CC-tf-1403","CC-tf-1404","E-mc-41","E-mc-54","E-mc-55","E-mc-56","E-mc-42","E-mc-57","E-mc-58","E-mc-59","E-mc-60","E-mc-61"]},
    {"id":"C12-15","stage":22,"order":21,"topic":"G","grade":12,"minutes":10,"title":"Học máy (machine learning) là gì?","intro":"Có những bài toán mà con người khó lòng viết ra một luật rõ ràng cho máy tính làm theo — chẳng hạn dạy máy nhận ra một bức ảnh có con mèo hay không. Bài học này giới thiệu **học máy** (`machine learning`): cách máy tính tự rút ra quy luật từ rất nhiều dữ liệu ví dụ, thay vì được lập trình theo từng luật do con người viết sẵn.","sections":[{"t":"story","text":"Giả sử bạn cần giúp một người chưa từng nhìn thấy con mèo bao giờ học cách nhận ra nó. Có hai cách để làm việc này.\n\nCách thứ nhất: đọc cho người đó một định nghĩa thật chi tiết — ‘mèo là loài vật có bốn chân, tai nhọn, đuôi dài, bộ ria quanh miệng, phát ra tiếng kêu đặc trưng’. Nghe có vẻ ổn, cho đến khi người đó gặp một con mèo tai cụp bẩm sinh, một con mèo bị cụt đuôi vì tai nạn, hay ngược lại, một con cáo cũng bốn chân, tai nhọn, đuôi dài chẳng kém gì mèo. Định nghĩa rõ ràng đến mấy cũng khó lòng liệt kê hết mọi trường hợp ngoại lệ.\n\nCách thứ hai: không đọc định nghĩa nào cả. Thay vào đó, đưa cho người đó xem thật nhiều bức ảnh, mỗi ảnh kèm một lời chú thích — ‘đây là mèo’ hoặc ‘đây không phải mèo’ — hết ảnh này đến ảnh khác, có khi lên đến hàng nghìn tấm. Không ai giảng giải luật gì cả, nhưng chỉ sau một thời gian, người đó tự nhiên nhận ra mèo ngay cả trong những bức ảnh hoàn toàn mới, dù có khi chính họ cũng không diễn đạt rành mạch được vì sao mình biết đó là mèo.\n\nCách thứ hai chính là tinh thần của học máy: thay vì viết luật, ta cho máy xem thật nhiều ví dụ, rồi để máy tự tìm ra quy luật ẩn trong đó."},{"t":"h","text":"1) Lập trình truyền thống: viết sẵn từng luật cho máy"},{"t":"text","text":"Trong cách lập trình quen thuộc nhất — thường gọi là **lập trình truyền thống** — người viết chương trình phải tự nghĩ ra và viết ra từng luật thật cụ thể, rõ ràng, để máy tính làm theo từng bước một. Chẳng hạn, muốn kiểm tra một số có phải là số chẵn hay không, chỉ cần viết đúng một luật: nếu số đó chia hết cho 2 thì là số chẵn, ngược lại là số lẻ. Máy tính cứ thế làm theo, không cần xem qua bất kỳ ví dụ nào trước.\n\nCách này hoạt động rất tốt với những bài toán có luật rõ ràng, không có ngoại lệ khó lường. Nhưng với nhiều bài toán khác, việc viết luật lại khó đến mức gần như bất khả thi. Hãy thử hình dung phải viết một luật đủ chính xác để nhận ra con mèo trong bất kỳ bức ảnh nào — như trong câu chuyện ở trên, mọi định nghĩa dù chi tiết đến đâu cũng có ngoại lệ. Liệt kê hết mọi trường hợp bằng luật viết tay, với những bài toán như vậy, gần như là điều không thể làm được."},{"t":"h","text":"2) Học máy: đưa dữ liệu, để máy tự rút ra quy luật"},{"t":"text","text":"**Học máy** (`machine learning`) đi theo hướng hoàn toàn khác. Thay vì lập trình viên phải nghĩ ra và viết sẵn từng luật, ta đưa cho máy xem rất nhiều **ví dụ** — gọi là **dữ liệu** — rồi để máy tự tìm ra quy luật ẩn trong dữ liệu đó, giống hệt cách người trong câu chuyện ở trên tự nhận ra mèo sau khi xem đủ nhiều ảnh, chứ không nhờ ai đọc định nghĩa cho nghe. Nói ngắn gọn: lập trình truyền thống là con người viết luật cho máy; học máy là máy tự rút ra luật từ dữ liệu con người cung cấp.\n\nHọc máy là một nhánh của **trí tuệ nhân tạo** (`Artificial Intelligence`, viết tắt `AI`) — lĩnh vực rộng hơn, nghiên cứu cách làm cho máy tính thực hiện được những việc vốn cần đến trí thông minh của con người, như nhận biết hình ảnh, hiểu ngôn ngữ hay đưa ra quyết định. Trong nhiều hướng để đạt được điều đó, học máy hiện là hướng đi phổ biến nhất: thay vì lập trình cứng từng luật, ta để máy tự học quy luật từ dữ liệu."},{"t":"h","text":"3) Dữ liệu huấn luyện: nguyên liệu quyết định máy học đúng hay sai"},{"t":"text","text":"Dữ liệu dùng để dạy máy được gọi là **dữ liệu huấn luyện** (`training data`). Đây là nguyên liệu duy nhất mà máy dựa vào để tự rút ra quy luật — máy không có cách nào khác để ‘biết’ điều gì ngoài những gì đã thấy trong dữ liệu huấn luyện.\n\nChính vì vậy, chất lượng và số lượng của dữ liệu huấn luyện quan trọng hơn rất nhiều so với người ta thường nghĩ. Dữ liệu càng nhiều và càng chính xác, máy càng có cơ hội nhận ra đúng quy luật chung. Ngược lại, nếu dữ liệu quá ít hoặc bị gắn nhãn sai — chẳng hạn nhiều ảnh chó bị chú thích nhầm thành mèo — máy sẽ học theo đúng những sai lầm đó, giống như một người học bài từ tài liệu sai thì hiểu sai kiến thức, dù có cố gắng học chăm chỉ đến đâu."},{"t":"h","text":"4) Một số ứng dụng quen thuộc của học máy"},{"t":"list","text":"Học máy hiện diện trong rất nhiều ứng dụng quen thuộc hằng ngày:","items":["**Lọc thư rác**: máy được cho xem rất nhiều email đã có sẵn nhãn ‘rác’ hoặc ‘không rác’, từ đó tự nhận ra những đặc điểm thường gặp ở thư rác để áp dụng cho những email mới.","**Gợi ý phim**: máy học từ lịch sử xem phim và đánh giá của rất nhiều người dùng, để nhận ra ai có sở thích giống ai, từ đó gợi ý những bộ phim một người có khả năng thích.","**Nhận diện chữ viết tay**: máy được cho xem rất nhiều hình ảnh chữ số hay chữ cái viết tay, mỗi ảnh kèm đúng nhãn của nó, để tự nhận ra ký tự nào ứng với những nét vẽ nào."]},{"t":"example","text":"Hãy xem gần hơn cách máy nhận diện chữ số viết tay. Máy được cho xem trước rất nhiều hình ảnh chữ số đã viết tay, mỗi ảnh kèm đúng nhãn là chữ số nào:","code":"Ảnh 1: một nét cong khép kín, tròn trịa → nhãn: 0\nẢnh 2: một nét thẳng đứng đơn giản → nhãn: 1\nẢnh 3: hai nét thẳng đứng nối bằng một nét ngang ở giữa → nhãn: 4\n... (thêm hàng nghìn ảnh khác đã gắn nhãn tương tự)\n\nẢnh mới, máy chưa từng thấy: có một vòng tròn nhỏ phía trên, nối liền với một nét thẳng đứng phía dưới → ?","output":"Máy so sánh nét vẽ của ảnh mới với các kiểu nét đã ‘thấy’ qua hàng nghìn ảnh huấn luyện trước đó, nhận ra nó gần giống nhất với nhóm ảnh từng được gắn nhãn ‘9’, nên dự đoán chữ số trong ảnh mới là 9. Không có luật nào kiểu ‘nếu có vòng tròn ở trên và nét thẳng ở dưới thì là số 9’ được ai viết sẵn cả — máy tự rút ra điều đó từ dữ liệu đã học."},{"t":"h","text":"5) Máy ‘học’ ở đây thực ra nghĩa là gì?"},{"t":"text","text":"Khi nói máy ‘học’, điều đó không có nghĩa là máy hiểu biết hay suy nghĩ như con người. Học máy thực chất là một quá trình **điều chỉnh dần dần**: ban đầu, máy đưa ra dự đoán gần như ngẫu nhiên; mỗi khi dự đoán sai so với nhãn đúng đã biết trong dữ liệu huấn luyện, máy tự điều chỉnh lại một chút; lặp lại việc này rất nhiều lần, qua rất nhiều ví dụ, để dự đoán ngày một chính xác hơn.\n\nQuá trình này giống hệt người trong câu chuyện mở đầu: lúc mới xem vài chục bức ảnh, người đó có thể đoán nhầm cáo thành mèo; nhưng sau khi xem qua hàng nghìn bức ảnh và nhiều lần được chỉ ra chỗ đoán sai, khả năng nhận ra mèo của người đó dần chính xác hơn hẳn. Máy học cũng cải thiện theo đúng cách đó — không phải bỗng dưng ‘thông minh’ ngay từ đầu, mà chính xác dần lên qua từng lần điều chỉnh dựa trên dữ liệu."},{"t":"note","text":"Một hiểu lầm khá phổ biến: cho rằng máy tính càng ‘mạnh’ thì học máy càng chính xác. Trên thực tế, nếu dữ liệu huấn luyện quá ít hoặc sai lệch, thì dù chạy trên máy tính mạnh đến đâu, mô hình vẫn sẽ rút ra quy luật sai. Dữ liệu huấn luyện — chứ không chỉ sức mạnh tính toán — mới là yếu tố quyết định máy học đúng hay sai."}],"keypoints":["**Lập trình truyền thống** yêu cầu con người viết sẵn từng luật cụ thể cho máy; **học máy** (`machine learning`) thì ngược lại — máy tự rút ra quy luật từ rất nhiều **dữ liệu** ví dụ, không cần ai viết luật sẵn.","Học máy là một nhánh của **trí tuệ nhân tạo** (`AI`) — hướng đi phổ biến nhất hiện nay để giúp máy thực hiện những việc vốn cần đến trí thông minh của con người.","**Dữ liệu huấn luyện** (`training data`) là nguyên liệu duy nhất máy dựa vào để học; dữ liệu càng nhiều và càng chính xác, máy càng có cơ hội học đúng quy luật.","Máy ‘học’ nghĩa là **điều chỉnh dần dần** qua rất nhiều lần dự đoán và sửa sai để ngày càng chính xác hơn — ứng dụng quen thuộc gồm lọc thư rác, gợi ý phim, nhận diện chữ viết tay."],"quiz":["CC-mc-1501","CC-mc-1502","CC-mc-1503","CC-mc-1504","CC-mc-1505","CC-tf-1501","CC-tf-1502","CC-tf-1503","CC-tf-1504","G-mc-19","G-mc-20","G-mc-21","G-tf-3","G-mc-28","G-mc-29","G-mc-30","G-mc-31","G-mc-45","G-tf-10"]},
    {"id":"C12-16","stage":22,"order":22,"topic":"G","grade":12,"minutes":11,"title":"Học máy: bài toán phân loại và dự đoán","intro":"Bài học giúp bạn phân biệt hai dạng bài toán phổ biến nhất trong học máy: phân loại (chọn một nhãn có sẵn) và dự đoán số (ước lượng một giá trị). Bạn cũng sẽ biết vì sao một mô hình học máy luôn cần được huấn luyện trên một phần dữ liệu, rồi kiểm tra trên phần dữ liệu khác trước khi tin dùng.","sections":[{"t":"story","text":"Hãy tưởng tượng một dây chuyền phân loại trái cây trong một nhà kho. Mỗi quả đi qua đều được một chiếc camera quét qua, ghi lại **màu sắc** và **kích thước** của nó. Dựa trên hai đặc điểm đó, hệ thống phải làm hai việc hoàn toàn khác nhau.\n\nViệc thứ nhất: quyết định quả đó là táo, cam hay chuối, rồi đẩy nó vào đúng giỏ. Đây là kiểu câu hỏi “quả này thuộc loại nào, trong số vài loại đã biết trước?”.\n\nViệc thứ hai: dựa vào kích thước, ước lượng luôn quả đó nặng khoảng bao nhiêu gam để in tem giá. Đây lại là một kiểu câu hỏi khác hẳn: “giá trị cần tìm là bao nhiêu?” — câu trả lời không phải một cái tên có sẵn, mà là một con số.\n\nCùng một dữ liệu đầu vào (màu sắc, kích thước), nhưng hai câu hỏi đặt ra lại thuộc hai dạng bài toán khác nhau trong học máy. Bài học này sẽ giúp bạn phân biệt rõ hai dạng bài toán đó."},{"t":"h","text":"1) Học máy: hai câu hỏi thường gặp nhất"},{"t":"text","text":"Phần lớn bài toán học máy, dù trông có vẻ rất đa dạng, thường quy về một trong hai câu hỏi sau.\n\nCâu hỏi thứ nhất: “Dữ liệu này thuộc nhóm nào, trong số các nhóm đã biết trước?”. Câu trả lời là một **nhãn** — một cái tên nhóm có sẵn. Đây là bài toán **phân loại** (`classification`).\n\nCâu hỏi thứ hai: “Giá trị cần tìm là bao nhiêu?”. Câu trả lời là một **con số**, có thể là bất kỳ giá trị nào trong một khoảng, chứ không bị giới hạn trong vài lựa chọn cho sẵn. Đây là bài toán **dự đoán số** (`regression`).\n\nDù thuộc dạng nào, cách máy học cũng giống nhau ở một điểm cốt lõi: máy cần được cho xem trước rất nhiều dữ liệu đã biết sẵn câu trả lời đúng, để tự tìm ra quy luật ẩn trong đó, rồi mới áp dụng quy luật ấy cho dữ liệu mới mà nó chưa từng gặp."},{"t":"h","text":"2) Phân loại (classification): gán nhãn cho dữ liệu"},{"t":"text","text":"**Phân loại** là bài toán mà máy phải chọn ra đúng một nhãn, trong số một vài nhãn đã quy định sẵn từ trước. Số lượng nhãn ở đây là hữu hạn và biết trước — giống như trong câu chuyện ở trên, chỉ có ba giỏ táo, cam, chuối để chọn, không tự nhiên xuất hiện thêm giỏ thứ tư.\n\nMột số bài toán phân loại quen thuộc: xem một email rồi quyết định đó là thư rác hay thư bình thường; xem một tấm ảnh rồi cho biết trong đó là chó hay mèo; đọc một bình luận rồi đánh giá là tích cực hay tiêu cực. Trong mọi trường hợp, kết quả đưa ra luôn là tên của một nhóm, không phải một con số."},{"t":"example","text":"Xét bài toán lọc thư rác. Máy được cho xem trước một số email đã có sẵn nhãn đúng:","code":"Email 1: có đường link lạ, nhiều lỗi chính tả → Rác\nEmail 2: gửi từ đồng nghiệp, nội dung công việc → Không rác\nEmail 3: hứa hẹn trúng thưởng, yêu cầu chuyển tiền → Rác\n\nEmail mới: quảng cáo giảm giá, có đường link lạ, không rõ người gửi → ?","output":"Email mới có nhiều đặc điểm giống các email từng bị gán nhãn Rác (đường link lạ, nội dung mời chào bất thường), nên máy dự đoán nhãn của nó là Rác."},{"t":"h","text":"3) Dự đoán số (regression): ước lượng một giá trị"},{"t":"text","text":"**Dự đoán số** là bài toán mà máy phải ước lượng ra một con số, thay vì chọn một cái tên nhóm. Con số này có thể nhận rất nhiều giá trị khác nhau, kể cả những giá trị chưa từng xuất hiện y hệt trong dữ liệu đã học — giống như cân nặng của quả trong câu chuyện mở đầu, có thể là 152 gam, 187 gam hay bất kỳ số nào khác, không bị bó buộc trong vài lựa chọn có sẵn.\n\nMột số bài toán dự đoán số quen thuộc: ước lượng giá một căn nhà dựa vào diện tích của nó; ước lượng điểm kiểm tra dựa vào số giờ ôn tập; dự đoán nhiệt độ ngày mai dựa vào dữ liệu thời tiết các ngày trước. Kết quả đưa ra luôn là một con số, có thể có phần thập phân, chứ không phải một nhãn."},{"t":"example","text":"Xét bài toán ước lượng giá nhà theo diện tích. Máy được cho xem trước dữ liệu của vài căn nhà đã bán, kèm giá thật:","code":"Nhà 1: 40 m² → 800 triệu đồng\nNhà 2: 60 m² → 1200 triệu đồng\nNhà 3: 80 m² → 1600 triệu đồng\n\nNhà mới: 70 m² → ?","output":"Giá tăng khá đều theo diện tích — cứ thêm 20 m² thì giá tăng thêm khoảng 400 triệu đồng. Theo quy luật đó, máy ước lượng nhà 70 m² có giá khoảng 1400 triệu đồng, dù con số này chưa từng xuất hiện trong dữ liệu đã xem."},{"t":"h","text":"4) Huấn luyện, kiểm tra và độ chính xác"},{"t":"text","text":"Dù là bài toán phân loại hay dự đoán số, quy trình xây dựng một mô hình học máy đều theo chung một khuôn.\n\nTrước tiên, toàn bộ dữ liệu đã có sẵn câu trả lời đúng được chia làm hai phần. Phần lớn hơn gọi là dữ liệu **huấn luyện** (`training`) — máy nhìn vào phần này để tự tìm ra quy luật. Phần còn lại gọi là dữ liệu **kiểm tra** (`test`) — phần này máy hoàn toàn chưa được nhìn thấy trong lúc học, chỉ dùng để chấm điểm mô hình sau khi học xong.\n\nĐể chấm điểm, người ta đo **độ chính xác** (`accuracy`): với bài toán phân loại, đó là tỉ lệ phần trăm số lần máy đoán đúng nhãn trên tổng số lần đoán ở tập kiểm tra. Với bài toán dự đoán số, người ta thường đo mức chênh lệch trung bình giữa con số máy đoán và con số thật — mức chênh lệch càng nhỏ, mô hình càng tốt."},{"t":"note","text":"Vì sao nhất thiết phải chấm điểm trên phần dữ liệu kiểm tra — tức phần máy chưa từng thấy — mà không chấm ngay trên chính dữ liệu đã dùng để học?\n\nBởi vì nếu chỉ kiểm tra lại trên dữ liệu đã học, máy có thể đạt điểm gần như tuyệt đối chỉ bằng cách ghi nhớ y nguyên từng trường hợp, giống một người học thuộc lòng đáp án của đúng những câu đã ôn mà không hiểu bản chất bài toán — hễ đề bài hỏi khác đi một chút là lúng túng ngay. Cách học như vậy thường được gọi vui là “học vẹt”. Chỉ khi máy vẫn đoán tốt trên dữ liệu hoàn toàn mới, ta mới yên tâm rằng nó đã thật sự nắm được quy luật chung, chứ không chỉ ghi nhớ máy móc."}],"keypoints":["Học máy thường giải hai dạng bài toán chính: **phân loại** (`classification`) — chọn một nhãn có sẵn cho dữ liệu, và **dự đoán số** (`regression`) — ước lượng một con số.","Phân loại cho ra một nhãn trong số hữu hạn nhãn biết trước (ví dụ thư rác/không rác); dự đoán số cho ra một con số bất kỳ trong một khoảng (ví dụ giá nhà, điểm số, nhiệt độ).","Quy trình chung: chia dữ liệu thành phần **huấn luyện** (để máy học quy luật) và phần **kiểm tra** (để đánh giá), rồi đo **độ chính xác** trên phần kiểm tra.","Phải đánh giá mô hình trên dữ liệu mới, chưa từng thấy, để chắc chắn máy nắm được quy luật chung chứ không chỉ “học vẹt” — ghi nhớ máy móc dữ liệu huấn luyện."],"quiz":["CC-mc-1601","CC-mc-1602","CC-mc-1603","CC-mc-1604","CC-mc-1605","CC-tf-1601","CC-tf-1602","CC-tf-1603","CC-tf-1604","G-mc-38","G-mc-42","CC-mc-2291","CC-mc-2292","CC-mc-2293","CC-tf-2291"]},
    {"id":"C12-27","stage":22,"order":23,"topic":"G","grade":12,"minutes":12,"title":"Dữ liệu có nhãn, dữ liệu không nhãn và bài toán phân cụm","intro":"Không phải lúc nào ta cũng có sẵn đáp án đúng để dạy máy. Bài học này đi vào một trục phân chia quan trọng của học máy: dữ liệu **có nhãn** hay **không nhãn**, từ đó phân biệt **học có giám sát** với **học không giám sát**, và tìm hiểu bài toán tiêu biểu nhất của nhóm thứ hai — **phân cụm** (`clustering`).","sections":[{"t":"story","text":"Cuối năm học, thư viện trường nhận về hai thùng sách quyên góp. Cô thủ thư nhờ hai bạn trong đội cộng tác viên giúp một tay, mỗi bạn một thùng.\n\nBạn thứ nhất nhận thùng có kèm một tờ danh mục ghi rõ từng cuốn: cuốn này xếp vào giá Văn học, cuốn kia vào giá Khoa học, cuốn nọ vào giá Truyện tranh. Vừa xếp, bạn ấy vừa để ý: sách bìa mềm, khổ nhỏ, nhiều tranh vẽ thì thường là truyện tranh; sách dày, bìa cứng, có nhiều bảng biểu thì thường là sách khoa học. Xếp xong thùng đó, cô thủ thư đưa thêm mười cuốn không hề có trong danh mục, vậy mà bạn ấy vẫn đoán được nên đặt mỗi cuốn vào giá nào.\n\nBạn thứ hai kém may hơn: thùng của bạn ấy chẳng kèm tờ giấy nào cả. Không ai nói cuốn nào thuộc loại gì, thậm chí cũng chẳng ai cho biết trong thùng có mấy loại sách. Bạn ấy đành làm theo cách của mình: lật từng cuốn, thấy cuốn nào giống nhau về độ dày, khổ giấy, cách trình bày thì để chung một chồng. Đến cuối buổi, trên bàn hiện ra bốn chồng sách khá rõ rệt. Lúc đó bạn ấy mới ngồi nhìn lại từng chồng và tự nghĩ ra tên gọi cho chúng.\n\nHai bạn cùng làm một việc là sắp xếp sách, nhưng xuất phát điểm hoàn toàn khác nhau: một bên có sẵn đáp án để học theo, một bên phải tự mò ra trật tự từ một đống lộn xộn. Máy tính cũng học theo đúng hai kiểu như vậy."},{"t":"h","text":"1) Dữ liệu có nhãn và dữ liệu không nhãn"},{"t":"text","text":"Trong học máy, mỗi mẫu dữ liệu thường gồm hai phần. Phần thứ nhất là các thông tin mô tả đối tượng: số buổi đi học thêm mỗi tuần, chiều cao, số tin nhắn gửi mỗi ngày, các điểm ảnh của một tấm ảnh… Phần thứ hai là đáp án đi kèm — chính là điều ta muốn máy học cách nói ra: cuốn sách này thuộc loại nào, bức ảnh này chụp con gì, email này có phải thư rác hay không.\n\nKhi mỗi mẫu dữ liệu đã kèm sẵn phần đáp án đúng, ta gọi đó là **dữ liệu có nhãn** (`labeled data`). Nhãn ở đây do con người xác định và gán vào từ trước, giống hệt tờ danh mục mà cô thủ thư đưa cho bạn thứ nhất. Ngược lại, khi dữ liệu chỉ có phần mô tả mà không hề có đáp án đi kèm, ta gọi đó là **dữ liệu không nhãn** (`unlabeled data`) — đúng như thùng sách trơ trọi mà bạn thứ hai nhận được.\n\nSự khác nhau tưởng chừng nhỏ này lại chính là căn cứ quan trọng nhất để chia học máy thành các nhóm phương pháp khác nhau. Cần nói thêm rằng gắn nhãn cho dữ liệu là công việc rất tốn công sức và tiền bạc: muốn có một triệu tấm ảnh đã ghi rõ trong ảnh có gì thì phải có người ngồi xem và ghi chú từng tấm. Vì vậy trong thực tế, dữ liệu không nhãn luôn nhiều hơn dữ liệu có nhãn rất nhiều lần."},{"t":"h","text":"2) Ba nhóm phương pháp học máy, chia theo dữ liệu đầu vào"},{"t":"text","text":"**Học có giám sát** (`supervised learning`) là cách học dựa trên dữ liệu ĐÃ có nhãn. Máy được xem thật nhiều cặp “phần mô tả — đáp án đúng”, dò tìm mối liên hệ giữa hai phần đó, để rồi khi gặp một mẫu mới chưa có nhãn thì tự đưa ra nhãn cho nó. Chữ “giám sát” ở đây mang nghĩa: trong suốt quá trình học, luôn có sẵn đáp án đúng do con người cung cấp để máy đối chiếu, chẳng khác gì có người kèm bên cạnh chỉ ra đúng sai sau mỗi lần thử.\n\n**Học không giám sát** (`unsupervised learning`) thì ngược lại: dữ liệu đưa vào hoàn toàn KHÔNG có nhãn, nên chẳng có đáp án nào để đối chiếu. Nhiệm vụ của máy lúc này không phải là dự đoán nhãn, mà là tự tìm ra **cấu trúc ẩn** trong dữ liệu — những trật tự, những quy luật vốn đã nằm sẵn trong đó nhưng chưa ai chỉ ra. Máy phải tự xoay xở đúng như bạn thứ hai với thùng sách không danh mục.\n\nNgoài hai nhóm trên, học máy còn một nhóm thứ ba là **học tăng cường** (`reinforcement learning`). Ở đây máy không học từ một bảng dữ liệu dọn sẵn, mà học qua thử – sai: cứ hành động, hành động tốt thì được thưởng điểm, hành động dở thì bị phạt, rồi dần dần điều chỉnh sao cho tổng điểm thưởng nhận về là cao nhất. Cách học này thường gặp trong các chương trình chơi cờ, chơi trò chơi điện tử và trong điều khiển rô-bốt."},{"t":"h","text":"3) Phân cụm: máy tự gom những đối tượng giống nhau"},{"t":"text","text":"**Phân cụm** (`clustering`) là bài toán tiêu biểu nhất của học không giám sát. Đầu vào là một tập đối tượng chưa có nhãn; nhiệm vụ của máy là gom những đối tượng giống nhau vào cùng một nhóm, gọi là một **cụm** (`cluster`), sao cho các đối tượng trong cùng một cụm thì gần giống nhau, còn đối tượng thuộc hai cụm khác nhau thì khác biệt rõ rệt.\n\nMuốn làm được điều đó, máy cần một cách đo **độ tương tự** giữa hai đối tượng. Thông thường mỗi đối tượng được mô tả bằng vài con số, và máy coi mỗi đối tượng như một điểm; hai điểm càng gần nhau thì hai đối tượng càng được xem là giống nhau. Từ đó máy gom những điểm nằm chụm lại với nhau thành một cụm, và tách những vùng thưa thớt ở giữa ra làm ranh giới. Có một chi tiết dễ bỏ qua: nếu các con số mô tả đối tượng chênh nhau quá xa về độ lớn — chẳng hạn một cột chạy từ 1 đến 5 còn cột kia chạy từ 10 đến 40 — thì cột có giá trị lớn sẽ lấn át hoàn toàn khi tính khoảng cách, nên trước khi phân cụm người ta thường đưa các cột về cùng một thang đo.\n\nĐiều quan trọng nhất cần nhớ: máy hoàn toàn không biết trước dữ liệu gồm mấy loại đối tượng, càng không biết mỗi cụm nên gọi tên là gì. Nó chỉ thấy các con số, thấy chỗ nào dày chỗ nào thưa. Việc nhìn vào từng cụm, hiểu ý nghĩa và đặt tên cho cụm đó là phần việc của con người, làm SAU khi máy đã chia xong."},{"t":"example","text":"Căng tin trường ghi lại thói quen mua đồ ăn sáng của tám bạn trong một tháng học (khoảng 20 buổi), chỉ gồm hai con số cho mỗi bạn: số buổi có mua và số tiền chi trung bình mỗi buổi. Bảng này hoàn toàn không có nhãn — không ai xếp trước bạn nào thuộc kiểu khách hàng nào:","code":"Bạn      Số buổi mua/tháng   Chi mỗi buổi (nghìn đồng)\nAn             18                      12\nBình           19                      15\nChi            17                      13\nDũng            4                      35\nGiang           3                      40\nHà              5                      38\nKhang          18                      36\nLinh           17                      39\n\nMáy coi mỗi bạn là một điểm có toạ độ (số buổi, số tiền),\nđo xem những điểm nào nằm gần nhau rồi gom lại:\n\nCụm 1: An, Bình, Chi        (mua nhiều buổi, mỗi buổi chi ít)\nCụm 2: Dũng, Giang, Hà      (ít khi mua, nhưng mua là chi nhiều)\nCụm 3: Khang, Linh          (mua nhiều buổi và mỗi buổi cũng chi nhiều)","output":"Máy tách ra ba cụm nhưng không hề biết gọi chúng là gì — nó chỉ thấy ba đám điểm nằm tách nhau; chính chúng ta mới là người nhìn vào và đặt tên: “khách quen ăn suất bình dân”, “thỉnh thoảng mới ghé nhưng ăn sang”, “khách quen chi nhiều”."},{"t":"list","text":"Phân cụm được dùng ở rất nhiều nơi, thường là khi ta có nhiều dữ liệu nhưng chưa biết nên chia chúng theo những nhóm nào:","items":["**Chia nhóm khách hàng theo thói quen mua sắm**: cửa hàng nhìn vào tần suất mua, mặt hàng hay chọn và mức chi tiêu để tách ra vài nhóm khách khác nhau, rồi thiết kế chương trình ưu đãi riêng cho từng nhóm.","**Gom các bài báo cùng chủ đề**: hàng nghìn bài viết mới mỗi ngày được máy gom thành từng cụm dựa trên những từ hay xuất hiện cùng nhau, giúp trang tin tự xếp các bài liên quan về cùng một chỗ.","**Chia nhóm học sinh theo đặc điểm học tập**: từ dữ liệu thời gian tự học, kết quả từng môn và mức độ tham gia hoạt động, máy tách ra vài nhóm có đặc điểm giống nhau để nhà trường chọn cách hỗ trợ phù hợp với từng nhóm.","**Phát hiện đối tượng bất thường**: những điểm dữ liệu không chịu thuộc về cụm nào, nằm lẻ loi tách hẳn khỏi phần còn lại, thường là dấu hiệu của điều gì đó đáng chú ý — chẳng hạn một tài khoản có hành vi khác thường."]},{"t":"h","text":"4) Phân cụm và phân loại — đừng nhầm hai bài toán này"},{"t":"text","text":"Đây là chỗ dễ nhầm nhất của bài học. Cả **phân loại** lẫn **phân cụm** đều cho ra kết quả trông giống nhau là “các nhóm đối tượng”, nên nhiều bạn tưởng chúng là một. Thực ra hai bài toán này khác nhau ngay từ điểm xuất phát.\n\nỞ phân loại, danh sách nhãn đã có sẵn và do con người định nghĩa từ trước; máy chỉ được chọn trong đúng những nhãn ấy, không hơn không kém. Dữ liệu huấn luyện cũng bắt buộc phải có nhãn thì máy mới học được. Vì vậy phân loại luôn thuộc về học có giám sát. Ở phân cụm thì không có danh sách nhãn nào cả: các nhóm là do máy tự tách ra từ dữ liệu, và con người phải nhìn lại từng cụm để tự đặt tên, tự giải thích xem cụm đó mang ý nghĩa gì. Vì vậy phân cụm thuộc về học không giám sát.\n\nMột hệ quả thú vị: chạy phân cụm hai lần với cách thiết lập khác nhau — chẳng hạn yêu cầu chia thành 3 cụm rồi lại chia thành 5 cụm — ta nhận được hai cách chia khác nhau mà không cách nào là “sai” cả. Máy chỉ nói được rằng “những đối tượng này nằm gần nhau”; còn cách chia nào có ý nghĩa và dùng được cho công việc thực tế thì vẫn phải do con người phán xét."},{"t":"note","text":"Một cái bẫy hay gặp trong đề thi: đề mô tả tình huống có sẵn danh sách nhóm do con người đặt ra — ví dụ “xếp mỗi học sinh vào một trong ba mức Tốt, Khá, Đạt theo tiêu chí nhà trường quy định” — rồi hỏi đó là phân cụm hay phân loại. Hễ thấy các nhóm đã được đặt tên và định nghĩa TRƯỚC, đó là **phân loại**, tức học có giám sát. Chỉ khi các nhóm do máy tự tách ra từ dữ liệu không nhãn, và con người phải đặt tên cho chúng sau đó, thì mới là **phân cụm**."}],"keypoints":["**Dữ liệu có nhãn** là dữ liệu mà mỗi mẫu đã kèm sẵn đáp án đúng do con người gán; **dữ liệu không nhãn** thì không có đáp án đi kèm. Đây chính là căn cứ để chia học máy thành các nhóm phương pháp khác nhau.","**Học có giám sát** học từ dữ liệu đã có nhãn để dự đoán nhãn cho dữ liệu mới; **học không giám sát** làm việc với dữ liệu không nhãn và tự tìm ra **cấu trúc ẩn** nằm sẵn trong dữ liệu.","**Phân cụm** (`clustering`) là bài toán tiêu biểu của học không giám sát: máy dựa trên **độ tương tự** để gom các đối tượng giống nhau vào cùng một cụm, dù không hề biết trước có bao nhiêu nhóm hay tên gọi của chúng.","**Phân loại** có sẵn danh sách nhãn do con người định nghĩa trước, còn với **phân cụm** thì con người phải tự đặt tên và giải thích ý nghĩa cho các cụm máy tách ra; ngoài hai nhóm này còn có **học tăng cường** — máy học qua thử – sai cùng cơ chế thưởng/phạt."],"quiz":["CC-mc-2701","CC-mc-2702","CC-mc-2703","CC-mc-2704","CC-mc-2705","CC-tf-2701","CC-tf-2702","CC-tf-2703","CC-tf-2704","G-mc-37","G-mc-43","G-tf-7","G-mc-50"]},
    {"id":"C12-17","stage":22,"order":24,"topic":"G","grade":12,"minutes":10,"title":"Khoa học dữ liệu là gì?","intro":"Mỗi ngày, thế giới tạo ra một lượng dữ liệu khổng lồ — từ hoá đơn bán hàng đến kết quả xét nghiệm y tế. Bài học này giúp bạn hiểu khoa học dữ liệu là gì: quá trình biến những con số rời rạc thành hiểu biết giúp con người ra quyết định tốt hơn.","sections":[{"t":"story","text":"Hãy tưởng tượng một cửa hàng quần áo nhỏ đã bán hàng được ba năm. Suốt thời gian đó, mỗi lần bán được món gì, người bán chỉ ghi vội vài dòng lên hoá đơn giấy rồi cất đi một chỗ. Ba năm sau, chồng hoá đơn ấy đã cao gần nửa mét, chữ viết tay lộn xộn, có tờ ghi thiếu ngày, có tờ trùng lặp vì đánh số hai lần, có tờ lại ghi nhầm giá.\n\nNhìn đống giấy đó, chủ cửa hàng không thấy được điều gì cả — chỉ là một mớ hỗn độn khó đọc. Nhưng khi nhờ một người biết cách xử lý dữ liệu giúp sắp xếp lại: gõ toàn bộ vào bảng tính, loại bỏ những tờ trùng, bổ sung ngày tháng còn thiếu, sửa các chỗ ghi nhầm, rồi thử vẽ vài biểu đồ theo từng tháng — bức tranh bỗng hiện ra rõ ràng: áo khoác bán chạy vào tháng 11 và 12, áo thun bán chạy nhất vào tháng 5 và 6, còn quần dài thì bán đều quanh năm.\n\nCùng một đống dữ liệu, lúc đầu chỉ là ‘rác’ không ai đọc nổi, nhưng sau khi qua một quy trình xử lý, nó trở thành hiểu biết có thể dùng để quyết định: nên nhập thêm áo khoác vào cuối năm, chuẩn bị áo thun từ đầu hè. Biến đống giấy lộn xộn ấy thành hiểu biết hữu ích — đó chính là công việc của khoa học dữ liệu."},{"t":"h","text":"Khoa học dữ liệu là gì?"},{"t":"text","text":"**Khoa học dữ liệu** (`data science`) là lĩnh vực nghiên cứu cách thu thập, xử lý và phân tích dữ liệu để tìm ra hiểu biết có ích, phục vụ cho việc ra quyết định.\n\nCần phân biệt hai khái niệm. **Dữ liệu thô** (`raw data`) là những con số, chữ viết, hình ảnh... được ghi lại nhưng chưa qua xử lý gì cả — giống chồng hoá đơn viết tay ở trên. **Hiểu biết** (`insight`) là quy luật hay xu hướng đã được rút ra từ dữ liệu, đủ rõ ràng để dựa vào đó mà hành động — chẳng hạn ‘áo khoác bán chạy vào mùa đông’.\n\nNói ngắn gọn, khoa học dữ liệu là công việc biến dữ liệu thô — vốn không nói lên điều gì nếu chỉ nhìn qua — thành hiểu biết có thể dùng được."},{"t":"h","text":"Quy trình năm bước xử lý dữ liệu"},{"t":"list","text":"Để biến dữ liệu thô thành hiểu biết, người làm khoa học dữ liệu thường đi qua năm bước sau:","items":["**Thu thập dữ liệu**: ghi lại hoặc lấy về số liệu cần dùng, ví dụ hoá đơn bán hàng, kết quả đo đạc, câu trả lời khảo sát.","**Làm sạch dữ liệu**: rà lại toàn bộ dữ liệu vừa thu thập, loại bỏ dữ liệu lỗi, bổ sung chỗ thiếu, xoá bản ghi bị trùng lặp.","**Phân tích dữ liệu**: tính toán, thống kê để tìm ra quy luật hay điểm bất thường ẩn trong dữ liệu.","**Trực quan hoá**: vẽ dữ liệu thành biểu đồ, bảng biểu để nhìn ra quy luật dễ dàng hơn là đọc hàng nghìn con số rời rạc.","**Rút kết luận và khuyến nghị**: dựa vào những gì tìm được để đưa ra nhận định hoặc đề xuất hành động cụ thể."]},{"t":"example","text":"Áp dụng năm bước trên vào chuyện cửa hàng quần áo ở trên, ta có thể thấy một phần dữ liệu trông như sau, trước và sau khi xử lý:","code":"Dữ liệu thô (trước khi làm sạch):\nMặt hàng: Áo khoác | Ngày: 15/11 | Số lượng: 3\nMặt hàng: Áo khoác | Ngày: 15/11 | Số lượng: 3   (bản ghi trùng)\nMặt hàng: Áo thun  | Ngày: ??    | Số lượng: 5\nMặt hàng: Áo khoác | Ngày: 02/12 | Số lượng: 4\nMặt hàng: Áo thun  | Ngày: 20/05 | Số lượng: 6","output":"Sau khi làm sạch (bỏ bản ghi trùng, bỏ dòng thiếu ngày) rồi phân tích theo tháng: tháng 11–12 bán được 7 áo khoác, tháng 5 bán được 6 áo thun. Trực quan hoá bằng biểu đồ cột theo tháng cho thấy rõ áo khoác tăng mạnh vào cuối năm. Kết luận: nên nhập thêm áo khoác vào khoảng tháng 10–11 hằng năm."},{"t":"note","text":"Trong năm bước trên, **làm sạch dữ liệu** thường tốn nhiều công sức nhất nhưng lại dễ bị xem nhẹ nhất. Nếu bỏ qua bước này, dữ liệu lỗi và trùng lặp sẽ khiến toàn bộ phân tích phía sau sai lệch — đúng như nguyên tắc quen thuộc trong xử lý dữ liệu: ‘rác vào thì rác ra’ (dữ liệu đầu vào tệ thì kết quả đầu ra cũng tệ, dù công cụ phân tích có tốt đến đâu)."},{"t":"list","text":"Khoa học dữ liệu ngày nay có mặt ở rất nhiều lĩnh vực:","items":["**Kinh doanh**: phân tích dữ liệu mua hàng để hiểu khách hàng thích gì, mua vào thời điểm nào, từ đó quyết định nhập hàng, giảm giá hợp lý — như ví dụ cửa hàng quần áo ở trên.","**Y tế**: phân tích dữ liệu bệnh nhân để phát hiện sớm nguy cơ bệnh, đánh giá hiệu quả của một phương pháp điều trị.","**Thể thao**: phân tích số liệu thi đấu để đánh giá phong độ vận động viên, xây dựng chiến thuật phù hợp cho từng trận đấu.","**Giáo dục**: phân tích kết quả học tập để nhận ra học sinh nào cần hỗ trợ thêm, môn nào cả lớp còn yếu.","Liên hệ với **học máy** (`machine learning`): dữ liệu đã được thu thập và làm sạch cẩn thận chính là nguyên liệu để huấn luyện các mô hình học máy — dữ liệu càng sạch, mô hình học được càng chính xác."]}],"keypoints":["**Khoa học dữ liệu** là quá trình biến **dữ liệu thô** thành **hiểu biết** có ích để ra quyết định.","Quy trình gồm năm bước: **thu thập** → **làm sạch** → **phân tích** → **trực quan hoá** → **rút kết luận**.","**Làm sạch dữ liệu** là bước quan trọng bậc nhất — dữ liệu đầu vào lỗi thì kết quả phân tích cũng sai theo nguyên tắc ‘rác vào thì rác ra’.","Khoa học dữ liệu có mặt trong kinh doanh, y tế, thể thao, giáo dục... và là nền tảng chuẩn bị dữ liệu để huấn luyện **học máy**."],"quiz":["CC-mc-1701","CC-mc-1702","CC-mc-1703","CC-mc-1704","CC-mc-1705","CC-tf-1701","CC-tf-1702","CC-tf-1703","CC-tf-1704","G-mc-22","G-mc-23","G-mc-24","G-mc-5","G-mc-39","G-tf-8"]},
    {"id":"C12-28","stage":22,"order":25,"topic":"G","grade":12,"minutes":12,"title":"Từ dữ liệu thô đến bảng số liệu đáng tin","intro":"Trước khi vẽ được bất kỳ biểu đồ nào, người làm dữ liệu phải trả lời hai câu hỏi rất thực tế: lấy dữ liệu ở đâu, và làm sao biết dữ liệu đó có dùng được không. Bài học này đi vào **các nguồn dữ liệu thường gặp**, cách một bảng dữ liệu được lưu trong tệp `CSV`, và bốn loại lỗi phải nhặt ra cùng cách xử lí từng loại.","sections":[{"t":"story","text":"Câu lạc bộ Xe đạp xanh của một trường THPT muốn đề xuất nhà trường mở thêm chỗ để xe. Để có căn cứ thuyết phục, các bạn làm một cuộc hỏi ý kiến nhỏ: mỗi học sinh cho biết mình đi từ nhà đến trường bằng phương tiện gì và mất khoảng bao nhiêu phút. Phiếu hỏi được gửi qua mạng, chỉ sau ba ngày đã có hơn bốn trăm bạn trả lời. Cả nhóm mừng rỡ, tưởng chừng chỉ còn việc tính toán rồi viết báo cáo.\n\nNhưng khi mở bảng kết quả ra thì mọi chuyện không đơn giản như vậy. Hơn chục bạn điền những con số ba chữ số — 400, 700, có bạn ghi tới 1200 — vì các bạn ấy hiểu nhầm câu hỏi và tính bằng giây thay vì bằng phút. Có bạn ghi ‘khoảng mười lăm đến hai mươi’ nên máy không tính được. Có mấy chục ô để trống vì người trả lời bỏ qua câu hỏi. Lại có những dòng giống hệt nhau từng chữ, do bạn nào đó bấm gửi hai lần cho chắc.\n\nNhóm trưởng thử tính ngay giá trị trung bình trên bảng thô: kết quả ra 38 phút. Con số này khiến ai cũng ngờ ngợ, vì trường nằm giữa thị trấn, hầu hết học sinh nhà chỉ cách trường vài cây số. Chỉ mười mấy dòng ghi sai đơn vị, mỗi dòng lớn gấp mấy chục lần một dòng bình thường, đã đủ sức kéo lệch con số trung bình của cả hơn bốn trăm phiếu.\n\nThế là cả nhóm dành trọn một buổi chiều ngồi rà lại từng dòng: đổi các số ghi bằng giây về phút, bỏ các dòng lặp, hỏi lại vài bạn có số liệu lạ. Tính lại lần nữa, con số trung bình chỉ còn 14 phút — hợp lí hẳn. Buổi chiều hôm đó dạy các bạn một điều: việc tốn công nhất trong một bài phân tích không phải là vẽ biểu đồ, mà là làm cho bảng số liệu trở nên đáng tin."},{"t":"h","text":"1) Dữ liệu đến từ những nguồn nào?"},{"t":"list","text":"Khi tìm hiểu về khoa học dữ liệu, ta đã biết một bài toán dữ liệu luôn bắt đầu từ khâu thu thập rồi mới đến làm sạch và phân tích. Câu hỏi đặt ra bây giờ là: dữ liệu ấy thực ra lấy từ đâu? Trong thực tế, bốn nguồn sau đây xuất hiện thường xuyên nhất, và mỗi nguồn lại có kiểu lỗi đặc trưng riêng mà người thu thập cần lường trước:","items":["**Khảo sát và biểu mẫu trực tuyến**: chính là cách câu lạc bộ trong câu chuyện trên đã dùng. Ưu điểm là thu được đúng thứ mình cần hỏi và gom rất nhanh; nhược điểm là phụ thuộc hoàn toàn vào việc người trả lời có nghiêm túc và hiểu đúng câu hỏi hay không.","**Cảm biến và thiết bị đo**: nhiệt kế điện tử trong phòng thí nghiệm, đồng hồ đo bước chân trên điện thoại, thiết bị đo bụi mịn đặt ngoài sân trường. Dữ liệu từ cảm biến sinh ra đều đặn và khách quan, nhưng dễ bị gián đoạn khi thiết bị mất điện, mất kết nối hoặc lệch chuẩn.","**Nhật kí hoạt động của hệ thống** (`log`): mỗi lần một học sinh mượn sách bằng thẻ, đăng nhập vào phần mềm học trực tuyến hay quẹt thẻ vào cổng, hệ thống tự ghi lại một dòng gồm thời điểm và thao tác. Nguồn này rất lớn và trung thực, nhưng thường lẫn nhiều dòng kĩ thuật không liên quan đến điều ta muốn tìm hiểu.","**Dữ liệu mở** (`open data`) do cơ quan nhà nước công bố: số liệu dân số, thống kê giáo dục, chất lượng không khí, kết quả tuyển sinh... được đăng công khai cho mọi người tải về dùng miễn phí. Đây là nguồn đáng tin và tiết kiệm công sức, nhưng ta phải chấp nhận đúng những gì họ công bố chứ không hỏi thêm được."]},{"t":"h","text":"2) Bảng dữ liệu và tệp CSV"},{"t":"text","text":"Dù đến từ nguồn nào, dữ liệu rồi cũng được sắp lại thành một **bảng** để máy tính xử lí được. Quy ước rất chặt chẽ và cần nhớ kĩ: **mỗi hàng là một quan sát**, tức một đối tượng được ghi nhận — một học sinh trả lời phiếu, một lần đo của cảm biến, một lượt mượn sách; còn **mỗi cột là một thuộc tính** của đối tượng đó — họ tên, lớp, phương tiện, thời gian đi đường. Hàng đầu tiên thường chỉ để ghi tên các cột, gọi là dòng tiêu đề.\n\nKhi cần lưu bảng đó ra tệp để gửi cho người khác hoặc nạp vào chương trình, định dạng phổ biến nhất là **CSV** (`Comma-Separated Values`, nghĩa là ‘các giá trị ngăn cách bởi dấu phẩy’). Tệp `CSV` là một tệp **văn bản thuần**: mỗi dòng văn bản ứng với một hàng của bảng, và trong mỗi dòng, các giá trị của các cột được viết liền nhau, chỉ cách nhau bằng dấu phẩy.\n\nChính vì là văn bản thuần nên tệp `CSV` có một ưu điểm rất lớn: mở được bằng bất kỳ trình soạn thảo văn bản đơn giản nào, đọc được bằng mắt thường, và hầu như phần mềm bảng tính hay ngôn ngữ lập trình nào cũng nạp được. Nhưng cũng chính vì đơn giản, `CSV` không hề kiểm tra hộ ta điều gì cả: một ô trống, một con số gõ nhầm, một dòng bị lặp — tệp vẫn nhận hết, không báo lỗi. Việc phát hiện những chỗ hỏng đó là phần việc của con người."},{"t":"example","text":"Dưới đây là dòng tiêu đề và sáu dòng dữ liệu đầu tiên của tệp `khaosat_dixe.csv` mà câu lạc bộ Xe đạp xanh tải về sau ba ngày mở phiếu. Hãy thử đóng vai người kiểm tra dữ liệu và soi xem có gì bất ổn:","code":"ho_ten,lop,phuong_tien,thoi_gian_phut,ngay_gui\nNguyen Minh An,12A1,xe dap,12,05/09/2025\nTran Bao Chau,12A1,xe buyt,25,05/09/2025\nTran Bao Chau,12A1,xe buyt,25,05/09/2025\nLe Hoang Duy,12A2,,18,2025-09-06\nPham Gia Han,12A2,xe may dien,khoang 20,06/09/2025\nVo Kim Ngan,12A3,di bo,400,06/09/2025","output":"Chỉ trong sáu dòng dữ liệu đã lộ đủ bốn kiểu hỏng: dòng của Tran Bao Chau bị lặp nguyên vẹn hai lần, dòng của Le Hoang Duy để trống ô phương tiện và ghi ngày theo kiểu khác hẳn các dòng còn lại, dòng của Pham Gia Han ghi thời gian bằng chữ nên không tính toán được, còn dòng của Vo Kim Ngan có giá trị 400 phút đi bộ — xa hẳn khoảng hợp lí của cả cột."},{"t":"h","text":"3) Bốn lỗi thường gặp và cách xử lí từng lỗi"},{"t":"list","text":"Bốn kiểu hỏng vừa thấy trong tệp trên không phải ngẫu nhiên: đó đúng là bốn lỗi phổ biến nhất mà bất kỳ bảng dữ liệu thực tế nào cũng mắc phải. Người làm dữ liệu chuyên nghiệp có thói quen soi lần lượt đủ bốn loại này trước khi tính bất cứ con số nào, và với mỗi loại lại có một cách xử lí riêng:","items":["**Giá trị bị thiếu** (ô trống) — xảy ra khi người trả lời bỏ qua một câu hỏi hoặc cảm biến mất tín hiệu. Nếu một cột số chỉ thiếu lác đác vài ô, có thể **điền bằng giá trị trung bình** của cột đó để không mất cả hàng; nhưng nếu một hàng thiếu quá nhiều ô thì giữ lại cũng vô nghĩa, tốt hơn là **loại bỏ cả hàng**.","**Bản ghi trùng lặp** — cùng một quan sát bị ghi hai lần trở lên, thường do người dùng bấm gửi lại cho chắc, hoặc do gộp nhiều tệp thu thập ở các đợt khác nhau. Cách xử lí là **xoá các bản trùng**, chỉ giữ lại đúng một bản cho mỗi quan sát; nếu để nguyên, những quan sát bị lặp sẽ được đếm hai lần, làm sai số lượng và các tỉ lệ tính ra từ bảng.","**Sai kiểu hoặc sai định dạng** — cột đáng lẽ chỉ chứa số thì lại có chữ (‘khoang 20’), cột ngày lúc ghi 05/09/2025 lúc ghi 2025-09-06, hoặc cùng một cột mà chỗ tính bằng phút chỗ tính bằng giờ. Cách xử lí là **chuẩn hoá** toàn cột về cùng một kiểu, cùng một định dạng ngày và cùng một đơn vị đo trước khi tính toán.","**Giá trị bất thường** — con số nằm ngoài khoảng hợp lí của cột, như 400 phút đi bộ giữa một cột toàn số dưới 40. Tuyệt đối không xoá vội: phải **kiểm tra lại** xem đó là lỗi nhập liệu (thì sửa hoặc bỏ) hay là dữ liệu thật của một trường hợp đặc biệt (thì giữ lại và ghi chú rõ trong báo cáo)."]},{"t":"h","text":"4) Dữ liệu bẩn, mô hình thiên lệch và trách nhiệm khi thu thập"},{"t":"text","text":"Vì sao phải nghiêm khắc với bốn lỗi trên đến vậy? Vì mọi con số về sau đều được tính ra từ bảng dữ liệu đó. Trong câu chuyện mở đầu, chỉ mười mấy dòng ghi sai đơn vị đã đủ đẩy con số trung bình của hơn bốn trăm phiếu từ 14 phút lên 38 phút — chênh gần ba lần. Nếu câu lạc bộ mang con số 38 phút đi thuyết trình, họ sẽ vô tình vẽ ra một bức tranh sai về chính ngôi trường mình, và mọi đề xuất dựa trên đó cũng lệch theo. **Dữ liệu bẩn dẫn tới kết luận sai**, dù người phân tích có tính toán cẩn thận đến đâu.\n\nHậu quả còn nghiêm trọng hơn khi dữ liệu được dùng để huấn luyện một mô hình **học máy**. Mô hình không có cách nào biết dữ liệu mình được cho xem là đúng hay sai; nó chỉ việc rút ra quy luật từ đúng những gì có trong đó. Vì thế, dữ liệu bẩn hoặc **thiên lệch** sẽ cho ra mô hình thiên lệch theo. Chẳng hạn, một phần mềm gợi ý sách cho thư viện trường được huấn luyện chỉ từ lịch sử mượn sách của các lớp chuyên Văn sẽ gợi ý rất kém cho học sinh yêu thích khoa học — không phải vì thuật toán yếu, mà vì dữ liệu ban đầu đã không đại diện cho toàn trường. Đổi sang thuật toán mạnh hơn cũng không cứu được điều đó; phải sửa từ khâu thu thập.\n\nCuối cùng, khi dữ liệu được thu thập về con người thì bên cạnh yêu cầu về chất lượng còn có yêu cầu về **trách nhiệm**. Nguyên tắc đầu tiên là **xin phép**: người trả lời phải biết mình đang cung cấp dữ liệu và đồng ý làm việc đó. Nguyên tắc thứ hai là **nêu rõ mục đích sử dụng** ngay từ đầu, và về sau không được dùng dữ liệu sang một mục đích khác với điều đã nói.\n\nNguyên tắc thứ ba là **ẩn danh** những thông tin định danh: khi phân tích thời gian đi học của toàn trường, ta hoàn toàn không cần biết bạn nào trả lời dòng nào, nên hãy thay cột họ tên bằng một mã số vô nghĩa như HS001, HS002. Nguyên tắc thứ tư là **chỉ thu thập vừa đủ** cho mục đích đã nêu: một khảo sát về phương tiện đi học thì không có lí do gì để hỏi thêm số điện thoại, địa chỉ nhà hay nghề nghiệp của bố mẹ. Dữ liệu thu thừa không giúp phân tích tốt hơn, mà chỉ làm tăng rủi ro nếu tệp dữ liệu chẳng may bị lộ."},{"t":"note","text":"Hai cái bẫy hay gặp trong đề thi. Thứ nhất, nhiều bạn mặc định giá trị bất thường luôn là lỗi và cần xoá ngay — sai; một học sinh nhà ở xã xa thật sự đi mất 90 phút là dữ liệu thật, xoá đi là làm méo bức tranh thực tế. Thứ hai, thấy ô trống là vội xoá cả hàng — cũng không nên; nếu hàng đó chỉ thiếu một ô ở cột số thì điền bằng giá trị trung bình sẽ giữ lại được toàn bộ các thông tin còn lại, chỉ khi hàng thiếu quá nhiều ô mới nên loại bỏ."}],"keypoints":["Dữ liệu thường đến từ bốn nguồn: **khảo sát và biểu mẫu trực tuyến**, **cảm biến và thiết bị đo**, **nhật kí hoạt động của hệ thống** (`log`) và **dữ liệu mở** do cơ quan nhà nước công bố.","Trong một bảng dữ liệu, **mỗi hàng là một quan sát, mỗi cột là một thuộc tính**; tệp **CSV** lưu bảng đó dưới dạng **văn bản thuần**, mỗi dòng một hàng, các giá trị ngăn cách bởi dấu phẩy.","Bốn lỗi phải soi khi làm sạch là **giá trị bị thiếu**, **bản ghi trùng lặp**, **sai kiểu hoặc sai định dạng** và **giá trị bất thường** — xử lí lần lượt bằng điền trung bình hoặc bỏ hàng, xoá bản trùng, chuẩn hoá định dạng và đơn vị, kiểm tra lại trước khi quyết định.","**Dữ liệu bẩn dẫn tới kết luận sai**, và mô hình học máy huấn luyện trên dữ liệu **thiên lệch** sẽ thiên lệch theo; khi thu thập dữ liệu về con người phải **xin phép, nêu rõ mục đích, ẩn danh thông tin định danh và chỉ thu vừa đủ**."],"quiz":["CC-mc-2801","CC-mc-2802","CC-mc-2803","CC-mc-2804","CC-mc-2805","CC-tf-2801","CC-tf-2802","CC-tf-2803","CC-tf-2804","G-tf-4","G-mc-6","G-mc-7","G-mc-10","C-mc-2","C-mc-8","G-mc-36"]},
    {"id":"C12-29","stage":22,"order":26,"topic":"G","grade":12,"minutes":12,"title":"Đọc bảng dữ liệu: từ con số đến tri thức","intro":"Một bảng số liệu tự nó chưa nói lên điều gì — nó chỉ trở nên có ích khi ta biết đặt câu hỏi và biết tính toán trên đó. Bài học này chỉ ra ba bậc **dữ liệu – thông tin – tri thức**, các đại lượng thống kê mô tả như **trung bình cộng** và **trung vị**, cùng ba thao tác quen thuộc để khai thác một bảng: **lọc**, **sắp xếp** và **nhóm**.","sections":[{"t":"story","text":"Trước cổng trường có một quán nước nhỏ. Mỗi tối, bà chủ quán lại mở cuốn sổ học sinh cũ ra, ghi vào đó đúng một dòng ngắn: ngày hôm nay bán được bao nhiêu chai nước, bao nhiêu cốc trà đá, thu về bao nhiêu tiền. Bà ghi như vậy suốt gần một năm, cuốn sổ dày lên trông thấy, chữ số kín cả trang.\n\nNhưng ghi rồi để đấy thì cuốn sổ cũng chỉ là một chồng con số. Nhìn vào dòng ‘ngày 12: 84 chai’, chẳng ai nói được điều gì thú vị, vì không biết 84 là nhiều hay ít, là bình thường hay bất thường.\n\nMãi đến khi cô con gái về nghỉ hè, hai mẹ con mới ngồi cộng lại theo từng tuần. Cộng xong thì mọi thứ khác hẳn: trung bình mỗi ngày quán bán khoảng 80 chai, ngày cao nhất lên tới 130 chai, ngày thấp nhất chỉ 25 chai. Đem xếp các ngày lại với nhau, hai mẹ con phát hiện ra tất cả những ngày bán ít đều rơi vào thứ Tư và thứ Bảy — đúng hai buổi mà trường chỉ học một ca, học sinh về sớm.\n\nTừ đó, bà chủ quán thay đổi cách làm: thứ Tư và thứ Bảy chỉ nhập một nửa lượng hàng thường ngày, còn những ngày học cả hai buổi thì chuẩn bị thêm đá và nước. Cuốn sổ vẫn là cuốn sổ cũ, nhưng bây giờ nó không còn là một chồng con số nữa — nó đã trở thành thứ giúp bà quyết định mỗi sáng nên nhập bao nhiêu hàng."},{"t":"h","text":"1) Ba bậc: dữ liệu, thông tin và tri thức"},{"t":"text","text":"Câu chuyện trên đi qua đúng ba bậc mà bài học này muốn nói tới. **Dữ liệu** là những con số, bản ghi thô được ghi lại đúng như nó xảy ra, chưa qua xử lí gì: dòng ‘ngày 12: 84 chai’ trong cuốn sổ, một ô điểm trong bảng điểm lớp, một dòng trong sổ mượn sách của thư viện. Mỗi mẩu dữ liệu đứng riêng lẻ thường không cho ta biết nhiều, vì nó thiếu chỗ dựa để so sánh.\n\n**Thông tin** là kết quả tổng hợp có ý nghĩa được rút ra từ dữ liệu. Khi cộng cả tuần lại để biết trung bình mỗi ngày bán 80 chai, khi tìm ra ngày cao nhất là 130 chai và ngày thấp nhất là 25 chai, ta đã biến một đống số rời rạc thành vài câu có nghĩa. Thông tin trả lời cho câu hỏi ‘số liệu đang nói lên điều gì?’, và bao giờ cũng gọn hơn dữ liệu gốc rất nhiều.\n\n**Tri thức** là bậc cao nhất: đó là quy luật, là hiểu biết đủ chắc để ta dựa vào mà hành động và ra quyết định. ‘Những ngày trường học một buổi thì quán bán ít hơn hẳn, nên hôm đó chỉ cần nhập một nửa lượng hàng’ — câu đó không còn là một con số, cũng không chỉ là một nhận xét, mà là một quy tắc dùng được cho những ngày sắp tới. Nói ngắn gọn: dữ liệu là cái ta ghi lại, thông tin là cái ta rút ra được, còn tri thức là cái ta mang ra dùng."},{"t":"h","text":"2) Rút thông tin từ một cột số: các đại lượng thống kê mô tả"},{"t":"list","text":"Muốn biến một cột số dài thành vài câu có nghĩa, ta dùng các **đại lượng thống kê mô tả**. Mỗi đại lượng trả lời một kiểu câu hỏi khác nhau, nên cần chọn đúng loại chứ không phải tính tất cả rồi mới nghĩ:","items":["**Tổng** — cộng toàn bộ giá trị trong cột. Trả lời câu hỏi ‘tất cả cộng lại được bao nhiêu?’, chẳng hạn tổng số suất ăn bán trong ngày hay tổng số tiền cả lớp quyên góp.","**Giá trị lớn nhất và nhỏ nhất** — hai đầu mút của cột dữ liệu. Chúng cho biết khoảng biến động và giúp phát hiện ngay những giá trị bất thường đáng ngờ.","**Trung bình cộng** — lấy tổng chia cho số giá trị. Đây là mức ‘chia đều’ cho mọi giá trị, rất tiện để so sánh hai nhóm có số lượng khác nhau.","**Trung vị** — sắp xếp cả dãy theo thứ tự tăng dần rồi lấy giá trị đứng chính giữa; nếu dãy có số phần tử chẵn thì lấy trung bình của hai giá trị giữa. Trung vị chia dãy thành hai nửa bằng nhau về số lượng.","**Tỉ lệ phần trăm** — lấy phần đang xét chia cho toàn bộ rồi nhân 100. Nó cho biết một nhóm chiếm bao nhiêu phần của tổng thể, điều mà một con số tuyệt đối không nói được."]},{"t":"example","text":"Lớp 12A5 quyên góp ủng hộ đồng bào vùng lũ. Mười bạn trong tổ 1 nộp lần lượt (đơn vị nghìn đồng): 20, 30, 20, 50, 30, 20, 40, 30, 20 và 740 — bạn cuối cùng nộp thay cả gia đình nên khoản này lớn vượt trội. Đoạn chương trình Python sau tính giúp các đại lượng mô tả cho cột số này:","code":"tien = [20, 30, 20, 50, 30, 20, 40, 30, 20, 740]\n\ntong = sum(tien)\ntrung_binh = tong / len(tien)\n\nday = sorted(tien)\nn = len(day)\nif n % 2 == 1:\n    trung_vi = day[n // 2]\nelse:\n    trung_vi = (day[n // 2 - 1] + day[n // 2]) / 2\n\nprint('Tong:', tong)\nprint('Lon nhat:', max(tien), '- Nho nhat:', min(tien))\nprint('Trung binh:', trung_binh)\nprint('Trung vi:', trung_vi)","output":"In ra: Tong: 1000 — Lon nhat: 740 - Nho nhat: 20 — Trung binh: 100.0 — Trung vi: 30.0; trung bình 100 nghìn cao gấp hơn ba lần mức đóng góp thường thấy vì bị khoản 740 kéo lệch, còn trung vị 30 nghìn mới mô tả trung thực cả tổ."},{"t":"h","text":"3) Lọc, sắp xếp và nhóm: ba thao tác khai thác một bảng dữ liệu"},{"t":"example","text":"Trên một bảng nhiều cột, ba thao tác được dùng nhiều nhất là **lọc** theo điều kiện để giữ lại đúng phần cần xem, **sắp xếp** để tìm ra nhóm cao nhất hoặc thấp nhất, và **nhóm dữ liệu** theo một cột rồi tính thống kê cho từng nhóm. Cả ba đều không làm mất dữ liệu gốc — chúng chỉ thay đổi cách ta nhìn vào bảng.\n\nDưới đây là sổ bán hàng một ngày của căng tin trường. Hãy quan sát cách cùng một bảng trả lời được ba câu hỏi rất khác nhau:","code":"Lượt | Buổi   | Món      | Số suất | Thành tiền\n-----+--------+----------+---------+-----------\n  1  | Sáng   | Bánh mì  |   12    |    180\n  2  | Sáng   | Xôi      |   20    |    200\n  3  | Sáng   | Sữa đậu  |   15    |    105\n  4  | Trưa   | Cơm suất |   45    |    900\n  5  | Trưa   | Bún      |   18    |    270\n  6  | Trưa   | Cơm suất |   30    |    600\n  7  | Chiều  | Bánh mì  |    8    |    120\n  8  | Chiều  | Sữa đậu  |   10    |     70\n\nLỌC (Buổi = 'Trưa')      -> còn lại lượt 4, 5, 6\n                            tổng số suất buổi trưa = 45 + 18 + 30 = 93\n\nSẮP XẾP (Số suất giảm dần) -> lượt 4 đứng đầu (Cơm suất, 45 suất)\n\nNHÓM theo cột Món, cộng cột Số suất:\n   Cơm suất 45 + 30 = 75 | Sữa đậu 15 + 10 = 25\n   Bánh mì  12 +  8 = 20 | Xôi 20 | Bún 18   (tổng: 158 suất)","output":"Nhóm theo cột Món rồi cộng cột Số suất cho thấy cơm suất đạt 75 suất, chiếm 75/158 ≈ 47,5% tổng số suất bán ra trong ngày — gần một nửa, nên đây là món căng tin cần chuẩn bị nhiều nhất, đặc biệt cho buổi trưa."},{"t":"h","text":"4) Vì sao phải nhờ đến máy tính, và dùng công cụ gì?"},{"t":"text","text":"Với tám dòng như bảng căng tin ở trên, ta hoàn toàn có thể tính tay. Nhưng nếu đó là sổ bán hàng của cả năm học với hàng chục nghìn dòng, hoặc dữ liệu điểm của toàn trường qua nhiều khoá, thì tính tay là điều không tưởng: chỉ riêng việc cộng thôi cũng mất nhiều ngày và gần như chắc chắn sẽ nhầm ở đâu đó. Máy tính xử lí được khối lượng dữ liệu vượt xa khả năng của con người, và quan trọng không kém, nó **tính lại rất nhanh khi dữ liệu thay đổi** — thêm một tháng số liệu mới, mọi tổng, trung bình, tỉ lệ đều được cập nhật lại chỉ trong tích tắc, thay vì phải làm lại từ đầu. Ngoài ra, máy tính còn giúp **lưu trữ và chia sẻ** dữ liệu: cùng một bảng, nhiều người ở nhiều nơi có thể cùng xem và cùng phân tích.\n\nHai nhóm công cụ thường dùng nhất là **phần mềm bảng tính** và ngôn ngữ **Python**. Phần mềm bảng tính hợp với những bảng vừa phải: ta gõ công thức vào một ô, chọn vùng dữ liệu, và kết quả hiện ra ngay; các lệnh lọc, sắp xếp, tạo bảng tổng hợp theo nhóm đều có sẵn trên thanh công cụ, không cần biết lập trình.\n\nPython mạnh hơn khi dữ liệu lớn hoặc khi công việc phải lặp lại nhiều lần theo cùng một cách. Người làm dữ liệu thường dùng thêm các **thư viện xử lí dữ liệu** viết sẵn cho Python — chúng cung cấp sẵn những hàm đọc tệp dữ liệu, lọc, nhóm và tính thống kê chỉ bằng vài dòng lệnh. Cái được lớn nhất khi dùng Python là đoạn chương trình đã viết có thể chạy lại y hệt cho tháng sau, năm sau, và ai đọc chương trình cũng kiểm tra được ta đã tính những gì."},{"t":"h","text":"5) Từ một câu hỏi cụ thể đến một câu kết luận"},{"t":"text","text":"Sai lầm hay gặp nhất khi mới làm quen với dữ liệu là mở bảng ra rồi tính lung tung mọi thứ có thể tính. Cách làm đúng đi theo ba bước ngắn gọn. Trước hết, **xác định rõ câu hỏi cần trả lời**, càng cụ thể càng tốt — ‘món nào nên chuẩn bị nhiều nhất cho buổi trưa?’ chứ không phải ‘xem thử bảng này có gì hay’. Tiếp theo, **chọn cột và phép tính phù hợp** với câu hỏi đó: câu hỏi vừa nêu cần lọc theo cột Buổi, nhóm theo cột Món rồi cộng cột Số suất, chứ không cần đụng tới cột Thành tiền. Cuối cùng, **diễn giải kết quả thành một câu kết luận** bằng tiếng Việt bình thường, có kèm con số làm bằng chứng: ‘Cơm suất chiếm gần một nửa số suất bán ra trong ngày, nên cần chuẩn bị nhiều nhất.’ Một con số trơ trọi như ‘75’ chưa phải là kết luận.\n\nĐến bước diễn giải thì phải hết sức cẩn thận với cái bẫy quen thuộc nhất: **hai đại lượng cùng tăng chưa chắc cái này gây ra cái kia**. Chẳng hạn, thống kê của một cửa hàng cho thấy tháng nào bán được nhiều nước mát thì tháng đó số ca say nắng ở địa phương cũng tăng. Kết luận ‘uống nước mát gây say nắng’ rõ ràng là vô lí — cả hai hiện tượng đều do một nguyên nhân thứ ba là trời nắng nóng gây ra. Việc hai cột số liệu biến thiên cùng chiều chỉ là **tương quan**; muốn khẳng định **nhân quả** thì cần thêm nhiều bằng chứng khác, và dữ liệu đơn thuần thường không đủ.\n\nCái bẫy thứ hai là quên mất rằng **kết luận rút ra chỉ đúng trong phạm vi dữ liệu đã thu thập**. Bảng căng tin ở trên là số liệu của đúng một ngày, tại đúng một trường — nó không cho phép ta nói ‘học sinh cả nước thích ăn cơm suất nhất’. Khi trình bày kết quả, hãy nói rõ dữ liệu lấy ở đâu, trong khoảng thời gian nào và trên bao nhiêu đối tượng. Một kết luận trung thực về phạm vi của mình luôn đáng tin hơn một kết luận kêu to nhưng vượt quá những gì dữ liệu có thể chứng minh."}],"keypoints":["**Dữ liệu** là con số, bản ghi thô; **thông tin** là kết quả tổng hợp có ý nghĩa rút ra từ dữ liệu; **tri thức** là quy luật, hiểu biết đủ chắc để hành động và ra quyết định.","Các **đại lượng thống kê mô tả** thường dùng gồm tổng, giá trị lớn nhất – nhỏ nhất, **trung bình cộng**, **trung vị** và tỉ lệ phần trăm; khi dãy có giá trị quá lớn hoặc quá nhỏ đột biến thì **trung vị** phản ánh trung thực hơn trung bình cộng.","Ba thao tác cơ bản để khai thác một bảng là **lọc** theo điều kiện, **sắp xếp** để tìm nhóm cao nhất – thấp nhất, và **nhóm dữ liệu** theo một cột rồi tính thống kê cho từng nhóm; máy tính đảm đương khối lượng lớn, tính lại tức thì khi dữ liệu đổi, với công cụ quen thuộc là **phần mềm bảng tính** và **Python** cùng các thư viện xử lí dữ liệu.","Quy trình đọc bảng gồm ba bước: xác định câu hỏi trước, chọn cột và phép tính phù hợp, rồi diễn giải thành một câu kết luận; nhớ rằng **tương quan không đồng nghĩa với nhân quả** và kết luận chỉ đúng trong **phạm vi dữ liệu đã thu thập**."],"quiz":["CC-mc-2901","CC-mc-2902","CC-mc-2903","CC-mc-2904","CC-mc-2905","CC-tf-2901","CC-tf-2902","CC-tf-2903","CC-tf-2904","G-mc-24","G-mc-11","G-mc-12","G-mc-13"]},
    {"id":"C12-18","stage":22,"order":27,"topic":"G","grade":12,"minutes":10,"title":"Trực quan hoá dữ liệu","intro":"Một bảng dài toàn số liệu rất khó để nhận ra xu hướng hay sự khác biệt giữa các nhóm. Bài học này giới thiệu cách chuyển số liệu thành biểu đồ để nhìn ra thông tin nhanh hơn, cùng những lưu ý để không bị một biểu đồ trình bày sai khiến hiểu nhầm.","sections":[{"t":"story","text":"Giả sử một cửa hàng ghi doanh thu của từng tháng suốt một năm vào một bảng tính, mười hai dòng, mỗi dòng một con số. Nhìn vào bảng đó, phải mất một lúc dò từng dòng, cộng trừ nhẩm trong đầu mới đoán được doanh thu đang tăng hay giảm, tháng nào bán chạy nhất, tháng nào ế nhất. Nếu bảng dài đến hàng trăm dòng — doanh thu theo từng ngày của nhiều năm liền — thì gần như không ai đủ kiên nhẫn để nhìn ra được điều gì từ đó nữa.\n\nNhưng chỉ cần đem đúng mười hai con số ấy vẽ thành một đường nối từ tháng 1 đến tháng 12, xu hướng hiện ra ngay trong một cái liếc mắt: đường đi lên, đi xuống hay đi ngang; tháng nào là đỉnh, tháng nào là đáy — tất cả lộ ra tức thì, không cần đọc từng con số một. Biến số liệu khô khan thành một hình ảnh dễ nhìn như vậy chính là chủ đề của bài học này."},{"t":"h","text":"1) Trực quan hoá dữ liệu là gì?"},{"t":"text","text":"**Trực quan hoá dữ liệu** (`data visualization`) là việc biến số liệu thô — vốn chỉ là những con số hoặc bảng chữ khô khan — thành **biểu đồ hoặc hình ảnh**, để bạn nhận ra nhanh những điều mà đọc số liệu thô sẽ mất rất nhiều thời gian mới thấy được: xu hướng đang tăng hay giảm, nhóm nào nổi bật hơn nhóm nào, mỗi phần đóng góp bao nhiêu trong một tổng thể.\n\nCon người vốn giỏi nhận ra hình dạng, độ cao và vị trí hơn là ghi nhớ hàng loạt con số rời rạc. Một cột cao hơn cột bên cạnh, một đường đi dốc lên, một miếng bánh to hơn hẳn phần còn lại — những điều này được mắt và não bộ tiếp nhận gần như ngay lập tức. Vì vậy, cùng một dữ liệu, trình bày dưới dạng biểu đồ phù hợp thường giúp người xem nắm được điều quan trọng nhanh hơn nhiều so với việc dò một bảng số liệu dài."},{"t":"h","text":"2) Ba loại biểu đồ thường dùng"},{"t":"list","text":"**Tuỳ vào câu hỏi muốn trả lời, mỗi loại biểu đồ sẽ phù hợp với một mục đích riêng:**","items":["**Biểu đồ cột** (`bar chart`): mỗi cột ứng với một nhóm hoặc một đối tượng, chiều cao cột thể hiện giá trị — dùng để **so sánh** nhiều nhóm với nhau, ví dụ điểm trung bình của các lớp, doanh thu của nhiều cửa hàng tại cùng một thời điểm.","**Biểu đồ đường** (`line chart`): nối các điểm dữ liệu theo thứ tự thời gian thành một đường liền — dùng để thể hiện **xu hướng biến đổi theo thời gian**, ví dụ nhiệt độ theo từng giờ trong ngày, doanh thu theo từng tháng trong năm.","**Biểu đồ tròn** (`pie chart`): chia một hình tròn thành nhiều miếng, mỗi miếng ứng với một phần — dùng để thể hiện **tỉ lệ phần trăm của từng phần so với tổng thể**, ví dụ tỉ lệ học sinh chọn từng môn tự chọn trong toàn khối."]},{"t":"example","text":"Xét bảng doanh thu của một cửa hàng trong nửa năm đầu, đơn vị triệu đồng:","code":"Tháng | Doanh thu\n1     | 120\n2     | 118\n3     | 135\n4     | 150\n5     | 162\n6     | 178","output":"Đây là dữ liệu biến đổi theo thời gian, nên biểu đồ đường là lựa chọn phù hợp: nối sáu điểm trên lại, đường đi gần như một mạch dốc lên rõ rệt từ tháng 1 đến tháng 6, cho thấy ngay doanh thu đang tăng trưởng đều — điều mà nhìn bảng số phải cộng trừ so sánh từng cặp mới nhận ra được. Nếu đây là doanh thu của sáu cửa hàng khác nhau trong cùng một tháng, biểu đồ cột mới là lựa chọn phù hợp, vì lúc đó câu hỏi cần trả lời là so sánh giữa các nhóm, chứ không phải xu hướng theo thời gian."},{"t":"h","text":"3) Đọc-hiểu một biểu đồ cho đúng"},{"t":"text","text":"Nhìn một biểu đồ đẹp mắt là chưa đủ; đọc đúng thông tin bên trong nó mới là điều quan trọng. Trước khi bạn rút ra bất kì kết luận nào từ một biểu đồ, hãy tập thói quen kiểm tra đủ ba điều sau.\n\nTrước hết là **tiêu đề**: biểu đồ đang nói về điều gì, của đối tượng nào, trong khoảng thời gian hay phạm vi nào. Kế đến là **các trục cùng đơn vị đi kèm**: trục ngang và trục đứng đang thể hiện đại lượng gì, tính bằng triệu đồng hay nghìn đồng, bằng phần trăm hay số lượng tuyệt đối — nhầm đơn vị có thể khiến toàn bộ kết luận rút ra bị sai lệch hoàn toàn. Cuối cùng, nếu biểu đồ có nhiều màu hay nhiều đường cùng lúc, cần xem **chú giải** (`legend`) để biết mỗi màu, mỗi đường tương ứng với đối tượng nào — bỏ qua chú giải rất dễ đọc nhầm đường này thành đường khác."},{"t":"h","text":"4) Cẩn thận: biểu đồ có thể khiến người xem hiểu sai"},{"t":"example","text":"Cùng một số liệu, cách vẽ khác nhau có thể khiến người xem cảm nhận hoàn toàn khác nhau. Doanh thu tháng này của cửa hàng A là 100 triệu, của cửa hàng B là 105 triệu — chênh lệch chỉ khoảng 5%. Xét hai cách vẽ biểu đồ cột dưới đây, cùng biểu diễn đúng hai con số đó:","code":"Cách 1 — trục tung bắt đầu từ 0 (mốc 0, 50, 100, 150):\nA |██████████          100\nB |███████████         105\n\nCách 2 — trục tung chỉ bắt đầu từ 95 (mốc 95, 100, 105):\nA |██                   100\nB |████████████████     105","output":"Ở cách 1, hai cột trông gần như bằng nhau, đúng với thực tế là chênh lệch không đáng kể. Ở cách 2, vì phần trục từ 0 đến 95 đã bị bỏ đi, cột B trông như cao gấp nhiều lần cột A, dù số liệu thật đằng sau chỉ chênh nhau 5 triệu. Đây là kiểu biểu đồ dễ gây hiểu nhầm nhất: cắt bớt trục hoặc phóng đại tỉ lệ khiến một khác biệt nhỏ trông như rất lớn, dù không hề có con số nào bị thay đổi."},{"t":"list","text":"**Trước khi bạn vẽ hoặc trước khi tin vào một biểu đồ, hãy tự hỏi dữ liệu đang trả lời câu hỏi nào:**","items":["Câu hỏi là **so sánh nhiều nhóm** với nhau tại một thời điểm? Chọn **biểu đồ cột**.","Câu hỏi là **theo dõi một đại lượng đổi thay ra sao theo thời gian**? Chọn **biểu đồ đường**.","Câu hỏi là **mỗi phần chiếm bao nhiêu phần trăm của một tổng thể**? Chọn **biểu đồ tròn** — chỉ khi các phần đó thực sự cộng lại thành một tổng có ý nghĩa.","Dù chọn loại biểu đồ nào, luôn kiểm tra lại xem trục có bị cắt bớt hay phóng đại hay không, đơn vị là gì, trước khi tin vào ấn tượng đầu tiên mà biểu đồ mang lại."]}],"keypoints":["**Trực quan hoá dữ liệu** là biến số liệu thô thành biểu đồ hoặc hình ảnh, giúp nhận ra nhanh xu hướng, phép so sánh giữa các nhóm, hay tỉ lệ của một tổng thể — điều mà đọc một bảng số liệu thô sẽ mất nhiều thời gian hơn hẳn.","Ba loại biểu đồ thường dùng: **biểu đồ cột** để so sánh các nhóm, **biểu đồ đường** để thể hiện xu hướng theo thời gian, **biểu đồ tròn** để thể hiện tỉ lệ phần trăm của một tổng thể.","Đọc một biểu đồ cho đúng cần kiểm tra tiêu đề, các trục cùng đơn vị đi kèm, và chú giải nếu biểu đồ có nhiều màu hoặc nhiều đường.","Biểu đồ có thể gây hiểu nhầm nếu trục bị cắt bớt hoặc tỉ lệ bị phóng đại; cần chọn đúng loại biểu đồ cho đúng loại dữ liệu, và đối chiếu lại với số liệu gốc khi nghi ngờ."],"quiz":["CC-mc-1801","CC-mc-1802","CC-mc-1803","CC-mc-1804","CC-mc-1805","CC-tf-1801","CC-tf-1802","CC-tf-1803","CC-tf-1804","G-mc-48","CC-mc-2791","CC-mc-2792","CC-mc-2793","CC-tf-2791"]},
    {"id":"C12-19","stage":22,"order":28,"topic":"G","grade":12,"minutes":10,"title":"Mô phỏng trên máy tính","intro":"Có những việc quá nguy hiểm, quá tốn kém, hoặc cần quá nhiều thời gian để thử trực tiếp ngoài đời — từ việc kiểm tra một cây cầu có chịu được bão hay không, đến việc dự đoán một dịch bệnh sẽ lan rộng ra sao. Bài học này giới thiệu cách máy tính giúp ta ‘thử trước’ những tình huống như vậy thông qua mô phỏng, cùng những giới hạn cần nhớ khi tin vào kết quả của nó.","sections":[{"t":"story","text":"Trước khi cho xây một cây cầu bắc qua sông, đội kĩ sư không thể chờ đến lúc cầu xây xong rồi mới biết nó có chịu được sức nặng của dòng xe cộ hay những cơn gió mạnh hay không — nếu cầu sập vào lúc đó thì đã quá muộn, thiệt hại về người và của là không thể cứu vãn. Thay vào đó, họ dựng một mô hình của cây cầu ấy trên máy tính, đầy đủ hình dạng, vật liệu và kích thước dự kiến.\n\nRồi họ ‘cho’ mô hình ấy chịu đủ loại thử thách: chất thêm xe cộ cho đến khi vượt tải trọng thiết kế, thổi gió mạnh dần từ nhiều hướng, thậm chí giả lập một trận động đất nhỏ. Tất cả diễn ra bên trong máy tính — không một viên gạch nào bị đặt ngoài công trường, không một ai gặp nguy hiểm — nhưng đội kĩ sư đã thấy trước được điểm nào của cây cầu dễ gãy nhất, cần gia cố thêm ở đâu, trước khi cây cầu thật được xây dựng. Đó chính là mô phỏng."},{"t":"h","text":"1) Mô phỏng trên máy tính là gì?"},{"t":"text","text":"**Mô phỏng** (`simulation`) là việc dùng máy tính **dựng một mô hình** — một phiên bản đã được đơn giản hoá của một sự vật hay hiện tượng có thật, mô tả bằng số liệu và quy luật — rồi **cho mô hình đó chạy thử**, để quan sát nó diễn biến ra sao và từ đó dự đoán điều gì có thể xảy ra, mà không cần làm điều đó ngoài đời thật.\n\nHai phần này luôn đi cùng nhau trong một mô phỏng. Phần thứ nhất là **mô hình**: một bản sao rút gọn của thực tế, không cần và cũng không thể chứa mọi chi tiết của hiện tượng gốc, mà chỉ giữ lại những yếu tố quan trọng nhất, đủ để trả lời đúng câu hỏi đang đặt ra — như trong ví dụ cây cầu ở trên, mô hình chỉ cần đủ hình dạng, vật liệu và kích thước để tính được nó chịu lực ra sao, chứ không cần thể hiện từng vết xi măng. Phần thứ hai là **chạy thử**: để máy tính tính toán xem, với những giả định và số liệu đầu vào đã cho, mô hình ấy sẽ vận hành và thay đổi như thế nào theo thời gian hoặc theo từng tình huống khác nhau."},{"t":"h","text":"2) Mô phỏng xuất hiện ở đâu trong đời sống?"},{"t":"list","text":"Mô phỏng được dùng rộng rãi trong nhiều lĩnh vực khác nhau, mỗi nơi phục vụ một mục đích riêng:","items":["**Dự báo thời tiết**: mô hình hoá nhiệt độ, áp suất, độ ẩm của khí quyển, rồi chạy thử để dự đoán trời sẽ mưa hay nắng trong vài ngày tới.","**Mô phỏng giao thông**: dựng mô hình các tuyến đường và dòng xe cộ, thử thay đổi cách bố trí đèn tín hiệu hay làn đường để xem tình trạng kẹt xe có giảm hay không, trước khi thi công thật ngoài đường.","**Mô phỏng lan truyền dịch bệnh**: mô hình hoá cách một bệnh lây từ người này sang người khác, để dự đoán dịch sẽ lan đến đâu và các biện pháp như tiêm chủng hay giãn cách có làm chậm nó lại hay không.","**Thử nghiệm vật lí**: mô phỏng va chạm của một chiếc xe, sức chịu của một toà nhà trước động đất, hay quỹ đạo của một vệ tinh — những thứ khó, đắt đỏ, hoặc quá nguy hiểm để thử bằng vật thật.","**Huấn luyện phi công bằng buồng lái mô phỏng** (`flight simulator`): phi công tập lái trong một buồng mô phỏng dựng lại đầy đủ bảng điều khiển và cảm giác bay, kể cả những tình huống khẩn cấp hiếm gặp, mà không một chiếc máy bay thật nào phải rời khỏi mặt đất."]},{"t":"example","text":"Để thấy rõ hơn cách một mô phỏng hoạt động, hãy xét một mô hình đơn giản về một bệnh cảm lây trong một nhóm 100 người. Giả định mỗi người đang mắc bệnh sẽ lây cho trung bình 2 người khác mỗi ngày nếu không ai đeo khẩu trang, hoặc chỉ còn lây cho 1 người khác mỗi ngày nếu mọi người đều đeo khẩu trang. Bắt đầu từ 1 người mắc bệnh ở ngày 0, mô hình này tính ra hai kịch bản sau:","code":"Ngày | Không đeo khẩu trang | Có đeo khẩu trang\n0    | 1 người              | 1 người\n1    | 3 người              | 2 người\n2    | 9 người              | 4 người\n3    | 27 người             | 8 người\n4    | 81 người             | 16 người","output":"Chỉ bằng cách đổi một con số giả định duy nhất — số người bị lây mỗi ngày — mô hình cho ra hai kết quả khác nhau rõ rệt, mà không cần một ai thật sự mắc bệnh trong lúc chạy thử này. Đây chính là kiểu câu hỏi ‘nếu... thì...’ mà mô phỏng trả lời rất tốt: nếu mọi người đeo khẩu trang thì tốc độ lây bệnh chậm lại đáng kể so với nếu không có biện pháp gì — điều những người làm chính sách y tế có thể thấy trước, thay vì phải chờ một dịch bệnh thật lan ra rồi mới biết mức độ nghiêm trọng của nó."},{"t":"h","text":"3) Vì sao mô phỏng lại hữu ích?"},{"t":"list","text":"So với việc thử trực tiếp ngoài đời thật, mô phỏng trên máy tính đem lại ba lợi ích rõ rệt:","items":["**An toàn**: có thể thử những tình huống nguy hiểm — như cho cây cầu ‘chịu’ một cơn gió cực mạnh, hay để một dịch bệnh ‘lan’ trong mô hình — mà không ai và không công trình nào bị tổn hại thật, vì mọi chuyện chỉ diễn ra bên trong máy tính.","**Tiết kiệm chi phí và thời gian**: không cần xây một cây cầu thật rồi mới biết nó có đứng vững hay không, không cần chờ một dịch bệnh thật bùng phát rồi mới biết cách ứng phó — chạy một mô phỏng thường rẻ hơn và nhanh hơn rất nhiều so với làm thật ngoài đời.","**Thử được nhiều tình huống ‘nếu... thì...’**: chỉ cần đổi một vài số liệu hay giả định đầu vào — như ví dụ đeo khẩu trang hay không ở trên — là có thể chạy lại mô phỏng để so sánh nhiều phương án khác nhau trong một khoảng thời gian ngắn, điều gần như không thể làm được nếu phải thử từng phương án ngoài đời thật."]},{"t":"h","text":"4) Giới hạn của mô phỏng"},{"t":"note","text":"Một mô phỏng chỉ đáng tin khi **mô hình đúng** và **dữ liệu đưa vào tốt**. Nếu mô hình bỏ sót một yếu tố quan trọng của thực tế, hoặc số liệu đầu vào sai lệch, kết quả mô phỏng — dù được máy tính tính ra rất chính xác về mặt con số — vẫn có thể khác xa thực tế. Ví dụ mô phỏng dịch bệnh ở trên chỉ giả định một con số lây nhiễm cố định mỗi ngày cho mọi người; thực tế còn phụ thuộc vào tuổi tác, mật độ dân cư, khả năng miễn dịch của từng người — những yếu tố mà mô hình đơn giản này chưa tính đến.\n\nVì vậy, kết quả của một mô phỏng luôn chỉ là **gần đúng** — một dự đoán có cơ sở, chứ không phải một lời khẳng định chắc chắn — và **không thể thay thế hoàn toàn** việc quan sát, đo đạc ngoài thực tế. Dự báo thời tiết đôi khi sai lệch chính vì lí do này: mô hình khí quyển dù rất phức tạp và được tính trên những máy tính mạnh nhất, vẫn chỉ là một xấp xỉ của bầu trời thật, chứ không phải bản sao hoàn hảo của nó."}],"keypoints":["**Mô phỏng** là dùng máy tính dựng một **mô hình** đơn giản hoá của một hiện tượng thực, rồi **chạy thử** mô hình đó để quan sát, dự đoán điều gì sẽ xảy ra — mà không cần làm thật ngoài đời.","Mô phỏng được dùng trong nhiều lĩnh vực: dự báo thời tiết, mô phỏng giao thông, lan truyền dịch bệnh, thử nghiệm vật lí, huấn luyện phi công bằng buồng lái mô phỏng.","Lợi ích chính của mô phỏng: **an toàn** khi thử các tình huống nguy hiểm, **tiết kiệm chi phí và thời gian** so với làm thật, và thử nhanh được nhiều tình huống **‘nếu... thì...’** khác nhau.","Giới hạn của mô phỏng: kết quả chỉ đáng tin khi **mô hình đúng** và **dữ liệu tốt**; mô phỏng luôn cho ra kết quả **gần đúng**, không thể thay thế hoàn toàn việc quan sát thực tế."],"quiz":["CC-mc-1901","CC-mc-1902","CC-mc-1903","CC-mc-1904","CC-mc-1905","CC-tf-1901","CC-tf-1902","CC-tf-1903","CC-tf-1904","G-mc-25","G-mc-26","G-mc-14","G-tf-1","G-mc-35","G-mc-41","G-tf-9"]},
    {"id":"C12-30","stage":22,"order":29,"topic":"G","grade":12,"minutes":13,"title":"Bên trong một mô hình: tham số, quy tắc và phép thử ‘nếu... thì...’","intro":"Ta đã biết mô phỏng cho phép thử nghiệm mà không cần làm thật. Bài này mở nắp chiếc hộp ra để xem bên trong: một **mô hình mô phỏng** được lắp từ những bộ phận nào, dựng một mô hình đơn giản trên phần mềm bảng tính ra sao, và dùng nó để trả lời câu hỏi dạng ‘nếu... thì...’ như thế nào.","sections":[{"t":"story","text":"Trường của Khanh có khoảng 800 học sinh. Đêm nhạc gây quỹ sẽ diễn ra vào cuối tuần sau, nhưng bảng tin của trường vừa được sơn lại nên chưa dán thông báo được. Là lớp trưởng, Khanh nghĩ ra một cách khác: nhờ đúng 5 bạn trong ban cán sự nhắn tin cho các bạn khác, rồi ai đã biết tin thì hôm sau lại kể tiếp cho người chưa biết.\n\nCâu hỏi làm Khanh băn khoăn là: liệu cách truyền miệng này có kịp không? Bạn ấy lấy tờ giấy nháp ra, giả sử mỗi ngày một bạn đã biết tin sẽ kể lại cho 2 bạn chưa biết. Ngày đầu có 5 bạn biết. Hôm sau, 5 bạn ấy kể cho 10 bạn nữa, thành 15. Hôm sau nữa thành 45, rồi 135, rồi 405... Chỉ sau vài dòng nháp, con số đã vượt qua 800. Khanh thở phào: kịp.\n\nNhưng rồi bạn ấy chợt nghĩ lại. Nếu ai đó bận, quên kể, mỗi ngày mỗi người chỉ kể được cho 1 bạn thôi thì sao? Muốn biết, Khanh phải xoá hết và tính lại từ dòng đầu tiên. Rồi lại tự hỏi tiếp: nếu ban đầu huy động 20 bạn chứ không phải 5 thì nhanh hơn được bao nhiêu? Lại xoá, lại tính lại. Tờ giấy nháp chi chít số, mà mỗi lần đổi một chi tiết nhỏ là phải làm lại toàn bộ.\n\nCái Khanh vừa làm trên giấy nháp — đặt ra vài con số ban đầu, đặt ra một luật chơi, rồi tính lần lượt từng ngày để xem chuyện gì xảy ra — chính là điều mà máy tính có thể làm hộ chúng ta nhanh hơn hàng nghìn lần."},{"t":"h","text":"1) Bên trong một mô hình mô phỏng: tham số, quy tắc và đầu ra"},{"t":"text","text":"Nhìn kỹ tờ giấy nháp của Khanh, ta sẽ thấy nó không hề lộn xộn mà có cấu trúc rất rõ ràng. Bất kỳ **mô hình mô phỏng** nào, dù là mô hình lan truyền tin trong trường hay mô hình dự báo lượng mưa của cả một vùng, cũng đều được lắp từ đúng ba bộ phận.\n\nBộ phận thứ nhất là các **tham số đầu vào** — những số liệu ban đầu do người xây dựng mô hình đặt ra trước khi cho mô hình chạy. Bộ phận thứ hai là các **quy tắc** hay **công thức**, mô tả cách hệ thống biến đổi từ bước này sang bước tiếp theo. Bộ phận thứ ba là các **đại lượng đầu ra** — những con số ta muốn quan sát sau khi mô hình đã chạy xong, vì chính chúng là câu trả lời cho câu hỏi ban đầu.\n\nBa bộ phận này có vai trò khác hẳn nhau, và phân biệt được chúng là việc đầu tiên phải làm khi đọc đề bài về mô phỏng. Tham số đầu vào là thứ ta tự do đặt và tự do đổi; quy tắc là phần thể hiện cách ta hiểu về hệ thống, thường giữ nguyên trong suốt quá trình thử nghiệm; còn đầu ra là thứ ta không được đặt tuỳ ý mà phải để mô hình tự tính ra."},{"t":"list","text":"Soi lại tờ giấy nháp trong câu chuyện mở đầu, ba bộ phận hiện ra rất rõ:","items":["**Tham số đầu vào**: số bạn biết tin ngày đầu tiên (5 bạn), số bạn mà mỗi người kể lại trong một ngày (2 bạn), tổng số học sinh toàn trường (800).","**Quy tắc biến đổi**: số bạn biết tin ngày hôm sau bằng số bạn biết tin hôm nay cộng thêm phần được kể mới, nhưng không bao giờ vượt quá tổng số học sinh của trường.","**Đại lượng đầu ra**: dãy số bạn đã biết tin theo từng ngày, và quan trọng nhất là con số ‘sau bao nhiêu ngày thì cả trường đều biết’.","**Bước thời gian**: mô hình nhảy theo từng ngày một — đây cũng là một lựa chọn của người dựng mô hình, có thể thay bằng từng buổi hoặc từng giờ nếu muốn chi tiết hơn."]},{"t":"h","text":"2) Giả thiết đơn giản hoá — cái giá phải trả để mô hình chạy được"},{"t":"text","text":"Hãy thành thật với nhau: câu ‘mỗi ngày một bạn kể lại cho đúng 2 bạn chưa biết’ là điều không bao giờ xảy ra chính xác như vậy ngoài đời. Có bạn hào hứng kể cho cả chục người, có bạn quên bẵng, có bạn kể lại cho người đã biết rồi nên chẳng thêm được ai. Vậy mà nếu không chấp nhận câu đó, ta sẽ không có công thức nào để viết, và mô hình sẽ không chạy được.\n\nNhững điều ta cố tình chấp nhận cho ‘gọn lại’ như thế gọi là **giả thiết đơn giản hoá**. Xây dựng mô hình luôn luôn đi kèm với việc bỏ bớt các yếu tố phụ: bỏ chuyện có bạn nghỉ ốm, bỏ chuyện cuối tuần học sinh không gặp nhau, bỏ cả chuyện tin có thể bị kể sai lệch. Không có mô hình nào giữ lại được toàn bộ thực tế, và cũng không cần thiết phải như vậy.\n\nĐiều phải nhớ là quan hệ đánh đổi giữa hai bên: mô hình càng thêm nhiều giả thiết đơn giản hoá thì càng dễ dựng, dễ tính, chạy càng nhanh — nhưng đồng thời cũng càng xa thực tế, nên kết quả càng phải đọc một cách dè dặt. Ngược lại, mô hình giữ lại nhiều chi tiết thì sát thực tế hơn nhưng phức tạp hơn nhiều, đòi hỏi nhiều dữ liệu hơn và cũng dễ mắc lỗi hơn. Người dựng mô hình giỏi là người biết bỏ đúng những thứ đáng bỏ, chứ không phải người bỏ ít nhất hay bỏ nhiều nhất."},{"t":"h","text":"3) Mô phỏng tất định và mô phỏng ngẫu nhiên"},{"t":"text","text":"Trong mô hình của Khanh, cứ đặt 5 bạn ban đầu và mỗi người kể cho 2 bạn thì lần nào tính cũng ra đúng dãy 5, 15, 45, 135, 405... Đưa cùng một bộ tham số đầu vào, kết quả nhận về luôn giống hệt nhau, dù tính lại một trăm lần. Loại mô hình như vậy gọi là **mô phỏng tất định**.\n\nNhưng ta hoàn toàn có thể dựng mô hình theo kiểu khác, sát đời hơn: thay vì bắt mỗi bạn kể cho đúng 2 người, ta để máy tự bốc ra một con số may rủi trong khoảng từ 0 đến 4 cho mỗi bạn, mỗi ngày. Khi đó mô hình có yếu tố may rủi bên trong, và mỗi lần chạy sẽ cho một kết quả hơi khác nhau — lần này 6 ngày, lần sau 5 ngày, lần sau nữa 8 ngày. Đó là **mô phỏng ngẫu nhiên**.\n\nSự khác biệt này dẫn tới một quy tắc sử dụng rất quan trọng. Với mô phỏng tất định, chạy một lần là đủ. Với mô phỏng ngẫu nhiên, chạy một lần rồi kết luận là sai lầm, vì con số nhận được có thể chỉ là một trường hợp may mắn hoặc xui xẻo hiếm gặp; phải chạy thật nhiều lần rồi lấy **trung bình** của các kết quả thì con số mới đáng tin. Kết quả lệch nhau giữa các lần chạy ở đây không phải là dấu hiệu chương trình bị lỗi, mà là bản chất của loại mô hình này."},{"t":"h","text":"4) Dựng mô hình trên phần mềm bảng tính"},{"t":"example","text":"Bảng tính là công cụ tiện nhất để dựng một mô hình nhỏ, vì nó tính lại toàn bộ ngay khi ta sửa một ô. Bí quyết là đặt mỗi tham số vào một ô riêng ở phía trên, rồi viết công thức tham chiếu tới các ô đó thay vì gõ thẳng con số vào công thức. Mỗi dòng phía dưới ứng với một bước thời gian, và ta chỉ cần kéo công thức xuống là xong:","code":"         A                                B\n 1   Số bạn biết tin ban đầu            5\n 2   Mỗi ngày một bạn kể cho            2\n 3   Tổng số học sinh toàn trường       800\n 4\n 5   Ngày                               Số bạn đã biết\n 6   0                                  =B1\n 7   1                                  =MIN($B$3, B6*(1+$B$2))\n 8   2                                  (kéo công thức ở ô B7 xuống)\n 9   3                                  (kéo tiếp)\n10   4                                  (kéo tiếp)\n11   5                                  (kéo tiếp)","output":"Cột B lần lượt hiện 5, 15, 45, 135, 405 rồi dừng lại ở 800 — theo mô hình này, sau đúng 5 ngày thì cả 800 học sinh của trường đều đã biết tin."},{"t":"text","text":"Hãy để ý hai chi tiết nhỏ nhưng quyết định trong công thức trên. Thứ nhất, các ô tham số được viết dưới dạng `$B$2`, `$B$3` có dấu đô la, để khi kéo công thức xuống thì phần tham chiếu này không bị trượt theo — mọi dòng đều lấy đúng tham số ở đầu bảng. Thứ hai, hàm `MIN` đóng vai trò một quy tắc chặn: số người biết tin không thể vượt quá sĩ số toàn trường, dù phép nhân có cho ra 1215 đi nữa. Nhờ cách bố trí này, ta có ngay công cụ để chạy **kịch bản giả định** dạng ‘nếu... thì...’: giữ nguyên toàn bộ mô hình — không sửa công thức, không sửa cấu trúc bảng — mà chỉ thay đổi lần lượt từng tham số đầu vào, rồi so sánh các kết quả đầu ra với nhau.\n\nSửa ô `B2` từ 2 xuống 1, bảng lập tức tính lại và cho dãy 5, 10, 20, 40, 80, 160, 320, 640 rồi mới tới 800: phải mất 8 ngày. Trả `B2` về 2 rồi sửa ô `B1` từ 5 lên 20, kết quả là 20, 60, 180, 540 rồi 800: mất 4 ngày. Hai kịch bản đó nói lên điều mà ngồi đoán mò không thể thấy được — huy động gấp bốn lần số người đưa tin ban đầu chỉ rút ngắn được 1 ngày, trong khi việc mỗi người kể cho 2 hay chỉ 1 bạn lại làm thời gian chênh nhau tới 3 ngày. Vậy yếu tố ảnh hưởng mạnh nhất không phải là ‘khởi đầu đông hay ít’ mà là ‘mỗi người có chịu kể tiếp hay không’. Cũng chính vì vậy mà mỗi lần chỉ được đổi một tham số: nếu đổi hai ba tham số cùng lúc, kết quả có thay đổi cũng không biết là do cái nào gây ra.\n\nCách bố trí ‘tham số ở trên, công thức ở dưới’ này không chỉ có ở bảng tính. Các phần mềm thí nghiệm ảo mà các em vẫn dùng ở môn Vật lí hay Hoá học cũng được lắp theo đúng ba bộ phận đã học: thanh trượt kéo được trên màn hình chính là **tham số đầu vào**, phần tính toán ẩn phía sau là **quy tắc**, còn đồ thị hoặc hình động hiện ra là **đại lượng đầu ra**. Nhận ra ba bộ phận quen thuộc đó khi mở một phần mềm lạ là cách nhanh nhất để biết mình được phép thay đổi cái gì và phải nhìn vào đâu để đọc kết quả.\n\nCũng cần cảnh giác một điều mà người mới dùng hay bỏ qua: thanh trượt bao giờ cũng có giới hạn, và giới hạn ấy không hề tuỳ tiện — nó đánh dấu vùng mà các giả thiết đơn giản hoá của mô hình còn có nghĩa. Ngay mô hình lan truyền tin ở trên cũng vậy: kéo bảng dài thêm hai chục dòng nữa thì cột B vẫn đứng yên ở 800 chứ không cho biết thêm điều gì, vì mô hình chỉ được dựng cho giai đoạn tin đang lan. Một kịch bản giả định chỉ đáng tin trong đúng phạm vi mà mô hình được xây dựng cho, ra ngoài phạm vi đó thì con số máy trả về vẫn có nhưng không còn ý nghĩa."},{"t":"note","text":"Một mô hình chạy mượt mà chưa chắc đã là mô hình đúng. Cách kiểm tra **độ tin cậy** là đối chiếu kết quả mô phỏng với những **số liệu thực đã biết**: cho mô hình chạy lại một tình huống mà ta đã có kết quả thật, rồi xem hai bên có khớp nhau không; nếu lệch nhiều thì quay lại điều chỉnh tham số hoặc sửa chính quy tắc của mô hình cho sát hơn rồi thử lại.\n\nBẫy rất hay gặp trong đề thi: thấy mô hình cho ra kết quả tròn trịa, đúng như mình mong đợi thì vội kết luận mô hình phản ánh đúng thực tế. Kết quả đẹp chỉ chứng tỏ công thức chạy trơn tru, hoàn toàn không chứng tỏ các giả thiết đơn giản hoá là hợp lí. Chừng nào chưa đối chiếu được với số liệu thực, con số mô phỏng vẫn chỉ là ‘nếu mọi thứ diễn ra đúng như ta giả định thì...’, chứ chưa phải là điều sẽ xảy ra."}],"keypoints":["Một mô hình mô phỏng luôn gồm ba bộ phận: các **tham số đầu vào** (số liệu ban đầu do người dùng đặt), các **quy tắc/công thức** mô tả cách hệ thống biến đổi qua từng bước, và các **đại lượng đầu ra** cần quan sát.","Mọi mô hình đều đi kèm **giả thiết đơn giản hoá** để bỏ bớt yếu tố phụ; càng nhiều giả thiết thì mô hình càng dễ tính nhưng càng xa thực tế.","**Mô phỏng tất định** cho cùng kết quả với cùng đầu vào nên chạy một lần là đủ; **mô phỏng ngẫu nhiên** có yếu tố may rủi nên phải chạy nhiều lần rồi lấy **trung bình**.","Chạy **kịch bản giả định** ‘nếu... thì...’ bằng cách giữ nguyên mô hình và mỗi lần chỉ đổi một tham số rồi so sánh đầu ra; **độ tin cậy** của mô hình được kiểm tra bằng cách đối chiếu với số liệu thực đã biết rồi hiệu chỉnh lại."],"quiz":["CC-mc-3001","CC-mc-3002","CC-mc-3003","CC-mc-3004","CC-mc-3005","CC-tf-3001","CC-tf-3002","CC-tf-3003","CC-tf-3004","G-mc-27","G-mc-32","G-mc-33","G-mc-34"]},
    {"id":"C12-20","stage":22,"order":30,"topic":"G","grade":12,"minutes":12,"title":"Dữ liệu lớn và xu hướng công nghệ","intro":"Bài học giới thiệu **dữ liệu lớn** (`big data`) — khối dữ liệu khổng lồ mà cả thế giới sinh ra mỗi ngày — cùng lí do vì sao nó quý giá, cách nó kết hợp với trí tuệ nhân tạo, điện toán đám mây và `IoT` để tạo ra nhiều ứng dụng thông minh, và trách nhiệm đi kèm khi khai thác nguồn dữ liệu ấy.","sections":[{"t":"story","text":"Hãy tưởng tượng bạn đứng giữa một thành phố lớn vào một ngày rất đỗi bình thường. Ngay lúc này, hàng triệu người đang gõ tin nhắn, chụp ảnh, bật định vị trên điện thoại; hàng nghìn camera an ninh đang ghi hình từng góc phố; đèn giao thông, cảm biến đo chất lượng không khí, máy đo nhiệt độ tự động gửi số liệu về trung tâm mỗi vài giây; các cửa hàng ghi lại từng hoá đơn, từng lượt quét mã giảm giá. Chỉ trong đúng một giây, cả thành phố ấy đã tạo ra một lượng thông tin nhiều đến mức không một người nào, dù chăm chỉ đến đâu, có thể đọc hết bằng mắt thường.\n\nGiờ hãy nhân cảnh tượng đó lên cho cả thế giới, với hàng tỉ chiếc điện thoại, hàng tỉ cảm biến, hàng triệu giao dịch diễn ra mỗi phút — ta có một “biển” dữ liệu khổng lồ, sinh ra liên tục, không lúc nào ngưng nghỉ. Biển dữ liệu ấy chính là nguyên liệu mà nhiều công nghệ hiện đại nhất hiện nay — từ gợi ý video bạn hay xem, dự báo thời tiết, cho đến xe tự lái — đang âm thầm khai thác mỗi ngày. Bài học này sẽ giúp bạn hiểu biển dữ liệu đó lớn và phức tạp đến mức nào, vì sao nó quý giá, và nó đang được kết hợp với những công nghệ nào để tạo ra các ứng dụng thông minh quanh ta."},{"t":"h","text":"1) Dữ liệu lớn (`big data`) là gì?"},{"t":"text","text":"Trong đời sống hằng ngày, ta quen với việc lưu vài trăm tấm ảnh trong điện thoại hay vài chục tệp văn bản trên máy tính — những khối dữ liệu mà một chiếc máy tính bình thường, một phần mềm quen thuộc như bảng tính, xử lí gọn gàng trong tích tắc.\n\n**Dữ liệu lớn** (tiếng Anh: `big data`) dùng để chỉ những khối dữ liệu có quy mô vượt xa mức đó — được sinh ra liên tục, từ rất nhiều nguồn khác nhau: bài đăng và tin nhắn trên mạng xã hội, hình ảnh từ camera an ninh, tín hiệu từ cảm biến và thiết bị `IoT`, lịch sử giao dịch mua bán, dữ liệu định vị từ điện thoại di động... Gọi là “lớn” không chỉ vì số lượng khổng lồ, mà còn vì tốc độ sinh ra quá nhanh và kiểu dữ liệu quá đa dạng, khiến các công cụ xử lí dữ liệu thông thường — như một phần mềm bảng tính hay một cơ sở dữ liệu cỡ nhỏ — gặp khó khăn, thậm chí không thể đảm đương nổi."},{"t":"example","text":"Để cảm nhận rõ hơn quy mô của dữ liệu lớn, hãy thử hình dung một bức tranh ước tính về lượng dữ liệu được cả thế giới tạo ra, chỉ trong đúng một phút:","code":"Hàng chục triệu tin nhắn được gửi đi trên các nền tảng mạng xã hội\nHàng triệu lượt tìm kiếm được thực hiện trên các công cụ tìm kiếm\nHàng trăm nghìn giờ video được tải lên các nền tảng chia sẻ video\nHàng triệu giao dịch mua bán được thực hiện trực tuyến\nHàng triệu tín hiệu được gửi về từ các cảm biến, thiết bị IoT đang hoạt động","output":"Đó mới chỉ là một phút, và con số này còn tiếp tục tăng lên mỗi năm khi ngày càng nhiều người, nhiều thiết bị kết nối mạng. Không một người hay một nhóm người nào có thể đọc hết, hiểu hết khối dữ liệu khổng lồ và hỗn độn này chỉ bằng cách nhìn qua — đó là lí do cần đến những công cụ và phương pháp chuyên biệt để lưu trữ, xử lí dữ liệu lớn."},{"t":"h","text":"2) Ba đặc điểm của dữ liệu lớn"},{"t":"list","text":"Các chuyên gia thường mô tả dữ liệu lớn qua ba đặc điểm nổi bật sau:","items":["**Khối lượng khổng lồ** (`volume`): dữ liệu được đo bằng những đơn vị rất lớn — hàng triệu, hàng tỉ bản ghi mỗi ngày — vượt xa khả năng lưu trữ của một chiếc máy tính hay điện thoại thông thường.","**Tốc độ sinh ra rất nhanh** (`velocity`): dữ liệu mới liên tục xuất hiện từng giây, từng phút — một bài đăng mạng xã hội, một lượt quẹt thẻ, một tín hiệu cảm biến — không hề dừng lại để chờ được xử lí.","**Đa dạng về loại** (`variety`): dữ liệu lớn không chỉ gồm những con số hay dòng chữ gọn gàng trong một bảng tính, mà còn có hình ảnh, âm thanh, video, vị trí địa lí, và nhiều định dạng khác trộn lẫn với nhau."]},{"t":"h","text":"3) Vì sao dữ liệu lớn quý giá?"},{"t":"text","text":"Tự thân một khối dữ liệu hỗn độn, khổng lồ chưa nói lên điều gì; giá trị thật sự nằm ở việc **phân tích** khối dữ liệu đó để tìm ra quy luật ẩn bên trong. Khi hàng triệu, hàng tỉ bản ghi được gộp lại và phân tích bằng những công cụ phù hợp, ta có thể nhận ra những xu hướng mà chỉ nhìn vào vài bản ghi riêng lẻ sẽ không bao giờ thấy được — chẳng hạn mặt hàng nào đang được ưa chuộng hơn theo mùa, khung giờ nào dễ xảy ra ùn tắc giao thông, hay dấu hiệu nào thường xuất hiện trước khi một thiết bị gặp sự cố.\n\nNhờ những phát hiện đó, các tổ chức — từ doanh nghiệp, bệnh viện, đến cơ quan quản lí đô thị — có thêm căn cứ để **ra quyết định** thay vì chỉ dựa vào phỏng đoán hay kinh nghiệm cá nhân. Không chỉ vậy, dữ liệu lớn còn là nguyên liệu để **huấn luyện** các hệ thống trí tuệ nhân tạo: một hệ thống học máy càng được học từ nhiều dữ liệu chất lượng, càng có cơ hội đưa ra dự đoán hay quyết định chính xác hơn."},{"t":"h","text":"4) Khi dữ liệu lớn kết hợp với công nghệ khác"},{"t":"text","text":"Dữ liệu lớn hiếm khi phát huy hết giá trị nếu đứng một mình; giá trị của nó bộc lộ rõ nhất khi được **kết hợp** với những công nghệ khác. Thiết bị `IoT` (Internet vạn vật) — cảm biến, camera, đồng hồ thông minh — là nguồn liên tục sinh ra dữ liệu lớn. **Điện toán đám mây** cung cấp nơi lưu trữ đủ rộng và sức mạnh tính toán đủ lớn để chứa và xử lí khối dữ liệu đó, thay vì bắt một chiếc máy tính đơn lẻ gánh vác. Còn **trí tuệ nhân tạo**, đặc biệt là **học máy**, đóng vai trò như “bộ não” phân tích dữ liệu lớn để tìm ra quy luật, đưa ra dự đoán hay tự động hoá quyết định. Sự kết hợp của bốn yếu tố này — dữ liệu lớn, `IoT`, điện toán đám mây và trí tuệ nhân tạo — đang tạo ra hàng loạt ứng dụng thông minh trong đời sống."},{"t":"list","text":"Một vài ứng dụng quen thuộc thể hiện rõ sự kết hợp này:","items":["**Gợi ý nội dung**: nền tảng xem video hay nghe nhạc phân tích dữ liệu lớn về thói quen của hàng triệu người dùng để gợi ý nội dung phù hợp với từng người.","**Xe tự lái**: liên tục thu thập dữ liệu từ nhiều cảm biến, camera gắn trên xe, kết hợp trí tuệ nhân tạo để nhận diện chướng ngại vật và ra quyết định trong tích tắc.","**Đô thị thông minh**: dữ liệu từ cảm biến giao thông, camera, thiết bị định vị được phân tích để điều chỉnh đèn tín hiệu, cảnh báo ùn tắc theo thời gian thực.","**Dự báo thời tiết, thiên tai**: dữ liệu từ vệ tinh và các trạm quan trắc khắp nơi được gộp lại, phân tích để đưa ra dự báo ngày càng chính xác hơn."]},{"t":"h","text":"5) Trách nhiệm và xu hướng tương lai"},{"t":"text","text":"Phần lớn dữ liệu lớn được tạo ra từ chính hoạt động thường ngày của con người — vị trí đang đứng, nội dung tìm kiếm, thói quen mua sắm — nên việc thu thập và khai thác dữ liệu lớn luôn phải đi kèm trách nhiệm bảo vệ **quyền riêng tư**. Một tổ chức thu thập dữ liệu cần minh bạch về việc mình thu thập gì, dùng vào việc gì, và phải bảo vệ dữ liệu đó trước nguy cơ bị rò rỉ hay sử dụng sai mục đích. Là người dùng, ta cũng nên quan tâm tìm hiểu chính sách quyền riêng tư của các dịch vụ mình sử dụng, thay vì đồng ý cho qua mà không để ý."},{"t":"note","text":"Lượng dữ liệu được tạo ra trên thế giới sẽ còn tiếp tục tăng nhanh hơn nữa, khi ngày càng nhiều thiết bị — đồ gia dụng, phương tiện giao thông, thiết bị đeo trên người — được kết nối mạng. Xu hướng công nghệ vì vậy cũng dịch chuyển theo: công cụ phân tích dữ liệu lớn ngày càng dễ tiếp cận hơn, trí tuệ nhân tạo được huấn luyện từ khối dữ liệu khổng lồ ngày càng chính xác hơn, và những nghề nghiệp liên quan đến thu thập, xử lí, bảo vệ dữ liệu lớn cũng vì vậy mà trở nên cần thiết hơn bao giờ hết. “Biển” dữ liệu ấy vẫn đang lớn dần lên từng giây — biết khai thác nó một cách có trách nhiệm chính là chìa khoá của rất nhiều công nghệ hiện đại."}],"keypoints":["**Dữ liệu lớn** (`big data`) là khối dữ liệu khổng lồ, sinh ra liên tục từ nhiều nguồn khác nhau — mạng xã hội, cảm biến, `IoT`, giao dịch mua bán... — lớn và phức tạp đến mức các công cụ xử lí dữ liệu thông thường khó đảm đương.","Ba đặc điểm cốt lõi của dữ liệu lớn: **khối lượng khổng lồ** (`volume`), **tốc độ sinh ra rất nhanh** (`velocity`), và **đa dạng về loại dữ liệu** (`variety`).","Dữ liệu lớn quý giá vì việc phân tích nó giúp phát hiện xu hướng ẩn, hỗ trợ **ra quyết định**, và là nguyên liệu để **huấn luyện trí tuệ nhân tạo, học máy**.","Dữ liệu lớn phát huy giá trị cao nhất khi **kết hợp** với `IoT`, **điện toán đám mây** và **trí tuệ nhân tạo** để tạo ra nhiều ứng dụng thông minh; đi kèm đó là trách nhiệm bảo vệ **quyền riêng tư** của dữ liệu."],"quiz":["CC-mc-2001","CC-mc-2002","CC-mc-2003","CC-mc-2004","CC-mc-2005","CC-tf-2001","CC-tf-2002","CC-tf-2003","CC-tf-2004","C-mc-11","G-mc-40","G-tf-6","G-mc-47"]}
  );
})();
